object Main extends App {

  def isLeftSmall(c1: String, c2: String): Boolean = {
    if (c1.takeRight(1).toInt < c2.takeRight(1).toInt) true else false
  }

  def bubbleSort(c: Array[String], n: Int) {
    for(i <- (0 to n - 1)) {
      for (j <- (n - 1 until i by -1)) {
        if (isLeftSmall(c(j), c(j - 1))) {
          val tmp_v = c(j)
          c(j) = c(j - 1)
          c(j - 1) = tmp_v
        }
      }
    }
    println(c.mkString(" "))
    println("Stable")
  }

  def selectionSort(c: Array[String], n: Int) {
    for (i <- (0 to n - 1)) {
      var min_j = i
      for (j <- (i to n - 1)) {
        if (isLeftSmall(c(j), c(min_j))) {
          min_j = j
        }
      }
      val tmp_v = c(i)
      c(i) = c(min_j)
      c(min_j) = tmp_v
    }
    println(c.mkString(" "))
  }

  val n = readLine.toInt
  val c = readLine.split(" ").toArray
  val c1 = c.clone
  val c2 = c.clone
  bubbleSort(c1, n)
  selectionSort(c2, n)
  if (c1 sameElements c2) println("Stable") else println("Not stable")
}

import java.util.Scanner

import scala.collection.mutable.ArrayBuffer

object Main {

  import ExtendedString._

  def main(args: Array[String]): Unit = {
    val sc = new Scanner(System.in)
    val n = sc.nextInt()
    val cards = Vector.fill(n)(sc.next())

    val bubCared = bub(n, ArrayBuffer.apply(cards: _*))
    val selCared = sel(n, ArrayBuffer.apply(cards: _*))
    println(bubCared.mkString(" "))
    println(isStable(cards, bubCared.toVector))
    println(selCared.mkString(" "))
    println(isStable(cards, selCared.toVector))
  }

  def bub(n: Int, cards: ArrayBuffer[String]): ArrayBuffer[String] = {
    (0 to n - 1).foreach { i =>
      (n - 1 to(i + 1, -1)).foreach { j =>
        if (cards(j).getCardValue < cards(j - 1).getCardValue) {
          val cj = cards(j)
          val cjMinusOne = cards(j - 1)
          cards(j) = cjMinusOne
          cards(j - 1) = cj
        }
      }
    }
    cards
  }

  def sel(n: Int, cards: ArrayBuffer[String]): ArrayBuffer[String] = {
    (0 to n - 1).foreach { i =>
      var minj = i
      (i to n - 1).foreach { j =>
        if (cards(j).getCardValue < cards(minj).getCardValue) {
          minj = j
        }
      }
      val ci = cards(i)
      val cmin = cards(minj)
      cards(i) = cmin
      cards(minj) = ci
    }
    cards
  }

  def isStable(before: Vector[String], after: Vector[String]): String = {
    val afterGroup = after.groupBy(_.getCardValue)
    before.groupBy(_.getCardValue).forall { case (i, b) =>
      afterGroup(i) == b
    } match {
      case true => "Stable"
      case false => "Not stable"
    }
  }

}

object ExtendedString {

  implicit class CardString(str: String) {
    def getCardValue = str.last.toInt
  }

}

object Main {
  def main(args: Array[String]): Unit = {
    val scanner = new java.util.Scanner(System.in)

    val a = Array.fill(scanner.nextInt)(parse(scanner.next))
    val b = bubbleSort(a)
    val s = SelectionSort(a)
    println(b.map(t => s"${t._1}${t._2}").mkString(" "))
    println(if(checkStable(b, a)) "Stable" else "Not stable")
    println(s.map(t => s"${t._1}${t._2}").mkString(" "))
    println(if(checkStable(s, a)) "Stable" else "Not stable")
  }

  def checkStable(target: Seq[(Char, Int)], original: Seq[(Char, Int)]): Boolean =
    (1 to 9).find(i => !target.filter(_._2 == i).equals(original.filter(_._2 == i))).isEmpty

  def parse(card: String): (Char, Int) =
    (card(0), card.substring(1).toInt)

  def bubbleSort(a: Seq[(Char, Int)]): Seq[(Char, Int)] = {
    val c = new Array[(Char, Int)](a.length)
    a.copyToArray(c)
    for(i <- 0 until c.length) {
      for(j <- c.length - 1 to i + 1 by -1) {
        if(c(j)._2 < c(j - 1)._2) {
          val t = c(j)
          c(j) = c(j - 1)
          c(j - 1) = t
        }
      }
    }
    c
  }

  def SelectionSort(a: Seq[(Char, Int)]): Seq[(Char, Int)] = {
    val c = new Array[(Char, Int)](a.length)
    a.copyToArray(c)
    var minj = 0
    for(i <- 0 until c.length) {
      minj = i
      for(j <- i until c.length) {
        if(c(j)._2 < c(minj)._2) {
          minj = j
        }
      }
      val t = c(i)
      c(i) = c(minj)
      c(minj) = t
    }
    c
  }
}

