    (0 until n).foreach { i =>
      (n - 1 until i by -1).foreach { j =>
        if (arr(j).num < arr(j - 1).num) {
          swap(arr, j, j - 1)
        }
      }
    }
    arr
  }

  def selectionSort(arr: Array[Card], n: Int): Array[Card] = {
    (0 until n).foreach { i =>
      var minj = i
      (i until n).foreach { j =>
        minj = if (arr(j).num < arr(minj).num) j else minj
      }
      swap(arr, minj, i)
    }
    arr
  }
}

