int BubbleSort(vector<string> &A)
{
    int count = 0;
    for(int i = 0; i < A.size(); i++){
        for(int j = A.size()-1; j >= i+1; j--){
            if(A[j][1] < A[j-1][1]){
                swap(A[j], A[j-1]);
                count++;
            }
        }
    }
    return count;
}
int selectionSort(vector<string>& A){
    int count = 0;
    for(int i = 0; i < A.size(); i++){
        int minj = i;
        for(int j = i; j < A.size(); j++){
            if(A[j][1] < A[minj][1]){
                minj = j;
            }
        }
        count += i != minj;
        swap(A[i], A[minj]);
    }
    return count;
}
