void trace(vector<pair<string, int>> &C) {
    for (size_t i = 0; i < C.size(); i++) {
        cout << C[i].first << C[i].second;
        cout << ((i != C.size() - 1) ? " " : "\n");
    }
}

void BubbleSort(vector<pair<string, int>> &C, int N) {
    for (int i = 0; i < N - 1; i++) {
        for (int j = N - 1; j > i; j--) {
            if (C[j - 1].second > C[j].second) {
                swap(C[j], C[j - 1]);
            }
        }
    }

    trace(C);
}

void SelectionSort(vector<pair<string, int>> &C, int N) {
    for (int i = 0; i < N - 1; i++) {
        int minj = i;
        for (int j = i; j < N; j++) {
            if (C[j].second < C[minj].second) {
                minj = j;
            }
        }
        swap(C[i], C[minj]);
    }
    trace(C);
}

void Compare(vector<pair<string, int>> &A, vector<pair<string, int>> &B) {
    for (size_t i = 0; i < A.size(); i++) {
        if (A[i].first != B[i].first || A[i].second != B[i].second) {
            cout << "Not stable" << endl;
            return;
        }
    }
    cout << "Stable" << endl;
}

