#include <iostream>
#include <vector>
using namespace std;

struct Card {
	char c;
	int v;
};

int BubbleSort(vector<Card>& C, int N) {
    bool flag = true;
    int cnt = 0;
    int i = 0;
    while (flag) {
        flag = false;
        for (int j = N-1; j > i; j--) {
            if (C[j-1].v > C[j].v) {
                Card tmp = C[j-1];
                C[j-1] = C[j];
                C[j] = tmp;
                flag = true;
                cnt++;
            }
        }
        i++;
    }
    return cnt;
}

int SelectionSort(vector<Card>& C, int N) {
	int cnt = 0;
	for (int i = 0; i < N; i++) {
		int minj = i;
		for (int j = i; j < N; j++) {
			if (C[j].v < C[minj].v) {
				int tmp = minj;
				minj = j;
				j = tmp;
			}
		}
		if (C[i].v != C[minj].v) {
			Card tmp = C[i];
			C[i] = C[minj];
			C[minj] = tmp;
		}
	}
	return cnt;
}

bool isSame(Card& a, Card& b) {
	return a.c == b.c && a.v == b.v;
}

bool isStable(vector<Card>& in, vector<Card>& out, int N) {
	for (int i = 0; i < N; i++) {
		for (int j = i+1; j < N; j++) {
			for (int a = 0; a < N; a++) {
				for (int b = a+1; b < N; b++) {
					if (in[i].v == in[j].v && isSame(in[i], out[b]) && isSame(in[j], out[a])) {
						return false;
					}
				}
			}
		}
	}
	return true;
}

void show(vector<Card>& card, int N) {
	for (int i = 0; i < N; i++) {
		if (i < N-1) cout << card[i].c << card[i].v << ' ';
		else cout << card[i].c << card[i].v << endl;
	}
}

