int bubble_sort(unsigned short int *n, unsigned short int N){
    int max = N-1;
    int flag;
    if(N >= 2){
        flag = 1; //ソート終了フラグ
    }else if(N<=1) flag = 0;
    int count=0; //交換回数
    while(flag == 1){
        for(int i=0; i<max; i++){
            if(n[i] > n[i+1]){
                count += 1;
                unsigned short int tmp = n[i];
                n[i] = n[i+1];
                n[i+1] = tmp;
            }
        }
        max = max-1;
        if(max == 0) flag = 0;
    }

    return count;
}

int selection_sort(unsigned short int *n, unsigned short int N){
    int count = 0;
    int flag;

    for(int i=0; i<N-1; i++){
        int minj = i;
        for(int j=i; j<N; j++){
            if(n[j] < n[minj]){
                minj = j;
                }
            }

        if(minj != i){
            count +=1;
            unsigned int tmp = n[i];
            n[i] = n[minj];
            n[minj] = tmp;
        }
    }
    return count;
}

