	bool flag = true;
	int tmp;
	int tmpstr;
	int cnt = 0;//交換回数のカウンタ

	/*まずソートを行う前の状態を出力
	for(int k=0;k<N-1;k++){
			cout <<A[k] <<" ";
		}
		cout <<A[N-1];
		cout <<endl;
		*/

	while(flag){
		flag = false;

		//交換が一回も行われなかった場合flag = trueでforループを抜ける
		for(int j=N-1;j>0;j--){
			if(A_num[j] < A_num[j-1]){
				tmp = A_num[j];
				A_num[j] = A_num[j-1];
				A_num[j-1] = tmp;
				tmpstr = A_symbol[j];
				A_symbol[j] = A_symbol[j-1];
				A_symbol[j-1] = tmpstr;
				cnt++;
				flag = true;
			}
		}
		/*この交換後の状態を出力
		for(int k=0;k<N-1;k++){
			cout <<A[k] <<" ";
		}
		cout <<A[N-1];
		cout <<endl;
		*/
	}
	/*ソート終了後の状態を出力*/
	for(int k=0;k<N-1;k++){
			cout <<A_symbol[k] << A_num[k] <<" ";
	}
	cout <<A_symbol[N-1] <<A_num[N-1] ;
	cout <<endl;
