#include<bits/stdc++.h>
using namespace std;

void output_vector(vector<string> &A) {
  int vector_size = A.size();

  for (int i = 0; i < vector_size-1; i++) {
    cout << A.at(i) << " ";
  }
  cout << A.at(vector_size-1) << endl;
}

vector<string> BubbleSort(vector<string> C, int N) {
  bool flag = true;
  while (flag) {
    flag = false;
    for (int j = N-1; j >=1; j--) {
      if (C.at(j).at(1) < C.at(j-1).at(1)) {
        string tmpC = C.at(j);
        C.at(j) = C.at(j-1);
        C.at(j-1) = tmpC;
        flag = true;
      }
    }
  }
  return C;
}

vector<string> SelectionSort(vector<string> C, int N) {
  for (int i = 0; i < N; i++) {
    int minj = i;
    for (int j = i; j < N; j++) {
      if (C.at(j).at(1) < C.at(minj).at(1)) {
        minj = j;
      }
    }
    if (minj != i) {
      string tmpC = C.at(i);
      C.at(i) = C.at(minj);
      C.at(minj) = tmpC;
    }
  }
  return C;
}

string isStable(vector<string> C, vector<string> result, int N) {
  for (int i = 0; i < N; i++) {
    for (int j = i+1; j < N; j++) {
      for (int a = 0; a < N; a++) {
        for (int b = a+1; b < N; b++) {
          if (C.at(i).at(1) == C.at(j).at(1) &&
             C.at(i) == result.at(b) &&
             C.at(j) == result.at(a)) {
            return "Not stable";
          }
        }
      }
    }
  }
  return "Stable";
}

int main() {
  int N;
  cin >> N;
  vector<string> C(N), result(N);

  for (int i = 0; i < N; i++) cin >> C.at(i);

  result = BubbleSort(C, N);
  output_vector(result);
  cout << isStable(C, result, N) << endl;

  result = SelectionSort(C, N);
  output_vector(result);
  cout << isStable(C, result, N) << endl;

}

