struct Card{
  char suit;
  int value;
};

void bubbleSort(struct Card c[], int n)
{
  REP(i, 0, n-1){
    REPR(j, n-1, i+1){
      if(c[j-1].value > c[j].value){
        swap(c[j-1], c[j]);
      }
    }
  }
}

void selectionSort(struct Card c[], int n)
{
  REP(i, 0, n-1){
    int minj = i;
    REP(j, i, n-1){
      if(c[j].value < c[minj].value){
        minj = j;
      }
    }
    if(minj != i) swap(c[i], c[minj]);
  }
}

bool isStable(struct Card c[], struct Card c2[], int n)
{
  rep(i, n) if(c[i].suit != c2[i].suit) return false;
  return true;
}

int main(){
  struct Card c[40], c2[40];
  int n;
  cin >> n;
  rep(i, n) cin >> c[i].suit >> c[i].value;
  memcpy(c2, c, sizeof(c));

  bubbleSort(c, n);
  rep(i, n){
    if(i>0) cout << " ";
    cout << c[i].suit << c[i].value;
  }
  cout << endl;
  cout << "Stable" << endl;

  selectionSort(c2, n);
  rep(i, n){
    if(i>0) cout << " ";
    cout << c2[i].suit << c2[i].value;
  }
  cout << endl;
  cout << (isStable(c, c2, n) ? "Stable" : "Not stable") << endl;

  return 0;
}

