void buble_sort(pair<int, char> a[], int n){
    rep(i,n)for(int j=n-1;j>i;j--)if(a[j].first < a[j-1].first)swap(a[j], a[j-1]);
}

void select_sort(pair<int, char> a[], int n){
    rep(i,n){
        int minj = i;
        REP(j,i,n)if(a[j].first < a[minj].first)minj = j;
        swap(a[i], a[minj]);
    }
}

