  for ( int i = 0; i < N; i++ ){
    for ( int j = i+1; j < N; j++ ){
      for ( int a = 0; a < N; a++ ){
        for ( int b = a+1; b < N; b++ ){
          if ( in[i][1] == in[j][1] && !strcmp(in[i], out[b]) && !strcmp(in[j], out[a] ) ) return false;
        }
      }
   }
  }
  return true;
}

