#include <string>
using namespace  std;

void fnInput(vector<string> &rvsSortBbl, vector<string> &rvsSortSel)
{
  int nMaxSiz;
  cin >> nMaxSiz;

  rvsSortBbl.resize(nMaxSiz);
  rvsSortSel.resize(nMaxSiz);
  for (int i = 0; i < nMaxSiz; i++)
  {
    cin >> rvsSortBbl[i];
    rvsSortSel[i] = rvsSortBbl[i];
  }
}

void fnBubbleSort(vector<string> &rvsSortBbl)
{
  int nSorting = 0;
  bool bSorting = true;

  while (bSorting)
  {
    bSorting = false;
    for (int j = rvsSortBbl.size() - 1; j > nSorting; j--)
    {
      if (rvsSortBbl[j].at(1) < rvsSortBbl[j - 1].at(1))
      {
        swap(rvsSortBbl[j], rvsSortBbl[j - 1]);
        bSorting = true;
      }
    }
    nSorting++;
  }
}

void fnOutputBbl(const vector<string> &cnrvsSortBbl)
{
  for (int i = 0; i < cnrvsSortBbl.size(); i++)
  {
    if (i) cout << " ";
    cout << cnrvsSortBbl[i];
  }
  cout << endl;
  cout << "Stable" << endl;
}

void fnSelectionSort(vector<string> &rvsSortSel)
{
  for (int nSorting = 0; nSorting < rvsSortSel.size() - 1; nSorting++)
  {
    int nMin = nSorting;
    bool bSorting = false;
    for (int j = nSorting + 1; j < rvsSortSel.size(); j++)
    {
      if (rvsSortSel[j].at(1) < rvsSortSel[nMin].at(1))
      {
        nMin = j;
        bSorting = true;
      }
    }
    if (bSorting == true)  swap(rvsSortSel[nSorting], rvsSortSel[nMin]);
  }
}

void fnOutputSel(const vector<string> &cnrvsSortSel, const vector<string> &cnrvsSortBbl)
{
  string sSortEnd = "Stable";

  for (int i = 0; i < cnrvsSortSel.size(); i++)
  {
    if (i) cout << " ";
    cout << cnrvsSortSel[i];

    if (cnrvsSortSel[i] != cnrvsSortBbl[i]) sSortEnd = "Not stable";
  }
  cout << endl;
  cout << sSortEnd << endl;
}

int main()
{
  cin.tie(0);
  ios::sync_with_stdio(false);

  vector<string> vsSortBbl, vsSortSel;

  fnInput(vsSortBbl, vsSortSel);
  fnBubbleSort(vsSortBbl);
  fnOutputBbl(vsSortBbl); 

  fnSelectionSort(vsSortSel);
  fnOutputSel(vsSortSel, vsSortBbl);

  return 0;
}

#include <cstdio>
#include <iostream>
using namespace std;
static int N_MAX = 100;

class Pair {
public:
	int value;
	char kind;	

	bool operator==(Pair &a) {
		return (this->kind == a.kind && this->value == a.value);
	}

};

void p(Pair C[], int N) {
	for (int i = 0; i < N; ++i) {
		if (i > 0) cout << " ";
		cout << C[i].kind << C[i].value;
	}
	cout << endl;
}

void swap(Pair &a, Pair &b) {
	Pair c = a;
	a = b;
	b = c;
}


void BubbleSort(Pair C[], int N) {
	for (int i = 0; i < N; ++i)
		for (int j = N - 1; j >= i; --j)
			if (C[j].value < C[j - 1].value)
					swap(C[j], C[j-1]);
}

void SelectionSort(Pair C[], int N) {
	for (int i = 0; i < N; ++i) {
		int minj = i;
		for (int j = i; j < N; ++j)
			if (C[j].value < C[minj].value) minj = j;
		if (minj != i) {
			swap(C[i], C[minj]);
		}
	}
}

bool isStable(Pair C[], Pair D[], int N) {
	bool stable = true;
	for (int i = 0; i < N - 1; ++i) {
		int j = i + 1;
		if (C[i].value == C[j].value) {
			int k = 0, l = 0;
			for (; k < N; ++k)
				if (D[k] == C[i])
					break;
			for (; l < N; ++l)
				if (D[l] == C[j])
					break;
			if (k > l)
				return false;
		}
	}
	return true;
}

int main() {
	int N;
	Pair C[N_MAX];
	Pair D[N_MAX];
	Pair E[N_MAX];
	cin >> N;
	for (int i = 0; i < N; ++i) {
		char c;
		int d;
		cin >> c >> d;
		C[i].kind = c;
		C[i].value = d;
		D[i] = C[i];
		E[i] = C[i];
	}

	BubbleSort(D, N);
	p(D, N);
	cout << (isStable(D, C, N) ? "Stable" : "Not stable") << endl;

	SelectionSort(E, N);
	p(E, N);
	cout << (isStable(E, C, N) ? "Stable" : "Not stable") << endl;
}

