#include <bits/stdc++.h>

using namespace std;

void swap(string& card1, string& card2) {
	string tmp = card1;
	card1 = card2;
	card2 = tmp;
}

int peek_number(string card) {
	return atoi(&card[1]);
}

vector<string> bubble_sort(vector<string> cards) {
	for (int i = 0; i < cards.size(); i++) {
		for (int j = cards.size() - 1; j > i; j--) {
			if (peek_number(cards[j]) < peek_number(cards[j - 1])) swap(cards[j], cards[j - 1]);
		}
	}

	return cards;
}

vector<string> selection_sort(vector<string> cards) {
	for (int i = 0; i < cards.size(); i++) {
		int minj = i;

		for (int j = i; j < cards.size(); j++) {
			if (peek_number(cards[j]) < peek_number(cards[minj])) minj = j;
		}

		swap(cards[i], cards[minj]);
	}

	return cards;
}

bool is_stable(vector<string> unsorted, vector<string> sorted) {
	for (int i = 0; i < unsorted.size(); i++) {
		for (int j = i + 1; j < unsorted.size(); j++) {
			if (i == j || peek_number(unsorted[i]) != peek_number(unsorted[j])) continue;

			for (int sorted_i = 0; sorted_i < sorted.size(); sorted_i++) {
				if (unsorted[i] != sorted[sorted_i]) continue;

				for (int sorted_j = 0; sorted_j < sorted.size(); sorted_j++) {
					if (unsorted[j] != sorted[sorted_j]) continue;

					if ((i < j && sorted_i < sorted_j) || (i > j && sorted_i > sorted_j)) return true;
					else return false;
				}
			}
		}
	}

	return false;
}

