void trace(std::vector<Card> c) {
	for (int i = 0; i < c.size() - 1; i++)
		std::cout << c[i] << " ";
	std::cout << c[c.size() - 1] << std::endl;
}

void bubble_sort(std::vector<Card> &c) {
	for (int i = 0; i < c.size(); i++) {
		for (int j = c.size() - 1; j > i; j--) {
			if (c[j].number < c[j - 1].number)
				std::swap(c[j], c[j - 1]);
		}
	}
}

void selection_sort(std::vector<Card> &c) {
	for (int i = 0; i < c.size(); i++) {
		int min = i;
		for (int j = i; j < c.size(); j++){
			if (c[j].number < c[min].number)
				min = j;
		}
		std::swap(c[i], c[min]);
	}
}



