string isStable(int sb[], string src[], string dst[], int n){
    for(int s=0; s<n-1; s++){
        for(int t=s+1; t<n; t++){
            for(int i=0; i<n-1; i++){
                for(int j=i+1; j<n; j++){
                    if(sb[s] == sb[t] && src[s] == dst[j] && src[t] == dst[i]){
                        return "Not Stable";
                    }
                }
            }
        }
    }
    return "Stable";
}

string bubblesort(int b[], string a[], int n){
    string src[100];
    int sb[100];
    memcpy(src, a, n*sizeof(string));
    memcpy(sb, b, n*sizeof(int));
    for(int i=0; i<n; i++){
        for(int j=n-1; j>i; j--){
            if(b[j] < b[j-1]) {
                swap(b[j], b[j-1]);
                swap(a[j], a[j-1]);
            }
        }
    }
    return isStable(sb, src, a, n);
}

string selectsort(int b[], string a[], int n){
    string src[100];
    int sb[100];
    memcpy(src, a, n*sizeof(string));
    memcpy(sb, b, n*sizeof(int));
    for(int i=0; i<n; i++){
        int minj = i;
        for(int j=i+1; j<n; j++){
            if(b[j] < b[minj]) minj = j;
        }
        swap(a[i], a[minj]);
        swap(b[i], b[minj]);
    }
    return isStable(sb, src, a, n);
}
