#include<iostream>
using namespace std;
typedef struct {
	char suit, value;
}card;
void change(card* a, card* b)
{
	card c;
	c.suit = b->suit;
	c.value = b->value;
	b->suit = a->suit;
	b->value = a->value;
	a->suit = c.suit;
	a->value = c.value;
}
void BubbleSort(card* sort, int N)
{
	int i, j,flag=1;
	for (i = 0; i < N && flag == 1; i++) //flag注意不要错误，错误只会进行一次冒泡排序
	{
		flag = 0;
		for (j = N - 1; j > i; j--)
			if (sort[j - 1].value > sort[j].value)
			{
				change(&sort[j - 1], &sort[j]);
				flag = 1;
			}
	}
}
void SelectionSort(card* sort, int N)
{
	int i, j,min;
	for (i = 0; i < N; i++)
	{
		for (min = i, j = i; j < N; j++)
			if (sort[j].value < sort[min].value)
				min = j;
		if (min != i)
			change(&sort[min], &sort[i]);
	}
}
void isStable(card* in, card* out,int N) //已知冒泡排序的稳定的，只要比较排序和冒泡排序的suit就可以了
{
	int i ;
	for(i=0;i<N;i++)
		if (in[i].suit != out[i].suit)
		{
			cout << "Not stable" << endl;
			return;
		}
	cout<< "Stable" << endl;
}
