    Card cards1[n];
    Card cards2[n];

    // 入力の読み込み
    REP(i, n) cin >> cards1[i].suit >> cards1[i].value;
    // 配列をコピー
    REP(i, n) cards2[i] = cards1[i];

    bubbleSort(cards1, n);
    printCards(cards1, n);

    // バブルソートは安定ソート
    cout << "Stable" << endl;

    selectionSort(cards2, n);
    printCards(cards2, n);

    bool isStable = isSame(cards1, cards2, n);
    if (isStable){
        cout << "Stable" << endl;
    } else {
        cout << "Not stable" << endl;
    }
}

