//多重ループをうまく抜けられなかったので関数にすることに
//goto使ってもよかったんだけど、まあ・・・。
/*
stableかかを文字列で返してくれる。
引数は比較するstring配列二つと大きさN
*/

//check stable
string check_stable(string *C, string *original, int N){
	int i,j;

	j=0;
	for(i=0;i<N; i++){
		for( ; ; j++){
			if(C[i]==original[j]) break;
			if(j>=N) return "Not stable"; //最後までいったのに同じのが見つからない?＞開始探索添え字以前にある。
		}
		//今回のキモ　探索開始添え字の場合分け
		if(i<N-1 && C[i][1]==C[i+1][1]) j++;
