    vector<string> arr;
    for(int i = 0; i < 9; i++){
        string s = "";
        arr.push_back(s);
    }

    for(int i = 0; i < N; i++){
        arr[int(A[i].value - '0')].push_back(A[i].mark);
    }
    for(int i = N - 1; i >= 0 ; i--){
        if(B[i].mark != arr[B[i].value - '0'].back()){
            return false;
        }else{
            arr[B[i].value - '0'].pop_back();
        }
    }
    return true;
}

