#include<bits/stdc++.h>
using namespace std;

struct Card { char suit, value; };

void selectionSort(struct Card a[], int N) {
	for (int i = 0; i < N; i++) {
		int minj = i;
		for (int j = i; j < N; j++) {
			if (a[j].value < a[minj].value) {
				minj = j;
			}
		}
		if (a[i].value != a[minj].value) {
			swap(a[i], a[minj]);
		}
	}
}

void pri(struct Card a[], int N) {
	for (int i = 0; i < N - 1; i++) {
		cout << a[i].suit << a[i].value << " ";
	}
	cout << a[N - 1].suit << a[N - 1].value << endl;
}

void BubbleSort(Card c[], int N) {
	for (int i = 0; i < N; i++) {
		for (int j = N - 1; j > i; j--) {
			if (c[j].value < c[j - 1].value) {
				swap(c[j], c[j - 1]);
			}
		}
	}
}

bool com(Card a[], Card b[], int N) {
	for (int i = 0; i < N; i++) {
		if (a[i].suit != b[i].suit)return false;
	}
	return true;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	int N; cin >> N;
	Card a[100], b[100];
	for (int i = 0; i < N; i++) {
		cin >> a[i].suit >> a[i].value;
		b[i] = a[i];
	}
	selectionSort(a, N);
	BubbleSort(b, N);
	pri(b, N);
	cout << "Stable" << endl;
	pri(a, N);
	if (com(a, b, N)) {
		cout << "Stable" << endl;
		return 0;
	}
	cout << "Not stable" << endl;
	return 0;
}

