int main() {
  int n; //number of entries;
  cin >> n;

  vector<string> sort_vec1;

  for (int i = 0; i < n; i++) {
    string entry;
    cin >> entry;
    sort_vec1.push_back(entry);
  }

  vector<string> sort_vec2 = sort_vec1; //make copy

  //bubble sort
  for (int i = 0; i < n; i++) {
    int min_index = i; // assume min is first element
    for (int j = i+1; j < n; j++) {
      // test for minimum 
      if (stoi(sort_vec1[j].substr(1)) < stoi((sort_vec1[min_index].substr(1)))) min_index = j;
    }
    if (i != min_index) {
      swap(sort_vec1[i], sort_vec1[min_index]); //swap 
    }
  }

  for (int i = 0; i < n; i++) {
    cout << sort_vec1[i];
    if (i < n - 1) cout << " ";
  }
  cout << endl;
  cout << "Stable" << endl; // bubble sort always stable

  //selection sort
  bool unstable = false;
  for (int i = 0; i < n; i++) {
    int min_index = i; // assume min is first element
    int min_value = stoi(sort_vec2[i].substr(1)); // value at minimum
    int repeated_index = -1; // track min index of repeated value
    for (int j = i+1; j < n; j++) {
      // test for minimum
      if (stoi(sort_vec2[j].substr(1)) == min_value) {
	if (repeated_index == -1) repeated_index = j; //set min index
      }					      
      if (stoi(sort_vec2[j].substr(1)) < stoi(sort_vec2[min_index].substr(1))) min_index = j;
    }
    if (i != min_index) {
      if (min_index > repeated_index) unstable = true;
      swap(sort_vec2[i], sort_vec2[min_index]); //swap 
    }
  }

  for (int i = 0; i < n; i++) {
    cout << sort_vec2[i];
    if (i < n - 1) cout << " ";
  }
  cout << endl;

  if (unstable == true) {
    cout << "Not stable" << endl;
  } else {
    cout << "Stable" << endl;
  }

}

