// 選択ソートを実施する関数
void selectionSort(vector<string> &str, int n)
{

	//cout << "選択ソート" << endl;

	// コピーコンストラクタ
	vector<string> base_str(str);

    int count = 0;
    // 最小値の存在する配列の要素No.
    int min_pos;

    for(int i = 0; i < n - 1; i++)
    {
        min_pos = i;

        for(int j = i; j < n; j++)
        {

            if( str[j][1] < str[min_pos][1] )
            {
                // 最小値の存在する位置を保存する
                min_pos = j;
            }
        }

        if( i != min_pos )
        {
            // 最小値を交換する
            swap(str[i], str[min_pos]);

            count++;
        }
    }

    // 結果を表示する
    print_method(str, n);
    check_stable(base_str, str, n);

    return;
}

// バブルソートを実施する関数
void bubbleSort(vector<string> &str, int n)
{
	//cout << "バブルソート" << endl;

	// コピーコンストラクタ
	vector<string> base_str(str);

    int count = 0, j = 0;
    bool flag = true;

    string tmp;

    while( flag )
    {
        flag = false;

        for(int i = n - 1; i > j; i--)
        {

            if( str[i - 1][1] > str[i][1] )
            {
                // 値の入れ替え
                tmp = str[i];
                str[i] = str[i - 1];
                str[i - 1] = tmp;

                flag = true;

                // 交換回数の保存
                count++;
            }
        }

        j++;
    }

    	// 結果を表示する
    print_method(str, n);
    check_stable(base_str, str, n);

    return;
}

// 安定なソートかの判定
void check_stable( vector<string> &in, vector<string> &out, int n )
{
	bool ret = true;

	for(int i = 0; i < n; i++)
    {
        for(int j = i + 1; j < n; j++)
        {
            for(int a = 0; a < n; a++)
            {
                for(int b = a + 1; b < n; b++)
                {
                    if( in[i][1] == in[j][1]
                            && in[i] == out[b] && in[j] == out[a] )
                    {
                        ret = false;
                    }
                }
            }
        }
    }

	if(ret == true)
	{
		cout << "Stable" << endl;
	}
	else
	{
		cout << "Not stable" << endl;
	}
	return;
}

