#include<bits/stdc++.h>
using namespace std;
#define rep(i,n) for (int i=0;i<(n);i++)
#define all(v) (v).begin(),(v).end()
#define pi 3.1415926535897932384
#define E9 1000000000

void bubble_sort(vector<pair<char,int>> A, vector<pair<char,int>> &B){
  // bubble sort
  int N = A.size();
  for (int i=0;i<N;i++){
    for (int j=N-1;j>=i+1;j--){
      if (A[j].second < A[j-1].second) swap(A[j], A[j-1]);
    }
  }
  rep(i,N) B.push_back(A[i]);
  return;
}

void selection_sort(vector<pair<char,int>> A, vector<pair<char,int>> &B){
  // selection sort
  int N = A.size();
  for (int i=0;i<N;i++){
    int minj = i;
    for (int j=i;j<N;j++){
      if (A[j].second < A[minj].second) minj = j;
    }
    swap(A[i], A[minj]);
  }
  rep(i,N) B.push_back(A[i]);
  return;
}

bool is_stable(vector<pair<char,int>> A, vector<pair<char,int>> A_sorted){
  int N = A.size();
  bool stable = true;
  for (int i=0;i<N-1;i++){
    if (A[i].second == A[i+1].second){
      for (int a=0;a<N;a++){
        for (int b=a+1;b<N;b++){
          if (A[i]==A_sorted[b] && A[i+1]==A_sorted[a]){
            stable = false;
            break;
          }
        }
        if (!stable) break;
      }

    }
    if (!stable) break;

  }

  return stable;
}

