static void bsort(char c[][3], int n) {
    for (int i = 0; i < n; ++i) {
        for (int j = n - 1; j > i; --j) {
            if (c[j][1] < c[j - 1][1]) {
                std::swap(c[j], c[j - 1]);
            }
        }
    }
}
static void ssort(char c[][3], int n) {
    for (int i = 0; i < n; ++i) {
        int min = i;
        for (int j = i + 1; j < n; ++j) {
            if (c[j][1] < c[min][1]) {
                min = j;
            }
        }
        if (min > i) {
            std::swap(c[i], c[min]);
        }
    }
}
