            if( A[j].value < A[j-1].value ){
                swap(A[j], A[j-1]);
                flag = 1;
            }
    }
}

void selectionSort(card A[], const int N){
    for(int i = 0; i < N;i++){
        int minj = i;
        for(int j = i; j < N;j++){
            if(A[j].value < A[minj].value){
                minj = j;
            }
        }
        if(i != minj) swap(A[i], A[minj]);
    }
}
