#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using vi = vector<int>;
using vs = vector<string>;
using vvi = vector<vi>;
using mcq = map<char, queue<char>>;

#define rep(i, n) for (int i = 0; i < (int)(n); i++)

vs bubble_sort(vs c, int n) {
  rep(i, n - 1) 
    for (int j = n - 1; j >= i + 1; j--) 
      if (c[j][1] < c[j - 1][1]) swap(c[j], c[j - 1]);

  return c;
}

vs selection_sort(vs c, int n) {
  rep(i, n - 1) {
    int minj = i;
    for (int j = i; j < n; j++) 
      if (c[j][1] < c[minj][1]) minj = j;

    if (i != minj) swap(c[i], c[minj]);
  }

  return c;
}

void print_vec(vs c, int n) {
  rep(i, n) {
    cout << c[i];
    i != n - 1 ? (cout << " ") : (cout << endl);
  } 
}

bool is_stable(mcq orig, vs sorted) {
  for (auto i: sorted) {
    auto &q = orig[i[1]];
    if (q.size()) {
      if (q.front() == i[0]) q.pop();
      else return false;
    }
  }

  return true;
}

int main() {
  int n;
  cin >> n;

  vs c(n);
  mcq orig;
  rep(i, n) {
    cin >> c[i];
    orig[c[i][1]].push(c[i][0]);
  } 

  auto bubble = bubble_sort(c, n);
  auto selection = selection_sort(c, n);

  print_vec(bubble, n); 
  cout << (is_stable(orig, bubble) ? "Stable" : "Not stable") << endl; 
  print_vec(selection, n); 
  cout << (is_stable(orig, selection) ? "Stable" : "Not stable") << endl; 
}

