}

bool BubbleSort(vector<Card> &C,int N){
	bool stable;
	int i, j;
	for(i=0;i<N;i++){
		for(j=N-1;j>i;j--){
			if(C[j].value < C[j-1].value)
				C[j].swapCard(C[j-1]);
		}
	}
	stable = true;
	return stable;
}

bool SelectionSort(vector<Card> &C,int N){
	bool stable = true;
	int i, j, k, minj;
	for(i=0;i<N-1;i++){
		minj = i;
		for(j=i;j<N;j++){
			if(C[j].value < C[minj].value){
				minj = j;

			}
		}
		for(k=minj-1;k>=0;k--){
			if(C[minj].value == C[k].value)
				stable = false;
		}
		C[i].swapCard(C[minj]);
	}
	return stable;
}

