void selection_sort(vector< pair<int,char> >& a) {
	int nos = 0;
	int minj,size = a.size();
	for (int i = 0; i < size; ++i) {
		minj = i;
		for (int j = i; j < size; ++j) {
			if (a[j].first < a[minj].first) {
				minj = j;
			}
		}
		swap(a[i],a[minj]);
	}
	return;
}

void bubble_sort(vector< pair<int,char> >& a) {
	int size = a.size();
	bool flag = true;
	while (flag) {
		flag = false;
		for (int i = size-1; i > 0; --i) {
			if (a[i].first < a[i-1].first) {
				swap(a[i].first,a[i-1].first);
				swap(a[i].second,a[i-1].second);
				flag = true;
			}
		}
	}
	return;
}

