{

    for( int i = 0 ; i < n ; i++ )  {

        for( int j = n-1 ; j >= i+1 ; j-- )  {

            if( v[j].first < v[j-1].first )  {

                swap( v[j] , v[j-1] ) ;    

            }

        }

    }

}

