{

    for( int i = 0 ; i < n ; i++ )  {

        int mini = i ;

        for( int j = i ; j < n ; j++ )  {

            if( v[j].first < v[mini].first )  {

                mini = j ; 

            }

        }

        swap( v[i] , v[mini] ) ;  

    }

}

