struct Card{char suit, value;};

void swapCard(Card c[],int i,int j){
	Card tmp=c[i];
	c[i]=c[j];
	c[j]=tmp;
}

void bubbleSort(Card c[], int N){
	for (int i=1;i<N;i++){
		for (int j=N-1;j>=i;j--){
			if (c[j].value<c[j-1].value){
				swapCard(c,j,j-1);
			}
		}
	}
}

void selectionSort(Card c[], int N){
	for(int i=0;i<N;i++){
		int minv=c[i].value;
		int minj=i;
		for(int j=i+1;j<N;j++){
			if(c[j].value<minv){
				minv=c[j].value;
				minj=j;
			}
		}
		if(minj!=i){
			swapCard(c,i,minj);
		}
	}
}

