using namespace std;

struct Card { char suit, value; };

void bubble(vector<Card> &arr, int n) {
  for (int i = 0; i < n; i++) {
    int j=1;
    while(j<n-i){
      if(arr[j].value<arr[j-1].value){
        Card t = arr[j];
        arr[j] = arr[j - 1];
        arr[j - 1] = t;
      }
        j++;
    }
  }
  return;
}

void selectSort(vector<Card> &arr, int n) {
  for (int i = 0; i < n; i++) {
    int minIndex = i;
    for (int j = i; j < n; j++) {
      if (arr[j].value < arr[minIndex].value) {
        minIndex = j;
      }
    }
    Card t=arr[i];
    arr[i]=arr[minIndex];
    arr[minIndex]=t;
  }
  return;
}

