    for (int i = 1; i < n; i++) for (int j = n - 1; j >= i; j--) {
        if (a[j].value < a[j-1].value) {
            swap(&a[j], &a[j-1]);
        }
    }
}

void selectionSort(Card* a, int n) {
    for (int i = 0; i < n; i++) {
        int min_j = i;
        for (int j = i; j < n; j++) {
            if (a[j].value < a[min_j].value) {
                min_j = j;
            }
        }
        swap(&a[i], &a[min_j]);
    }
}

