void bubble_sort(card a[], int n) {
  bool flag = true;
  while (flag) {
    flag = false;
    for (int i = n - 1; i > 0; --i) {
      if (a[i].second < a[i - 1].second) {
        std::swap(a[i], a[i - 1]);
        flag = true;
      }
    }
  }
}

void selection_sort(card a[], int n) {
  for (int i = 0; i < n; ++i) {
    int minj = i;
    for (int j = i; j < n; ++j) {
      if (a[minj].second > a[j].second)
        minj = j;
    }
    std::swap(a[minj], a[i]);
  }
}

