void bubbleSort(std::vector<Card> &a) {
  bool flag = true;
  int count = 0;
  while (flag) {
    flag = false;
    for (int i = (int)a.size() - 1; i >= 0; i--) {
      if (a[i].num < a[i - 1].num) {
        std::swap(a[i], a[i - 1]);
        count++;
        flag = true;
      }
    }
  }
}

void selectionSort(std::vector<Card> &a) {
  int min, n = (int)a.size(), count = 0;
  for (int i = 0; i < n; i++) {
    min = i;
    for (int j = i; j < n; j++) {
      if (a[j].num < a[min].num) {
        min = j;
      }
    }
    if (i != min) {
      std::swap(a[i], a[min]);
      count++;
    }
  }
}

