#include<iostream>
#include<memory.h>
using namespace std;

bool selectionSort(char R[36][3], int N)
{
	bool isStable = true;
	for (int i = 1; i < N; i++)
	{
		char v[3];
		memcpy(v, &R[i][0], sizeof(v));

		int j = i - 1;
		while ((j >= 0) && (R[j][1] > v[1]))
		{
			memcpy(R[j + 1], R[j], sizeof(R[0]));
			j--;
		}
		memcpy(R[j + 1], v, sizeof(v));
		if (R[j + 2][1] == v[1])
		{
			isStable = false;
		}
	}
	return isStable;
}

bool bubbleSort(char R[36][3], int N)
{
	bool isStable = true;

	for (int i = 0; i < (N - 1); i++)
	{
			if (R[j - 1][1] >= R[j][1])
			{
				if (R[j - 1][1] == R[j][1]) isStable = false;
				char temp[3];
				memcpy(temp, R[j], sizeof(temp));
				memcpy(R[j], R[j - 1], sizeof(R[0]));
				memcpy(R[j - 1], temp, sizeof(R[0]));
			}
	}
	return isStable;
}

void traceData(char R[36][3], int N, bool isStable)
{
	for (int i = 0; i < N - 1; i++)
	{
		cout << R[i] << " ";
	}
	cout << R[N - 1] << endl;
	if (isStable)
	{
		cout << "Stable" << endl;
	}
	else
	{
		cout << "Not Stable" << endl;
	}
}

