	{
		cin >> CARD1[i];
	}
	memcpy(CARD2, CARD1, sizeof(CARD2));
	isStable = selectionSort(CARD1, N);
	traceData(CARD1, N, isStable);

	isStable = bubbleSort(CARD2, N);
	traceData(CARD2, N, isStable);

	return 0;
}

#include <algorithm>
