void bubbleSort(Card A[], int N)
{
	bool flag = 1;
	int  c;
	Card v;
	c = 0;

	while (flag)
	{
		flag = 0;
		for (int j = N - 1;j > 0;j--)//数列最後尾から順に逆順要素の有無確認
		{
			if (A[j].value < A[j - 1].value)//逆順要素入れ替え
			{
				v = A[j];
				A[j] = A[j - 1];
				A[j - 1] = v;
				c = c + 1;
				flag = 1;//逆順要素入れ替えした場合、flag=1にする。
			}
		}
	}
}
void selectionSort(struct Card A[], int N)
{
	int minj;
	Card v;
	int c = 0;

	for (int i = 0;i < N;i++)
	{
		minj = i;

		for (int j = i; j<N;j++)//未整列の領域（iからn-1）から最小値検索
		{
			if (A[j].value < A[minj].value)
			{
				minj = j;
			}
		}
		v = A[i];
		A[i] = A[minj];
		A[minj] = v;
		if (i != minj)c = c + 1;
	}
}

