}

bool isStable(struct Card in[], struct Card out[], int N)
{
	for (int i = 0; i < N; i++)
	{
		for (int j = i + 1; j < N; j++)
		{
			for (int a = 0; a < N; a++)
			{
				for (int b = a + 1; b < N; b++)
				{
					if (in[i].value == in[j].value && DataEqual(&in[i],&out[b]) && DataEqual(&in[j], &out[a]))
					{
						return false;
					}
				}
			}
		}
	}
	return true;
}

bool DataEqual(struct Card* in, struct Card* out)
{
	return in->value == out->value && in->suit == out->suit;
}

