                Swap(v[j], v[j - 1]);
            }
        }
    }

    return v;
}

vector<card> SelectionSort(vector<card> v) {
    int mini;
    for (int i = 0; i < v.size(); ++i) {
        mini = i;
        for (int j = i + 1; j < v.size(); ++j) {
            if (v[j].second < v[mini].second)
                mini = j;
        }
        Swap(v[mini], v[i]);
    }

    return v;
}

