void c_3_3() {
	int n;
	bool flag;
	int count;

	cin >> n;
	// int price[n];
	vector<int> a(n);
	REPEAT(i, n) {
		cin >> a[i];
	}

	flag = true;
	count = 0;
	for (int i = 0; flag; i++) {
		flag = false;
		DECFOR(j, n - 1, i) {
			if (a[j] >= a[j - 1]) {
				continue;
			}
			const auto v = a[j];
			a[j] = a[j - 1];
			a[j - 1] = v;
			flag = true;
			++count;
		}
	}
	REPEAT(k, a.size()) {
		cout << (k ? " " : "") << a[k];
	}
	cout << endl;
	cout << count << endl;
	// 初解と正解との違い: 交換と非交換を繰り返して出会った一番小さい要素を移動させているという理解が欠如していた
	// よって動作的には正しいが無駄な部分を走査していた
	// swap関数があるのを知らなかった
}

