vector<string> BubbleSort(vector<string> s) {
	for (int i = 0; i < s.size(); ++i) {
		for (int k = s.size() - 1; k > i; --k) {
			if ((s[k])[1] < (s[k - 1])[1])		swap(s[k], s[k - 1]);
		}
	}
	return s;
}

vector<string> SelectionSort(vector<string> s) {
	int mink;
	for (int i = 0; i < s.size(); ++i) {
		mink = i;
		for (int k = i; k < s.size(); ++k)
			if ((s[k])[1] < (s[mink])[1])		mink = k;
		swap(s[i], s[mink]);
	}
	return s;
}

