	bool flag = true;
	int i = 0;
	while (flag){
		flag = false;
		for (int j = size - 1; j > i; j--) {
			if (cards[j].value < cards[j - 1].value) {
				Card c = cards[j]; cards[j] = cards[j-1]; cards[j-1] = c;
				flag = true;
			}
		}
		i++;
	}
}

