	BubbleSort(copycard, N);//バブルソート
	ResultOutput(copycard, N);//結果出力

	//安定判定
	if (IsStable(copycard, N)) {
		cout << "Stable" << endl;
	}
	else {
		cout << "Not Stable" << endl;
	}

	//もう一度コピー
	Copy(copycard, card, N);

	SelectSort(copycard, N);//選択ソート

	ResultOutput(copycard, N);

	//安定判定
	if (IsStable(copycard, N)) {
		cout << "Stable" << endl;
	}
	else {
		cout << "Not Stable" << endl;
	}

	return 0;
}

