void bubble(vector<string> &a) {
    for (int i = 0; i < a.size(); i++) {
        for (int o = a.size() - 1; o > i; o--) {
            if (a[o][1] < a[o - 1][1]) swap (a[o][1], a[o - 1][1]);
        }
    }
}

void select(vector<string> &b) {
    for (int i = 0; i < b.size(); i++) {
        int mini = i;
        for (int j = i; j < b.size(); j++) {
            if (b[j][1] < b[mini][1]) mini = j;
        }
        if (i < mini) swap (b[i], b[mini]);
    }
}

