bublesort(unsigned char d[][2], n)
{
	unsigned int num = 0;

	bool flag = true;
	while (flag) {
		flag = false;
		for (unsigned int i = n-1; i > 0; --i) {
			if (d[i][1] < d[i-1][1]) {
				char x = d[i-1][1];
				char y = d[i-1][0];
				d[i-1][0] = d[i][0];
				d[i-1][1] = d[i][1];
				d[i][0] = y;
				d[i][1] = x;
				flag = true;
				++num;
			}
		}
	}

	return num;
}

unsigned int selectionsort(unsigned char d[][2], n)
{
	unsigned int num = 0;
	for (unsigned int i = 0; i < n; ++i) {
		unsigned int minj = i;
		for (unsigned int j = i+1; j < n; ++j) {
			if (d[j][1] < d[minj][1]) {
				minj = j;
			}
		}
		if (i != minj) {
			char s = d[i][0];
			char t = d[i][1];
			d[i][0] = d[minj][0];
			d[i][1] = d[minj][1];
			d[minj][0] = s;
			d[minj][1] = t;
			++num;
		}
	}

	return num;
}

