void bubbleSort(string A[], int N) {
    int flag = true;
    int count = 0, i = 0;
    while (flag) {
        flag = false;
        for (int j = N - 1; j >= i + 1; j--) {
            if (A[j][1] < A[j - 1][1]) {
                swap(A[j], A[j - 1]);
                count++;
                flag = true;
            }
        }
        i++;
    }
    print(A, N);
    //cout << count << "\n";

}

