    int count = 0;
    int i = 0;
    while(flag){
        flag = 0;
        for(int j = N -1; j > i; j--){
            if(A[j].value < A[j-1].value){
                struct Card tmp = A[j];
                A[j] = A[j-1];
                A[j-1] = tmp;
                flag = 1;
                count++;
            }
        }
        i++;
    }
