void bubbleSort(cards C[], int N)
{
    for (int i = 0; i < N; i++) {
        for (int j = N - 1; j >= i + 1; j--)
            if (C[j].getNum() < C[j - 1].getNum())
                swap(C[j], C[j - 1]);
    }
}

void selectionSort(cards C[], int N)
{
    for (int i = 0; i < N; i++) {
        int min = i;
        for (int j = i; j < N; j++)
            if (C[j].getNum() < C[min].getNum())
                min = j;
        swap(C[i], C[min]);
    }
}

