void Swap(card &a, card &b) {
    card temp = a;
    a = b;
    b = temp;
}
void BubbleSort(card cards[],int N) {
    for(int i=0; i<N; i++) {
        for(int j=N-1; j>i; j--) {
            if(cards[j].value<cards[j-1].value)Swap(cards[j],cards[j-1]);
        }
    }
}
void SelectionSort(card cards[], int N) {
    for(int i=0; i<N; i++) {
        int minj = i;
        for(int j=i+1; j<N; j++) {
            if(cards[j].value<cards[minj].value)minj = j;
        }
        Swap(cards[i],cards[minj]);
    }
}

