using namespace std;

struct Card {
  char suit;
  int value;
};

void trace(const vector<Card>& a) {
  for (int i = 0; i < a.size(); i++) {
    cout << a[i].suit << a[i].value << ((i != a.size() - 1)? " " : "");
  }
  cout << endl;
}

bool is_stable(const vector<Card>& in, const vector<Card>& out) {
  deque<Card> dep;
  for (size_t i = 0; i < out.size() - 1; i++) {
    if (dep.size() != 0 && out[i].value == dep.front().value) {
      dep.push_back(out[i]);
      continue;
    }
    if (out[i].value == out[i + 1].value) {
      dep.push_front(out[i]);
      continue;
    }
  }
  for (size_t i = 0; i < in.size() - 1; i++) {
    if (in[i].value == dep.front().value) {
      if (in[i].suit != dep.front().suit) return false;
      dep.pop_front();
    }
  }
  return true;
}

vector<Card> bubble_sort(vector<Card> c, int n) {
  for (int i = 0; i < n; i++) {
    for (int j = n - 1; j > i; j--) {
      if (c[j].value < c[j - 1].value) swap(c[j], c[j - 1]);
    }
  }
  return c;
}

vector<Card> selection_sort(vector<Card> c, int n) {
  for (int i = 0; i < n; i++) {
    int minj = i;
    for (int j = i; j < n; j++) {
      if (c[j].value < c[minj].value) minj = j;
    }
    swap(c[i], c[minj]);
  }
  return c;
}

int main() {
  int n;
  cin >> n;
  vector<Card> v(n);
  for (int i = 0; i < n; i++) {
    string s;
    cin >> s;
    v[i].suit = s[0];
    v[i].value = s[1] - '0';
  }
  auto v1 = bubble_sort(v, n);
  trace(v1);
  if (is_stable(v, v1)) cout << "Stable" << endl;
  else cout << "Not stable" << endl;
  auto v2 = selection_sort(v, n);
  trace(v2);
  if (is_stable(v, v2)) cout << "Stable" << endl;
  else cout << "Not stable" << endl;
}

