        for ( int j = i + 1; j < n; j++ ) {
            if ( card[minj].value > card[j].value ) {
                minj = j;
            }
        }
        if ( card[i].value > card[minj].value ) {
            std::swap(card[i], card[minj]);
        }
    }
}

