using namespace std;

bool isstable(char *c1, char *c2, int n) {
    bool flag = true;
    for (int i = 0; i < n; i++) {
        if (c1[i] != c2[i]) {
            flag = false;
            break;
        }
    }

    return flag;
}

void bubble(int *a, char *c, int n) {
    for (int i = 0; i < n; i++) {
        int j = n - 1;
        while (j > i) {
            if (a[j] < a[j - 1]) {
                swap(a[j], a[j - 1]);
                swap(c[j], c[j - 1]);
            }
            j--;
        }
    }
}

void selection(int *a, char *c, int n) {
    for (int i = 0; i < n; i++) {
        int minj = i;
        int mina = a[i];
        for (int j = i; j < n; j++) {
            if (a[j] < mina) {
                minj = j;
                mina = a[j];
            }
        }
        swap(a[i], a[minj]);
        swap(c[i], c[minj]);
    }
}

