void bubble_sort(string* cards, int length) {
    for (int i = 0; i < length; ++i) {
        for (int j = length - 1; j >= i + 1; --j) {
            if (cards[j - 1][1] > cards[j][1]) swap(cards[j - 1], cards[j]);
        }
    }
}

void selection_sort(string* cards, int length) {
    for (int i = 0; i < length; ++i) {
        int min_idx = i;
        for (int j = i + 1; j < length; ++j) {
            if (cards[j][1] < cards[min_idx][1]) min_idx = j;
        }
        if (i != min_idx) swap(cards[i], cards[min_idx]);
    }
}

