// sort "intput" by bubble sort
// then put the result into "output"
void bubble_sort(string *input, string *output)
{
    // copy input to output
    rep(i,n) output[i] = input[i];
    // execute bubble sort
    rep(i,n) for(int j = n-1; j > i; j--)
        if(compare(output[j], output[j-1]))
            swap(output[j], output[j-1]);
    return;
}

// sort "intput" by selection sort
// then put the result into "output"
void selection_sort(string *input, string *output)
{
    // copy input to output
    rep(i,n) output[i] = input[i];
    // execute selection sort
    rep(i,n){
        int min = i;
        for(int j = i; j < n; j++)
            if(compare(output[j],output[min])) 
                min = j;
        swap(output[i], output[min]);
    }
    return;
}

