void BubbleSort(vector<string> &C, int N) {
	for (int i = 0;i < N - 1;i++) {
		for (int j = N - 1;j > i;j--) {
			if ((int)C[j-1][1] > (int)C[j][1]) {
				string tmp = C[j];
				C[j] = C[j - 1];
				C[j - 1] = tmp;
			}
		}
	}
}

void SelectionSort(vector<string> &C, int N) {
	for (int i = 0;i < N - 1;i++) {
		int minj = i;
		for (int j = i + 1;j < N;j++) {
			if ((int)C[minj][1] > (int)C[j][1]) minj = j;
		}
		if (minj != i) {
			string tmp = C[minj];
			C[minj] = C[i];
			C[i] = tmp;
		}
	}
}

