struct Card {
    char suit, value;  // 数字はvalueのままで比較できる
};

void BubbleSort(vector<string> &vec) {
    /*
     * 右端から隣の要素を比較して、
     * 左が大きかったら入れ替え
     * １周するとソート済みの数字が左端に1つ追加される
     */
    // prepare int_vec
    int N = vec.size();
    vector<int> int_vec(vec.size());
    REP(i, vec.size()) int_vec.at(i) = ctoi(vec.at(i).at(1));

    // BubbleSort
    REP(i, vec.size()) {
        for (int j = vec.size() - 1; i < j; --j) {
            if (int_vec.at(j-1) > int_vec.at(j)) {
                swap(int_vec.at(j-1), int_vec.at(j));
                swap(vec.at(j-1), vec.at(j));
            }
        }
    }
}

void SelectionSort(vector<string> &vec) {
    int N = vec.size();

    // prepare int_vec
    vector<int> int_vec(N);
    REP(i, N) int_vec.at(i) = ctoi(vec.at(i).at(1));

    // SelectionSort
    REP(i, N) {
        int min_idx = i;
        for (int j = i + 1; j < N; j++) {
            if (int_vec.at(min_idx) > int_vec.at(j)) {
                // 等しいときは動かさない
                min_idx = j;
            }
        }
        // ここまでで最小値のインデックスを得られる
        // ループの最後に左端と最小値を入れ替える
        swap(int_vec.at(i), int_vec.at(min_idx));
        swap(vec.at(i), vec.at(min_idx));
    }

}

bool isStable(vector<string> vec_bub, vector<string> vec2) {
    int N = vec_bub.size();
    // 構造体の配列
    Card cards_bub[N], cards2[N];
    REP(i, N) {
        // vec_bub
        cards_bub[i].suit = vec_bub.at(i).at(0);
        cards_bub[i].value = vec_bub.at(i).at(1);
        // vec2
        cards2[i].suit = vec2.at(i).at(0);
        cards2[i].value = vec2.at(i).at(1);
    }

    // 判定
    // バブルソートは常に安定なソートであるため
    // それを基準にする
    for (int i = 0; i < N; ++i) {
        if (cards_bub[i].suit != cards2[i].suit) return false;
    }
    return true;
}


int main() {
    // input
    int N;
    cin >> N;
    vector<string> vec_start(N), vec_bub, vec_sel;
    REP(i, N) cin >> vec_start.at(i);
    COPY(vec_start, vec_bub);
    COPY(vec_bub, vec_sel);

    // calculation
    BubbleSort(vec_bub);
    SelectionSort(vec_sel);

    // output
    printVec(vec_bub);
    cout << "Stable" << endl;
    printVec(vec_sel);
    if (isStable(vec_bub, vec_sel)) {
        cout << "Stable" << endl;
    } else {
        cout << "Not stable" << endl;
    }
    return 0;
}


