using namespace std;
#define rep(i, n) for (int i = 0; i < (n); i++)

struct Card {
  char suit;
  int value;
};

void selectionSort(vector<Card> &cards) {
  rep(i, cards.size() - 1) {
    int minj = i;
    for (int j = i; j < cards.size(); j++) {
      if (cards[j].value < cards[minj].value) minj = j;
    }
    if (minj != i) swap(cards[minj], cards[i]);
  }
}

void bubbleSort(vector<Card> &cards) {
  bool flag = true;
  while (flag) {
    flag = false;
    for (int i = cards.size() - 1; i > 0; i--) {
      if (cards[i].value < cards[i - 1].value) {
        swap(cards[i], cards[i - 1]);
        flag = true;
      }
    }
  }
}

void buildKeymap(vector<Card> cards, map<int, vector<char> > &keymap) {
  rep(i, cards.size()) keymap[cards[i].value].push_back(cards[i].suit);
}

bool isStable(vector<Card> sorted_cards, vector<Card> org_cards) {
  map<int, vector<char> > org_keymap, sorted_keymap;
  buildKeymap(org_cards, org_keymap);
  buildKeymap(sorted_cards, sorted_keymap);

  bool flag_stable = true;
  for (map<int, vector<char> >::iterator itr = org_keymap.begin();
       itr != org_keymap.end(); itr++) {
    int v = itr->first;
    rep(i, org_keymap[v].size()) {
      if (org_keymap[v][i] != sorted_keymap[v][i]) {
        flag_stable = false;
        break;
      }
    }
    if (!flag_stable) break;
  }
  return flag_stable;
}

void print_cards(vector<Card> cards) {
  rep(i, cards.size()) {
    if (i > 0) cout << " ";
    cout << cards[i].suit << cards[i].value;
  }
  cout << endl;
}

void print_is_stable(bool is_stable) {
  if (is_stable)
    cout << "Stable" << endl;
  else
    cout << "Not stable" << endl;
}

int main() {
  int n;
  cin >> n;
  vector<Card> org_cards(n), cards1(n), cards2(n);
  rep(i, n) cin >> org_cards[i].suit >> org_cards[i].value;
  rep(i, n) {
    cards1[i].suit = org_cards[i].suit;
    cards1[i].value = org_cards[i].value;
    cards2[i].suit = org_cards[i].suit;
    cards2[i].value = org_cards[i].value;
  }

  bubbleSort(cards1);
  bool is_stable_bubble = isStable(cards1, org_cards);
  print_cards(cards1);
  print_is_stable(is_stable_bubble);

  selectionSort(cards2);
  bool is_stable_selection = isStable(cards2, org_cards);
  print_cards(cards2);
  print_is_stable(is_stable_selection);

  return 0;
}

