void BubbleSort(int c[100], char d[100], int N){
    bool flag = true;
    while(flag){
        flag = false;
        for(int i = N - 1; i > 0; i--){
            if(c[i] < c[i - 1]){
                swap(c[i], c[i - 1]);
                swap(d[i], d[i - 1]);
                flag = true;
            }
        }
    }
    return;
}

void SelectionSort(int c[100], char d[100], int N){
    for(int i = 0; i < N; i++){
        int minj = i;
        for(int j = i; j < N; j++){
            if(c[minj] > c[j]){
                minj = j;
            }
        }
        if(minj != i){
            swap(c[minj], c[i]);
            swap(d[minj], d[i]);
        }
    }
    return;
}

