#include<iostream>
#include<cstdio>
#include<cmath>
using namespace std;

struct Card {
    char suit, value;
};
// 冒泡排序法
void bubble(struct Card A[], int n) {
    // 标记是否需要继续冒泡
    int flag = 1;
    for (int i = 0; flag; i++) {
        flag = 0;
        for (int j = n - 1; j >= i + 1; j--) {
            // 交换两个相邻的元素
            if (A[j].value < A[j - 1].value) {
                swap(A[j], A[j - 1]);
                flag = 1;
            }
        }
    }
}
// 选择排序法
void selection(struct Card A[], int n) {
    for (int i = 0; i < n; i++) {
        int minj = i;
        for (int j = i; j < n; j++) {
            if (A[j].value < A[minj].value)
                minj = j;
        }
        if (i != minj)
            swap(A[i], A[minj]);
    }
}
// 冒泡排序法是稳定排序，选择排序后的花色和其比较则可得知排序是否稳定的
bool isStable(struct Card C1[], struct Card C2[], int n) {
    for (int i = 0; i < n; i++) {
        if (C1[i].suit != C2[i].suit)
            return false;
    }
    return true;
}
// 打印输出
void print(struct Card C[], int n) {
    for (int i = 0; i < n; i++) {
        printf("%c%c%c", C[i].suit, C[i].value, i == n - 1 ? '\n' : ' ');
    }
}
int main() {
    Card C1[100], C2[100];
    int n;

    scanf("%d", &n);
    getchar();
    for (int i = 0; i < n; i++) {
        scanf("%c%c", &C1[i].suit, &C1[i].value);
        getchar();
        C2[i] = C1[i];
    }
    // 对于C1数列进行冒泡排序，对C2数列进行选择排序，然后比较两者排序后的花色
    // 则可得知选择排序是否稳定
    bubble(C1, n);
    selection(C2, n);

    print(C1, n);
    printf("Stable\n");
    print(C2, n);
    if (isStable(C1, C2, n))
        printf("Stable\n");
    else
        printf("Not stable\n");

    return 0;
}

#include "stdio.h"
#include <iostream>

using namespace std;

static int MAX_N = 36;

struct Card {
	char suit;
	int value;
};

void bubbleSort(int n, Card* cardList) {
	//       	   n - 1
	int flag = 1;
	for(int i = 0; flag; i ++) {
		flag = 0;
		for(int j = n - 1; j >= i; j --) {
			if(cardList[j].value < cardList[j - 1].value) {
				Card temp = cardList[j - 1];
				cardList[j - 1] = cardList[j];
				cardList[j] = temp;
				flag = 1;
			}
		}
	}
}

void selectionSort(int n, Card* cardList) {

	for(int i = 0; i < n - 1; i ++) {
		int minIndex = i;
		for(int j = i + 1; j < n; j ++) {
			if(cardList[j].value < cardList[minIndex].value) {
				minIndex = j;
			}
		}
		if(minIndex != i) {
			Card temp = cardList[i];
			cardList[i] = cardList[minIndex];
			cardList[minIndex] = temp;
		}

	}

}

bool isStable(Card* cardListA, Card* cardListB, int n) {
	for(int i = 0; i < n; i ++) {
		if(cardListB[i].suit != cardListA[i].suit) {
			return false;
		}
	}
	return true;
}

void print(struct Card cardList[], int n) {
	for(int i = 0; i < n; i ++) {
		if(i > 0) 
			printf(" ");
		printf("%c%d", cardList[i].suit, cardList[i].value);
	}
	printf("\n");
}

int main() {
	int n;
	Card cardList[MAX_N];
	Card cardListA[MAX_N];
	Card cardListB[MAX_N];

	scanf("%d", &n);
	getchar();
	for(int i = 0; i < n - 1; i ++) {
		scanf("%c%d ", &cardList[i].suit, &cardList[i].value);
	}
	scanf("%c%d", &cardList[n - 1].suit, &cardList[n - 1].value);

	for(int i = 0; i < n; i ++) {
		cardListA[i] = cardList[i];
		cardListB[i] = cardList[i];
	}

	bubbleSort(n, cardListA);
	print(cardListA, n);
	printf("Stable\n");

	selectionSort(n, cardListB);
	print(cardListB, n);
	bool flag = isStable(cardListA, cardListB, n);
	if(!flag) {
		printf("Not stable\n");
	} else {
		printf("Stable\n");
	}
}

