int cmp(void *x, void *y)
{
    return ((char *)y)[1] - ((char *)x)[1];
}

void print_array(char (*A)[3], u32 N)
{
    rep (i, N)
    {
        if (i)
        {
            cout << " ";
        }
        cout << A[i];
    }
    cout << "\n";
}

void bubbleSort(void *A, u32 N, int (*comp)(void *, void *))
{
    char (*a)[3] = (char (*)[3])A;
    bool flag = true;
    for (int i = 0; flag; ++i)
    {
        flag = false;
        for (int j = N - 1; j > i; --j)
        {
            if ((*comp)((void *)a[j], (void *)a[j - 1]) > 0)
            {
                swap(*(a + j), *(a + j - 1));
                flag = true;
            }
        }
    }
}

void selectionSort(void *A, u32 N, int (*comp)(void *, void *))
{
    char (*a)[3] = (char (*)[3])A;
    rep (i, N)
    {
        int minj = i;
        for (int j = i; j < N; ++j)
        {
            if ((*comp)((void*)a[j], (void *)a[minj]) > 0)
            {
                minj = j;
            }
        }
        if (minj != i)
        {
            swap(*(a + i), *(a + minj));
        }
    }
}

int checkStable(char (*A)[3], char (*B)[3], u32 N)
{
    rep (i, N)
    {
        if (strcmp(A[i], B[i]))
        {
            return 1;
        }
    }
    return 0;
}

