int BubbleSort(Card A[],int n)
{
  int i,j;
  Card temp;

  for(i=0;i < n;i++){
    for(j=n-1;j > i;j--){
      if(A[j-1].num > A[j].num){
	temp = A[j-1];
	A[j-1] = A[j];
	A[j] = temp;
      }
    }
  }
  return 0; 
}

int SelectionSort(Card A[],int n)
{
  int i,j;

  int mini;
  Card temp;

  for(i=0;i < n;i++){
    mini = i;

    for(j = i+1;j < n;j++){
      if(A[j].num < A[mini].num) mini = j;
    }

    temp = A[mini];
    A[mini] = A[i];
    A[i] = temp;
  }
  return 0; 
}

