}

void bubble_sort(vector<P>& a){
    bool flag = true;
    for(ll i = 0; flag; ++i){
        flag = false;
        for(ll j = a.size() - 1; j > i; --j){
            if(a.at(j).first < a.at(j - 1).first){
                swap(a.at(j), a.at(j - 1));
                flag = true;
            }
        }
    }
}

void selection_sort(vector<P>& a){
    ll count = 0;
    for(ll i = 0; i < a.size(); ++i){
        ll minj = i;
        for(ll j = i + 1; j < a.size(); ++j){
            if(a.at(j).first < a.at(minj).first){
                minj = j;
            }
        }
        swap(a.at(i), a.at(minj));
    }
}

