void bubble_sort(card *array, int n){
	for(int i = n-1; i > 0; --i){
		bool is_swaped = false;
		for(int j = 0; j < i; ++j){
			if(array[j].value > array[j+1].value){
				swap(array[j], array[j+1]);
				is_swaped = true;
			}
		}
		if(!is_swaped){
			return;
		}
	}
}
void selection_sort(card *array, int n){
	for(int i = 0; i < n; ++i){
		bool is_swaped = false;
		int minj = i;
		for(int j = i; j < n; ++j){
			if(array[j].value < array[minj].value){
				minj = j;
				is_swaped = true;
			}
		}
		if(is_swaped){
			swap(array[i], array[minj]);
		}
	}
}

