		return  (num == right.num) && (mark == right.mark);
	}


};

template<typename T>
int bubbleSort(list<T>&arr) {
	int cunt = 0;
	bool cont = true;
	int n = arr.size();
	while (cont)
	{
		typename	list<T>::iterator it1 = arr.begin(), it2 = arr.begin();
		advance(it2, 1);
		cont = false;
		for (int i = 1; i < n; ++i, advance(it1, 1), advance(it2, 1))
		{
			if ( *it2 < *it1 ) {
				swap(*it1, *it2);
				cont = true;
				cunt++;
			}
		}
	}
	return cunt;
}

template <typename T>
int selectionSort(list<T>& arr) {
	int cunt = 0;
	int n = arr.size();
	typename list<T>::iterator it1, it2, min, itend = arr.end();
	for (it1 = arr.begin(); it1 != itend; advance(it1, 1))
	{
		min = it1;
		for (it2 = next(it1); it2 != itend; advance(it2, 1))
		{
			if (*it2 < *min)
				min = it2;
		}
		if (it1 != min) {
			cunt++;
			swap(*it1, *min);
		}
	}
	return cunt;	
}

