#include <iostream>
using namespace std;

struct Card {
    char value;
    char suit;
};

void swap(struct Card a[], int i, int j) {
    Card tmp = a[i];
    a[i] = a[j];
    a[j] = tmp;
}

void bubbleSort(struct Card a[], int n, int &ans) {
    for (int i = 0; i < n; ++i) {
        for (int j = n - 1; i - 1 < j; --j) {
            if (a[j].value < a[j - 1].value) {
                swap(a, j, j - 1);
            }
        }
    }
}

void selectionSort(struct Card a[], int n, int &ans) {
    for (int i = 0; i < n; ++i) {
        int minj = i;
        for (int j = i; j < n; ++j) {
            if (a[j].value < a[minj].value) minj = j;
        }
        swap(a, i, minj);
        if (i == minj) ++ans;
    }
}

void print(int ans) {
    if (ans % 2 == 0) {
        cout << "Stable" << endl;
    } else {
        cout << "Not stable" << endl;
    }
}

