template< typename iterator >
void bubble_sort(iterator first, iterator last)
{
    using std::swap ;
    bool flag = 1 ;
    while(flag)
    {
        flag = 0 ;
        for(iterator iter = last-1 ; iter != first ; --iter)
        {
            if(*iter < *(iter-1))
            {
                swap(*iter, *(iter-1)) ;
                flag = 1 ;
            }
        }
    }
}

template< typename iterator >
void selection_sort(iterator first, iterator last)
{
    using std::swap ;
    for(iterator iter1 = first ; iter1 != last ; ++iter1)
    {
        iterator min_iter = iter1 ;
        for(iterator iter2 = iter1 ; iter2 != last ; ++iter2)
        {
            if(*min_iter > *iter2)
            {
                min_iter = iter2 ;
            }
        }
        swap(*iter1 , *min_iter) ;
    }
}

