            if(C[j].value < C[j-1].value) {
                swap(C[j], C[j-1]);
            }
        }
    }
}

void SelectionSort(Card C[], int N) {
    for(int i = 0; i < N; i++) {
        int mini = i;
        for (int j = i; j < N; j++) {
            if(C[mini].value > C[j].value) mini = j;
        }
        if(i != mini) {
            swap(C[i], C[mini]);
        }
    }
}

