using namespace std;

int peek_number(string card) {
	return atoi(&card[1]);
}

vector<string> bubble_sort(vector<string> cards) {
	for (int i = 0; i < cards.size(); i++) {
		for (int j = cards.size() - 1; j >= 0; j--) {
			if (peek_number(cards[j]) < peek_number(cards[j - 1])) {
				string tmp = cards[j];
				cards[j] = cards[j - 1];
				cards[j - 1] = tmp;
			}
		}
	}

	return cards;
}

vector<string> selection_sort(vector<string> cards) {
	for (int i = 0; i < cards.size(); i++) {
		int min_idx = i;

		for (int j = i; j < cards.size(); j++) {
			if (peek_number(cards[j]) < peek_number(cards[min_idx])) {
				min_idx = j;
			}
		}

		string tmp = cards[i];
		cards[i] = cards[min_idx];
		cards[min_idx] = tmp;
	}

	return cards;
}

int index_of(vector<string> v, string target) {
	for (int i = 0; i < v.size(); i++) {
		if (v[i] == target) {
			return i;
		}
	}

	return -1;
}

