void print_array(int N, std::pair<char, int> *array)
{
    for (int i = 0; i < N - 1; i++)
        std::cout << array[i].first << array[i].second << " ";
    std::cout << array[N - 1].first << array[N - 1].second << std::endl;
}

void copy(int N, std::pair<char, int> *source, std::pair<char, int> *destination)
{
    for (int i = 0; i < N; i++)
        destination[i] = source[i];
}

void bubble_sort(int N, std::pair<char, int> *array)
{
    for (int i = 0; i < N; i++)
    {
        for (int j = N - 1; j > i; j--)
        {
            if (array[j].second < array[j - 1].second)
            {
                std::swap(array[j], array[j - 1]);
            }
        }
    }
}

int selection_sort(int N, std::pair<char, int> *array)
{
    for (int i = 0; i < N; i++)
    {
        int minj = i;
        for (int j = i; j < N; j++)
        {
            if (array[j].second < array[minj].second)
                minj = j;
        }
        if (i != minj)
        {
            std::swap(array[i], array[minj]);
        }
    }
}

bool isStable(int N, std::pair<char, int> *stable, std::pair<char, int> *unknown)
{
    bool flag = true;
    for (int i = 0; i < N; i++)
    {
        if (stable[i].first != unknown[i].first)
        {
            flag = false;
            break;
        }
    }
    return flag;
}

