  if (s1[1] > s2[1]) return 1;
  return -1;
}

void bubble_sort(vector<string> &arr)
{
  for (int i = 0; i < arr.size(); i++) {
    for (int j = arr.size()-1; j > i; j--) {
      if (cmp(arr[j], arr[j-1]) < 0) {
        swap(arr[j], arr[j-1]);
      }
    }
  }
}

void selection_sort(vector<string> &arr)
{
  for (int i = 0; i < arr.size(); i++) {
    int min_i = i;
    for (int j = i; j < arr.size(); j++) {
      if (cmp(arr[j], arr[min_i]) < 0) {
        min_i = j;
      }
    }
    swap(arr[i], arr[min_i]);
  }
}

bool is_stable(vector<string> &original, vector<string> &sorted)
{
  for (int i1 = 0; i1 < sorted.size()-1; i1++) {
    for (int i2 = i1+1; i2 < sorted.size(); i2++) {
      if (cmp(sorted[i1], sorted[i2]) != 0)
        continue;
      for (int j1 = 0; j1 < original.size()-1; j1++) {
        for (int j2 = j1+1; j2 < original.size(); j2++) {
          if (cmp(original[j1], original[j2]) != 0)
            continue;
          if (sorted[i1] == original[j2] && sorted[i2] == original[j1])
            return false;
        }
      }
    }
  }
  return true;
}

