void doBubbleSort(Card *a, size_t size)
{
    bool flag = true;
    for (size_t i = 0; flag; ++i)
    {
        flag = false;
        for (size_t j = size - 1; j > i; --j)
        {
            if (a[j].number < a[j - 1].number)
            {
                swap(a[j], a[j - 1]);
                flag = true;
            }
        }
    }
}

void doSelectionSort(Card *a, size_t size)
{
    for (size_t i = 0; i < size; ++i)
    {
        size_t minj = i;
        for (size_t j = i; j < size; ++j)
        {
            if (a[j].number < a[minj].number)
            {
                minj = j;
            }
        }
        if (i != minj)
        {
            swap(a[i], a[minj]);
        }
    }
}

