vector<pair<char, char>> bubbleSort(vector<pair<char, char>> data, int N){
    int count = 0;
    for(int j = 0; j < N - 1; j++){
        for(int i = N - 1; i > j; i--){
            if(data.at(i).second < data.at(i - 1).second){
                swap(data.at(i), data.at(i - 1));
                count++;
            }
        }
    }

    rep(i, N){
        cout << data.at(i).first << data.at(i).second;
        if(i < N - 1) cout << ' ';
    }

    cout << endl;
    cout << "Stable" << endl;
    return data;
}

vector<pair<char, char>> selectionSort(vector<pair<char, char>> data, int N){
    int count = 0;
    int min_i;

    for (int i = 0; i < N; i++)
    {
        int min = 101;
        for(int j = i; j < N; j++){
            if(data.at(j).second < min){
                min_i = j;
                min = data.at(j).second;
            }
        }
        if(i != min_i){
            swap(data.at(i), data.at(min_i));
            count++;
        }
    }

    rep(i, N){
        cout << data.at(i).first << data.at(i).second;
        if(i < N - 1) cout << ' ';
    }
    cout << endl;
    return data;
}

