void bubble(vector<pair<char,int> > &v,int n){
    for(int i=0;i<n;i++){
        for(int j=0;j<n-i-1;j++){
            if(v[j].second>v[j+1].second)swap(v[j],v[j+1]);
        }
    }
}

void select(vector<pair<char,int> > &v,int n){
    for(int i=0;i<n;i++){
        int mij=i,mi=v[i].second;
        for(int j=i;j<n;j++){
            if(mi>v[j].second){
                mi=v[j].second;
                mij=j;
            }
        }
        swap(v[i],v[mij]);
    }
}


