using namespace std;

struct Card
{
	int num;
	char type;	
};

void trace(int n, Card c[])
{
	for (int i = 0; i < n; ++i)
	{
		cout << c[i].type << c[i].num;
		if (i < n - 1)
		{
			cout << " ";
		}
	}
	cout << endl;
}

void bubbleSort(int n, Card c[])
{
	for (int i = 0; i < n; ++i)
	{
		for (int j = n - 1; j > i; j--)
		{
			if (c[j].num < c[j - 1].num)
			{
				swap(c[j], c[j - 1]);
			}
		}
	}
	return;
}

void selectionSort(int n, Card c[])
{
	int min = 0;
	for (int i = 0; i < n; ++i)
	{
		min = i;
		for (int j = i; j < n; ++j)
		{
			if (c[j].num < c[min].num)
			{
				min = j;
			}
		}
		if (i != min)
		{
			swap(c[i], c[min]);
		}
	}
	return;
}

