			if(e[j].first<e[mi].first)mi=j;
		}
		char x=e[i].second;
		int y=e[i].first;
		e[i].first=e[mi].first;
		e[i].second=e[mi].second;
		e[mi].first=y;
		e[mi].second=x;
	}
	int f=0;
	rep(i,n){
		if(d[i].second!=e[i].second)f=1;
	}
	rep(j,n-1)cout<<d[j].second<<d[j].first<<" ";
	cout<<d[n-1].second<<d[n-1].first<<endl;
	cout<<"Stable"<<endl;
	rep(j,n-1)cout<<e[j].second<<e[j].first<<" ";
	cout<<e[n-1].second<<e[n-1].first<<endl;
	if(f==0)cout<<"Stable"<<endl;
	else cout<<"Not stable"<<endl;

