// Bubble sort
 void BubbleSort(vector<string> &a, int n){
  for(int j=n;j>=1;j--){
    for(int i=1;i<j;i++){
      if(a.at(i-1).at(1)>a.at(i).at(1)){
        string wk = a.at(i-1);
        a.at(i-1)=a.at(i);
        a.at(i)=wk;
      }
    }
  }
 }

// Selection sort
void SelectionSort(vector<string> &a, int n){
  for(int i=0;i<n;i++){
    int min_j=i;
    for(int j=i;j<n;j++){
      if(a.at(j).at(1)<a.at(min_j).at(1))
        min_j=j;
    }
    if(a.at(i).at(1)>a.at(min_j).at(1)){
      string wk=a.at(i);
      a.at(i)=a.at(min_j);
      a.at(min_j)=wk;
    }
  }
}

