          if (itr[j].value < itr[min_i].value)
            {
              min_i = j;
            }
        }
      if (i != min_i){
        swap(itr[i], itr[min_i]);
        cnt++;
      }
    }

  return cnt;
}


int bubbleSort(Card *begin, Card *end)
{
  auto swap = [](auto &a, auto &b){
                auto tmp = a;
                a = b;
                b =tmp;
              };

  auto n = std::distance(begin, end);
  auto itr = begin;

  auto cnt = 0;

  for (int i=0; i<n; i++)
    {
      for (int j=n-1; j>i; j--)
        {
          if (itr[j-1].value > itr[j].value)
            {
              swap(itr[j-1], itr[j]);
              cnt++;
            }
        }
    }

  return cnt;
}

