template<typename T>
vector<T> bubble_sort(vector<T> v) {
    for (uint32_t i = 0; i < v.size(); i++) {
        for (uint32_t j = v.size() - 1; j > i; j--) {
            if (v[j] < v[j - 1]) {
                swap(v[j], v[j - 1]);
            }
        }
    }

    return v;
}

template<typename T>
vector<T> insertion_sort(vector<T> v) {
    for (uint32_t i = 0; i < v.size(); i++) {
        uint32_t mini = i;
        for (uint32_t j = i; j < v.size(); j++) {
            if (v[j] < v[mini]) {
                mini = j;
            }
        }

        if (i != mini) {
            swap(v[i], v[mini]);
        }
    }

    return v;
}

