		for ( int j = size-1 ; j >= i+1 ; j-- ) {
			if ( p[j-1].number > p[j].number ) {
				card_t tmp;
				tmp = p[j-1];
				p[j-1] = p[j];
				p[j] = tmp;
			}
		}
	}	
}

