void Swap(struct Card *x, struct Card *y){
	struct Card z = *x;
	*x = *y;
	*y = z;
}

void BubbleSort(struct Card *C, int n){
	for(int i=0;i<n;i++)
		for(int j=n-1;j>=i;j--)
			if(C[j].value < C[j-1].value)
				Swap(&C[j], &C[j-1]);
}

void SelectionSort(struct Card *C, int n){
	for(int i=0;i<n;i++){
		int minj = i;
		for(int j=i;j<n;j++)
			if(C[j].value < C[minj].value)
				minj = j;
		Swap(&C[minj], &C[i]);
	}
}

bool isStable(struct Card *in, struct Card *out, int n){
	for(int i=0;i<n;i++)
		for(int j=i+1;j<n;j++)
			for(int a=0;a<n;a++)
				for(int b=a+1;b<n;b++)
					if((in[i].value == in[j].value) && (in[i].mark == out[b].mark) && (in[i].value == out[b].value)
						&& (in[j].mark == out[a].mark) && (in[j].value == out[a].value))
						return false;
	return true;
}

