  }

  BubbleSort(a, n);
  Print(a, n);
  printf("Stable\n");

  SelectionSort(b, n);
  Print(b, n);
  if (IsStable(a, b, n)) {
    printf("Stable\n");
  } else {
    printf("Not stable\n");
  }
