void BubbleSort(int NumCard, string InCard[]){
    bool Unsorted = true;
    int SortedNum = 0; //Aの最初からSortedNum個目まではソート済
    int SwapNum = 0; //交換数

    while(Unsorted){
        Unsorted = false;
        for(int CurPos = NumCard-1; CurPos >= SortedNum + 1; --CurPos){
            if(InCard[CurPos][1] < InCard[CurPos-1][1]){
                swap(InCard[CurPos], InCard[CurPos-1]);
                ++SwapNum;
                Unsorted = true;
            }
        }
        ++SortedNum;
    }

    return;
}

void SelectSort(int NumCard, string InCard[]){
    int SwapNum = 0; //交換数

    for(int SortedNum = 0; SortedNum < NumCard; ++SortedNum){    //Aの最初からSortedNum個目まではソート済
        bool Swapped = false; //このループで交換が行われたか
        int MinPos = SortedNum;    //未ソート部分での最小要素の位置
        for(int CurPos = SortedNum; CurPos < NumCard; ++CurPos){
            if (InCard[CurPos][1] < InCard[MinPos][1]){
                Swapped = true;
                MinPos = CurPos;
            }
        }
        swap(InCard[SortedNum], InCard[MinPos]);
        if(Swapped) ++SwapNum;
    }
}

bool IsStable(int NumCard, const string OldCard[], string NewCard[]){
    for(int i = 0; i < NumCard; i++){
        for(int j = i+1; j < NumCard; j++){
            for(int a = 0; a < NumCard; a++){
                for(int b = a+1; b < NumCard; b++){

                    if (OldCard[i][1] == OldCard[j][1]){
                        if (OldCard[j][1] == NewCard[a][1]){
                            if(NewCard[a][1] == NewCard[b][1]){//注目している数字が全て同じ
                                if(OldCard[i][0] == NewCard[b][0]){
                                    if(OldCard[j][0] == NewCard[a][0]){//その中で文字の前後関係が逆
                                        return false;
                                    }
                                }
                            }
                        }
                    }

               }
            }
        }
    }
    return true;
}

