        int j = n - 1;
        for (; j > i; j--)
        {
            if (A[j].value < A[j - 1].value)
            {
                swap(A[j], A[j - 1]);
            }
        }
    }
}

void selectionSort(Card A[], int n)
{
    for (int i = 0; i < n; i++)
    {
        int min = i;
        for (int j = i + 1; j < n; j++)
        {
            if (A[j].value < A[min].value)
            {
                min = j;
            }
        }
        swap(A[min], A[i]);
    }
}

