      std::cout << A[i].patt << A[i].num;
      if( i < A.size()-1 ) std::cout << " ";
      else std::cout << std::endl;
  }
}

int bubbleSort( std::vector<Card>& A, int N ){
  int cnt = 0;
  for( int i = 1; i < N; i++ ){
    for( int j = i; j > 0; j-- ){
      if( A[j-1].num > A[j].num ){
        std::swap( A[j], A[j-1] );
        cnt++;
      } else  break;
    }
  }
  return cnt;
}

int selectionSort( std::vector<Card>& A, int N ){
  int cnt = 0;
  for( int i = 0; i < N-1; i++ ){
    int minj = i;
    for( int j = i+1; j < N; j++ ){
      if( A[minj].num > A[j].num ){
        minj = j;
      }
    }
    if( i != minj ){
      std::swap( A[minj], A[i] );
      cnt++;
    }
  }
  return cnt;
}

bool isSafe( const std::vector<Card> target, const std::vector<Card> base ){
  std::vector<char> patt(0);
  for( int i = 1; i <= 9; i++ ){
    for( int j = 0; j < base.size(); j++ ){
      if( base[j].num == i ){
        patt.push_back( base[j].patt );
      }
    }
  }

  for( int i = 0; i < target.size(); i++ ){
    if( target[i].patt != patt[i] )
      return false;
  }
  return true;
}

