  display( bubble );
  std::cout << ((isSafe( bubble, A )) ? "Stable":"Not stable" ) << std::endl; 

  std::vector<Card> selection( A );
  selectionSort( selection, N );
  display( selection );
  std::cout << ((isSafe( selection, A )) ? "Stable":"Not stable" ) << std::endl;
}

