				swap( aa[j-1],aa[j]);
			}
		}
	}
}

void sectionsort(struct Card aa[], int n) {
	for (int i = 0; i<n; ++i) {
		int minj=i;
		for (int j = i; j<n; j++) {
			if(aa[j].value<aa[minj].value){minj=j;}
		}
			swap(aa[i], aa[minj]);
		}
}
