void elem_swap(int &a,int &b){
  int temp=a;
  a=b;
  b=temp;
}
void bubbleSort(vector<int> &vec,vector<char> &cvec,int size){
  bool flag=true;
  char temp;
  for(int i=0;i<size-1;i++){
    for(int j=0;j<size-1-i;j++){
      if(vec.at(j)>vec.at(j+1)){
        elem_swap(vec.at(j),vec.at(j+1));
        temp=cvec.at(j);
        cvec.at(j)=cvec.at(j+1);
        cvec.at(j+1)=temp;
        flag=false;
      }
    }
    if(flag) break;
  }
}
void selectionSort(vector<int> &vec,vector<char> &cvec,int size){
  int min_index;
  char temp;
  for(int i=0;i<size-1;i++){
    min_index=i;
    for(int j=i;j<size;j++){
      if(vec.at(min_index)>vec.at(j)){
        min_index=j;
      }
    }
    if(min_index>i){
      elem_swap(vec.at(i),vec.at(min_index));
      temp=cvec.at(i);
      cvec.at(i)=cvec.at(min_index);
      cvec.at(min_index)=temp;
    }
  }
}

