void bubble_sort(vector<string>& A) {
  int N = A.size();
  for (int i = 0; i < N; i++) {
    for (int j = N-1; i < j; j--) {
      if (A[j][1] < A[j-1][1]) swap(A[j], A[j-1]);
    }
  }
}

void selection_sort(vector<string>& A) {
  int N = A.size();
  for (int i = 0; i < N; i++) {
    int minj = i;
    for (int j = i; j < N; j++) {
      if (A[j][1] < A[minj][1]) minj = j;
    }
    if (i != minj) swap(A[i], A[minj]);
  }
}

