void bSort(vector<string> &data){
	int n = data.size();
	for (int i = 0; i < n; ++i){
		int count = 0;
		for (int j = n - 1; j > i; --j){
			if (data[j][1] < data[j - 1][1]){
				swap(data[j], data[j - 1]);
				count++;
			}
		}
		if (0 == count) break;
	}
}


void selSort(vector<string> &data){
	int n = data.size();
	for (int i = 0; i < n; ++i){
		int idx = i;
		for (int j = i; j < n; ++j)
			if (data[j][1] < data[idx][1]) idx = j;
		swap(data[idx], data[i]);
	}
}


