void isStable(vector<Card> input_vec, vector<Card> output_vec, int len_vec)
{
    out_vec(output_vec, len_vec);
    int i = 0;
    while (i < len_vec)
    {
        int j = i + 1;
        int i_value = output_vec[i].value;
        vector<Card> part_out = {output_vec[i]};
        while (output_vec[j].value == i_value && j < len_vec)
        {
            part_out.emplace_back(output_vec[j]);
            j++;
        }
        if (part_out.size() >= 2)
        {
            // vector<Card> part_in = {};
            int k = 0;
            int part_count = 0;
            while (part_count < part_out.size() && k < len_vec)
            {
                if (input_vec[k].value == i_value)
                {
                    if (input_vec[k].suit != part_out[part_count].suit)
                    {
                        cout << "Not stable\n";
                        return;
                    }
                    part_count++;
                }
                k++;
            }
        }
        i += part_out.size();
    }
    cout << "Stable\n";
    return;
}

