	int n;
	cin >> n;

	vector<string> cards(n);
	for (int i = 0; i < n; i++) cin >> cards[i];

	vector<string> bubble_sorted = bubble_sort(cards);
	vector<string> selection_sorted = selection_sort(cards);

	print_array(bubble_sorted);
	cout << (is_stable(cards, bubble_sorted) ? "Stable" : "Not stable") << endl;

	print_array(selection_sorted);
	cout << (is_stable(cards, selection_sorted) ? "Stable" : "Not stable") << endl;

	return 0;
}

