void trace(string a[], int n)
{
    for (int i = 0; i < n - 1; i++)
        cout << a[i] << " ";
    cout << a[n - 1] << "\n";
}

void swap(string *x, string *y)
{
    string tmp = *x;
    *x = *y;
    *y = tmp;
}

void bubbleSort(string a[], int n)
{
    for(int i = 0; i < n; i++)
        for(int j = n-1; j >= i+1; j--)
        {
            if(a[j][1] < a[j-1][1])
                swap(&a[j], &a[j-1]);
        }
    trace(a, n);
    cout << "Stable\n";
}

void SelectionSort(string a[], int n)
{
    bool flag = true;
    int count = 0;
    int minj;
    int same;
    for (int i = 0; i < n; i++)
    {
        same = -1;
        minj = i;
        for (int j = i+1; j < n; j++)
        {
            if (a[j][1] < a[minj][1])
                minj = j;
            else if(a[j][1] == a[i][1])
                same = j;
        }
        if (i != minj)
        {
            swap(&a[i], &a[minj]);
            if(same > 0 && minj > same)
                flag = false;
        }
        trace(a, n);
    }
    trace(a, n);
    if(flag)
        cout << "Stable\n";
    else
        cout << "No stable\n";
}

