void BubbleSort(vector<pair<int, int>>& pairs, int N){

  int i, j;

  for( i = 0; i < N; i++ ){
    for( j = N-1; j >= i+1; j-- ){
      if( pairs[j].first < pairs[j-1].first ){
        swap( pairs[j], pairs[j-1]);
      }
    }
  }
}

void SelectionSort(vector<pair<int, int>>& pairs, int N){

  int i, j;
  int minj;

  for( i = 0; i <= N-1; i++ ){
    minj = i;
    for( j = i; j <= N-1; j++ ){
      if( pairs[j].first < pairs[minj].first ){
        minj = j;
      }
    }
    swap( pairs[minj], pairs[i]);
  }
}

int Judge( string* C, vector<pair<int, int>> Bubble, vector<pair<int, int>> Selec, int N ){

  for( int i = 0; i < N; i++ ){
    if( C[Bubble[i].second] != C[Selec[i].second] ){
      return -1;
    }
  }

  return 0;

}


