vs BubbleSort(vs A, int N) {

    bool flag = true;
    string tmp;
    int i = 0;
    while (flag) {
        flag = false;
        for (int j = N - 1; j > i; j--) {
            if (int(A[j][1]) < int(A[j - 1][1])) {
                tmp = A[j];
                A[j] = A[j - 1];
                A[j - 1] = tmp;
                flag = true;
            }
        }
        i++;
    }

    return A;
}

vs SelectionSort(vs A, int N) {

    int minj;
    string tmp;
    for (int i = 0; i < N; i++) {
        minj = i;
        for (int j = i; j < N; j++) {
            if (int(A[j][1]) < int(A[minj][1])) minj = j;
        }
        if (i != minj) {
            tmp = A[minj];
            A[minj] = A[i];
            A[i] = tmp;
        }
    }

    return A;
}


