void sort_bubble(char a[][2], int n) {
	for (int i = 0; i < n; i++) {
		int flag = 0;
		for (int j = 0; j < n-i-1; j++) {
			if (a[j][1] > a[j + 1][1]) {
				swap(a[j], a[j + 1]);
				flag = 1;
			}
		}
		if (!flag) break;
	}
}
void sort_select(char a[][2], int n) {
	for (int i = 0; i < n; i++) {
		int k = i; 
		int  min = a[i][1];
		for (int j = i; j < n; j++) {
			if (a[j][1] < min) {
				min = a[j][1];
				k = j;
			}
		}
		swap(a[i], a[k]); 
	}
}
int is_stable(char a[][2], char b[][2],int n) {
	for (int i = 0; i < n; i++) {
		if (a[i][0] != b[i][0] || a[i][1] != b[i][1]) return 0;
	}
	return 1;
}
