#include <iostream>
using namespace std;

struct Card{ char suit; value;} ;

void bubbleSort(struct Card C[],int N){
  int i,j;
  for(i=0;i<N;i++){
    for(j=N-1;j<=i+1;j--){
      if(C[j].value<C[j-1].value){
        Card t=C[j];
        C[j]=C[j-1];
        C[j-1]=t;
      }
    }
  }
}

void selecitonSort(struct Card C[],int N){
  int i,j,minj;
  struct Card t;
  for(i=0;i<N;i++){
    minj=i;
    for(j=i;j<N;j++){
      if(C[j].value<C[minj].value)minj=j;
    }
    Card t=C[i];
    C[i]=C[minj];
    C[minj]=t;
  }
}

int hantei(struct Card C0[],struct Card C[],int N){
  int i,j;
  for(i=0;i<N-1;i++){
    if(C[i].value==C[i+1].value){
      for(j=0;j<N-1;j++){
        if(C[i].value==C0[j].value)
          if(C[i].suit==C0[j].suit&&C[i+1].suit==C0[j+1].suit)return 1;
      }
    }  
  }
  return 0;
}

void syutryoku(struct Card C[],int N){
  int i;
  for(i=0;i<N;i++){
    if(i>0)printf(" ");
    cout << C[i].suit << C[i].value;
  }
  cout << endl;
}
