using namespace std;

struct Card{
	char suit;
	int value;
}; 

void BubbleSort(struct Card A[],int N){
	bool flag = true;
	for(int i = 0;flag;i++){
		flag = false;
		for(int j = N-1; j>=i+1;j--){
			if(A[j].value < A[j-1].value){
				Card t = A[j];
				A[j] = A[j-1];
				A[j-1] = t;
				flag = true;	
			}
		}
	}
}

void SelectionSort(struct Card A[],int N){
	int minj;
	for(int i = 0; i<N;i++){
		minj = i;
		for(int j = i+1; j<N;j++){
			if(A[j].value < A[minj].value){
				minj = j;
			}
		}
		Card t = A[i];
		A[i] = A[minj];
		A[minj] = t;
	}
}

void trace(struct Card A[],int N){
	for(int i = 0; i<N;i++){
		if(i) printf(" ");
		cout << A[i].suit<< A[i].value;
	}
	printf("\n");
}

bool isStable(struct Card C1[], struct Card C2[],int N){
	bool flag = true;
	for(int i = 0; i<N;i++){
		if(C1[i].value==C2[i].value&&C1[i].suit!=C2[i].suit){
			flag = false;
		}
	}
	return flag;
}

