class card
{
public:
	char s;
	int c;
};

void swap(card& a, card& b)
{
	card v;
	v = a;
	a = b;
	b = v;
}

void print(card a[], int n)
{
	int i;
	for (i = 0; i < n; i++)
	{
		if (i)cout << " ";
		cout << a[i].s << a[i].c;
	}
	cout << endl;
}

int check(card a[], card b[], int n)
{
	int i, j, k, l;
	for (i = 0; i < n - 1; i++)
	{
		for (j = i + 1; j < n; j++)
		{
			if (a[i].c == a[j].c)
			{
				for (k = 0; k < n - 1; k++)
				{
					for (l = k + 1; l < n; l++)
					{
						if (a[i].s == b[l].s && a[j].s == b[k].s)
						{
							return 0;
						}
					}
				}
			}
		}
	}
	return 1;
}

