void bubble(card a[], int n)
{
    bool f = true;
    for (int i=0; f; ++i) {
        f = false;
        for (int j=n-1; j > i; --j) {
            if (a[j-1] > a[j]) {
                swap(a[j-1], a[j]);
                f = true;
            }
        }
    }
    return;
}

void selection(card a[], int n)
{
    rep(i, n-1) {
        card *pt = min_element(a+i, a+n);
        if (a+i != pt) {
            swap(a[i], *pt);
        }
    }
    return ;
}

bool same(const card a[], const card b[], int n)
{
    rep(i, n) {
        if (a[i] != b[i]) return false;
    }
