void bubbleSort(CARD* A, int N){

  bool flag = true;

  while(flag){
    flag = false;

    for(int i = N-1; i > 0; i--){
      if(A[i].num < A[i-1].num){
        CARD tmp = A[i];
        A[i] = A[i -1];
        A[i-1] = tmp;
        flag = true;
      }
    }
  }

  return;
}

