typedef vector<string> card_list;

bool comp(string a, string b) {
    int x = static_cast<int>(a[1]) - 48;
    int y = static_cast<int>(b[1]) - 48;
    return x < y;
}

int bubbleSort(card_list& A) {
    int N = A.size();
    int c = 0;
    for (int i = 0; i < N; ++i) {
        for (int j = N-1; j > i; --j) {
            if (comp(A[j], A[j-1])) {
                swap(A[j], A[j-1]);
                c++;
            }
        }
    }
    return c;
}

int selectionSort(card_list& A) {
    int N = A.size();
    int c = 0;
    for (int i = 0; i < N; ++i) {
        int min = i;
        for (int j = i; j < N; ++j) {
            if (comp(A[j], A[min])) {
                min = j;
            }
        }
        if (i != min) {
            swap(A[i], A[min]);
            c++;
        }
    }
    return c;
}

