bool ordered(int length, int* ordered_list)
{
    int sum = 0;
    for (int i = 0; i < length; i++) {
        if (ordered_list[i]) {
            sum++;
        }
    }
    for (int i = 0; i < sum; i++) {
        if (!ordered_list[i]) {
            return false;
        }
    }
    return true;
}

void check_stable(int num, std::string* list, std::string* list2)
{
    int* check_table = (int*)calloc(10, sizeof(int));
    for (int i = 0; i < num; i++) {
        int a = list[i][1] - 48;
        check_table[a] += 1;
    }

    bool no_same_num = true;
    std::vector<int> check_list;

    for (int i = 0; i < 10; i++) {
        if (check_table[i] > 1) {
            no_same_num = false;
            check_list.push_back(i);
        }
    }

    if (no_same_num) {
        std::cout << "Stable" << std::endl;
        return;
    }
    for (int i = 0; i < check_list.size(); i++) {
        std::vector<std::string> order_vector;
        for (int j = 0; j < num; j++) {
            if (list[j][1] - 48 == check_list[i]) {
                order_vector.push_back(list[j]);
            }
        }
        int order_check_flags[order_vector.size()] = {};
        for (int k = 0; k < num; k++) {
            for (int j = 0; j < order_vector.size(); j++) {
                if (order_vector[j] == list2[k]) {
                    order_check_flags[j] = 1;
                }
                if (!ordered(order_vector.size(), order_check_flags)) {

                    std::cout << "Not stable" << std::endl;
                    return;
                }
            }
        }
    }
    std::cout << "Stable" << std::endl;
    return;
}

