    }
    return B;
}

vector<string>SelectionSort(vector<string>&A){
    vector<string>B=A;
    rep(i,N){
        int mi=i;
        for(int j=i+1;j<N;j++)if(B[mi][1]>B[j][1])mi=j;
        swap(B[i],B[mi]);
    }
    return B;
}

bool isStable(vector<string>&A,vector<string>&B){
    rep(i,B.size()){
        for(int j=i+1;j<N;j++){
            if(B[i][1]!=B[j][1])continue;
            int x,y;
            rep(k,A.size()){
                if(A[k]==B[i])x=k;
                else if(A[k]==B[j])y=k;
            }
            if(x>y)return false;
        }
    }
    return true;
}

