#include <iostream>

using namespace std;

struct Card{char suit, value;};


void bubbleSort(struct Card a[], int n)
{
    for(int i = 1; i<n; i++){//1回ループするたびに一番右が最も大きい値になる
        for(int j = 0; j<n-i; j++){
        if(a[j].value > a[j+1].value){
          Card temp = a[j];
          a[j] = a[j+1];
          a[j+1] = temp;//この三行で右の方が大きくなる
        }
    }
  }
}

void selectionSort(struct Card a[], int n)//選択ソートはもっとも小さい値を見つけて１番右にもっていく
{
    for(int i = 0; i<n; i++){
        int min = i;//この時点での未ソートの部分のインデックス
        for(int j = i; j < n; j++){//最小の値を探すループ//jの初期値は未ソート部分の最も左のインデックス
          if(a[j].value < a[min].value)
              min = j;//最小の値のインデックスを探す
        }
          Card temp = a[i];
          a[i] = a[min];
          a[min] = temp;
    }
}

