#include <iostream>
using namespace std;

class Card{public:char suit,value;};

void bubble(Card A[],int N){
    for(int i=0;i<N;i++){
        for(int j=N-1;j>i;j--){
            if(A[j-1].value>A[j].value){
                swap(A[j],A[j-1]);
            }
        }
    }
}

void selection(Card A[],int N){
    for(int i=0;i<N;i++){
        int minj = i;
        for(int j=i;j<N;j++){
            if(A[minj].value>A[j].value)minj = j;
        }
        swap(A[minj],A[i]);
    }
}

void print(Card A[],int N){
    for(int i=0;i<N;i++){
        if(i)cout<<' ';
        cout<<A[i].suit<<A[i].value;
    }
    cout<<endl;
}

bool isStable(Card C1[],Card C2[],int N){
    for(int i=0;i<N;i++){
        if(C1[i].suit!=C2[i].suit) return false;
    }
    return true;
}

