void bubbleSort (struct Card C[], int n) {

    int i, j;
    Card v;

    for (i = 0; i < n; i++) {

        for (j = n - 1; j >= i + 1; j++) {

            if (C[j].value < C[j - 1].value) {

                v = C[j];
                C[j] = C[j - 1];
                C[j - 1] = v;

            }

        }

    }

}

void selectionSort (struct Card C[], int n) {

    int i, j, minj;
    Card v;

    for (i = 0; i < n; i++) {

        minj = i;

        for (j = i; j < n; j++) {

            if (C[j].value < C[minj].value) {

                minj = j;

            }

        }

        v = C[i];
        C[i] = C[minj];
        C[minj] = v;

    }

}

