std::vector< std::pair<char,int> > bubbleSort(std::vector< std::pair<char,int> > );
std::vector< std::pair<char,int> > selectionSort(std::vector< std::pair<char,int> >);
bool stable_judge(std::vector< std::pair<char,int> >,std::vector< std::pair<char,int> >);

int main(int argc, char const *argv[]){
	int N;
	std::cin >> N;
	std::vector< std::pair<char,int> > input;

	for (int i = 0; i < N; ++i){
		std::string buff;
		std::cin >> buff;
		input.push_back(std::make_pair(buff[0],buff[1]-'0'));
	}

	std::vector< std::pair<char,int> > bubble = bubbleSort(input);
	std::vector< std::pair<char,int> > select = selectionSort(input);

	for (int i = 0; i < N; ++i){
		std::cout << bubble[i].first << bubble[i].second << " ";
	}
	std::cout << std::endl;

	if(stable_judge(input,bubble)){
		std::cout << "Stable" << std::endl;
	}else{
		std::cout << "Not Stable" << std::endl;		
	}

	for (int i = 0; i < N; ++i){
		std::cout << select[i].first << select[i].second << " ";
	}
	std::cout << std::endl;

	if(stable_judge(input,select)){
		std::cout << "Stable" << std::endl;
	}else{
		std::cout << "Not stable" << std::endl;		
	}


	return 0;
}

std::vector< std::pair<char,int> > bubbleSort(std::vector< std::pair<char,int> > fig){
	for (int i = 0; i < fig.size(); ++i){
		for (int j = fig.size()-1; j > i ; --j){
			if(fig[j].second<fig[j-1].second){
				std::pair<char,int> buff = fig[j];
				fig[j] = fig[j-1];
				fig[j-1] = buff;
			}				
		}
	}
	return fig;
}

std::vector< std::pair<char,int> > selectionSort(std::vector< std::pair<char,int> > fig){
	for (int i = 0; i < fig.size(); ++i){
		int minj = i;
		for (int j = i; j < fig.size(); ++j){
			if(fig[j].second < fig[minj].second){
				minj = j;
			}				
		}
		if(i!=minj){
			std::pair<char,int> buff = fig[i];
			fig[i] = fig[minj];
			fig[minj] = buff;
		}
	}
	return fig;
}

bool stable_judge(std::vector< std::pair<char,int> > before, std::vector< std::pair<char,int> > after){

	while(!before.empty()){

		std::string str_before;
		std::string str_after;
		int fig = after[0].second;

		for (int i = 0; i < before.size(); ++i){
			if(fig==before[i].second){
				str_before += before[i].first;
				before.erase(before.begin() + i);
				i -= 1;
			}
		}

		for (int i = 0; i < after.size(); ++i){
			if(fig==after[i].second){
				str_after += after[i].first;
				after.erase(after.begin() + i);
				i -= 1;
			}
		}
		if(str_before != str_after)return false;
	}
	return true;
}

