  char num;
};

void bubble_sort(card c1[]){

  for( int i = 0 ; i < n ; i++ ){
    for( int j = n - 1 ; j > i ; j-- ){
      if( c1[j - 1].num > c1[j].num ){
	card t = c1[j - 1];
	c1[j - 1] = c1[j];
	c1[j] = t;
      }
    }
  }
}

void selection_sort(card c2[]){

  for( int i = 0 ; i < n ; i++ ){
    int mini = i;
    for( int j = i ; j < n ; j++ ){
      if( c2[j].num < c2[mini].num ) mini = j;
    }
    card t = c2[i];
    c2[i] = c2[mini];
    c2[mini] = t;
  }
}

