void bubbleSort(Node a[], int N) {
    bool flag = true;
    for (int i = 0; flag; i++) {
        flag = false;
        for (int j = N-1; j > i; j--) {
            if (a[j-1].v > a[j].v) {
                swap(a[j-1].c, a[j].c);
                swap(a[j-1].v, a[j].v);
                flag = true;
            }
        }
    }
}

void selectionSort(Node a[], int N) {
    for (int i = 0; i < N; i++) {
        int mi = i;
        for (int j = i + 1; j < N; j++) {
            if (a[j].v < a[mi].v) {
                mi = j;
            }
        }
        swap(a[i].v, a[mi].v);
        swap(a[i].c, a[mi].c);
    }
}

