#include <iostream>
#include <utility>
#include <vector>
#include <string>
using namespace std;

void Output(vector<string>& C)
{
    for (int i = 0; i < C.size(); ++i) {
        cout << C[i];
        if (i != C.size() - 1) {
            cout << " ";
        }
    }
    cout << endl;
}

vector<string> BubbleSort(vector<string> C)
{
    for (int i = 0; i < C.size() - 1; ++i) {
        for (int j = C.size() - 1; j > i; --j) {
            if (C[j-1][1] > C[j][1]) {
                swap(C[j-1], C[j]);
            }
        }
    }
    return C;
}

vector<string> SelectionSort(vector<string> C)
{
    for (int i = 0; i < C.size() - 1; ++i) {
        string minC = C[i];
        int idx = i;
        for (int j = i + 1; j < C.size(); ++j) {
            if (C[j][1] < minC[1]) {
                minC = C[j];
                idx = j;
            }
        }
        if (idx != i) {
            swap(C[i], C[idx]);
        }
    }
    return C;
}

bool IsStableSort(vector<string>& C1, vector<string>& C2)
{
    for (int i = 0; i < C1.size() - 1; ++i) {
        for (int j = i + 1; j < C1.size(); ++j) {
            if (C1[i][1] == C1[j][1]) {
                for (int k = 0; k < C2.size() - 1; ++k) {
                    for (int l = k + 1; l < C2.size(); ++l) {
                        if (C1[i] == C2[l] && C1[j] == C2[k]) {
                            return false;
                        }
                    }
                }
            }
        }
    }
    return true;
}

int main()
{
    int n;
    cin >> n;

    vector<string> C;
    for (int i = 0; i < n; ++i) {
        string c;
        cin >> c;
        C.push_back(c);
    }

    vector<string> Cb = BubbleSort(C);
    Output(Cb);
    if (IsStableSort(C, Cb)) {
        cout << "Stable" << endl;
    } else {
        cout << "Not stable" << endl;
    }
    vector<string> Ci = SelectionSort(C);
    Output(Ci);
    if (IsStableSort(C, Ci)) {
        cout << "Stable" << endl;
    } else {
        cout << "Not stable" << endl;
    }

    return 0;
}

