//sortを降順にする時は greater<型>()
vector<string> bubble(vector<string> a){
  bool flag=1;
  while(flag){
    flag = 0;
    for (int i = a.size()-1; i >= 1; i--) {
      if(a[i][1] < a[i-1][1]){
        swap(a[i],a[i-1]);
        flag = 1;
      }
    }
  }
  return a;
}

vector<string> selection(vector<string> a){
  for (int i = 0; i < a.size(); i++) {
    ll mini = i;
    for (int j = i; j < a.size(); j++) {
      if(a[j][1] < a[mini][1]){
        mini = j;
      }
    }
    swap(a[i],a[mini]);
  }
  return a;
}

bool check(vector<string> in , vector<string> out){
  for (int i = 0; i < in.size(); i++) {
    for (int l = i+1; l < in.size(); l++) {
      for (int a = 0; a < out.size(); a++) {
        for (int b = a+1; b < out.size(); b++) {
          if(in[i][1] == in[l][1] && in[i] == out[b] && in[l] == out[a])return false;
        }
      }
    }
  }
  return true;
}
