		for (int j=N-1; j>i; j--){
			if (B[j].value < B[minj].value){
				minj = j;
			}
		}
		if (minj != i){
			Card tmp;
			tmp = B[i];
			B[i] = B[minj];
			B[minj] = tmp;
		}
	}
}

