#include <iostream>
using namespace std;

struct card {
	char suit, value;
};

void bubble(struct card a[], int n) {
	for (int i = 0; i < n; i++) {
		for (int j = n - 1; j >= i; j--) {
			if (a[j].value < a[j - 1].value) swap(a[j], a[j - 1]);
		}
	}
}

void selection(struct card a[], int n) {
	for (int i = 0; i < n; i++) {
		int minj = i;
		for (int j = i; j < n; j++) {
			if (a[j].value < a[i].value) minj = j;
		}
		swap(a[i], a[minj]);
	}
}

bool isStable(struct card c1[], struct card c2[], int n) {
	for (int i = 0; i < n; i++) {
		if (c1[i].suit != c2[i].suit) return false;
	}
	return true;
}

