struct Card {
  Card() { };
  Card(char suit, int value) :
    suit_(suit),
    value_(value) { };

  char suit_;
  int value_;
  //enum Suit {'S', 'H', 'C', 'D'};
  void print(){ cout << suit_ << value_; }
};

class Solution {
public:
  Solution();
  ~Solution();
  void pre();
  void run();
  void post();
private:
  int dataSize;
  Card *inputCards;
  Card* copyCards(const Card* pCard, const int size);
  void bubbleSort(Card* pCard, const int size);
  void selectionSort(Card* pCard, const int size);
  void swap(Card &c0, Card &c1);
  void printArray(const Card* pCard, const int size);
  bool isStable(const Card* p0, const Card* p1, const int size);
};

/* Run time: O(n)
 * Memory : O(2n)
 */
bool Solution::isStable(const Card* p0, const Card* p1, const int size) {
  // Card value ranges from 1 to 9
  const int start_val = 1;
  const int end_val = 9;
  vector< vector<char> > vv0(9), vv1(9);

  for (int i = 0; i < size; i++) {
    vv0[p0[i].value_ - start_val].push_back(p0[i].suit_);
    vv1[p1[i].value_ - start_val].push_back(p1[i].suit_);
  }

  // Assume each card sorted out already; just check its stability here
  for (int i = 0; i < end_val; i++) {
    if (vv0[i].size()) {
      for (int j = 0; j < vv0[i].size(); j++) {
        if (vv0[i][j] != vv1[i][j]) {
          //cout << "Not stable" << endl;
          cout << "Not stable";
          return false;
        }
      }
    }
  }
  cout << "Stable" << endl;
  return true;
}

Solution::Solution() {
  cin >> dataSize; cin.ignore();
  assert(dataSize > 0);

  inputCards = new Card[dataSize];
  for (int i=0; i < dataSize; i++)
    cin >> inputCards[i].suit_ >> inputCards[i].value_;

#ifdef DEBUG
  cout << "INPUT: "; printArray(inputCards, dataSize);
#endif
}

Solution::~Solution() {
  if (inputCards)   delete [] inputCards;
}

void Solution::pre() { }

void Solution::run() {
  Card* cards0 = copyCards(inputCards, dataSize);
  bubbleSort(cards0, dataSize);
  printArray(cards0, dataSize);
  isStable(inputCards, cards0, dataSize);
  delete [] cards0;

  Card* cards1 = copyCards(inputCards, dataSize);
  selectionSort(cards1, dataSize);
  printArray(cards1, dataSize);
  isStable(inputCards, cards1, dataSize);
  delete [] cards1;
}

void Solution::post() { }

Card* Solution::copyCards(const Card* pCard, const int size) {
  Card* newCards = new Card[size];
  for (int i=0; i < size; i++)
    newCards[i] = pCard[i];
  return newCards;
}

void Solution::bubbleSort(Card* pCard, const int size) {
  if (pCard == nullptr || size <= 1) return;

  for (int i = 0; i < size; i++) {
    for (int j = size-1; j > i; j--) {
      if (pCard[j].value_ < pCard[j-1].value_)
        swap(pCard[j], pCard[j-1]);
    }
  }
}

void Solution::selectionSort(Card* pCard, const int size) {
  for (int i = 0; i < size-1; i++) {
    int min = i;
    for (int j = i+1; j < size; j++) {
      if (pCard[j].value_ < pCard[min].value_)
        min = j;
    }
    if (min != i)
      swap(pCard[min], pCard[i]);
  }
}

void Solution::printArray(const Card* pCard, const int size) {
  for (int i=0; i < size; i++) {
    if (i > 0)  cout << " ";
    cout << pCard[i].suit_ << pCard[i].value_;
  }
  cout << endl;
}

void Solution::swap(Card &c0, Card &c1) {
  Card temp = c0;
  c0 = c1;
  c1 = temp;
}

int main() {
  Solution solution;
  solution.pre();
  solution.run();
  solution.post();
  return 0;
}

#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

struct Card {
  char type;
  int value;
  std::string raw;

  Card(std::string s) {
    raw = s;
    type = s[0];
    value = s[1] - '0';
  }
};

void swap(std::vector<Card>& cards, int a, int b) {
  auto buf = cards[a];
  cards[a] = cards[b];
  cards[b] = buf;
}

std::vector<Card> bubbleSort(std::vector<Card> cards) {
  for (int i = 0; i < cards.size(); i++) {
    for (int j = cards.size() - 1; j > i; j--) {
      if (cards[j].value < cards[j - 1].value) swap(cards, j, j - 1);
    }
  }
  return cards;
}
std::vector<Card> selectionSort(std::vector<Card> cards) {
  for (int i = 0; i < cards.size(); i++) {
    int min = i;
    for (int j = i; j < cards.size(); j++) {
      if (cards[j].value < cards[min].value) min = j;
    }
    if (i != min) swap(cards, i, min);
  }
  return cards;
}

bool isStable(const std::vector<Card>& origin,
              const std::vector<Card>& sorted) {
  std::vector<std::vector<Card>> originTable(9, std::vector<Card>());

  std::for_each(origin.begin(), origin.end(), [&](Card card) {
    originTable[card.value - 1].push_back(card);
  });

  for (int i = sorted.size() - 1; i >= 0; i--) {
    auto& card = sorted[i];
    auto& back = originTable[card.value - 1].back();
    if (back.type != card.type) return false;
    originTable[card.value - 1].pop_back();
  }
  return true;
}

void trace(std::vector<Card>& cards) {
  for (int i = 0; i < cards.size(); i++) {
    std::cout << cards[i].raw;
    std::cout << (i == cards.size() - 1 ? '\n' : ' ');
  }
}

int main() {
  int n;
  std::cin >> n;
  std::vector<Card> cards;
  for (int i = 0; i < n; i++) {
    std::string buf;
    std::cin >> buf;
    cards.emplace_back(buf);
  }
  auto bCards = bubbleSort(cards);
  auto sCards = selectionSort(cards);
  trace(bCards);
  std::cout << (isStable(cards, bCards) ? "Stable" : "Not stable") << std::endl;
  trace(sCards);
  std::cout << (isStable(cards, sCards) ? "Stable" : "Not stable") << std::endl;
  return 0;
}

