#include <iostream>
using namespace std;

struct Card {
    char suit, value;
};

int selectionSort(Card A[], int N) {
    int Count = 0;

    for (int i = 0; i < N; i++) {
        int minKey = i;
        for (int j = i + 1; j < N; j++) {
            if (A[minKey].value > A[j].value) {
                minKey = j;
            }
        }
        if (minKey != i) {
            swap(A[i], A[minKey]);
            Count++;
        }
    }

    return Count;
}

int bubbleSort(Card A[], int N) {
    int Count = 0;

    for (int i = 0; i < N; i++) {
        for (int j = N - 1; j > i; j--) {
            if (A[j].value < A[j-1].value) {
                swap(A[j], A[j-1]);
                Count++;
            }
        }
    }

    return Count;
}

void printCards(Card A[], int N) {
    for (int i = 0; i < N; i++) {
        if (i) {
            cout << " ";
        }
        cout << A[i].suit << A[i].value;
    }
}

bool isStable(Card A[], Card B[], int N) {
    for (int i = 0; i < N; i++) {
        if (A[i].suit != B[i].suit) {
            return false;
        }
    }

    return true;
}

int main(void) {
    int N;
    cin >> N;
    Card* A1 = new Card[N];
    Card* A2 = new Card[N];

    for (int i = 0; i < N; i++) {
        cin >> A1[i].suit >> A1[i].value;
    }
    for (int i = 0; i < N; i++) A2[i] = A1[i];

    bubbleSort(A1, N);
    selectionSort(A2, N);

    printCards(A1, N);
    cout << endl;
    cout << "Stable" << endl;
    printCards(A2, N);
    cout << endl;
    if (isStable(A1, A2, N)) {
        cout << "Stable" << endl;
    } else {
        cout << "Not stable" << endl;
    }
}

