		cin >> x;
	ss = bs;

	auto cmp = [](s a, s b){return a[1] < b[1];};
	stable_sort(bs.begin(), bs.end(), cmp);
	p(bs);
	cout << "Stable" << endl;

	for (auto i = ss.begin(), e = ss.end(); i != e - 1; i++) {
		auto min = i, j = i;
		for (; j != e; j++)
			if (cmp(*j, *min))
				min = j;
