int bubbleSort(card* A, int N){
    int flag = 1;
    int count = 0;
    while(flag){
        flag = 0;
        for(int j = 1; j < N; j++){
            if(A[j].value < A[j - 1].value){
                swap(A[j], A[j - 1]);
                flag = 1;
                count += 1;
            }
        }
    }
    return count;
}

int selectionSort(card* A, int N){
    int count = 0;
    for(int i = 0; i < N; i++){
        int minj = i;
        for(int j = i; j < N; j++){
            if(A[j].value < A[minj].value){
                minj = j;
            }
        }
        if (i != minj){
        swap(A[i], A[minj]);
        count++;
        }
    }
    return count;
}

bool is_stable(card *A, card *B, int N){
    vector<string> arr;
    arr.resize(9);
    for(int i = 0; i < 9; i ++){
        arr[i] = "";
    }

    for(int i = 0; i < N; i++){
        arr[int(A[i].value - '0')].push_back(A[i].mark);
    }
    for(int i = N - 1; i >= 0 ; i--){
        if(B[i].mark != arr[B[i].value - '0'].back()){
            return false;
        }else{
            arr[B[i].value - '0'].pop_back();
        }
    }
    return true;
}

