void insertionSort(int A[], char B[], int N) {
	for (int i = 1; i < N; i++) {
		int val = A[i];
		char cval = B[i];
		int j = i - 1;
		while (j >= 0 && A[j] > val) {
			A[j + 1] = A[j];
			B[j + 1] = B[j];
			j--;
		}
		A[j + 1] = val;
		B[j + 1] = cval;
	}
}

void bubbleSort(int A[], char B[], int N) {
	for (int i = 0; i < N - 1; i++) {
		for (int j = N - 1; i < j; j--) {
			if (A[j - 1] > A[j]) {
				swap(A[j - 1], A[j]);
				swap(B[j - 1], B[j]);
			}
		}
	}
}

void selectionSort(int A[], char C[], int N) {
	for (int i = 0; i < N; i++) {
		int minj = i;
		for (int j = i + 1; j < N; j++) {
			if (A[j] < A[minj])
				minj = j;
		}
		swap(A[minj], A[i]);
		swap(C[minj], C[i]);
	}
}

