void bubbleSort(vector<string> &v){
    int size = v.size(), i;
    bool changed = true;
    while(changed){
        changed = false;
        for(i = 0; i < size-1; i++){
            if((int)v[i].at(1) > (int)v[i+1].at(1)){
                string tmp = v[i];
                v[i] = v[i+1];
                v[i+1] = tmp;
                changed = true;
            }
        }
    }
}
void selectionSort(vector<string> &v){
    int size = v.size(), i, j, min;
    for(i = 0; i < size; i++){
        min = i;
        for(j = i; j < size; j++){
            min = (int)v[j].at(1) < (int)v[min].at(1) ? j : min;
        }
        if(i != min){
            string tmp = v[i];
            v[i] = v[min];
            v[min] = tmp;
        }
    }
}

