#include<iostream>
#include<string>
using namespace std;
#define SWAP(a,b) {Trump tmp = a;a = b; b= tmp;}

class Trump{
    int num;
    char mark;
public:
    Trump(int a=1,char b='H'):num(a),mark(b){}
    char getMark(){return mark;}
    void set(int a,char b){
        this->num = a;
        this->mark = b;
    }
    string show(){
        return mark+to_string(num);
    }
    bool operator < (const Trump& right)const{
        return this->num < right.num;
    }
    bool operator > (const Trump& right)const{
        return this->num > right.num;
    }
    bool operator <= (const Trump& right)const{
        return this->num <= right.num;
    }
    bool operator >= (const Trump& right)const{
        return this->num >= right.num;
    }
};

void selectionsort(Trump A[],int n){

    for(int i=0;i<n;i++){
        int minj = i;
        for(int j=i;j<n;j++){
            if(A[j]<A[minj])minj=j;
        }
        if(i!=minj)SWAP(A[i],A[minj]);
    }
}

void bubblesort(Trump A[],int n){
    for(int i=0;i<n;i++){
        for(int j=n-1;j>i;j--){
            if(A[j]<A[j-1])SWAP(A[j],A[j-1]);
        }
    }
}

int main(){
    int n;
    cin >> n;
    Trump A[n],B[n];
    char ct;
    int ci;
    for(int i=0;i<n;i++){cin >> ct >> ci;A[i].set(ci,ct);B[i].set(ci,ct);}
    selectionsort(B,n);
    bubblesort(A,n);
    cout << A[0].show();
    for(int i=1;i<n;i++)cout <<" "<< A[i].show();
    cout << endl;
    cout << "Stable" << endl;
    cout << B[0].show();
    for(int i=1;i<n;i++)cout <<" "<< B[i].show();
    cout << endl;
    for(int i=0;i<n;i++)if(A[i].show()!=B[i].show()){cout << "Not stable" <<endl;return 0;}
    cout << "Stable" << endl;
    return 0;
}

