void priv(vector<string> &a){
  int N = a.size();
  rep(i, N){
    cout <<a[i];
    if (i == N-1) cout <<endl;
    else cout <<" ";
  }
}

bool bubbleSort(vector<string> &a, int N){
  int res = 0;
  bool flag = true;
  while (flag){
    flag = false;
    for (int j=N-1; j>=1; j--){
      if (a[j-1][1] > a[j][1]){
        swap(a[j-1], a[j]);
        res++;
        flag = 1;
      }
    }
  }
  priv(a);
  return true;
}

bool selectionSort(vector<string> &a, int N){
  int res = 0;
  for (int i=0; i<N; i++){
    int minj = i;
    for (int j=i; j<N; j++){
      if (a[minj][1] > a[j][1]) minj = j;
    }
    if (a[i][1] > a[minj][1]) res++;
    swap(a[i], a[minj]);
  }
  priv(a);
  return res;
}


