    while (next) {
        next = false;
        for (size_t i = cardList.size() - 1; i >= 1; --i) {
            if (cardList[i].num < cardList[i - 1].num) {
                auto tmp = cardList[i];
                cardList[i] = cardList[i - 1];
                cardList[i - 1] = tmp;
                next = true;
                ++swapCount;
            }
        }
    }

    return swapCount;
}

int selectionSort(std::vector<Card>& cardList) {
    using std::swap;


    int swapCount = 0;

    for (size_t i=0; i < cardList.size(); ++i) {
        size_t minj = i;

        for (size_t j = i; j < cardList.size(); ++j) {
            if (cardList[j].num < cardList[minj].num) {
                minj = j;
            }
        }

        if (i != minj) {
            swap<Card>(cardList[i], cardList[minj]);
            ++swapCount;
        }
    }

    return swapCount;
}

bool IsStable(const std::vector<Card>& cardList, const Card& prev, const Card& curr) {
    bool findPrev = false;
    int targetNum = prev.num;
    for (size_t i = 0; i < cardList.size(); ++i) {
        if (cardList[i].num == targetNum) {
            if (!findPrev && cardList[i].str == prev.str) {
                findPrev = true;
            } else if (findPrev) {
                if (cardList[i].str == curr.str) {
                    return true;
                }
            }
        }
    }
    return false;
}

void show(std::vector<Card>& sortedList, std::vector<Card>& orgList) {
    Card* prev = &sortedList.front();
    printf("%s", prev->str.c_str());
    bool isStable = true;
    for (size_t i = 1; i < sortedList.size(); ++i) {
        printf(" ");
        printf("%s", sortedList[i].str.c_str());

        if (prev->num == sortedList[i].num) {
            isStable &=  IsStable(orgList, *prev, sortedList[i]);
        }

        prev = &(sortedList[i]);
    }

    if (isStable) {
        printf("\nStable\n");
    } else {
        printf("\nNot stable\n");
    }
}

