int memo;
void judge(struct Card origin[],struct Card a[],int n){
  int finish=0;
  for (int i=0;i<n;i++){
    if(i==0){
      memo=0;
    }
    if(i<n && a[i-1].value!=a[i].value){
      memo=0;
    }
    if(finish!=0){
      break;
    }
    for (int j =memo;j<n;j++){
      if(a[i].value==origin[j].value){
        if(a[i].suit !=origin[j].suit){
          cout<<"Not stable"<<endl;
          finish++;
          break;
        }
        if(i<n-1 && a[i].value==a[i+1].value){
          memo=j+1;
          break;
        }
      }
    }
  }
  if(finish==0){
    cout<<"Stable"<<endl;
  }
}

