template<typename U>
void sort_bubble(std::vector<U> &x) {
	// init
	for (int i=0; i<x.size(); ++i) ix[i] = i;
	// sort
	for (int i=0; i<x.size(); ++i) {
		for (int j=x.size()-1; j>i; --j) {
			if (x[j] < x[j-1]) {
				swap(x[j], x[j-1]);
			}
		}
	}
}

template<typename T>
void sort_selection(std::vector<T> &x){
	// init
	for (int i=0; i<x.size(); ++i) ix[i] = i;
	// sort
	for (int i=0; i<x.size(); ++i) {
		int min_index = i;
		for (int j=i+1; j<x.size(); ++j) {
			if (x[j] < x[min_index]) min_index = j; 
		}
		if (x[i] == x[min_index]) {
			continue;
		}
		swap(x[i], x[min_index]);
	}
}

template<typename T>
bool check_stability(const std::vector<T> &x) {
	for (int i=1; i<x.size(); ++i) {
		if (x[i-1].value == x[i].value
		    &&  x[i-1].index > x[i].index) {
			return false;
		}
	}
	return true;
}

