	Trump tmp;
	for (int i = 0; i < N; i++)
	{
		for (int j = N-1; j >= i+1; j--)
		{
			if (C[j].value < C[j - 1].value) {
				tmp = C[j];
				C[j] = C[j - 1];
				C[j - 1] = tmp;
			}
		}
	}
