using namespace std;

int BUBBLE_SORT(int A[], char C[], int N){

	bool flag = true;
	int c = 0, tmp;
	char tmpc;

	while (flag){
		flag = false;
		for (int j = N - 1; j >= 1; j--){
			if (A[j] < A[j - 1]){
				tmp = A[j];
				A[j] = A[j - 1];
				A[j - 1] = tmp;
				tmpc = C[j];
				C[j] = C[j - 1];
				C[j - 1] = tmpc;
				c++;
				flag = true;
			}
		}
	}

	return c;
}

int SELECTION_SORT(int A[], char C[], int N){
	int c = 0;
	int minj, tmp;
	char tmpc;
	REP(i, N){
		minj = i;
		FOR(j, i, N){
			if (A[j] < A[minj]){
				minj = j;
			}
		}
		tmp = A[i];
		A[i] = A[minj];
		A[minj] = tmp;
		tmpc = C[i];
		C[i] = C[minj];
		C[minj] = tmpc;
		if (minj != i){
			c++;
		}
	}
	return c;
}


