void BubbleSort(vector<pair<char,int>>& a)
{
    int N=a.size();
    for(int i=0;i<=N-2;i++){
        for(int j=N-1;j-1>=i;j--){
            if(a[j-1].second>a[j].second) swap(a[j-1],a[j]);
        }
    }
}

void SelectionSort(vector<pair<char,int>>& a)
{
    int N=a.size();
    for(int i=0;i<=N-2;i++){
        int mn=a[i].second,idx=i;
        for(int j=i+1;j<N;j++) if(a[j].second<mn){
            mn=a[j].second; idx=j;
        }
        swap(a[i],a[idx]);
    }
}

