int ToInt(string str)
{
	int ret = 0;

	switch(str[0])
	{
		case 'S':
			ret = 0;
			break;
		case 'H':
			ret = 1;
			break;
		case 'D':
			ret = 2;
			break;
		case 'C':
			ret = 3;
			break;	
	}

	ret += (str[1] - '1') * 4;

	return ret;
}

string ToCard(int n)
{
	string ret = "";
	switch(n % 4)
	{
		case 0:
			ret += 'S';
			break;
		case 1:
			ret += 'H';
			break;
		case 2:
			ret += 'D';
			break;
		case 3:
			ret += 'C';
			break;
	}

	ret += (char)(n / 4 + '1');

	return ret;
}

