			B[i][j] = A[i][j];
		}
	}

	bool stbl;
	for (int i = 0; i < 2; i++) {
		switch (i) {
			case 0: {
				stbl = bubbleSort(A, n);
				print(A, n);
				break;
			}
			case 1: {
				stbl = selectionSort(B, n);
				print(B, n);
				break;
			}
		}
		switch (stbl) {
			case true: {
				cout << "Stable" << endl;
				break;
			}
			default: {
				cout << "Not stable" << endl;
				break;
			}
		}
	}

	return 0;
}

