}

void bs(struct card a[], int n) {
	int i = 0;
	int flag = 1;
	while (flag) {
		flag = 0;
		for (int j = n - 1; j >= i + 1; j--) {
			if (a[j].value < a[j - 1].value) {
				swap(a[j], a[j - 1]);
				flag = 1;
			}
		}
		i++;
	}
	return;
