      if(a[j].val > a[j+1].val){
        swap(a[j], a[j+1]);
      }
    }
  }
}
void SelectionSort(vector<Node>&a){
  for(int i = 0; i < a.size() - 1; i++){
    int p = i;
    for(int j = i + 1; j < a.size(); j++){
      if(a[p].val > a[j].val){
        p = j;
      }
    }
    if(p != i){
      swap(a[p], a[i]);
    }
  }
}
