void SelectionSort(Card A[], int N) {
    for (int i = 0; i < N; ++i) {
    	int minIndex = i;
    	int j = i;
    	for (; j < N; ++j) {
    		if (A[j].value < A[minIndex].value)
    			minIndex = j;
    	}
    	if (i != minIndex)
    		swap(A[i], A[minIndex]);
    }
}

