vector<Card> bubble(std::vector<Card> C, int N) {
  rep(i, N) {
    int j = N - 1;
    while (j > i) {
      if (C[j].value < C[j - 1].value) {
        swap(C[j], C[j - 1]);
      }
      j--;
    }
  }
  return C;
}

vector<Card> selection(std::vector<Card> C, int N) {
  rep(i, N) {
    int minj = i;
    int j = i;
    while (j < N) {
      if (C[j].value < C[minj].value) {
        minj = j;
      }
      j++;
    }
    if (i != minj) {
      swap(C[i], C[minj]);
    }
  }
  return C;
}

