void bubble_sort(Card c[], int n)
{
	bool flag = true;
	int i = 0;

	while ( flag ) {
		flag = false;

		for ( int j = n - 1; j > i; --j )
			if ( c[j].rank < c[j - 1].rank ) {
				swap(c[j - 1], c[j]);
				flag = true;
			}

		++i;
	}
}

void selection_sort(Card c[], int n)
{
	Card minv;
	int minj;

	for ( int i = 0; i < n - 1; ++i ) {
		minj = i;
		minv = c[i];

		for ( int j = i + 1; j < n; ++j )
			if ( c[j].rank < minv.rank ) {
				minj = j;
				minv = c[j];
			}

		if ( minj != i ) {
			c[minj] = c[i];
			c[i] = minv;
		}
	}
}

