void BubbleSort(Card A[], int N) {
    for (int i = 0; i < N; i++) {
        for (int j = N - 1; j >= i + 1; j--) {
            if (A[j].mValue < A[j - 1].mValue) {
                Card cardT = A[j];
                A[j] = A[j - 1];
                A[j-1] = cardT;
            }
        }
    }
}

void SelectionSort(Card A[], int N) {
    int min{ 0 };
    for (int i = 0; i < N; i++) {
        min = i;
        for (int j = i; j < N; j++) {
            if (A[j].mValue < A[min].mValue) {
                min = j;
            }
        }
        if (i != min) {
            Card cardT = A[i];
            A[i] = A[min];
            A[min] = cardT;
        }
    }
}

