        if (i < A.size() - 1) {
            cosp(A[i]);
        } else {
            co(A[i]);
        }
    }
}

void bubbleSort(vector<string> &A, int N, int &changed) {
    int flag = 1;
    int i = 0;
    while (flag) {
        flag = 0;
        repb(j, N - 1, i + 1) {
            if (A[j][1] < A[j - 1][1]) {
                swap(A[j], A[j - 1]);
                flag = 1;
                changed++;
            }
        }
        i++;
    }
}

void selectionSort(vector<string> &A, int N, int &changed) {
    rep(i, 0, N - 1) {
        int minv = A[i][1], tmp = 0;
        rep(j, i + 1, N - 1) {
            if (A[j][1] < minv) {
                minv = A[j][1];
                tmp = j;
            }
        }
        if (A[i][1] != minv) {
            swap(A[i], A[tmp]);
            changed++;
        }
    }
}

string isStable(vector<string> &in, vector<string> &out) {
    int N = in.size();
    rep(i, 0, N - 1) {
        rep(j, i + 1, N - 1) {
            rep(a, 0, N - 1) {
                rep(b, a + 1, N - 1) {
                    tuple<string, string, string, string, string, string> t;
                    t = make_tuple(in[i][1], in[j][1], in[i], out[b], in[j], out[a]);
                    if (in[i][1] == in[j][1] && in[i] == out[b] && in[j] == out[a]) {
                        return "Not stable";
                    }
                }
            }
        }
    }
    return "Stable";
}

