void bubbleSort(vector<pair<char, int>> &A, int N) {
  bool flag = 1;
  for (int i = 0; flag; i++) {
    flag = 0;
    for (int j = N - 1; j >= i; j--) {
      if (A[j].second < A[j - 1].second) {
        swap(A[j], A[j - 1]);
        flag = 1;
      }
    }
  }
}

void selectionSort(vector<pair<char, int>> &A, int N) {
  for (int i = 0; i < N; i++) {
    int minj = i;
    for (int j = minj; j < N; j++) {
      if (A[minj].second > A[j].second) {
        minj = j;
      }
    }
    if (i == minj) {
      continue;
    }
    swap(A[i], A[minj]);
  }
};


