void bubblesort(Card A[],int N){
    for(int fixed=0;fixed<N-1;fixed++){
        for(int i=N-2;i>=fixed;i--){
            if(A[i+1].v<A[i].v){
                swap(A[i],A[i+1]);
        }
    }
  }
}

void selectionsort(Card A[],int N){
    int mind;
    for(int i=0;i<N-1;i++){
        mind=i;
        for(int j=i;j<=N-1;j++){
            if(A[j].v<A[mind].v) mind=j;
        }
        if(i!=mind) swap(A[i],A[mind]);
    }
}

int is_stable(Card in[],Card out[],int n){
    for(int i=0;i<=n-1;i++){
        for(int j=i+1;j<=n-1;j++){
            for(int a=0;a<=n-1;a++){
                for(int b=a+1;b<=n-1;b++){
                    if(in[i].v==in[j].v && in[i].s==out[b].s && in[i].v==out[b].v && in[j].s==out[a].s && in[j].v==out[a].v){
                        return false;
                    }
                }
            }
        }
    }
    return true;
}

