template <class T>
void BubbleSort(vector<T> &a) {
  int N = a.size();
  REP(i, N) {
    for (int j = N-1; j>=i+1; --j) {
      if (a[j] < a[j-1]) {
         swap(a[j], a[j-1]);
      }
    }
  }
}

template <class T>
void SelectionSort(vector<T> &a) {
  int N = a.size();
  int minj;
  REP(i, N) {
    minj = i;
    FOR(j, i, N) {
      if (a[j] < a[minj]) minj = j;
    }
    if (i != minj) {
      swap(a[i], a[minj]);
    }
  }
}

