#include <bits/stdc++.h>
using namespace std;

class Card {
public:
    char mark;
    int num;

    Card() {}
    Card(char mark, int num) {
        this->mark = mark;
        this->num = num;
    }
};

void bsort(vector<Card> &v) {
    for (int i = 0; i < v.size(); i++) {
        for (int j = v.size() - 1; j > i; j--)
            if (v[j - 1].num > v[j].num)
                swap(v[j - 1], v[j]);
    }
}

void ssort(vector<Card> &v) {
    for (int i = 0; i < v.size(); i++) {
        int minj = i;
        for (int j = i; j < v.size(); j++) {
            if (v[j].num < v[minj].num)
                minj = j;
        }
        swap(v[i], v[minj]);
    }
}

bool isStable(vector<Card> &v, map<int, string> &m) {
    bool ok = true;
    int idx = 0;
    for (int i = 0; i < v.size(); i++) {
        if (v[i].mark != m[v[i].num][idx++])
            ok = false;
        if (m[v[i].num].size() == idx)
            idx = 0;
    }

    return ok;
}

void disp(const vector<Card> &v) {
    for (int i = 0; i < v.size(); i++)
    {
        cout << v[i].mark << v[i].num;
        if (i < v.size() - 1)
            cout << " ";
    }
    cout << '\n';
}
