    vector<Card> card(n), card_(n);
    map<int, string> mark;
    for (int i = 0; i < n; i++) {
        string s;
        cin >> s;
        card[i] = Card(s[0], atoi(&s[1]));
        mark[atoi(&s[1])] += s[0];
    }

    card_ = card;
    bsort(card);
    disp(card);
    cout << (isStable(card, mark) ? "Stable" : "Not stable") << '\n';
    ssort(card_);
    disp(card_);
    cout << (isStable(card_, mark) ? "Stable" : "Not stable") << '\n';
    return 0;
}

