void bubble(struct Card A[], int n) {  

    int flag = 1;  
    for (int i = 0; flag; i++) {  
        flag = 0;  
        for (int j = n - 1; j >= i + 1; j--) {  
            if (A[j].value < A[j - 1].value) {  
                swap(A[j], A[j - 1]);  
                flag = 1;  
            }  
        }  
    }  
}  
void selection(struct Card A[], int n) {  
    for (int i = 0; i < n; i++) {  
        int minj = i;  
        for (int j = i; j < n; j++) {  
            if (A[j].value < A[minj].value)  
                minj = j;  
        }  
        if (i != minj)  
            swap(A[i], A[minj]);  
    }  
}  

