void BubbleSort(int a[],char c[],int n){
  int st;
  char stc;
  for(int i=0;i<n;i++){
    for(int j=n;j>i-1;j--){
      if(a[j]<a[j-1]){
	st=a[j];
	a[j]=a[j-1];
	a[j-1]=st;
	stc=c[j];
	c[j]=c[j-1];
	c[j-1]=stc;
      }
    }     
  }
}


int Partition(int a[],char c[],int p,int r){
  int x,i,j,st;
  char stc;

  x=a[r];
  i=p-1;

  for(j=p;j<=r-1;j++){
    if(a[j]<=x){
      i++;

      //exchange a[i] and a[j]
      st=a[i];
      a[i]=a[j];
      a[j]=st;

      stc=c[i];
      c[i]=c[j];
      c[j]=stc;

    }
  }

  //exchange a[i] and a[j]
    st=a[i+1];
    a[i+1]=a[r];
    a[r]=st;

    stc=c[i+1];
    c[i+1]=c[r];
    c[r]=stc;

    return i+1;

}


void QuickSort(int a[],char c[],int p,int r){
  int q;
  if(p<r){
    q=Partition(a,c,p,r);
    QuickSort(a,c,p,q-1);
    QuickSort(a,c,q+1,r);
  }
}

