//バブルソートと選択ソートでトランプを昇順に並び替え、安定かを判断するプログラム
int main(){
    int N, i, j, flag, min, judge = 0;
    string prev, array[36] = {}, bubble_array[36] = {}, select_array[36] = {};

    //トランプを配列に格納
    cin >> N;
    i = 0;
    while(i < N){
        cin >> array[i];
        bubble_array[i] = array[i];
        select_array[i] = array[i];
        i++;
    }

    //バブルソート
    flag = 1;
    while(flag){
        flag = 0;
        i = N - 1;
        while(i > 0){
            if (bubble_array[i][1] < bubble_array[i-1][1]){
                prev = bubble_array[i];
                bubble_array[i] = bubble_array[i-1];
                bubble_array[i-1] = prev;
                flag = 1;
            }
            i--;
        }
    }

    //結果の出力
    i = 0;
    while(i < N){
        cout << bubble_array[i];
        if (i < N-1) cout << ' ';
        i++;
    }
    cout << endl;

    //安定かどうかの判定とその出力
    cout <<  "Stable" << endl;      //バブルソートは常に安定なソート


    //選択ソート
    for(i=0; i <= N-1; i++){
        min = i;
        for(j = i; j <= N-1; j++){
            if (select_array[j][1] < select_array[min][1]) min = j;
        }
        prev = select_array[i];
        select_array[i] = select_array[min];
        select_array[min] = prev;
    }

    //結果の出力
    i = 0;
    while(i < N){
        cout << select_array[i];
        if (i < N-1) cout << ' ';
        i++;
    }
    cout << endl;

    //安定かどうかの判定とその出力
    i = 0;
    while(i < N){
        if (bubble_array[i][0] != select_array[i][0]) judge = 1;
        i++;
    }
    if (judge == 0) cout << "Stable" << endl;
    else if (judge == 1) cout << "Not stable" << endl;


    return 0;
}

