void bubble(struct Card A[], int N) {
    for(int i = 0; i < N; i++)
    {
        for(int j = N -1; j >= i; j--)
        {
            if (A[j].value < A[j - 1].value) {
                auto t = A[j];
                A[j] = A[j - 1];
                A[j - 1] = t;
            }
        }
    }
}

void selection(struct Card A[], int N) {
    for(int i = 0; i < N; i++)
    {
        auto minj = i;
        for(int j = i; j < N; j++)
        {
            if (A[j].value < A[minj].value) {
                minj = j;
            }            
        }
        auto t = A[i];
        A[i] = A[minj];
        A[minj] = t;
    }
}

