using namespace std;

class Card {
public:
    char l;
    int n;

    Card(char l, int n) {
        this->l = l;
        this->n = n;
    }

    bool operator==(const Card &a) const {
        return n == a.n && l == a.l;
    }

    bool operator<(const Card &a) const {
        return n < a.n;
    }
};

void bubleSort(vector<Card> *a, int n) {
    int flag = true;
    while (flag) {
        flag = 0;
        for (int i = n - 1; i >= 1; i--) {
            if ((*a)[i].n < (*a)[i - 1].n) {
                swap((*a)[i], (*a)[i - 1]);
                flag = true;
            }
        }
    }
}

void selectionSort(vector<Card> *a, int n) {
    REP(i, n) {
        int minj = i;
        FOR(j, i, n) {
            if ((*a)[j].n < (*a)[minj].n)
                minj = j;
        }
        swap((*a)[i], (*a)[minj]);
    }
}

