  for (unsigned int i = 0u; i < n; ++i) {
    /*
    if (!(cards2[i].rank == cards1[i].rank &&
          cards2[i].suit == cards1[i].suit)) {
    */
    if (!cards2[i].same(cards1[i])) {
      std::cout << "Not stable" << std::endl;
      return 0;
