void trace(int N, Card A[]) {
    for(int i = 0; i < N; i++) {
        if(i >= 1) {
            cout << " ";
        }
        cout << A[i].suit << A[i].value;
    }
    cout << endl;
}

void swap(Card a[], int n1, int n2) {
    Card temp = a[n1];
    a[n1] = a[n2];
    a[n2] = temp;
}

void bubble_sort(int n, Card a[]) {
    for(int i = 0; i < n; i++) {
        for(int j = n - 1;  i!=j; j--) {
            if(a[j].value < a[j-1].value){
                swap(a, j-1, j);
            }
        }
    }
}

void selection_sort(int n, Card a[]) {
    for(int i =0;i<n;i++){
        int minj=i;
        for(int j=i;j<n;j++){
            if(a[minj].value > a[j].value){
                minj = j;
            }
        }
        swap(a,minj,i);
    }
}

bool is_stable(int n,Card a[], Card a2[]){
    for(int i=0;i<n;i++){
        if(a[i].suit!=a2[i].suit){
            return false;
        }
    }
    return true;
}

int main() {
    int n;
    cin >> n;
    Card a[n];
    Card a2[n];
    for(int i = 0; i < n; i++) {
        cin >> a[i].suit >> a[i].value;
        a2[i].value = a[i].value;
        a2[i].suit = a[i].suit;
    }

    bubble_sort(n,a);
    trace(n,a);
    cout << "Stable" << endl;
    selection_sort(n,a2);
    trace(n,a2);
    if(is_stable(n,a,a2)){
        cout << "Stable" << endl;
    }else{
        cout << "Not stable" << endl;
    }
}

#include <iostream>
#include <string>
#include <vector>
#include <cstdlib>

using namespace std;

int peek_number(string card) {
	return atoi(&card[1]);
}

vector<string> bubble_sort(vector<string> cards) {
	for (int i = 0; i < cards.size(); i++) {
		for (int j = cards.size() - 1; j >= 0; j--) {
			if (peek_number(cards[j]) < peek_number(cards[j - 1])) {
				string tmp = cards[j];
				cards[j] = cards[j - 1];
				cards[j - 1] = tmp;
			}
		}
	}

	return cards;
}

vector<string> selection_sort(vector<string> cards) {
	for (int i = 0; i < cards.size(); i++) {
		int min_idx = i;

		for (int j = i; j < cards.size(); j++) {
			if (peek_number(cards[j]) < peek_number(cards[min_idx])) {
				min_idx = j;
			}
		}

		string tmp = cards[i];
		cards[i] = cards[min_idx];
		cards[min_idx] = tmp;
	}

	return cards;
}

int index_of(vector<string> v, string target) {
	for (int i = 0; i < v.size(); i++) {
		if (v[i] == target) {
			return i;
		}
	}

	return -1;
}

bool is_stable(vector<string> unsorted, vector<string> sorted) {
	bool result = true;

	for (int i = 0; i < unsorted.size(); i++) {
		for (int j = 0; j < unsorted.size(); j++) {
			if (i == j) continue;
			if (peek_number(unsorted[i]) != peek_number(unsorted[j])) continue;

			int sorted_i = index_of(sorted, unsorted[i]);
			int sorted_j = index_of(sorted, unsorted[j]);

			if ((i < j && sorted_i < sorted_j) || (i > j && sorted_i > sorted_j)) continue;

			result = false;
			goto END;
		}
	}

	END:
		return result;			
}

void print_array(vector<string> v) {
	for (int i = 0; i < v.size(); i++) {
		if (i != 0) cout << " ";
		cout << v[i];
	}
	cout << endl;
}

int main() {
	int n;
	cin >> n;

	vector<string> cards(n);
	for (int i = 0; i < n; i++) cin >> cards[i];

	vector<string> bubble_sorted = bubble_sort(cards);
	vector<string> selection_sorted = selection_sort(cards);

	print_array(bubble_sorted);
	cout << (is_stable(cards, bubble_sorted) ? "Stable" : "Not stable") << endl;

	print_array(selection_sorted);
	cout << (is_stable(cards, selection_sorted) ? "Stable" : "Not stable") << endl;

	return 0;
}

