void bubbleSort(struct card C[], int n){
    bool flag = true;
    int i,j;
    i = 0;
    card temp;
    while (flag) {
        flag = false;
        for (j = n-1; j>i; j--){
            if (C[j].value < C[j-1].value){
                temp = C[j];
                C[j].value = C[j-1].value;
                C[j].suit = C[j-1].suit;
                C[j-1] = temp;
                flag = true;
            }
        }
        i++;
    }//End of while
}// End of bubble sort

void selectionSort(card C[], int n){
    int min;
    card temp;
    for (int i = 0; i<n; i++){
        min = i;
        for (int j = i; j<n; j++){
            if (C[j].value < C[min].value){
                min = j;
            }
        }
        temp = C[i];
        C[i] = C[min];
        C[min] = temp;
    }
}

