};

void bubbleSort(Node a[],int n)
{
   bool flag=true;
   while(flag)
   {
      flag=false;
      for(int j=n-1;j>0;j--)
      {
         if(a[j].d<a[j-1].d)
         {
             swap(a[j],a[j-1]);
             flag=true;
         }

      }
   }
}

void selectionSort(Node a[],int n)
{
   for(int i=0;i<n;i++)
   {
      int minJ=i;
      for(int j=i+1;j<n;j++)
      {
         if(a[minJ].d>a[j].d)
            minJ=j;
      }
      swap(a[i],a[minJ]);
   }
}

