void swap(int x,int y,struct card A[])
{
	struct card tmp;
	tmp=A[x];
	A[x]=A[y];
	A[y]=tmp;
}
void bubble(struct card A[],int n){
	int i,j;
	for(i=0;i<n;i++){
		for(j=n-1;j>i;j--){
			if(A[j].num<A[j-1].num)
				swap(j-1,j,A);
		}
	}
}
void selection(struct card A[],int n){
	int i,j,min;
	for(i=0;i<n;i++){
		min=i;
		for(j=i+1;j<n;j++){
			if(A[j].num<A[min].num)
				min=j;
		}
		if(min!=i)
			swap(min,i,A);
	}
}
bool isStable(struct card A[],struct card B[],int n){
	int i;
	for(i=0;i<n;i++){
		if(A[i].letter!=B[i].letter)
			return false;
	}
	return true;
}
