void BubbleSort(Card *C, int n){
    for(int i = 0; i < n; i++){
        for(int j = n - 1; j > i; j--){
            if(C[j].value < C[j-1].value){
                Card tmp = C[j];
                C[j] = C[j-1];
                C[j-1]= tmp;
            }
        }
    }
}

void SelectionSort(Card *C, int n){
    for(int i = 0; i < n; i++){
        int mini = i;
        for(int j = i; j < n; j++) if(C[j].value < C[mini].value) mini = j;
        if(i != mini){
            Card tmp = C[i];
            C[i] = C[mini];
            C[mini] = tmp;
        }
    }
}

bool isStable(Card *C1, Card *C2, int n){
    for(int i = 0; i < n; i++) if(C1[i].suit != C2[i].suit) return false;
    return true;
}

