#include<iostream>
#include<algorithm>

using namespace std;

typedef struct card
{
    char suit;
    char value;
}Card;

// バブルソートを実施する関数
void bubbleSort(Card A[], int n)
{
    Card tmp;

    int count = 0, j = 0;
    bool flag = true;

    while( flag )
    {
        flag = false;

        for(int i = n - 1; i > j; i--)
        {

            if( A[i - 1].value > A[i].value )
            {
                // 値の入れ替え
                tmp = A[i];
                A[i] = A[i - 1];
                A[i - 1] = tmp;

                flag = true;

                // 交換回数の保存
                count++;
            }
        }

        j++;
    }

    return;
}

// 選択ソートを実施する関数
void selectionSort(Card A[], int n)
{

    int count = 0;

    // 最小値の存在する配列の要素No.
    int min_pos;

    for(int i = 0; i < n - 1; i++)
    {
        min_pos = i;

        for(int j = i; j < n; j++)
        {

            if( A[j].value < A[min_pos].value )
            {
                // 最小値の存在する位置を保存する
                min_pos = j;
            }
        }

        if( i != min_pos )
        {
            // 最小値を交換する
            swap(A[i], A[min_pos]);

            count++;
        }
    }

    return;
}

