#include <iostream>
#include <algorithm>

using namespace std;

struct card {
	int num;
	char ch;
};

void show(card cd[], int n) {
	for (int i = 0; i < n - 1; i++)
		cout << cd[i].ch<<cd[i].num << " ";
	cout << cd[n - 1].ch<< cd[n - 1].num << endl;
}
void insertionSort(card cd[],int n) {
	int j;
	card v;
	for (int i = 1; i < n; i++) {
		v = cd[i];
		j = i - 1;
		while (j >= 0 && cd[j].num > v.num) {
			cd[j + 1] = cd[j];
			j--;
		}
		cd[j + 1] = v;
	}
}

void stable(card cd_1[], card cd_2[], int n) {
	int i = 0;
	while (cd_1[i].ch == cd_2[i].ch) {
		if (i >= n - 1)
			break;
		i++;
	}
	if (i == n - 1)
		cout << "Stable" << endl;
	else
		cout << "Not stable" << endl;
}

void bubbleSort(card cd[], int n) {
	bool f = true;
	while (f) {
		f = false;
		for (int i = n - 1; i >= 1; i--)
			if (cd[i].num < cd[i - 1].num) {
				swap(cd[i],cd[i-1]);
				f = true;
			}
	}
}

void selsctionSort(card cd[], int n) {
	int minj;
	for (int i = 0; i < n - 1; i++) {
		minj = i;
		for (int j = i + 1; j < n; j++) {
			if (cd[j].num < cd[minj].num)
				minj = j;
		}
		if (i != minj) {
			swap(cd[i], cd[minj]);
		}
	}
}

int main() {
	card cd[100];
	card cd_m[100];
	card cd_t[100];
	int n;
	cin >> n;
	for (int i = 0; i < n; i++) {
		cin >> cd[i].ch >> cd[i].num;
		cd_t[i] = cd_m[i] = cd[i];
	}

	insertionSort(cd_m, n);

	bubbleSort(cd, n);
	show(cd, n);
	stable(cd, cd_m, n);

	for (int i = 0; i < n; i++)
		cd[i] = cd_t[i];

	selsctionSort(cd, n);
	show(cd, n);
	stable(cd, cd_m, n);
	return 0;
}

#include<cstdio>
#include<algorithm>

#define MAX_SIZE 36

struct Tramp{
  char mark;
  int number;
};

void bubble_sort(Tramp array[], int size) {
  for(int i = 0; i < size - 1; i++) {
    for(int j = size - 1; j > i; j--) {
      if(array[j].number < array[j - 1].number) {
        std::swap(array[j - 1], array[j]);
      }
    }
  }
}

void selection_sort(Tramp array[], int size) {
  for(int i = 0; i < size - 1; i++) {
    int min_index = i;
    for (int j = i + 1; j < size; j++) {
      if(array[j].number < array[min_index].number) {
        min_index = j;
      }
    }

    if(i != min_index) {
      std::swap(array[i], array[min_index]);
    }
  }
}

bool check_selection_stable(Tramp bubble[], Tramp selection[], int size) {
  for(int i = 0; i < size; i++) {
    if(
      selection[i].mark != bubble[i].mark ||
      selection[i].number != bubble[i].number
    ) {
      return false;
    }
  }
  return true;
}

void print_tramp(Tramp tramps[], int size) {
  for(int i = 0; i < size; i++) {
    printf("%c%d", tramps[i].mark, tramps[i].number);
    if(i != size - 1) {
      printf(" ");
    }
  }
  printf("\n");
}

int main() {
  int size;
  Tramp bubble_array[MAX_SIZE], selection_array[MAX_SIZE];
  scanf("%d%*c", &size);

  for(int i = 0; i < size; i++) {
    scanf("%c%d ", &bubble_array[i].mark, &bubble_array[i].number);
    selection_array[i].mark = bubble_array[i].mark;
    selection_array[i].number = bubble_array[i].number;
  }

  bubble_sort(bubble_array, size);
  selection_sort(selection_array, size);

  print_tramp(bubble_array, size);
  printf("Stable\n");
  print_tramp(selection_array, size);

  bool is_selection_stable = check_selection_stable(bubble_array, selection_array, size);
  if(is_selection_stable) {
    printf("Stable\n");
  } else {
    printf("Not stable\n");
  }

}

