using namespace std;
template<typename T> inline bool chmax(T& a,T b) { if (a < b) { a = b; return true; } return false; }
template<typename T> inline bool chmin(T& a,T b) { if (a > b) { a = b; return true; } return false; }
const int INF = 1e9;

template<typename T> vector<T> Bubble(vector<T> A) {
    int N = A.size();
    for (int i = 0; i < N; i++) {
        for (int j = N-1; j > i; j--) {
            if (A[j].first < A[j-1].first) swap(A[j], A[j-1]);
        }
    }
    return A;
}

template<typename T> vector<T> Selection(vector<T> A) {
    int N = A.size();
    for (int i = 0; i < N; i++) {
        int mn = i;
        for (int j = i; j < N; j++) {
            if (A[j].first < A[mn].first) mn = j;
        }
        swap(A[i], A[mn]);
    }
    return A;
}

template<typename T> vector<T> stablesort(vector<T> A) {
    int N = A.size();
    vector<T> res(N);
    vector<bool> use(N, false);
    for (int p = 0; p < N; p++) {
        int mn = -1, value = INF;
        for (int i = 0; i < N; i++) if (!use[i]) { mn = i; break; }
        for (int i = 0; i < N; i++) if (!use[i]) {
            if (chmin(value, A[i].first)) mn = i;
        }
        res[p] = A[mn]; use[mn] = true;
    }
    return res;
}

