#include <cstdio>
#include <iostream>
#include <vector>

class Card {
    public:
        Card() {};
        char suit;
        int value;
};

void swap(Card* a, Card* b)
{
    Card tmp;
    tmp.suit = a->suit;
    tmp.value = a->value;
    a->suit = b->suit;
    a->value = b->value;
    b->suit = tmp.suit;
    b->value = tmp.value;
}

void do_bubble_sort(std::vector<Card>& data)
{
    for(int i = 0; i < data.size() - 1; i++) {
        for(int j = 0; j < data.size() - i - 1; j++) {
            if(data[j + 1].value < data[j].value) {
                swap(&data[j], &data[j + 1]);
            }
        }
    }
}

void do_selection_sort(std::vector<Card>& data)
{
    int min_index;
    for(int i = 0; i < data.size() - 1; i++) {
        min_index = i;
        for(int j = i + 1; j < data.size(); j++) {
            if(data[j].value < data[min_index].value) {
                min_index = j;
            }
        }
        if(min_index != i) {
            swap(&data[i], &data[min_index]);
        }
    }
}

void show_data(std::vector<Card>& data)
{
    printf("%c%d", data[0].suit, data[0].value);
    for(int i = 1; i < data.size(); i++) {
        printf(" %c%d", data[i].suit, data[i].value);
    }
    puts("");
}

bool is_accidentally_stable(std::vector<Card>& stable_data, std::vector<Card>& unstable_data)
{
    for(int i = 0; i < stable_data.size() && i < unstable_data.size(); i++) {
        if(stable_data[i].suit != unstable_data[i].suit) {
            return false;
        }
    }
    if(stable_data.size() == unstable_data.size()) {
        return true;
    } else {
        return false;
    }
}

int main()
{
    int input_size;
    std::cin >> input_size;
    std::vector<Card> data1(input_size);
    std::vector<Card> data2(data1.size());
    for(int i = 0; i < data1.size(); i++) {
        std::cin >> data1[i].suit >> data1[i].value;
    }
    std::copy(data1.begin(), data1.end(), data2.begin());

    do_bubble_sort(data1);
    do_selection_sort(data2);

    show_data(data1);
    puts("Stable");
    show_data(data2);
    if(is_accidentally_stable(data1, data2)) {
        puts("Stable");
    } else {
        puts("Not stable");
    }

    return 0;
}

