#define arr_print_card(a, n) for(int i=0;i<(n);++i)printf(i==(n)-1?"%c%d\n":"%c%d ",(a)[i].symbol, (a)[i].num)

typedef struct Card {
    char symbol;
    int num;

    bool operator<(const Card &right) const {
        return num < right.num;
    }

    bool operator!=(const Card &right) const {
        return symbol != right.symbol || num != right.num;
    }
} Card;

void bubble_sort(Card *a, const int N) {
    for(int i = 0; i < N; ++i) {
        for(int j = N - 1; j > i; --j) {
            if(a[j] < a[j - 1]) {
                Card tmp = a[j];
                a[j] = a[j - 1];
                a[j - 1] = tmp;
            }
        }
    }
}

void selection_sort(Card *a, const int N) {
    for(int i = 0; i < N; ++i) {
        int minj = i;
        for(int j = i + 1; j < N; ++j) {
            if(a[j] < a[minj]) minj = j;
        }
        if(i != minj) {
            Card tmp = a[i];
            a[i] = a[minj];
            a[minj] = tmp;
        }
    }
}

bool arr_cmp(Card *a, Card *b, const int N) {
    for(int i = 0; i < N; ++i) {
        if(a[i] != b[i]) return false;
    }
    return true;
}

