    bubble_sort(a, n);
    selection_sort(b, n);

    arr_print_card(a, n);
    printf("Stable\n");
    arr_print_card(b, n);
    printf(arr_cmp(a,b,n)?"Stable\n":"Not Stable\n");
    return 0;
}

