void bubbleSort(Card c[], int n) {
  for (int i = 0; i < n; i++) {
    for (int j = n - 1; j > i ; j--) {
      if (c[j].value < c[j-1].value) {
        swap(c[j], c[j-1]);
      }
    }
  }
}

void selectionSort(Card c[], int n) {
  for (int i = 0; i < n; i++) {
    int mini = i;

    for (int j = i; j < n; j++) {
      if (c[j].value < c[mini].value) {
        mini = j;
      }
    }

    if (i != mini) {
      swap(c[i], c[mini]);
    }
  }
}

