void insertSort(poker arr[],int n)
{
    int j;
    poker v;
    for(int i = 1;i<n;i++)
    {
        v = arr[i];
        j = i-1;
        while(j >= 0 && arr[j].value > v.value)
        {
            arr[j+1] = arr[j];
            j--;
        }
        arr[j+1] = v;
    }
}
void selectionSort(poker arr[],int n)
{
    for(int i = 0;i<n-1;i++)
    {
        int key = i;
        bool flag = 0;
        for(int j =i+1;j<n;j++)
            if(arr[j].value<arr[key].value)
            {
                key = j;
                flag = 1;
            }
        if(flag)
            swap(arr[i],arr[key]);
    }
}
