    while(flag){
        flag = 0;
        for(int j = 1; j < N; j++){
            if(A[j].value < A[j - 1].value){
                swap(A[j], A[j - 1]);
                flag = 1;
                count += 1;
            }
        }
    }
    return count;
}

int selectionSort(card* A, int N){
    int count = 0;
    for(int i = 0; i < N; i++){
        int minj = i;
