#include <stdio.h>
#define TRUE 1
#define FALSE 0

int N;

typedef struct{
  char mark;
  int value;
} trump;

/* 値をいれかえる関数*/
void swap(trump *a, trump *b){
  trump tmp;

  tmp = *a;
  *a = *b;
  *b = tmp;
}

void BubblleSort(trump C[]){
    int i,j;

    for(i=0; i<N-1; i++){
      for(j=N-1; j>=i+1; j--){
        if(C[j].value < C[j-1].value) 
          swap(&C[j],&C[j-1]);
      }
    }
}

void SelectionSort(trump C[]){
  int i,j;
  int minj;

  for(i=0; i<N; i++){
    minj = i;
    for(j=i; j<N; j++){
      if(C[j].value < C[minj].value)
        minj = j;
    }

    swap(&C[i],&C[minj]);
  }
}

/* ソートの結果を出力する関数*/

void Allprint(trump C[]){
  int i;

  for(i=0; i<N; i++){
    if(i != 0) printf(" ");
    printf("%c%d",C[i].mark,C[i].value);
  }
  printf("\n");
}

/*安定かどうかを調べ、安定ならTRUE(1)を、そうでないならFALSE(0)を返す関数*/

int check_stable(trump in[],trump out[]){
  int i,j,k,l;
  for(i=0; i<N; i++){
    for(j=i+1; j<N; j++){
      for(k=0; k<N; k++){
        for(l=k+1; l<N; l++){
          if(in[i].value == in[j].value
             && in[i].value == out[l].value 
             && in[i].mark == out[l].mark 
             &&in[j].value == out[k].value
             &&in[j].mark == out[k].mark)
            return FALSE;
        }
      }
    }
  }

  return TRUE;
}


