  for(i=0; i<N; i++){ 
    scanf(" %c%d",&in[i].mark,&in[i].value);
  }

  /*バブルソート、選択ソートをした結果をそれぞれ保存する配列を用意する*/
  for(i=0; i<N; i++){
    bubble[i] = in[i];
    selection[i] = in[i];
  }

  /*バブルソートの結果と安定かどうか出力する*/
  BubblleSort(bubble);
  Allprint(bubble);
  if( check_stable(in,bubble) ) printf("Stable\n");
  else printf("Not stable\n");

  /*選択ソートの結果と安定かどうか出力する*/
  SelectionSort(selection);
  Allprint(selection);
  if(check_stable(in,selection)) printf("Stable\n");
  else printf("Not stable\n");

  return 0;

}

