void bubble_sort(struct Card *card,int n){
        int i,j;
        int a,b;
        Card tmp;
        for(i=0;i<n-1;i++){
                for(j=n-1;j>i;j--){
                        a=j;
                        b=j-1;
                        if(card[b].num>card[a].num){
                                tmp=card[b];
                                card[b]=card[a];
                                card[a]=tmp;
                        }
                }
        }

}

void selection_sort(struct Card *card,int n){
        int i,j;
        int minj;
        Card tmp;
        for(i=0;i<n;i++){
                minj=i;
                for(j=i;j<n;j++){
                        if(card[j].num<card[minj].num){
                                minj=j;
                        }
                }
                tmp=card[i];
                card[i]=card[minj];
                card[minj]=tmp;
        }
}

