void bubbleSort(Card A[], int N)
{
	int flg = 1;
	int replace = 0;

	while (flg)
	{
		flg = 0;
		for (int i = N - 1; i>0; i--)
		{
			if (A[i].value < A[i - 1].value)
			{
				swap(A[i], A[i - 1]);
				replace++;
				flg = 1;
			}
		}
	}
}

void selectSort(Card A[], int N)
{
	int min;
	int replace = 0;


	for (int i = 0; i < N; i++)
	{
		min = i;
		for (int j = i; j < N; j++)
		{
			if (A[min].value > A[j].value) 
			{
				min = j;

			}
		}
		if (min != i) 
		{
			swap(A[min], A[i]);
			replace++;
		}
	}
}

