    for (int i = 0; i < n; i++) cin >> r[i];

    memcpy(r1, r, sizeof(r));
    bubbleSort(r1, n); // stable
    trace(r1, n);
    stableOrNot(r, r1, n);

    memcpy(r2, r, sizeof(r));
    selectionSort(r2, n); // not stable
    trace(r2, n);
    stableOrNot(r, r2, n);
    return 0;
}

