void Bubble_Sort(char a[],char b[],int n)  //基于flag的冒泡排序 升序   
{
	char temp;
	bool flag = 1; 	//当一趟扫描不存在逆序数的时候，合理的剪枝。 
	for(int i=1;flag;i++){
		flag=0;
	for(int j=0;j<n-i;j++)
	{
		if(b[j]>b[j+1])
		{
			temp = a[j];
			a[j] = a[j+1];
			a[j+1]= temp;
			temp = b[j];
			b[j] = b[j+1];
			b[j+1]= temp;
			flag=1;
		 } 
	}
}
}

void Selection_Sort(char a[],char b[],int n)	//选择排序 
{
	int minj;
	for(int i=0;i<n;i++)
	{
		minj=i ;
	for(int j=i+1;j<n;j++)
	{
		if(b[j]<b[minj])
		{
			minj = j;
		}
	}
	if(i!=minj) 
	{
		swap(a[i],a[minj]);
		swap(b[i],b[minj]); 
	}
	}
}

int isStable(char a[],char b[],char c[],char d[],int n)
{
	for(int i=0;i<n;i++)
	{
		if(a[i]!=c[i])
		{
			cout<<"Not stable"<<endl;
			return 0;
		}
		else if(b[i]!=d[i])
		{
			cout<<"Not stable"<<endl;
			return 0;
		}

	}
	cout<<"Stable"<<endl;
	return 0;
}

