vector<string> bubbleSort(vector<string>& a, int n) {
    vector<string> b(a.size());
    copy(a.begin(), a.end(), b.begin());
    for (int i=0; i<n; i++) {
        for (int j=n-1; j>0; j--) {
            if (b[j][1] < b[j-1][1]) {
                swap(b[j], b[j-1]);
            }
        }
    }
    for (int i=0; i<n-1; i++) cout << b[i] << " ";
    cout << b[n-1] << endl;

    return b;
}

vector<string> selectionSort(vector<string>& a, int n) {
    vector<string> b(a.size());
    copy(a.begin(), a.end(), b.begin());
    for (int i=0; i<n; i++) {
        int min_j = i;
        for (int j=i; j<n; j++) {
            if (b[j][1] < b[min_j][1]) {
                min_j = j;
            }
        }
        swap(b[i], b[min_j]);
    }
    for (int i=0; i<n-1; i++) cout << b[i] << " ";
    cout << b[n-1] << endl;

    return b;
}

bool isStable(vector<string>& a, vector<string>& b, int n) {
    for (int i=0; i<n; i++) {
        for (int j=i+1; j<n; j++) {
            for (int x=0; x<n; x++) {
                for (int y=x+1; y<n; y++) {
                    if (a[i][1] == a[j][1] && a[i] == b[y] && a[j] == b[x]) {
                        return false;
                    }
                }
            }
        }
    }
    return true;
}

