	for (int i = 1; i < N; i++) {
		int val = A[i];
		char cval = B[i];
		int j = i - 1;
		while (j >= 0 && A[j] > val) {
			A[j + 1] = A[j];
			B[j + 1] = B[j];
			j--;
		}
		A[j + 1] = val;
		B[j + 1] = cval;
	}
}

