	for (int i = 0; i < N - 1; i++) {
		for (int j = N - 1; i < j; j--) {
			if (A[j - 1] > A[j]) {
				swap(A[j - 1], A[j]);
				swap(B[j - 1], B[j]);
			}
		}
	}
}

