	int min_index=0;
	for(int i=0; i<array_size-1; i++){
		min_index=i;
		for(int j=i+1; j<array_size; j++){
			if(array[j].number<array[min_index].number){
				min_index=j;
			}
		}
		swap(&array[min_index],&array[i]);
	}
}

