    cin >> A.at(i);
  }

  // Compute
  // Bubble sort
  vector<string> A_bs(N);
  A_bs = A;
  string temp;
  for (int i = 0; i < N; i++) {
    for (int j = N - 1; j > i; j--) {
      if (str2i(A_bs.at(j-1)) > str2i(A_bs.at(j))) {
        temp = A_bs.at(j-1);
        A_bs.at(j-1) = A_bs.at(j);
        A_bs.at(j) = temp;
      }
    }
  }
  for (int i = 0; i < N; i++) {
    if (i != 0) {
      cout << " ";
    }
    cout << A_bs.at(i);
  }
  cout << endl;
  cout << "Stable" << endl;

  // Selection sort
  vector<string> A_ss(N);
  A_ss = A;
  int min_j;
  for (int i = 0; i < N; i++) {
    min_j = i;
    for (int j = i; j < N; j++) {
      if (str2i(A_ss.at(j)) < str2i(A_ss.at(min_j))) {
        min_j = j;
      }
    }
    temp = A_ss.at(i);
    A_ss.at(i) = A_ss.at(min_j);
    A_ss.at(min_j) = temp;
  }

  for (int i = 0; i < N; i++) {
    if (i != 0) {
      cout << " ";
    }
    cout << A_ss.at(i);
  }
  cout << endl;

  if (A_ss == A_bs) {
    cout << "Stable" << endl;
  }
  else {
    cout << "Not stable" << endl;
  }
}

