struct Card {
	char c;
	int v;
};
bool operator ==(Card c1, Card c2) {
	if ((c1.c == c2.c) && (c1.v = c2.v))
		return true;
	else
		return false;
}
bool operator !=(Card c1, Card c2) {
	if ((c1.c != c2.c) || (c1.v != c2.v))
		return true;
	else
		return false;
}
void Copy(Card c1[], Card c2[], int n) {
	for (int i = 0; i < n; i++) {
		c1[i].c= c2[i].c;
		c1[i].v = c2[i].v;
	}
}
void Bubble(Card c[], int n) {
	for (int i = 0; i < n; i++) {
		for (int j = n - 1; j > i; j--) {
			if (c[j].v < c[j - 1].v)
				swap(c[j], c[j - 1]);
		}
	}
}
void Selection(Card c[], int n) {
	for (int i = 0; i < n; i++) {
		int minv = i,flag=0;
		for (int j = i; j < n; j++) {
			if (c[minv].v > c[j].v) {
				minv = j;
				flag = 1;
			}
		}
		if (flag)
			swap(c[i], c[minv]);
	}
}
void Print(Card c[], int n) {
	for (int i = 0; i < n; i++) {
		cout << c[i].c << c[i].v;
		if (i != n)
			cout << ' ';
	}
	cout << endl;
}
int ISstable(Card in[], Card out[],int n) {
	for (int i = 0; i < n; i++) {
		for (int j = i + 1; j < n; j++) {
			for (int a = 0; a < n; a++) {
				for (int b = a + 1; b < n; b++) {
					if ((in[i].v == in[j].v) && (in[i] == out[b]) && (in[j] == out[a])) {
						cout << "Not stable" << endl;
						return 0;
					}
				}
			}
		}
	}
	cout << "Stable" << endl;
	return 0;
}
int ISstable1(Card b[], Card s[], int n) {
	for (int i = 0; i < n; i++) {
		if (b[i] != s[i]) {
			cout << "Not stable" << endl;
			return 0;
		}
	}
	cout << "Stable" << endl;
	return 0;
}
