        flag = false;
        for (j = num - 1; j > i; j--) {
            if ((pCard + j)->iNum < (pCard + j - 1)->iNum) {
                swap(*(pCard + j), *(pCard + j - 1));
                flag = true;
            }
        }
        if (flag == false) {
            break;
        }
    }

    return;
}

