{
    int i, j;
    int min;

    for (i = 0; i < num; i++) {
        min = i;
        for (j = i + 1; j < num; j++) {
            if ((pCard + min)->iNum > (pCard + j)->iNum) {
                min = j;
            }
        }
        if (min != i) {
            swap(*(pCard + i), *(pCard + min));
        }
    }

    return;
}

