#include <iostream>
#include <cstdlib>

#define ELEMENT_NUM_MAX 10
#define MAX 36
#define BUFSIZE 128
#define CARD_VAL_STR_SIZE 4

/**
*カードの情報を格納する構造体
*カードは一文字のアルファベットと1~9の数字からなる
*例)D5
*/
typedef struct Card
{
    char cCardType;     /*カードの種類(1文字):H,S,C,D*/
    int iCardVal;       /*カードの値(1~9)*/
    int iInputOrder;    /*入力順序*/
}Card;


/*関数のプロトタイプ宣言*/
int IntegerInputByGetline(void);
void CardReader(Card* ptCard);
void BubbleSort(Card* ptCard, int iEleNum);
void SelectionSort(Card* ptCard, int iEleNum);
void SwapCards(Card* ptCardX, Card* ptCardY);
void StabilityCheck(Card* ptCard, int iEleNum);
void DisplayCards(Card* ptCard, int iEleNum);
void CopyCards(Card* ptCard, Card* ptCopy, int EleNum);

/**
*関数名:Main
*機能:
*/

int main( void )
{
    Card atBufCard[MAX] = { {0} };
    Card atBufCardCopy[MAX] = { {0} };

    /*次のCardReaderでもgetlineを使用するので、改行、空白の取り扱いのためstd::cinではなくgetlineを使用*/
    int iEleNum = IntegerInputByGetline(); 

    CardReader(atBufCard);

    CopyCards(atBufCard, atBufCardCopy, iEleNum);

    BubbleSort(atBufCardCopy, iEleNum);

    CopyCards(atBufCard, atBufCardCopy, iEleNum);

