#include <bits/stdc++.h>
using namespace std;

void bubbleSort(vector<tuple<string, int>>& C, int N) {
  for (int i = 0; i < N - 1; i++) {
    for (int j = N - 1; j > i; j--) {
      if (get<1>(C.at(j)) < get<1>(C.at(j - 1))) {
        swap(C.at(j), C.at(j - 1));
      }
    }
  }
}

void selectionSort(vector<tuple<string, int>>& C, int N) {
  for (int i = 0; i < N - 1; i++) {
    int minJ = i;
    for (int j = i + 1; j < N; j++)
      if (get<1>(C.at(j)) < get<1>(C.at(minJ))) minJ = j;
    swap(C.at(i), C.at(minJ));
  }
}

bool isStable(vector<tuple<string, int>> original,
              vector<tuple<string, int>> sorted, int N) {
  for (int i = 1; i < 10; i++) {
    vector<char> types;
    for (auto o : original) {
      if (get<1>(o) == i) types.push_back(get<0>(o).at(0));
    }
    int j = 0;
    for (auto s : sorted) {
      if (get<1>(s) == i) {
        char type = get<0>(s).at(0);
        if (type != types.at(j)) return false;
        j++;
      }
    }
  }
  return true;
}

