int out_card(vector<card> &A,int n){
	int i;
	for (i=0;i<=n-2;i++){
		cout << A[i].suit << A[i].num <<" ";
	}
	cout << A[n-1].suit << A[n-1].num <<endl;
}

void BubbleSort(vector<card> &A, int n){
	int i,j;
	for (i=0;i<n;i++){
		for (j=n-1;j>i;j--){
			if (A[j].num < A[j-1].num){
				swap(A[j],A[j-1]);
			}
		}
	}
}

void SelectSort(vector<card> &A, int n){
	int i,j,minj;
	for(i=0;i<n;i++){
		minj=i;
		for (j=i;j<n;j++){
			if (A[j].num<A[minj].num){
				minj=j;
			}
		}
		swap(A[i],A[minj]);
	}
}

