bool check( vector<pair<char, char>> &in, vector<pair<char, char>> &out, int N )
{
	for( int i = 0; i < N; i++ ) {
		for( int j = i + 1; j < N; j++ ) {
			for( int a = 0; a < N; a++ ) {
				for( int b = a + 1; b < N; b++ ) {
					if( in[i].second == in[j].second && in[i] == out[b] && in[j] == out[a] ) {
						return false;
					}
				}
			}
		}
	}
	return true;
}

