void BubbleSort(std::vector<Card> &c, int n)
{
    for (int i = 0; i < n; i++) {
        for (int j = n - 1; j > i; j--) {
            if (c[j].value < c[j - 1].value) {
                Card tmp = c[j];
                c[j] = c[j - 1];
                c[j - 1] = tmp;
            }
        }
    }
}

void SelectionSort(std::vector<Card> &c, int n)
{
    for (int i = 0; i < n; i++) {
        int minj = i;
        for (int j = i; j < n; j++) {
            if (c[j].value < c[minj].value) {
                minj = j;
            }
        }

        Card tmp = c[i];
        c[i] = c[minj];
        c[minj] = tmp;
    }
}

