#include<iostream>
#include<cstdio>

using namespace std;

const int maxn = 36;

struct task
{
    char name;
    int time;
};
struct task T1[maxn] , T2[maxn];

void BubbleSort (struct task A[] , int n)
{
    for (int i = 1 ; i < n ; i ++){
        for (int j = n ; j >= i + 1 ; j --){
            if (A[j].time < A[j - 1].time){
                task t = A[j];
                A[j] = A[j - 1];
                A[j - 1] = t;
            }
        }
    }
}

void InsertSort(struct task A[] , int n)
{
    for (int i = 1 ; i <= n ; i ++){
        int minA = A[i].time;
        int minj = i;
        for (int j = i + 1 ; j <= n ; j ++){
            if (A[j].time < minA){
                minA = A[j].time;
                minj = j;
            }
        }
        if (minj != i){
            task t = A[i];
            A[i] = A[minj];
            A[minj] = t;
        }
    }
}

bool Stability (struct task T1[] , struct task T2[] , int n)
{
    for (int i = 1 ; i <= n ; i ++){
        if (T1[i].name != T2[i].name)
            return false;
    }
    return true;
}

void print (struct task A[] , int n)
{
    for (int i = 1 ; i <= n ; i ++){
        cout << A[i].name << A[i].time;
        if (i != n)
            cout << " ";
    }
    cout << endl;
}

int main()
{
    int n ;
    while (scanf("%d",&n)!= EOF){
        for (int i = 1 ; i <= n ; i ++){
            cin >> T1[i].name >> T1[i].time;
            T2[i] = T1[i];
        }

        BubbleSort(T1 , n);
        print(T1 , n);
        cout << "Stable" << endl;
        InsertSort(T2 , n);
        print(T2 , n);
        if (Stability(T1 , T2 , n))
            printf("Stable\n");
        else
            printf("Not stable\n");
    }
    return 0;
}

