void BubbleSort(Trump x[], int N) {
    for(int i = 0; i < N; i++){
        for(int j = N - 1; j >= i; j--){
            if(x[j].value < x[j-1].value){
                swap(x[j], x[j-1]);
            }
        }
    }
}

void SelectionSort(Trump x[], int N){
    for(int i = 0; i < N; i++){
        int minj = i;
        for(int j = i; j < N; j++){
            if(x[minj].value > x[j].value){
                minj = j;
            }
        }
        swap(x[minj], x[i]);
    }
}

void trace(Trump x[], int N){
    int i;
    for(i = 0; i < N - 1; i++){
        cout << x[i].suit << x[i].value << " ";
    }
    cout << x[i].suit << x[i].value << endl;
}

