template<class T>
void bubbleSort(T* array, int size)
{
        for(int i=size; i>0; i--){
                for(int j=0; j<i-1; j++){
                        if( array[j].n > array[j+1].n ){
                                T tmp = array[j+1];
                                array[j+1] = array[j];
                                array[j] = tmp;
                        }
                }
        }
}

template<class T>
void selectionSort(T* array, int size)
{
        int min;
        for(int i=0; i<size-1; i++){
                min = i;
                for(int j=i+1; j<size; j++){
                        if( array[j].n < array[min].n ){ min = j; }
                }
                T tmp;
                if( min != i){
                        tmp = array[min];
                        array[min] = array[i];
                        array[i] = tmp;
                }
        }
}



