{
  vector<string> vo = vs;


  int mi;

  REP(i,N)
    {
      mi = i;

      FOR(j,i+1,N)
	{
	  if( val(vo[j]) < val(vo[mi]) )
	    {
	      mi = j;

	    }


	}

      swap(vo[i],vo[mi]);


    }

  return vo;




}


