void Selection_sort(struct Card A[], int N) {
    int tmp_minj, minj, j;
    for (int i=0; i<N; i++) {
        minj = i;
        tmp_minj = i;
        for (j=i; j<N; j++) {
            if (A[j].value < A[minj].value) { minj = j; }
        }
        if (tmp_minj != minj) { 
            swap(A[i].suit, A[minj].suit);
            swap(A[i].value, A[minj].value);
            }
    }
}

void BubbleSort(struct Card A[], int n) {
    int flag = 1;
    while (flag == 1) {
        flag = 0;
        for (int j=n-1; j>0; j--){
            if ( A[j].value < A[j-1].value ){
                swap(A[j].suit, A[j-1].suit);
                swap(A[j].value, A[j-1].value); 
                flag = 1;
            }
        }
    }
}

