#include <iostream>
using namespace std;

struct Card {
  char mark;
  int value;
};

int bubbleSort(Card card[], int n) {
  int count = 0;
  Card tmpc;
  for (int i = 0; i < n; ++i) {
    for (int j = n - 1; j > i; --j) {
      if (card[j].value < card[j - 1].value) {
        tmpc = card[j];
        card[j] = card[j - 1];
        card[j - 1] = tmpc;
        count++;
      }
    }
  }
  return count;
}

int selectionSort(Card card[], int n) {
  int count = 0;
  Card tmpc;
  for (int i = 0; i < n; ++i) {
    int minj = i;
    for (int j = i; j < n; ++j) {
      if (card[j].value < card[minj].value) {
        minj = j;
      }
    }
    if (i != minj) {
      tmpc = card[i];
      card[i] = card[minj];
      card[minj] = tmpc;
      count++;
    }
  }
  return count;
}

bool isStable(struct Card bS[], struct Card sS[], int n) {
  for (int i = 0; i < n; ++i) {
    if (bS[i].mark != sS[i].mark || bS[i].value != sS[i].value)
      return false;
  }
  return true;
}

