  {
    for(int j=N-1;j>i;j--)
    {
      if(si[j]<si[j-1])
      {
        swap(si[j],si[j-1]);
        swap(sc[j],sc[j-1]);
      }
    }
  }
}

void selection(int si[],char sc[],int N)
{
  for(int i=0;i<N;i++)
  {
    int mini = i;
    for(int j=i;j<N;j++)
    {
      if(si[j]<si[mini]) mini=j;
    }
    swap(si[i],si[mini]);
    swap(sc[i],sc[mini]);
  }
}

