void BubbleSort(int n,int x[],string y[]){
    int flag = 1;
    int ok = 0;

    while(flag) {
        flag = 0;
        for(int i=n-1 ; i>=ok+1 ; i--){
            if(x[i] < x[i-1]) {
                swap(x[i],x[i-1]);
                swap(y[i],y[i-1]);
                flag = 1;
            }
        }
        ok++;
    }

    rep(i,n) cout << y[i] << (i != n-1 ? ' ': '\n');
    return;
 }

void SelectSort(int n,int x[],string y[]){
    rep(i,n){
        int minj = i;
        for(int j=i ; j<n ; j++){
            if(x[minj]>x[j]) minj = j;
        }
        if(x[i]>x[minj]) {
            swap(x[i],x[minj]);
            swap(y[i],y[minj]);
        }
    }
    rep(i,n) cout << y[i] << (i != n-1 ? ' ': '\n');
    return;
}

string check(int n,string x[] , string y[]){
    bool flag = 1;
    rep(i,n){
        if(x[i] != y[i]) flag = 0;
    }
    return(flag ? "Stable" : "Not stable");
}

