			for (int j = 0, k = 0; j < N && k <= 1; j++) {
				if (after[i] == c[j]) {
					if (cafter[i + k] == cc[j]) k++;
					else { flag = 0; break; }
				}
			}
		}
	}
	if (flag == 1) cout << "Stable" << endl;
	else cout << "Not stable" << endl;
}

