};

bool operator==(const Card& lhs, const Card& rhs) {
    return (lhs.suit == rhs.suit && lhs.value == rhs.value);
}

bool isStable(Card in[], Card out[], int N) {
    for (int i = 0; i < N; i++) {
        for (int j = i+1; j < N; j++) {
            for (int a = 0; a < N; a++) {
                for (int b = a+1; b < N; b++) {
                    if (in[i].value == in[j].value && in[i] == out[b] && in[j] == out[a]) {
                        return false;
                    }
                }
            }
        }
    }
    return true;
}

