void bubbleSort(Card C1[], int n){
	int flag = 1;
	for(int i=0; flag; i++){
		flag = 0;
		for (int j=n-1; j>i; j--){
			if(C1[j].value < C1[j-1].value){
				Card t = C1[j];
				C1[j] = C1[j-1];
				C1[j-1] = t;
				flag = 1;
			}
		}
	}
	printList(C1, n);
}
void selectionSort(Card C2[], int n){
	for(int i=0; i<n; i++){
		int minj = i;
		for(int j=i; j<n; j++){
			if(C2[j].value < C2[minj].value)
				minj = j;
		}
		if(minj != i){
			Card t = C2[i];
			C2[i] = C2[minj];
			C2[minj] = t;
		}
	}
	printList(C2, n);
}
