#include <iostream>
#include <algorithm>
#include <string>

using namespace std;

class Stability
{
 public:
  void solve( int n, string bsa[], string ssa[] );
  void bubblesort( int n, string a[]);
  void selectionsort( int n, string a[]);
};

void Stability::solve( int n, string bsa[], string ssa[] )
{
  bool stability_check = true;

  bubblesort( n, bsa );
  selectionsort( n, ssa );

  cout << bsa[0];
  for( int i = 1; i < n; i++ )
    {
      cout << " " << bsa[i];
    }
  cout << endl;
  cout << "Stable" << endl;

  cout << ssa[0];
  for( int i = 1; i < n; i++ )
    {
      cout << " " << ssa[i];
    }
  cout << endl;

  for( int i = 0; i < n; i++ )
    {
      if( bsa[i] != ssa[i] )
        stability_check = false;
    }

  if( stability_check )
    cout << "Stable" << endl;
  else
    cout << "Not stable" << endl;
}

void Stability::bubblesort( int n, string a[] )
{
  for( int i = 0; i < n; i++ )
    {
      for( int j = n - 1; j > i; j-- )
        {
          if( a[j][1] < a[j-1][1] )
            {
              swap( a[j], a[j-1] );
            }
        }
    }
}

void Stability::selectionsort( int n, string a[] )
{
  int mini;

  for( int i = 0; i < n; i++ )
    {
      mini = i;
      for( int j = i; j < n; j++ )
        {
          if( a[j][1] < a[mini][1] )
            mini = j;
        }
      swap(a[i], a[mini]);
    }
}

int main( void )
{
  int n;
  string bsa[36];
  string ssa[36];

  Stability *st = new Stability();

  cin >> n;
  for( int i = 0; i < n; i++ )
    {
      cin >> bsa[i];
      ssa[i] = bsa[i];
    }

