void b_sort(card* a , int n){
	for(int i=n;i>=0;--i){
		for(int j=0;j<i-1;++j){
			if(a[j].n>a[j+1].n){
				swap(a[j].n,a[j+1].n);
				swap(a[j].m,a[j+1].m);
			}
		}
	}
}

void s_sort(card* a , int n){
	int lowest;
	for(int i=0;i<n;++i){
		lowest=i;
		for(int j=i+1 ; j<n ;++j){
			if(a[j].n<a[lowest].n){
				lowest=j;
				}
			}
		if(a[i].n>a[lowest].n){
		swap(a[i].n , a[lowest].n);
		swap(a[i].m , a[lowest].m);
		}
	}	
}

