void swap ( vector<string> &v, int i, int j )
{
	string tmp = v[i];
	v[i] = v[j];
	v[j] = tmp;
}

vector<string> BubbleSort ( vector<string> v )
{

	int i,j;
	for ( i = 0 ; i < v.size()-1 ; i++ )
	{
		for ( j = v.size()-1 ; i < j ; j-- )
		{
			if ( v[j-1][1] > v[j][1] )
			{
				swap ( v, j-1, j );
			}
		}
	}

	return v;
}

vector<string> SelectionSort ( vector<string> v )
{

	int i,j,min_index;

	for ( i = 0 ; i < v.size() ; i++ )
	{
		min_index = i;
		for ( j = i ; j < v.size() ; j++ )
		{
			if ( v[min_index][1] > v[j][1] )
			{
				min_index = j;
			}
		}
		if ( min_index != i )
		{
			swap ( v, min_index, i );
		}
	}

	return v;
}

