void printCards(const std::vector<std::pair<char, int>> &cards) {
  auto len = cards.size();
  for (auto i=0; i<len-1; ++i)
    std::cout << cards[i].first << cards[i].second << " ";
  std::cout << cards.back().first << cards.back().second << std::endl;
}

void BubbleSort(std::vector<std::pair<char, int>> &cards) {
  auto len = cards.size();

  for (auto i=0; i<len-1; ++i) {
    for (auto j=len-1; j>=i+1; --j) {
      if (cards.at(j).second < cards.at(j-1).second)
        std::swap(cards.at(j), cards.at(j-1));
    }
  }
}

void SelectionSort(std::vector<std::pair<char, int>> &cards) {
  auto len = cards.size();

  for (auto i=0; i<len-1; ++i) {
    auto min_idx = i;
    for (auto j=i+1; j<len; ++j) {
      if (cards.at(j).second < cards.at(min_idx).second) {
        min_idx = j;
      }
    }
    std::swap(cards.at(i), cards.at(min_idx));
  }
}

