        str_repr[1] = str[1];
        str_repr[2] = '\0';
    }

    bool operator==(Card rhs){
        return suit == rhs.suit && value == rhs.value;
    }

    bool operator<(Card rhs){
        return value < rhs.value;
    }

    operator const char*() const{
        return str_repr;
    }

};


