struct Card {
	char suit;
	char value;
};


void bubbleSort(Card A[], int N) {
	bool flag = true;
	int i = 1;
	while (flag) {
		flag = false;
		for (int j = N - 1; j >= i; j--) {
			if (A[j - 1].value > A[j].value) {
				Card temp = A[j];
				A[j] = A[j - 1];
				A[j - 1] = temp;
				flag = true;
			}
		}
		i++;
	}
}


void selectionSort(Card A[], int N) {
	for (int i = 0; i < N; i++) {
		int minj = i;
		for (int j = i; j < N; j++) {
			if (A[j].value < A[minj].value) {
				minj = j;
			}
		}
		if (i != minj) {
			Card temp = A[i];
			A[i] = A[minj];
			A[minj] = temp;
		}
	}
}

