#include <bits/stdc++.h>
#define FOR(i, a, b) for(int i = a; i < b; i++)
#define RFOR(i, a, b) for(int i = b; i >= a; i--)
#define REP(i, n) FOR(i, 0, n)
#define SZ(x) ((int)(x).size())
using namespace std;
#define vc vector<card>

struct card {
    char s;
    int n;
};

void BubSort(vc &C) {
    REP(i, SZ(C))
        RFOR(j, i+1, SZ(C)-1)
            if (C[j].n < C[j-1].n) {
                card t = C[j];
                C[j] = C[j-1];
                C[j-1] = t;
            }
}

void SelSort(vc &C) {
    REP(i, SZ(C)) {
        int minj = i;
        FOR(j, i, SZ(C)) {
            if (C[j].n < C[minj].n) minj = j;
        }
        card t = C[i];
        C[i] = C[minj];
        C[minj] = t;
    }
}

int main(){
    int n; cin >> n;
    vc CS(n);
    REP(i, n) {
        string s; cin >> s;
        CS[i].s = s[0];
        CS[i].n = (int)s[1]-'0';
    }
    vc CB = CS;
    BubSort(CB);
    SelSort(CS);
    REP(i, SZ(CB)) {
        cout << CB[i].s << CB[i].n;
        i != SZ(CB)-1 ? cout << " " : cout << endl;
    }
    cout << "Stable" << endl;
    REP(i, SZ(CS)) {
        cout << CS[i].s << CS[i].n;
        i != SZ(CS)-1 ? cout << " " : cout << endl;
    }
    bool f = false;
    REP(i, SZ(CS)) if(CB[i].s != CS[i].s) f = true;
    f ? cout << "Not stable" << endl : cout << "Stable" << endl;
}

