{
    for(int i = 0; i < N-1; i++){
        for(int j = N-1; j > i; j--){
            if(C[j][1] < C[j-1][1]) swap(C[j], C[j-1]);    
        }
    }
}

void SelectionSort(string C[], int N)
{
    for(int i = 0; i < N; i++){
        int min = i;
        for(int j = i+1; j < N; j++){
            if(C[min][1] > C[j][1]) min = j;
        }
        swap(C[min], C[i]);
    }
}

