int bubbleSort(char (*a)[3], int n){
    int i = 0;
    char tmp;
    int c;
    int flag = 1;
    while(flag){
        flag = 0;
        for(int j=n-1;j>i;j--){
            if(a[j][1]<a[j-1][1]){
                tmp = a[j][0];
                a[j][0] = a[j-1][0];
                a[j-1][0] = tmp;
                tmp = a[j][1];
                a[j][1] = a[j-1][1];
                a[j-1][1] = tmp;
                flag = 1;
                c++;
            }
        }
        i++;
    }
    return c;
}

int selectionSort(char (*a)[3], int n){
    int i, j, minj;
    char tmp;
    int c = 0;
    for(i=0;i<n;i++){
        minj = i;
        for(j=i+1;j<n;j++){
            if(a[j][1]<a[minj][1])minj = j;
        }
        if(minj!=i){
            tmp = a[i][0];
            a[i][0] = a[minj][0];
            a[minj][0] = tmp;
            tmp = a[i][1];
            a[i][1] = a[minj][1];
            a[minj][1] = tmp;
            c++;
        }
    }
    return c;
}

int stability(char (*in)[3], char (*out)[3], int n){
    int i,j,a,b;
    for(i=0;i<n;i++){
        for(j=i+1;j<n;j++){
            for(a=0;a<n;a++){
                for(b=a+1;b<n;b++){
                    if(in[i][1]==in[j][1]&&in[i][0]==out[b][0]&&in[i][1]==out[b][1]&&in[j][0]==out[a][0]&&in[j][1]==out[a][1])return 1;
                }
            }
        }
    }
    return 0;
}

