  for (int i = 0; i < n; i++) {
    std::cout << list[i]->card << list[i]->value;

    if (i < (n - 1)) {
      std::cout << " ";
    } else {
      std::cout << std::endl;
    }
  }

  if (isStable(list, n)) {
    std::cout << "Stable" << std::endl;
  } else {
    std::cout << "Not stable" << std::endl;
  }
}

