  int i,j;
  for (i=0;i<n;i++){
    for (j=n-1;j>i;j--){
      if (a[j]<a[j-1]){
        swap(a[j],a[j-1]);
        swap(b[j],b[j-1]);
      }
    }
  }
}
void sortSelection(int *a,char *b,size_t n){
  int i,j,min;
  for (i=0;i<n;i++){
    min=i;
    for (j=i;j<n;j++){
      if (a[j]<a[min])min=j;
    }
    swap(a[i],a[min]);
    swap(b[i],b[min]);
  }
}

