};

void bubble(int n, struct card* c)
{
    for (int i = 0; i < n; ++i) {
        for (int j = n-1; j > i; --j) {
            if (c[j].value < c[j-1].value) {
                char cbuf    = c[j].suit;
                int  vbuf    = c[j].value;
                c[j].value   = c[j-1].value;
                c[j].suit    = c[j-1].suit;
                c[j-1].value = vbuf;
                c[j-1].suit  = cbuf;
            }
        }
    }
}

void select(int n, struct card* c)
{
    for (int i = 0; i < n; ++i) {
        int mini = i;
        for (int j = i; j < n; ++j) {
            if (c[j].value < c[mini].value) {
                mini = j;
            }
        }
        char cbuf    = c[i].suit;
        int  vbuf    = c[i].value;
        c[i].value   = c[mini].value;
        c[i].suit    = c[mini].suit;
        c[mini].value = vbuf;
        c[mini].suit  = cbuf;
    }
}

bool isStable(int n, struct card* c, struct card* orig)
{
    for (int i = 1; i <= 9; ++i) {
        std::vector<char> modCharList;
        std::vector<char> orgCharList;
        for (int j = 0; j < n; ++j) {
            if (c[j].value == i) {
                modCharList.push_back(c[j].suit);
            }

            if (orig[j].value == i) {
                orgCharList.push_back(orig[j].suit);
            }
        }

        if (modCharList != orgCharList) {
            return false;
        }
    }

    return true;
}

