typedef vector< pair<char, int> > Trump;

namespace {
	void BubbleSort(Trump& t, int N)
	{
		bool flag = true;
		while (flag)
		{
			flag = false;
			for (int i = N - 1; i > 0; --i)
				if (t[i].second < t[i - 1].second)
					swap(t[i], t[i - 1]), flag = true;
		}
	}

	void SelectionSort(Trump& t, int N)
	{
		for (int i = 0; i < N; ++i)
		{
			int min = i;
			for (int j = i; j < N; ++j)
				if (t[j].second < t[min].second)
					min = j;

			if (i != min)
				swap(t[i], t[min]);
		}
	}
}

