#include <iostream>

int bubble_sort(int n, std::string ary[]) {

  int i;
  int index_last = n - 2;
  std::string temp;

  while (index_last >= 0) {

    for (i = 0; i <= index_last; i++) {
      if (ary[i][1] > ary[i + 1][1]){
        temp       = ary[i];
        ary[i]     = ary[i + 1];
        ary[i + 1] = temp;
      }
    }
    index_last --;
  }
  return 0;
}

int selection_sort(int n, std::string ary[]) {

  int i, j, min, min_index;
  std::string temp;

  for (i = 0; i <= n - 2; i++) {

    min       = ary[i][1];
    min_index = i;

    for (j = i; j <= n - 1; j++) {
      if (min > ary[j][1]) {
        min       = ary[j][1];
        min_index = j;
      }
    }
    if (ary[i] != ary[min_index]) {
      temp           = ary[i];
      ary[i]         = ary[min_index];
      ary[min_index] = temp;
    }
  }
  return 0;
}

std::string check_stable(int num, std::string ary_org[], std::string ary[]) {

  int i, j, indexA, indexB;
  std::string str;

  indexA = indexB = -1;

  for (i = 0; i <= num - 2; i++) {
    if (ary[i][1] == ary[i + 1][1]) {

      for (j = 1; j <= num - 1; j++) {
        if (ary_org[j] == ary[i])     indexA = j;
        if (ary_org[j] == ary[i + 1]) indexB = j;
      }
      if (indexA > indexB) {
        str = "Not stable";
        return str;
      }
      else indexA = indexB = -1;
    }
  }
  str = "Stable";
  return str;
}

