void bubble_sort(vector<string> &C,int N){
  for(int i=0;i<N;i++){
    for(int j=N-1;j>i;j--){
      if(int(C.at(j).at(1))<int(C.at(j-1).at(1))){
        swap(C.at(j),C.at(j-1));
      }
    }
  }
}

void selection_sort(vector<string> &C,int N){
  for(int i=0;i<N;i++){
    int minj= i; 
    for(int j=i;j<N;j++){
      if(int(C.at(j).at(1))<int(C.at(minj).at(1))){
        minj = j;
      }
    }
    swap(C.at(i),C.at(minj));
  }
}

