#define FOR(i, a, b) for (int i = (a); i < (b); ++i)
#define REPEAT(i, n) FOR(i, 0, n)
#define DECFOR(i, a, b) for (int i = (a); (b) < i; --i)

using namespace std;

bool isStable(std::vector<std::tuple<char, int>> in, std::vector<std::tuple<char, int>> out);

void c_3_5() {
	int n;
	int minj;

	// input
	std::cin >> n;
	std::vector<std::tuple<char, int>> a(n);
	std::vector<std::tuple<char, int>> b(n);
	std::vector<std::tuple<char, int>> c(n);
	REPEAT(i, n) {
		std::string v;
		char v1;
		int v2;

		std::cin >> v;
		const int count = std::sscanf(v.c_str(), "%c%d", &v1, &v2);
		assert(count == 2);
		a[i] = std::make_tuple(v1, v2);
		c[i] = b[i] = a[i];
	}
	assert(a[0] == b[0]);
	// buble sort
	REPEAT(i, n) {
		for (int j = n - 1; j > i; j--) {
			if (std::get<1>(a[j]) >= std::get<1>(a[j - 1])) {
				continue;
			}
			swap(a[j], a[j - 1]);
		}
	}
	// output
	REPEAT(i, a.size()) {
		std::cout << (i == 0 ? "" : " ") << std::get<0>(a[i]) << std::get<1>(a[i]);
	}
	std::cout << std::endl;
	std::cout << (isStable(c, a) ? "Stable" : "Not stable") << std::endl;

	// selection sort
	FOR(i, 0, n) {
		minj = i;
		FOR(j, i + 1, n) {
			if (std::get<1>(b[j]) >= std::get<1>(b[minj])) {
				continue;
			}
			minj = j;
		}
		if (minj == i) {
			continue;
		}
		std::swap(b[i], b[minj]);
	}
	// output
	REPEAT(i, b.size()) {
		std::cout << (i == 0 ? "" : " ") << std::get<0>(b[i]) << std::get<1>(b[i]);
	}
	std::cout << std::endl;
	std::cout << (isStable(c, b) ? "Stable" : "Not stable") << std::endl;
}

bool isStable(std::vector<std::tuple<char, int>> const in, std::vector<std::tuple<char, int>> const out) {
	// combination round-trip
	REPEAT(i, in.size()) {
		FOR(j, i + 1, in.size()) {
			REPEAT(k, out.size()) {
				FOR(l, k + 1, out.size()) {
					if (std::get<1>(in[i]) == std::get<1>(in[j]) && in[i] == out[l] && in[j] == out[k]) {
						// found reverse order
						return false;
					}
				}
			}
		}
	}
	return true;
}

