using namespace std;

void trace(string a[], int n) {
    for (int i = 0; i < n; i++) {
        if (i > 0) cout << " ";
        cout << a[i];
    }
    cout << endl;
}

void bubbleSort(string r[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = n - 1; j >= i + 1; j--) {
            if (r[j][1] < r[j - 1][1]) {
                swap(r[j], r[j - 1]);
            }
        }
    }
}

void selectionSort(string r[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int minj = i;
        for (int j = i; j < n; j++) {
            if (r[minj][1] > r[j][1]) minj = j;
        }
        swap(r[minj], r[i]);
    }
}

void stableOrNot(string in[], string out[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 1; j < n - 1; j++) {
            for (int a = 0; a < n - 1; a++) {
                for (int b = a + 1; b < n - 1; b++) {
                    if (in[i][1] == in[j][1]) {
                        if (in[i] == out[b] && in[j] == out[a]) {
                            cout << "Not stable" << endl;
                            return;
                        }
                    }
                }
            }
        }
    }
    cout << "Stable" << endl;
    return;
}

