void print(elem a,int n)
{
	for (int i = 0; i < n; i++)
	{
		if (i > 0)
			cout << ' ';
		cout << a[i].ch<<a[i].num;
	}
	cout << endl;
}

int BubbleSort(elem a, int n)
{
	int m = 0;
	el t ;
	int flag = n-1;
	int k=0;
	for (int i = 0; i < n-1; i++)
	{
		for (int j = 0; j < flag; j++)
		{
			if (a[j].num > a[j+1].num)
			{
				t = a[j];
				a[j] = a[j+1];
				a[j+1] = t;
				m++;
				k = j + 1;
			}
		}
		flag = k;
	}
	return m;
}


int selectSort(elem a, int n)
{
	int m = 0;
	int min,k;
	el t;
	for (int i = 0; i < n-1; i++)
	{
		min = a[i].num;
		k = i;
		for (int j = i + 1; j < n; j++)
		{
			if (a[j].num < min)
			{
				min = a[j].num;
				k = j;
			}	
		}
		if (min != a[i].num)
		{
			t = a[k];
			a[k] = a[i];
			a[i] = t;
			m++;
		}	
	}
	return m;

}
