#include <iostream>
using namespace std;

//カードの構造体
struct Card {
    char suit;
    int value;
};

void print_array(int n,Card a[]){
    for(int i = 0; i < n; i++){
        cout << a[i].suit << a[i].value;
        if(i < n-1) cout << ' ';
    }
    cout << endl;
}

void Bubble_Sort(int n, Card A[]){
    //バブルソート
    int flag = 1;
    int i = 0;//未ソート部分の先頭インデクス
    while(flag){
        flag = 0;
        for(int j = n-1; j >= i+1 ; j--){
            if(A[j].value < A[j-1].value){
                swap(A[j], A[j-1]);
                flag = 1;
            }
        }
        i++;
    }
}

void Selection_Sort(int n, Card A[]){
    //選択ソート O(n**2)
    for (int i = 0; i < n-1; i++){
        int minj = i;
        for (int j = i; j < n; j++){
            if (A[minj].value > A[j].value) minj = j;
        }
        if (i != minj){
            swap(A[i], A[minj]);
        }
    }
}

//愚直法　O(n**4)
bool check_stable(int n, Card origin[], Card target[]){
    for (int i = 0; i < n; i++){
        for (int j = i+1; j < n; j++){
            for (int a = 0; a < n; a++){
                for (int b = a+1; b < n-1; b++){
                    if (origin[i].value == origin[j].value //数字が等しい組があった時
                        && origin[i].value == target[b].value
                        && origin[i].suit == target[b].suit
                        && origin[j].value == target[a].value
                        && origin[j].suit == target[a].suit){
                            return false;
                        }
                }
            }
        }
    }
    return true;
}

int main(){
    int N;
    Card B[36], S[36], O[36];
    cin >> N;
    for (int i = 0; i < N; i++) {
        cin >> B[i].suit >> B[i].value;
        S[i].suit = B[i].suit;
        S[i].value = B[i].value;
        O[i].suit = B[i].suit;
        O[i].value = B[i].value;
    }

    Bubble_Sort(N, B);
    Selection_Sort(N, S);
    print_array(N, B);
    cout << "Stable" << endl;//バブルソートはいつでも安定
    print_array(N, S);
    if(check_stable(N, O, S) == true){
        cout << "Stable" << endl;
    }else{
        cout << "Not stable" << endl;
    }
    return 0;
}

