		cin >> C1[i].suit >> C1[i].value;
		C2[i] = C1[i];
	}

	//for(int i = 0;i < n;i++)C2[i] = C1[i];

	bubbleSort(C1,n);
	SelectionSort(C2,n);

	//bubbleSort
