using namespace std;

#define REPR(i,n) for(int i=(n); i >= 0; --i)
#define FOR(i, m, n) for(int i = (m); i < (n); ++i)
#define REP(i, n) for(int i=0, i##_len=(n); i<i##_len; ++i)
#define ALL(a)  (a).begin(),(a).end()

template<class T>bool chmin(T &a, const T &b) { if (b<a) { a=b; return true; } return false; }
template<class T>bool chmax(T &a, const T &b) { if (a<b) { a=b; return true; } return false; }
typedef long long ll;

vector<string> bubble_sort(const vector<string> &v) {
    vector<string> vv;
    for(const auto &it: v) vv.push_back(it);

    REP(i,vv.size()) {
        for(int j = vv.size()-1 ; j > i ; j--) {
            if(vv[j][1] < vv[j-1][1]) iter_swap(vv.begin()+j,vv.begin()+j-1);
        }
    }

    return vv;
}

vector<string> selection_sort(const vector<string> &v) {
    vector<string> vv;
    for(const auto &it: v) vv.push_back(it);

    int minj,minv;
    REP(i,vv.size()) {
        minj = i;
        minv = vv[i][1];
        FOR(j,i,vv.size()) if(chmin(minv,int(vv[j][1]))) minj = j;
        iter_swap(vv.begin()+i,vv.begin()+minj);
    }

    return vv;
}

bool is_stable(const vector<string> &in,const vector<string> &out) {
    REP(i,in.size()) FOR(j,i+1,in.size()) REP(k,out.size()) FOR(l,k+1,out.size()) {
        if(in[i][1] == in[j][1] && in[i] == out[l] && in[j] == out[k]) return false;
    }
    return true;
}

bool output(const vector<string> &v) {
    REP(i,v.size()-1) cout << v[i] << " ";
    cout << v[v.size()-1] << endl;
}

void solve() {
    int N;
    cin >> N;
    vector<string> v(N);
    REP(i,N) cin >> v[i];
    auto b = bubble_sort(v);
    output(b);
    auto ret = is_stable(v,b) ? "Stable" : "Not stable";
    cout << ret << endl;

    auto s = selection_sort(v);
    output(s);
    ret = is_stable(v,s) ? "Stable" : "Not stable";
    cout << ret << endl;
}

