char a[36],b[36];

string check() { //安定・不安定評価部
    for(i=0;i<n;i++) {
        if(a[i]==b[i] && A[i]==B[i]) { //バブルソートと選択ソートが同じ場合安定
            continue; //以下の処理をスキップ
            return "Not stable"; //不安定
        }
    }
    return "Stable"; //安定
}

int main(void)
{
    int n,i,j,min;
    int A[36],B[36];
    char a[36],b[36];

    cin>>n; //カード枚数入力

    for(i=0;i<n;i++) { //カード入力部
        cin>>a[i]>>A[i]; //数字はA,アルファベットはaに格納
        b[i]=a[i]; //アルファベット部
        B[i]=A[i]; //数字部
    }
    for(i=0;i<n-1;i++) { //バブルソート
        for(j=n-1;j>i;j--) {
            if(A[j]<A[j-1]) {
                swap(a[j],a[j-1]); //アルファベット部の入れ替え
                swap(A[j],A[j-1]); //数字部の入れ替え
            }
        }
    }
    for(i=0;i<n-1;i++) { //選択ソート
        min=i;
        for(j=i+1;j<n;j++) {
            if(B[j]<B[min]) {
                min=j;
            }
        }
        swap(b[i],b[min]); //アルファベット部の入れ替え
        swap(B[i],B[min]); //数字部の入れ替え
    }
