void BubbleSort(vector<string> &A)
{	
	for(int i = 0; i <= A.size() - 1; i++){
		for(int j = A.size() - 1; j >= i + 1; j--){
			if(A[j][1] < A[j - 1][1]){
				string a = A[j];
				A[j] = A[j - 1];
				A[j - 1] = a;
			}
		}
	}
}

void SelectionSort(vector<string> &A)
{	
	for(int i = 0; i <= A.size() - 1; i++){
		int mini= i;
		for(int j = i; j <= A.size() - 1; j++){
			if(A[j][1] < A[mini][1]){
				mini = j;
			}
		}
		if(i != mini){
			string a = A[i];
			A[i] = A[mini];
			A[mini] = a;
		}
	}
}
