std::tuple<std::vector<int>, int>
    InsertionSort(std::vector<int> ary, int gap = 1) {
    int cnt = 0;
    if (gap < 1) {
        std::cout << "Invalid gap is inputted." << std::endl;
    }
    int n = ary.size();
    for (int i=gap; i<n; i++) {
        int temp = ary[i];
        int j = i - gap;
        while(j>=0 && ary[j] > temp) {
            ary[j+gap] = ary[j];
            cnt++;
            j -= gap;
        }
        ary[j+gap] = temp;
    }
    return std::tuple<std::vector<int>, int>(ary, cnt);
}

