            std::cout << " ";
        }
        std::cout << cards[i].suit << cards[i].value;
    }
    std::cout << std::endl;
}

void BubbleSort(struct PokerCard *cards, int N) {
    bool flag;
    int i;

    flag = 1;
    i = 0;

    while (flag) {
        flag = 0;
        for (int j = N - 1; j > i; j--) {
            if (cards[j].value < cards[j - 1].value) {
                struct PokerCard tmp;
                tmp = cards[j];
                cards[j] = cards[j - 1];
                cards[j - 1] = tmp;
                flag = 1;
            }
        }
        i++;
    }

}

void SelectionSort(struct PokerCard *cards, int N) {
    int minIndex;

    for (int i = 0; i < N - 1; i++) {
        minIndex = i;
        for (int j = i; j < N; j++) {
            if (cards[j].value < cards[minIndex].value) {
                minIndex = j;
            }
        }

        if (minIndex != i) {
            struct PokerCard tmp;
            tmp = cards[i];
            cards[i] = cards[minIndex];
            cards[minIndex] = tmp;
        }
    }

}

