bool IsStable(vector<string>& original_v, vector<string>& sorted_v){
	bool isStable = true;
	vector<vector<string> > pairs_with_same_value;
	for(int i=0; i<sorted_v.size()-1; i++){
		if((int)sorted_v.at(i).at(1) == (int)sorted_v.at(i+1).at(1)){
			vector<string> pair;
			pair.push_back(sorted_v.at(i));
			pair.push_back(sorted_v.at(i+1));
			pairs_with_same_value.push_back(pair);
		}
	}

	for(int i=0; i<pairs_with_same_value.size(); i++){
		string former_elem = pairs_with_same_value.at(i).at(0);
		string latter_elem = pairs_with_same_value.at(i).at(1);
		for(int j=0; j<original_v.size(); j++){
			if(former_elem == original_v.at(j)){
				break;
			}
			if(latter_elem == original_v.at(j)){
				isStable = false;
				return isStable;
			}
		}
	}

	return isStable;
}


int BubbleSort(vector<string>& v, const int n_elem){
	int flag = 1;
	int n_swp = 0;
	while(flag){
		flag = 0;
		for(int i=n_elem-1; i>=1; i--){
			char str_i_1 = v[i-1][1];
			char str_i   = v[i][1];

			int num_i_1 = (int)str_i_1;
			int num_i   = (int)str_i;
			if(num_i_1 > num_i){
				string tmp = v.at(i);
				v.at(i) = v.at(i-1);
				v.at(i-1) = tmp;
				flag = 1;
				n_swp = n_swp + 1;
			}
		}
	}
	return n_swp;
}

void writeVector(const vector<string>& v){
	for(int i=0; i<v.size(); i++){
		if(i==v.size()-1){
			cout << v.at(i);
			break;
		}
		cout << v.at(i) << " ";
	}
	cout << "\n";
}

int SelectionSort(vector<string>& v, const int n_elem){
	int n_swp = 0;
	for(int i=0; i<n_elem; i++){
		int min_i = i;
		for(int j=i; j<n_elem; j++){
			if((int)v.at(j)[1] < (int)v.at(min_i)[1]){
				min_i = j;
			}
		}

		if(i != min_i){
		    string tmp = v.at(i);
		    v.at(i) = v.at(min_i);
		    v.at(min_i) = tmp;
		    n_swp = n_swp + 1;
		}
	}
	return n_swp;
}

