        for (int j = i; j < n; j++) {
            if (std::get<1>(ary[j]) < std::get<1>(ary[min_ix])) {
                min_ix = j;
            }
        }
        if (i != min_ix) {
            std::swap(ary[i], ary[min_ix]);
        }
    }
    return ary;
}

