vector<string> bubbleSort(vector<string> v, int N) {
	int i = 0;
	while (1) {
		for (int j = N - 1; j > i; j--) {
			if (v.at(j).at(1) < v.at(j - 1).at(1)) {
				string x = v.at(j);
				v.at(j) = v.at(j - 1);
				v.at(j - 1) = x;
			}
		}
		i++;
		if (i == N - 1) break;
	}

	display(v, N);
	return v;
}

vector<string> selectionSort(vector<string> v, int N) {
	int cnt = 0;
	for (int i = 0; i < N; i++) {
		int minj = i;

		for (int j = i; j < N; j++) {
			if (v.at(j).at(1) < v.at(minj).at(1)) minj = j;
		}

		if (i != minj) {
			string n = v.at(i);
			v.at(i) = v.at(minj);
			v.at(minj) = n;
			cnt++;
		}
	}

	display(v, N);
	return v;
}

