        value = orig[i].value;
        orig_names.clear();
        sorted_names.clear();

        for (int j = 0; j < N; j++) {
            if(orig[j].value == value) {
                orig_names.push_back(orig[j].name);
            }
            if(sorted[j].value == value) {
                sorted_names.push_back(sorted[j].name);
            }
        }

        for(int k = 0; k < orig_names.size(); k++) {
            if (orig_names[k] != sorted_names[k]) {
                return("Not stable");
            }
        }
    }
    return("Stable");
}

