int checkStable(vector<card> before_sort, vector<card> after_sort, int n){
    vector<queue<int>> vec_q(10);

    for(int i = 0; i < n; i++){
        int value = before_sort.at(i).value - 1;
        char suit = before_sort.at(i).suit;
        vec_q.at(value).push(suit);
    }

    // ソート後の配列を見てゆき、queueと一致した場合、除去
    for(int i = 0; i < n; i++){
        int value = after_sort.at(i).value - 1;
        char suit = after_sort.at(i).suit;

        if(suit == vec_q.at(value).front()){
            vec_q.at(value).pop();
        }
    }

    // queueの中身が0であるか確認
    for(int i = 0; i < 10; i++){
        if(vec_q.at(i).size() != 0){
            cout << "Not stable" << endl;
            return 0;

        }
    }
    cout << "Stable" << endl;
    return 1;
}

