    return a;
}

deque<string> selectionSort(int n, deque<string> a) {
    for (int i = 0; i <= n - 1; ++i) {
        int minj = i;
        for (int j = i; j <= n - 1; ++j) {
            if (a[j][1] < a[minj][1]) {
                minj = j;
            }
        }
        if (i != minj) {
            string t = a[i];
            a[i] = a[minj];
            a[minj] = t;
        }
    }

    for (int i = 0; i < n-1; ++i) {
        cout << a[i] << " ";
    }
