void BubbleSort(Card *card, int n)
{
	Card temp;
	for (int i = 0; i < n; ++i)
	{
		for (int j = n - 1; j >= i + 1; --j)
		{
			if(card[j].number < card[j-1].number)
			{
				temp = card[j];
				card[j] = card[j-1];
				card[j-1] = temp;
			}
		}
	}
}


void SelectionSort(Card *card, int n)
{
	int min;
	for (int i = 0; i < n; ++i)
	{
		// i は配列の中の未ソート部分の先頭を表す
		min = i;
		for (int j = i; j < n; ++j)
		{
			if(card[j].number < card[min].number)
			{
				min = j;
			}
		}
		Card temp = card[min];
		card[min] = card[i];
		card[i] = temp;
	}
}


