{
	for (int k = 0; k < n; ++k)
	{
		if (k == n- 1)
		{
			printf("%c%d\n", card[k].symbol, card[k].number);
		}
		else
		{
			printf("%c%d ", card[k].symbol, card[k].number);
		}
	}
}

