struct Card {
    char ch;
    int num;
    bool operator != (Card a) {
        return (this->ch != a.ch || this->num != a.num);
    }
};
Card *master;
int n;

void bubble(Card* d){
    int count = 0;
    bool replaced = true;
    while(replaced){
        replaced = false;
        for(int i = 0; i < n - count - 1; i++){
            if(d[i].num > d[i+1].num){
                Card buf = d[i];
                d[i] = d[i+1];
                d[i+1] = buf;
                replaced = true;
            }
        }
        count++;
    }
}

void selection(Card* d){
    int start = 0;
    for(int i = 0; i < n; i++){
        Card minCa = d[start];
        int min = d[start].num, pos = start;
        for(int k = start; k < n; k++){
            if(d[k].num < min){
                min = d[pos = k].num;
                minCa = d[k];
            }
        }
        d[pos] = d[start];
        d[start++] = minCa;
    }
}

