using namespace std;

struct Card {
    char suit, value;
};

void trace(struct Card A[], int N) {
    for(int i = 0; i < N; i++) {
        if(i > 0) cout << " ";
        cout << A[i].suit << A[i].value;
    }
    cout << endl;
}

void bubbleSort(struct Card A[], int N) {
    bool flag = true;
    int i = 0;
    while(flag) {
        flag = false;
        for(int j = N - 1; j > i; j--) {
            if(A[j].value < A[j - 1].value) {
                swap(A[j], A[j - 1]);
                flag = true;
            }
        }
        i++;
    }
}

void selectionSort(struct Card A[], int N) {
    int minj;
    for(int i = 0; i < N; i++) {
        minj = i;
        for(int j = i; j < N; j++) {
            if(A[j].value < A[minj].value) {
                minj = j;
            }
        }
        swap(A[i], A[minj]);
    }
}

bool isStable(struct Card A[], struct Card B[], int N) {
    for(int i = 0; i < N; i++) {
        if(A[i].suit != B[i].suit) return false;
    }
    return true;
}

int main() {
    int N;
    cin >> N;
    Card A[N], B[N];
    for(int i = 0; i < N; i++) {
        cin >> A[i].suit >> A[i].value;
    }
    for(int i = 0; i < N; i++) {
        B[i] = A[i];
    }

    bubbleSort(A, N);
    selectionSort(B, N);

    trace(A, N);
    cout << "Stable" << endl;
    trace(B, N);
    if(isStable(A, B, N)) {
        cout << "Stable" << endl;
    } else {
        cout << "Not stable" << endl;
    }
}

