				string tmp;
				tmp = array[j-1];
				array[j-1]=array[j];
				array[j]=tmp;
			}
		}
	}
}

void selectionSort(string array[],int n){
	for(int i=0;i<n;i++){
		int minj=i;
		for(int j=i;j<n;j++){
			if(array[minj][1]>array[j][1]){
				minj=j;
			}
		}
		if(minj!=i){
			string tmp;
			tmp = array[minj];
			array[minj]=array[i];
			array[i]=tmp;
		}
	}
}

bool is_stable(string card[],string array[],int n){
	for(int i=0;i<n;i++){
