			for(int a=0;a<n;a++){
				for(int b=a+1;b<n;b++){
					if((card[i][1]==card[j][1])&&(card[i]==array[b])
					&&(card[j]==array[a])){
						return false;
					}
				}
			}
		}
	}
	return true;
}

