void buble_Sort(vector<int> v, int n)
{
    bool flag = true;
    //int count_exchange = 0;
    bool notStable = false;
    while (flag)
    {
        flag = false;
        for (int j = n - 1; j >= 1; j--)
        {
            if (v[j] < v[j - 1])
            {
                //count_exchange++;
                if(v[j] == v[j - 1]) notStable = true;

                int temp = v[j];
                v[j] = v[j - 1];
                v[j - 1] = temp;
                flag = true;
            }
        }
    }

    print_vector(v);
    cout << is_Stable(notStable) << endl;
}

void seliction_Sort(vector<int> v, int n)
{
    int mini;//, count = 0;
    bool notStable = false;
    for (int i = 0; i < n - 1; i++)
    {
        mini = i;
        for (int j = i + 1; j < n; j++){
            if (v[j] < v[mini])
                mini = j;
        }

        if (i != mini){
            //count++;
            if(v[i], v[mini]) notStable = true;
            swap(v[i], v[mini]);
        }
    }

    print_vector(v);
    cout << endl << is_Stable(notStable) << endl;
}

