		suit[i] = s[i];
	}
}

void selectionSort(int n[], char s[], int N, Card c)
{
	int num[36];
	char suit[36];
	for(int i = 0; i < N; i++)
	{
		num[i] = n[i];
		suit[i] = s[i];
	}
	int min;
	for(int i = 0; i<N; i++)
	{
		min = i;
		for(int j = i; j < N; j++)
		{
			if(num[j]<num[min])
				min = j;
		}
		swap(num[i], num[min]);
		swap(suit[i], suit[min]);
	}
	showArray(num, suit, N);
	showStable(num, suit, N, c);
}

