template<class T>
int selection_sort(T xs[], int n){
    int cnt = 0;
    for(int i = 0; i < n; ++i){
        int mini = i;
        for(int j = i; j < n; ++j){
            if(xs[j] < xs[mini]){
                mini = j;
            }
        }
        if(mini != i){
            ++cnt;
            swap(xs[mini], xs[i]);
        }
    }
    return cnt;
}

template <class T>
int bubble_sort(T xs[], int n){
    int cnt = 0;
    for(int i = 0; i < n; ++i){
        for(int j = n-1; j > i; --j){
            if(xs[j] < xs[j-1]){
                ++cnt;
                swap(xs[j], xs[j-1]);
            }
        }
    }
    return cnt;
}

template <class T>
void print_array(T xs[], int n){
    for(int i = 0; i < n-1; ++i){
        cout << xs[i] << ' ';
    }
    cout << xs[n-1] << '\n';
}

template<class T>
bool eq_array(T xs[], T ys[], int n){
    for(int i = 0; i < n; ++i){
        if(xs[i] != ys[i]){
            return false;
        }
    }
    return true;
}

