        xs[i] = Card(temp);
        ys[i] = xs[i];
    }
    bubble_sort(xs, n);
    print_array(xs, n);
    cout << "Stable\n";
    selection_sort(ys, n);
    print_array(ys, n);
    if(!eq_array(xs, ys, n)){
        cout << "Not stable\n";
    } else {
        cout << "Stable\n";
    }
}

