#include <cstdio>
#include <array>
#define NMAX	36

struct trump{
	char	mark;
	int 	value;
};

void swap(std::array<trump, NMAX> &array, int a, int b){
	trump tmp;

	tmp = array[a];
	array[a] = array[b];
	array[b] = tmp;

	return;
}

void bubbleSort(std::array<trump, NMAX> &array, int N){
	bool is_sorted = false;
	for(int j=0 ; (j<=N-1)&&(!is_sorted) ; j++){
		is_sorted = true;
		for(int i=N-1 ; i>j ; i--){
			if(array[i].value < array[i-1].value){
				is_sorted = false;
				swap(array, i, i-1);
			}
		}
	}

	return;
}

void selectionSort(std::array<trump, NMAX> &array, int N){
	for(int i=0 ; i<N ; i++){
		int jmin = i;
		for(int j=i+1 ; j<N ; j++){
			if(array[jmin].value > array[j].value){
				jmin = j;
			}
		}
		if(jmin != i){
			swap(array, jmin, i);
		}
	}

	return;
}

int main(int argc, char *argv[]){
	int N;
	std::array<trump, NMAX> C;

	std::scanf("%d",&N);
	for(int i=0 ; i<N ; i++){
		std::scanf(" %c%d", &C[i].mark, &C[i].value);
	}

	std::array<trump, NMAX> C_bubble(C);
	std::array<trump, NMAX> C_selection(C);

	bubbleSort(C_bubble, N);
	selectionSort(C_selection, N);

	for(int i=0 ; i<N-1 ; i++){
		std::printf("%c%d ", C_bubble[i].mark, C_bubble[i].value);
	}
	std::printf("%c%d\n", C_bubble[N-1].mark, C_bubble[N-1].value);
	std::printf("Stable\n");

	for(int i=0 ; i<N-1 ; i++){
		std::printf("%c%d ", C_selection[i].mark, C_selection[i].value);
	}
	std::printf("%c%d\n", C_selection[N-1].mark, C_selection[N-1].value);

	bool is_stable = true;
	for(int i=0 ; i<N ; i++){
		if((C_bubble[i].mark != C_selection[i].mark) || (C_bubble[i].value != C_selection[i].value)){
			is_stable = false;
			break;
		}
	}

	if(is_stable){
		std::printf("Stable\n");
	}
	else{
		std::printf("Not stable\n");
	}

	return 0;
}

#include <iostream>

void BubbleSort(char* A, char* a, int N)
{
  for(int i=0; i<N-1; ++i){
    for(int j=N-1; j>i; --j){
      if( a[j] < a[j-1] ){
        std::swap(A[j], A[j-1]);
        std::swap(a[j], a[j-1]);
      }
    }
  }
}

void SelectionSort(char* B, char* b, int N)
{
  for(int i=0; i<N-1; ++i){
    int minj = i;
    for(int j=i+1; j<N; ++j){
      if( b[j] < b[minj] ){
        minj = j;
      }
    }
    if(i != minj){
      std::swap(B[i], B[minj]);
      std::swap(b[i], b[minj]);
    }
  }
}


