    for(int j=0; j<N; j++){
        for(int i=N-1; i>j; i--){
            if(C[i].value < C[i-1].value){
                Card t = C[i-1];
                C[i-1] = C[i];
                C[i] = t;
            }
        }
    }
}
void SelectionSort(struct Card C[], int N){
    int minj;
    for (int j=0; j<N; j++){
        minj = j;
        for (int i=j+1; i<N; i++){
            if(C[minj].value > C[i].value){
                minj = i;
            }
        }
        if(minj != j){
            Card t = C[minj];
            C[minj] = C[j];
            C[j] = t;
        }
    }
}

