template<typename T>
void swapArgs(T& a, T& b) {
    T t = a;
    a = b;
    b = t;
}

typedef struct playCards {
    int iOrder;
    char mark;
    int value;
};

void bubbleSort(playCards* a, int n) {
    for (int i = 0; i < n; i++) {
        for (int j = n - 1; j > i; j--) {
            if (a[j].value < a[j - 1].value)swapArgs(a[j], a[j - 1]);
        }
    }
}

void selectionSort(playCards* a, int n) {
    for (int i = 0; i < n; i++) {
        int minj = i;
        for (int j = i; j < n; j++) {
            if (a[j].value < a[minj].value)minj = j;
        }
        swapArgs(a[i], a[minj]);
    }
}

