void trace(const vector<Card>& a) {
  for (int i = 0; i < a.size(); i++) {
    cout << a[i].suit << a[i].value << ((i != a.size() - 1)? " " : "");
  }
  cout << endl;
}

bool is_stable(const vector<Card>& in, const vector<Card>& out) {
  for (int i = 0; i < in.size(); i++) {
    if (in[i].value != out[i].value || in[i].suit != out[i].suit) return false;
  }
  return true;
}

vector<Card> bubble_sort(vector<Card> c, int n) {
  for (int i = 0; i < n; i++) {
    for (int j = n - 1; j > i; j--) {
      if (c[j].value < c[j - 1].value) swap(c[j], c[j - 1]);
    }
  }
  return c;
}

vector<Card> selection_sort(vector<Card> c, int n) {
  for (int i = 0; i < n; i++) {
    int minj = i;
    for (int j = i; j < n; j++) {
      if (c[j].value < c[minj].value) minj = j;
    }
    swap(c[i], c[minj]);
  }
  return c;
}

