void swapEx(char *a, char *b)
{
	char temp[3];
	strcpy(temp, b);
	strcpy(b, a);
	strcpy(a, temp);
}

void BubleSort(char C[][3], int N)
{
	int flag = 1;
	for (int i = 0; i < N, flag == 1; i++) {
		flag = 0;
		for (int j = N-1; j > i; j--) {
			if (C[j - 1][1] > C[j][1]) {
				swapEx(C[j - 1], C[j]);
				flag = 1;
			}
		}
	}
	for (int i = 0; i < N-1; i++) cout << C[i] << " ";
	cout << C[N - 1] << endl;
}

void SelectionSort(char C[][3], int N)
{
	int minj;
	for (int i = 0; i < N; i++) {
		minj = i;
		for (int j = i+1; j < N; j++) {
			if (C[minj][1] > C[j][1]) {
				minj = j;
			}
		}
		swapEx(C[minj], C[i]);
	}
	for (int i = 0; i < N - 1; i++) cout << C[i] << " ";
	cout << C[N - 1] << endl;
}

