  int number;
} typedef card_t;

card_t new_card(char picture, int number) {
  card_t card;
  card.picture = picture;
  card.number = number;
  return card;
}

void dump_cards(card_t cards[], int n) {
  for(int i=0; i<n; i++) {
    printf("%c%d", cards[i].picture, cards[i].number);
    if(i < n-1) {
      printf(" ");
    }
  }
}

void bubble_sort(card_t cards[], int n) {
  for(int i=0; i<n; i++) {
    for(int j=n-1; j>i; j--) {
      if(cards[j].number < cards[j-1].number) {
        card_t tmp = cards[j];
        cards[j] = cards[j-1];
        cards[j-1] = tmp;
      }
    }
  }
}

// 0 -> stable, 1 -> not stable
int selection_sort(card_t cards[], int n) {
  int not_stable = 0;
  for(int i=0; i<n; i++) {
    int minj = i;
    for(int j=i; j<n; j++) {
      if(cards[j].number < cards[minj].number) {
        minj = j;
      }
    }
    if(minj != i) {
      if(cards[i].picture == cards[minj].picture) {
        not_stable = 1;
      }
      card_t tmp = cards[i];
      cards[i] = cards[minj];
      cards[minj] = tmp;
    }
  }
  return not_stable;
}


