  }

  card_t cards_bubble[MAX_N];
  card_t cards_selection[MAX_N];
  memcpy(cards_bubble, cards, sizeof(card_t)*MAX_N);
  memcpy(cards_selection, cards, sizeof(card_t)*MAX_N);

  bubble_sort(cards_bubble, n);
  int not_stable = selection_sort(cards_selection, n);

  dump_cards(cards_bubble, n);
  printf("\nStable\n");
  dump_cards(cards_selection, n);
  if(not_stable == 0) {
    printf("\nStable\n");
  } else {
    printf("\nNot stable\n");
  }

}

