				swap(a[i], a[i - 1]);
				flag = 1;
				count++;
			}
		}
	}
	return a;
}
vector<string> selectionSort(vector<string>a, lint n) {
	int minj,count=0;
	rep(i, n) {
		minj = i;
		repi(j, i, n) {
			if (value(a[j]) < value(a[minj]))minj = j;
		}
		swap(a[i], a[minj]);
		if(i!=minj)count++;
	}
	return a;
}
