void out(const int n, std::string* a)
{
    for(int i=0; i<n; i++){
        cout << a[i];
        if(i != n-1) cout << " ";
    }
    cout << endl;
}

int BubbleSort(const int n, std::string* a)
{
    int cnt = 0;
    for(int i=0; i<n; i++){
        for(int j=n-1; j>i; j--){
            if(a[j-1][1]>a[j][1]){
                std::string tmp = a[j-1];
                a[j-1] = a[j];
                a[j] = tmp;
                cnt++;
            }
        }
    }
    return cnt;
}

int SelectionSort(const int n, std::string* a)
{
    int cnt = 0;
    for(int i=0; i<n; i++){
        int min_index = i;
        for(int j=i+1; j<n; j++){
            if(a[min_index][1] > a[j][1]){
                min_index = j;
            }
        }
        if(min_index != i){
            std::string tmp = a[i];
            a[i] = a[min_index];
            a[min_index] = tmp;
            cnt++;
        }
    }
    return cnt;
}

void chackStable(const int n, std::string* org, std::string* sorted)
{
    std::map<int, std::vector<char>> v1;
    for(int i=0; i<n; i++){
        for(int j=i+1; j<n; j++){
            if(sorted[i][1] == sorted[j][1]){
                int num = sorted[i][1];
                int letter = sorted[i][0];
                v1[num].push_back(letter);
            }
        }
    }
    std::map<int, std::vector<char>> v2;
    for(int i=0; i<n; i++){
        for(int j=i+1; j<n; j++){
            if(org[i][1] == org[j][1]){
                int num = org[i][1];
                int letter = org[i][0];
                v2[num].push_back(letter);
            }
        }
    }
    for(int i=0; i<v1.size(); i++){
        for(int j=0; j<v1[i].size(); j++){
            if(v1[i][j] != v2[i][j]){
                cout << "Not stable" << endl;
                return;
            }
        }
    }
    cout << "Stable" << endl;
}

