};

void trace(struct Card *a, int n) {
    for (int i = 0; i < n - 1; i++) {
        cout << a[i].trump << a[i].value << " ";
    }
    cout << a[n-1].trump << a[n-1].value << endl;
}

void bubbleSort(struct Card *c, int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = n - 1; j > i; j--) {
            if (c[j].value < c[j - 1].value) {
                struct Card tmp = c[j];
                c[j] = c[j - 1];
                c[j - 1] = tmp;
            }
        }
    }
}

void selectionSort(struct Card *c, int n) {
    for (int i = 0; i < n - 1; i++) {
        int minoff = i;
        for (int j = i + 1; j < n; j++) {
            if (c[j].value < c[minoff].value) {
                minoff = j;
            }
        }
        if (i != minoff) {
            struct Card tmp = c[i];
            c[i] = c[minoff];
            c[minoff] = tmp;
        }
    }
}

