#define rep(i, n) for (int i = 0; i < (n); i++)
#define rrep(i, n) for (int i = (n) - 1; i >= 0; i--)
#define rep1(i, s, n) for (int i = (s); i <= (n); i++)
#define rrep1(i, s, n) for (int i = (s); i >= (n); i--)

typedef struct {
	char suit;
	int value;
} deck;

deck BS[36];
deck SS[36];

void BubbleSort(deck* C, int N)
{
	int tmp1, tmp2;

	rep(i, N) {
		rrep1(j, N - 1, i + 1) {
			if (C[j].value < C[j - 1].value) {
				tmp1 = C[j].value;
				tmp2 = C[j].suit;
				C[j].value = C[j - 1].value;
				C[j].suit = C[j - 1].suit;
				C[j - 1].value = tmp1;
				C[j - 1].suit = tmp2;
			}
		}
	}

	rep(i, N - 1) cout << C[i].suit << C[i].value << " ";
	cout << C[N - 1].suit << C[N - 1].value << endl;
	cout << "Stable" << endl;
}

void SelectionSort(deck* C, int N, deck* Compare)
{
	int tmp1, tmp2, mini;
	bool isStable = true;

	rep(i, N) {
		mini = i;
		rep1(j, i, N - 1) {
			if (C[j].value < C[mini].value) mini = j;
		}
		tmp1 = C[mini].value;
		tmp2 = C[mini].suit;
		C[mini].value = C[i].value;
		C[mini].suit = C[i].suit;
		C[i].value = tmp1;
		C[i].suit = tmp2;
	}

	rep(i, N - 1) cout << C[i].suit << C[i].value << " ";
	cout << C[N - 1].suit << C[N - 1].value << endl;

	rep(i, N) {
		if ((C[i].value != Compare[i].value)
			|| (C[i].suit != Compare[i].suit)){
			isStable = false;
			break;
		}
	}

	if (isStable) cout << "Stable" << endl;
	else cout << "Not stable" << endl;
}

