namespace
{
	template<int N>
	std::array<int, N> GetValue(std::istream& stream)
	{
		std::string buf;
		std::getline(stream, buf);

		std::stringstream sstr(buf);
		std::array<int, N> retval;

		for (int i = 0; i < N; ++i)
		{
			std::getline(sstr, buf, ' ');
			retval[i] = std::stoi(buf);
		}

		return retval;
	}

	std::vector<int> GetValue(std::istream& stream, int num, char delim)
	{
		std::string buf;
		std::vector<int> retval;
		retval.reserve(num);

		for (int i = 0; i < num; ++i)
		{
			std::getline(stream, buf, delim);
			retval.push_back(std::stoi(buf));
		}

		return retval;
	}

	int GetValue(std::istream& stream)
	{
		int in;
		stream >> in;

		return in;
	}

	std::vector<std::string> GetValueString(std::istream& stream, int num, char delim)
	{
		std::string buf;
		std::vector<std::string> retval;
		retval.reserve(num);

		std::getline(stream, buf);
		std::stringstream sstr(buf);

		for (int i = 0; i < num; ++i)
		{
			std::getline(sstr, buf, delim);
			retval.push_back(std::move(buf));
		}

		return retval;
	}

	template<typename Pred>
	std::vector<std::string> BubbleSort(std::vector<std::string> sequence, 
		Pred pred)
	{
		bool flag = true;

		while (flag)
		{
			flag = false;

			for (size_t i = sequence.size() - 1; i > 0; --i)
			{
				if(pred(sequence[i - 1], sequence[i]))
				{
					flag = true;
					std::swap(sequence[i], sequence[i - 1]);
				}
			}
		}

		return sequence;
	}

	template<typename Pred>
	std::vector<std::string> SelectionSort(std::vector<std::string> sequence,
		Pred pred)
	{
		for (size_t i = 0; i < sequence.size() - 1; ++i)
		{
			size_t min_index = i;

			for (size_t j = i; j < sequence.size() - 1; ++j)
			{
				if(pred(sequence[min_index], sequence[j + 1]))
				{
					min_index = j + 1;
				}
			}

			if (i != min_index)
			{
				std::swap(sequence[i], sequence[min_index]);
			}
		}

		return sequence;
	}

	template<typename T>
	void Print(const std::vector<T>& sequence)
	{
		std::cout << sequence[0];

		for (size_t i = 1; i < sequence.size(); ++i)
		{
			std::cout << ' ' << sequence[i];
		}

		std::cout << std::endl;
	}
}

