{
	auto file = (argc == 1) ? std::ifstream() : std::ifstream(argv[1]);
	std::istream& stream = (argc == 1) ? std::cin : file;

	int num = GetValue<1>(stream)[0];
	std::vector<std::string> values = GetValueString(stream, num, ' ');

	auto f = [](const std::string& p1, const std::string& p2)
	{
		if (p2[1] < p1[1])
		{
			return true;
		}
		else
		{
			return false;
		}
	};

	std::vector<std::string> bubble = BubbleSort(values, f);
	std::vector<std::string> selection = SelectionSort(values, f);

