bool isStable(char* A, char *B, int N)
{
	for (int i=0; i<N; i++) {
		if (A[i] != B[i]) return false;
	}
	return true;
}

void copy(int *A, int *B, int N)
{
	for (int i=0; i<N; i++) A[i] = B[i];
}

void copy(char *A, char *B, int N)
{
	for (int i=0; i<N; i++) A[i] = B[i];
}

void show(char *suits, int* nums, int N)
{
	std::cout << suits[0] << nums[0];
	for (int i=1; i<N; i++) std::cout << " " << suits[i] << nums[i];
	std::cout << std::endl;
}

void swap(int& a, int& b)
{
	int tmp = a; a = b; b = tmp;
}

void swap(char& a, char& b)
{
	char tmp = a; a = b; b = tmp;
}

void bubbleSort(char* suits, int* nums, int N)
{
	for (int i=0; i<N; i++) {
		for (int j=N-1; j>i; j--) {
			if (nums[j-1] > nums[j]) {
				swap(suits[j-1], suits[j]); 
				swap(nums[j-1], nums[j]);
			}
		}
	}
}

void selectionSort(char* suits, int* nums, int N)
{
	for (int i=0; i<N; i++) {
		int min_i = i;
		for (int j=i; j<N; j++) {
			if (nums[j] < nums[min_i]) min_i = j;
		}
		if (i < min_i) {
			swap(suits[i], suits[min_i]); 
			swap(nums[i], nums[min_i]); 
		}
	}
}

int main()
{
	int N;
	std::cin >> N;

	char *suits = new char[N];
	int *nums = new int[N];
	for (int i=0; i<N; i++) {
		std::cin >> suits[i] >> nums[i];
	}

	char *suits_cpy = new char[N];
	int *nums_cpy = new int[N];
	copy(suits_cpy, suits, N);
	copy(nums_cpy, nums, N);

	bubbleSort(suits, nums, N);
	show(suits, nums, N);
	std::cout << "Stable" << std::endl;

	selectionSort(suits_cpy, nums_cpy, N);
	show(suits_cpy, nums_cpy, N);
	if (isStable(suits, suits_cpy, N)) std::cout << "Stable" << std::endl;
	else std::cout << "Not stable" << std::endl;

	delete[] suits;
	delete[] nums;
	delete[] suits_cpy;
	delete[] nums_cpy;

	return 0;
}

