	while (isSort) {
		isSort = false;
		for (int i = arraySize - 1; i > sortedIndex; i--) {
			if (cardArray[i - 1].number > cardArray[i].number) {
				swap(cardArray[i - 1], cardArray[i]);
				isSort = true;
			}
		}

		sortedIndex++;
	}

	// 結果出力
	// ソート済み配列
	for (int i = 0; i < arraySize; i++) {
		if (i != arraySize - 1) {
			printf("%s ", originalInput[cardArray[i].originIndex]);
		}
		else {
			printf("%s\n", originalInput[cardArray[i].originIndex]);
		}
	}
}

void SelectionSort(SCard* cardArray, int arraySize, const char originalInput[][INPUT_LENGTH_MAX])
{

	for (int i = 0; i < arraySize; i++) {
		int minIndex = i;

		for (int j = i + 1; j < arraySize; j++) {
			if (cardArray[minIndex].number > cardArray[j].number) {
				minIndex = j;
			}
		}

		if (minIndex != i) {
			swap(cardArray[minIndex], cardArray[i]);
