  for (int i = 0; i < C.Count(); i++) {
    for (int j = C.Count() - 1; j >= i + 1; j--) {
      if(C[j].value() < C[j - 1].value()){
        swap(C[j], C[j - 1]);
      }
    }
  }
}

void SelectionSort(CardList &C){
  for(int i = 0; i < C.Count(); i++){
    int minJ = i;
    for(int j = i; j < C.Count(); j++){
      if(C[j].value() < C[minJ].value()){
        minJ = j;
      }
    }
    swap(C[i], C[minJ]);
  }
}

