vector<string> BubbleSort(vector<string> A)
{
	for (int i = 0; i < N - 1; i++)
	{
		for (int j = N - 1; j >= i + 1; j--)
		{
			if (A.at(j - 1).at(1) > A.at(j).at(1))
			{
				swap(A.at(j - 1), A.at(j));
			}
		}
	}
	return A;
}

vector<string> SelectionSort(vector<string> A)
{
	for (int i = 0; i < N; i++)
	{
		int minj = i;
		for (int j = i + 1; j < N; j++)
		{
			if (A.at(j).at(1) < A.at(minj).at(1))
			{
				minj = j;
			}
		}
		swap(A.at(i), A.at(minj));
	}
	return A;
}

