bool selection_sort (vector<string> & a )
{
	vector<string> pre = a;
	int n = a.size();

	rep (i, n ){
		int mini = i;
		for (int j = i; j < n; j++ ){
			if ((int)(a[j][1] - '0' ) < (int)(a[mini][1] - '0' ) ){
				mini = j;
			} // end if
		} // end for
		if (i != mini ){
			swap (a[i], a[mini] );
		} // end if
	} // end rep

	vector<string> p(10, "" ), q(10, "" );
	rep (i, n ){
		int num1 = (int)(pre[i][1] - '0' );
