bool SelectionSort(vector<string> *vec) {
	auto &v = *vec;
	bool is_stable = true;
	REP(i, v.size()) {
		int minj = i;
		FOR(j, i + 1, v.size()) {
			if (v[minj][1] > v[j][1]) {
				minj = j;
			}
		}
		FOR(j, i + 1, minj) {
			if (v[i][1] == v[j][1]) {
				is_stable = false;
			}
		}
		swap(v[i], v[minj]);
	}
	return is_stable;
}
bool BubbleSort(vector<string> *vec) {
	auto &v = *vec;
	bool is_stable = true;
	REP(i, v.size()) {
		for(int j = v.size() - 1; j >= i + 1; --j) {
			if (v[j - 1][1] > v[j][1]) {
				swap(v[j - 1], v[j]);
				if (v[j - 1][1] == v[j][1]) {
					is_stable = false;
				}
			}
		}
	}
	return is_stable;
}

