    for (int i = 0; i < n - 1; i++) {
        for (int j = 1; j < n - 1; j++) {
            for (int a = 0; a < n - 1; a++) {
                for (int b = a + 1; b < n - 1; b++) {
                    if (in[i][1] == in[j][1]) {
                        if (in[i] == out[b] && in[j] == out[a]) return false;
                    }
                }
            }
        }
