                                tmp=card[b];
                                card[b]=card[a];
                                card[a]=tmp;
                        }
                }
        }

}

void insert_sort(struct Card *card,int n){
        int i,j;
        Card tmp;
        for(i=1;i<n;i++){
                tmp=card[i];
                j=i-1;
                while((j>=0)&&(tmp.num<card[j].num)){
                        card[j+1]=card[j];
                        j--;
                }
                card[j+1]=tmp;
        }
}

