}

int getMark(char M){
  if(M == 'H'){ return 0; }
  if(M == 'C'){ return 1; }
  if(M == 'S'){ return 2; }
  if(M == 'D'){ return 3; }
  return -1;
}

int selectionSort(char *M,int *A,int N,int data[10][4]){
  int i,j,temp,min,idx,cur[10],isStable = 1;
  char temp2;
  memset(cur,0,sizeof(cur));
  for(i = 0 ; i < N ; i++){
    min = A[i]; idx = i;
    for(j = i+1 ; j < N ; j++){
      if(A[j] < min){
        min = A[j];
        idx = j;
      }
    }
    if(A[idx] < A[i]){
      temp = A[i];
      A[i] = A[idx];
      A[idx] = temp;
      temp2 = M[i];
      M[i] = M[idx];
      M[idx] = temp2;
    }
  }
  for(i = 0 ; i < N ; i++){
    if(data[A[i]][cur[A[i]]] != getMark(M[i])){
      isStable = 0;
      break;
    }
    ++cur[A[i]];
  }
  return isStable;
}

int bubbleSort(char *M,int *A,int N,int data[10][4]){
  int i,j,temp,cur[10],isStable = 1;
  char temp2;
  memset(cur,0,sizeof(cur));
  for(i = 0 ; i < N ; i++){
    for(j = N-1 ; j > i ; j--){
      if(A[j-1] > A[j]){
        temp = A[j];
        A[j] = A[j-1];
        A[j-1] = temp;
        temp2 = M[j];
        M[j] = M[j-1];
        M[j-1] = temp2;
      }
    }
  }
  for(i = 0 ; i < N ; i++){
    if(data[A[i]][cur[A[i]]] != getMark(M[i])){
      isStable = 0;
      break;
    }
    ++cur[A[i]];
  }
  return isStable;
}

