vector<string> BubbleSort(vector<string> vs, int n)
{
  int i, j, flag;
  for(i=1; i<n; i++)
  {
    flag = 0;
    for(j=0; j<n-i; j++)
    {
      if(vs[j][1] > vs[j+1][1])
      {
        swap(vs[j], vs[j+1]);
        flag = 1;
      }
    }
    if(flag == 0)
      break;
  }
  return vs;
}

vector<string> SelectionSort(vector<string> vs, int n)
{
  int i, j, minv;
  for(i=0; i<n-1; i++)
  {
    minv = i;
    for(j=i+1; j<n; j++)
    {
      if(vs[j][1] < vs[minv][1])
        minv = j;
    }
    swap(vs[i], vs[minv]);
  }
  return vs;
}

