vector<card> bubble_sort(vector<card> c){
    for(int i=0; i<c.size(); i++){
        for(int j=(int)c.size()-1; j>=i+1; j--){
            if(c[j].second < c[j-1].second){
                card temp = c[j];
                c[j] = c[j-1];
                c[j-1] = temp;
            }
        }
    }
    return c;
}

vector<card> selection_sort(vector<card> c){
    for(int i=0; i<c.size(); i++){
        int min_idx = i;
        for(int j=i; j<c.size(); j++){
            if(c[j].second < c[min_idx].second){
                min_idx = j;
            }
        }
        if(min_idx==i) continue;
        card temp = c[i];
        c[i] = c[min_idx];
        c[min_idx] = temp;
    }
    return c;
}

