void bubbleSort(card a[], int len) {

	bool flag = false;	//是否完成
	for (int i = 0; i < len; i++) {
		flag = true;
		for (int j = len - 1; j > i; j--) {
			if (a[j].val < a[j - 1].val) {
				swap(a[j], a[j - 1]);
				flag = false;
			}
		}
		if (flag) return;
	}
}


void selectionSort(card a[], int len) {

	for (int i = 0; i < len; i++) {
		int min = i;
		for (int j = i + 1; j < len; j++) {
			if (a[min].val > a[j].val) min = j;
		}
		if (min != i) swap(a[i], a[min]);
	}
}

