    for(int i=0; i<N; i++) {
        int minj = i;
        for(int j=i+1; j<N; j++) {
            if(A[j].value < A[minj].value) {
                minj = j;
            }
        }
        if(i != minj) {
            swap(A[i], A[minj]);
        }
    }
} 

