public:

	void bubble_sort(Card *card, int N){
		for(int i = 0; i < N; ++i){
			for(int j = N-1; j > i; --j){
				if(card[j-1].value > card[j].value){
					Card tmp = card[j];
					card[j] = card[j-1];
					card[j-1] = tmp;
				}
			}
		}
		return;
	}

	void selection_sort(Card *card, int N){
		for(int i = 0; i < N; ++i){
			int minj = i;
			for(int j = i; j < N; ++j){
				minj = (card[minj].value > card[j].value) ? j : minj;
			}
			if(i != minj){
				Card tmp = card[i];
				card[i] = card[minj];
				card[minj] = tmp;
			}
		}
		return;
	}

	void isStable(Card *A, Card *B, int N){
		for(int i = 0; i < N; ++i){
			if(A[i].suit != B[i].suit){
				std::cout << "Not stable" << std::endl;
				return;
			}
		}
		std::cout << "Stable" << std::endl;
	}
	void output(Card *card, int N){
		for(int i = 0; i < N; ++i){
			if(i > 0) std::cout << " ";
			std::cout << card[i].suit << card[i].value;
		}
		std::cout << std::endl;
		return;
	}
};

