    for(i=0;<n;i++) { //選択ソート結果表示部
        if(i) {
            cout<<' ';
            cout<<b[i]<<B[i];
        }
    }
    cout<<endl<<check()<<endl; //安定・不安定評価の後結果表示
    return (0);
}

