	{
		for (int j = N - 1; j > i; j--)
		{
			if (a[j].key < a[j - 1].key)
			{
				swap(a[j], a[j - 1]);
			}
		}
	}


}

void selectionsort(card a[])
{
	for (int i = 0; i < N; i++)
	{
		int mini = i;
		for (int j = i + 1; j < N; j++)
		{
			if (a[j].key < a[mini].key)
				mini = j;
		}
		if (i != mini)
		{
			swap(a[i], a[mini]);
		}
	}
}

