{
	for (int i = 1; i < N; i++)
	{
		if (b[i].key == b[i - 1].key)
		{
			char c = b[i - 1].suit;
			int k = b[i].key;
			for (int j = 0; j < N; j++)
			{
				if (a[j].key == k&&a[j].suit != c)
					return 1;
				else if (a[j].key == k&&a[j].suit == c)
				{
					a[j].key = Nil;
					break;
				}

