    for (int i = 0; i < list.size(); i++) {
        for (int j = list.size() - 1; i < j; j--) {
            if (list[j].number < list[j-1].number) {
                std::swap(list[j], list[j-1]);
            }
        }
        // printList(list);
    }
    return list;
}

static bool unstable = false;
vector<Card> insertSort(vector<Card> list){
    // insert sort
    for(int i = 0; i < list.size(); i++){
        int minIndex = i;
        for(int j = i + 1; j < list.size(); j++){
            if(list[j].number < list[minIndex].number){
               minIndex = j;
            }
        }
        if(i != minIndex) {
            std::swap(list[i], list[minIndex]);
            // printf("minIndex: %d\n", minIndex);
            // printf("i       : %d\n", i);
            for(int k = minIndex - 1; i <= k; k--){
                // printf("k: %d -> %d    min: %d -> %d\n", k, list[k].number, minIndex, list[minIndex].number);
                if(list[k].number == list[minIndex].number){
                    unstable = true;
                }
            }
        }
        // printList(list);
    }
    return list;
} 



