};

void BubbleSort(CARD *C, int n)
{
    for (int i = 0; i < n; ++i) {
        for (int j = n-1; j > i; --j) {
            if (C[j].value < C[j-1].value) {
                CARD save = C[j];
                C[j] = C[j-1];
                C[j-1] = save;
            }
        }
    }
}

void SelectionSort(CARD *C, int n)
{
    for (int i = 0; i < n; ++i) {
        int min = i;
        for (int j = i; j < n; ++j) {
            if (C[j].value < C[min].value) {
                min = j;
            }
        }
        if (i != min) {
            CARD save = C[i];
            C[i] = C[min];
            C[min] = save;
        }
    }
}

bool isStable(CARD *C1, CARD *C2, int n)
{
    for (int i = 0; i < n; ++i) {
        if (C1[i].suit != C2[i].suit && C1[i].value == C2[i].value)
            return false;
    }
    return true;
}

