typedef struct{
    char suit;
    int value;
    bool check;
}CARD;

bool checkStable(int n, CARD c[], CARD a[])
{
    for (int i = 0;i < n;i++)
    {
        for (int j = 0;j < n;j++)
        {
            if (a[i].value == c[j].value)
            {
                if (a[i].suit != c[j].suit)
                {
                    if (!c[j].check) return false;
                }
                else
                {
                    c[j].check = true;
                    break;
                }
            }
        }
    }
    for (int i = 0;i < n;i++)
    {
        c[i].check = false;
    }
    return true;
}

void bubbleSort(int n, CARD a[])
{
    for (int i = 0;i < n;i++)
    {
        for (int j = n-1;j >= i+1;j--)
        {
            if (a[j].value < a[j-1].value)
            {
                CARD temp = a[j];
                a[j] = a[j-1];
                a[j-1] = temp;
            }
        }
    }
}

void selectionSort(int n, CARD a[])
{
    for (int i = 0;i < n;i++)
    {
        int mini = i;
        for (int j = i;j < n;j++)
        {
            if (a[j].value < a[mini].value)
            {
                mini = j;
            }
        }
        if (mini != i)
        {
            CARD temp = a[i];
            a[i] = a[mini];
            a[mini] = temp;
        }
    }
}

