class Tramp{
 public:
  char suit;
  int num;

  bool operator ==(const Tramp T){
    if(this->suit == T.suit && this->num == T.num)return true;
    else return false;
  }
  bool operator !=(Tramp T){
    return !(*this == T);
  }
};

void printAll(Tramp a[],int N){
  rep(i,N-1) cout << a[i].suit << a[i].num << " ";
  cout << a[N-1].suit << a[N-1].num << endl;
}

void bubbleSort(Tramp A[],int N){
  bool flag = true;
  while(flag){
    flag = false;
    for(int i=N-1;i>0;i--){
      if(A[i].num < A[i-1].num){
        swap(A[i],A[i-1]);
        flag = true;
      }
    }
  }
}

void selectionSort(Tramp A[],int N){
  for(int i=0;i<N;i++){
    int min_j = i;

    for(int j=i;j<N;j++){
      if(A[j].num < A[min_j].num)swap(min_j,j);
    }

    if(i != min_j)swap(A[i],A[min_j]);
  }
}

bool isStable(Tramp A[],Tramp c[],int N){
  for(int i=0;i<N;i++){
    for(int j=i+1;j<N;j++){
      for(int a=0;a<N;a++){
        for(int b=a+1;b<N;b++){
          if(A[i].num == A[j].num && A[i] == c[b] && A[j] == c[a]){
            return false;
            }
        }
      }
    }
  }
  return true;
}

