    std::cin >> n;
    std::cin.ignore();  //ignore \n

    const auto arr0
        = std::make_unique<Trump[]>(n);
    get_array(arr0.get(), std::cin);
    const auto arr1
        = std::make_unique<Trump[]>(n);
    std::memcpy(arr1.get(), arr0.get(), sizeof(Trump) * n);

    bubble_sort(arr0.get(), n);
    selection_sort(arr1.get(), n);

    print(arr0.get(), n);
    std::cout << std::endl;
    std::cout << "Stable" << std::endl;
    print(arr1.get(), n);
