        C[j] = C[j - 1];
        C[j - 1] = temp;
      }
    }
  }
}

void selectionSort(Card C[], int N)
{
  for (int i = 0; i < N; i++)
  {
    int minIndex = i;
    // より小さいものはないか探すループ
    for (int j = i; j < N; j++)
    {
      if (C[j].num < C[minIndex].num)
      {
        minIndex = j;
      }
    }
    // 最も小さいものを添え字0から順に入れていく
    Card temp = C[i];
    C[i] = C[minIndex];
    C[minIndex] = temp;
  }
}

