int checker(struct Card a[],struct Card b[],int n){
    int i,flag=0;
    for(i=0;i<n;i++){
        if(a[i].value==b[i].value&&a[i].suit!=b[i].suit)return 0;
        else if(a[i].value==b[i].value&&a[i].suit==b[i].suit)flag=1;

