void SelectionSort(vector<string> &A, int n) {
  for(int i = 0; i < n; i++) {
    int minj = i;
    for(int j = i; j < n; j++) {
      if(A[j][1] < A[minj][1]) {
        minj = j;
      }
    }
    if(minj != i) {
      string tmp = A[i];
      A[i] = A[minj];
      A[minj] = tmp;
    }
  }
}

void BubbleSort(vector<string> &A, int n) {
  bool flg = true;
  int sw = 0;
  while(flg) {
    flg = false;
    for(int i = n-1; i > sw; i--) {
      if(A[i-1][1] > A[i][1]) {
        string tmp = A[i];
        A[i] = A[i-1];
        A[i-1] = tmp;

        flg = true;
      }
    }
    sw++;
  }
}

int main(){
  int n;
  cin >> n;
  vector<string> c(n); // selection sort
  for(int i = 0; i < n; i++) cin >> c[i];

  vector<string> b(n); // bubble sort
  for(int i = 0; i<n; i++) b[i] = c[i];

  SelectionSort(b, n);
  BubbleSort(c, n);

  for(int i = 0; i < n; i++) {
    cout << c[i];
