    }
    swap(C[min],C[i]);
}
REP(i,N){
    for(int j=N-1;j>i;j--){
    if(B[j-1][1]>B[j][1])swap(B[j-1],B[j]);
}
}
REP(i,N-1)cout<<B[i]<<" ";
cout<<B[N-1]<<endl<<"Stable"<<endl;
if(isNotStable(N,B,C))st="Not stable";
REP(i,N-1)cout<<C[i]<<" ";
cout<<C[N-1]<<endl<<st<<endl;;
}

