    int n;
};

void trace(card a[], int n){
	for (int i = 0; i < n; i++){
		cout << a[i].s << a[i].n;
		if (i != n - 1) cout << " ";
		else cout << endl;
	}
}

void swap(card *a, card *b){
	card temp = *a;
	*a = *b;
	*b = temp;
}

void bubbleSort(card a[], int n){
	int flag = 1;
	for(int i = 0; flag; i++){
		flag = 0;
		for(int j = n - 1; j > i; j--){
			if(a[j - 1].n > a[j].n){
				swap(a[j - 1], a[j]);
				flag = 1;
			}
		}
	}
}

void selectionSort(card a[], int n){
	for(int i = 0; i < n - 1; i++){
		int minj = i;
		for(int j = i + 1; j < n; j++){
			if(a[minj].n > a[j].n) minj = j;
		}
		swap(a[i], a[minj]);
	}
}

string orderCheck(string a[], string b[]){
    string message = "Stable";
    for(int i = 0; i < 9; i++)
        if(a[i] != b[i]) message = "Not stable"; 
    return message;
}

