    int same_num;
    char fast_mark;

    for(int i = 0;i < n - 1;i++){
        for(int j = i + 1;j < n;j++){
            if(out[i].num == out[j].num){
                same_num = out[i].num;
                fast_mark = out[i].mark;

                for(int i = 0;i < n - 1;i++){
                    if((in[i].num == same_num) && (in[i].mark == fast_mark)) break;
                    else if((in[i].num == same_num) && (in[i].mark != fast_mark)) return false;
                }
            }
        }
    }

    return true;
}

