void bubbleSort(vector<pair<char,int> > &A, int n) {
	REP(i, n) {
		RFOR(j, n, i + 1) {
			if (A[j].second < A[j - 1].second) {
				A[j].swap(A[j-1]);
			}
		}
	}
	return;
}

void selectionSort(vector<pair<char,int> > &A, int n) {
	REP(i, n) {
		int mini = i;
		FOR(j, i, n) {
			if (A[j].second < A[mini].second) {
				mini = j;
			}
		}
		A[i].swap(A[mini]);
	}
}

