#include<iostream>

using namespace std;

struct poker{
    char suit;
    int data;
    bool operator !=(const poker& b){
        return this->suit != b.suit || this->data != b.data; 
    }
};

void swap(poker& a, poker& b){
    poker t;
    t = a; a = b; b = t;
}

int bubbleSort(poker a[], int n){
    int cnt = 0;
    for(int i = 1; i < n; ++i){
        bool f = true;
        for(int j = n; j > i; --j){
            if(a[j].data < a[j - 1].data) { swap(a[j], a[j - 1]); ++cnt; f = false; }
        }
        if(f) break;
    }
    return cnt;
}

int selectSort(poker a[], int n){
    int cnt = 0;
    for(int i = 1; i <n; ++i){
        a[0].data = i;
        for(int j = i + 1; j <= n; ++j){
            if(a[j].data < a[a[0].data].data) a[0].data = j;
        }
        if(a[0].data != i) { swap(a[a[0].data], a[i]); ++cnt; }
    }
    return cnt;
}

bool isStable(poker a[], poker b[], int n){
    bool f = true;
    for(int i = 1; i <= n; ++i){
        if(a[i] != b[i]) return false;
    }
    return f;
}

