    for(int i = 1; i <= n; ++i) { cin >> suit >> x; a[i].suit = b[i].suit = suit; a[i].data = b[i].data = x; }
    bubbleSort(a, n); selectSort(b, n);
    for(int i = 1; i < n; ++i) cout << a[i].suit << a[i].data << " ";
    cout << a[n].suit << a[n].data << endl << "Stable" << endl;
    for(int i = 1; i < n; ++i) cout << b[i].suit << b[i].data << " ";
    cout << b[n].suit << b[n].data << endl << (isStable(a, b, n) ? "Stable" : "Not stable") << endl;
    return 0;
}

