#include <cstdio>
#include <vector>
using namespace std;

typedef struct Node {
	char c;
	int v;
} Node;

void BubbleSort(vector<Node>& nums)
{
	for(unsigned int i = 1; i < nums.size(); ++i) {
		bool flag = true;
		for(unsigned int j = 0; j < nums.size()-i; ++j) {
			if(nums[j].v > nums[j+1].v) {
				Node t = nums[j+1]; nums[j+1] = nums[j]; nums[j] = t;
				flag = false;
			}
		}
		if(flag) {
			break;
		}
	}
}

void SelectSort(vector<Node>& nums)
{
	for(unsigned int i = 0; i < nums.size()-1; ++i) {
		unsigned int k = i;
		for(unsigned int j = i+1; j < nums.size(); ++j) {
			if(nums[j].v < nums[k].v) {
				k = j;
			}
		}
		if(k != i) {
			Node t = nums[k]; nums[k] = nums[i]; nums[i] = t;
		}
	}
}

void PrintNums(vector<Node>& nums)
{
	for(unsigned int i = 0; i < nums.size(); ++i) {
		if(i) {
			putchar(' '); 
		}
		printf("%c%d",nums[i].c,nums[i].v);
	}
	putchar('\n');	
}

int main()
{
	int n; scanf("%d%*c",&n);
	vector<Node> nums(n);
	for(int i = 0; i < n; ++i) {
		scanf("%c%d%*c",&nums[i].c,&nums[i].v);
	}
	vector<Node> nums_a(nums);
	BubbleSort(nums_a);
	PrintNums(nums_a);
	printf("Stable\n");

	vector<Node> nums_b(nums);
	SelectSort(nums_b);
	PrintNums(nums_b);
	bool Stable = true;
	for(int i = 0; i < n; ++i) {
		if(nums_a[i].c != nums_b[i].c) {
			Stable = false;
			break;
		}
	}
	printf("%s\n",!Stable?"Not stable":"Stable");
	return 0;
}

