void swap(Card &a, Card &b) {
	Card tmp = a;
	a = b;
	b = tmp;
}

void bubble_sort(Card A[], int n) {
	bool flag = true;
	int i = 0;
	while (flag) {
		flag = false;
		for (int j = n - 1; j > i; j --) {
			if (A[j].value < A[j - 1].value) {
				swap(A[j], A[j - 1]);
				flag = true;
			}
		}
		i ++;
	}
}

void selection_sort(Card A[], int n) {
	for (int i = 0; i < n - 1; i ++) {
		int minIndex = i;
		for (int j = i + 1; j < n; j ++) {
			if (A[minIndex].value > A[j].value) {
				minIndex = j;
			}
		}

		if (minIndex != i) {
			swap(A[minIndex], A[i]);
		}
	}
}

