void Card::setCard(int n[], char s[], int N)
{
	for(int i = 0; i<N; i++)
	{
		num[i] = n[i];
		suit[i] = s[i];
	}
}

void selectionSort(int n[], char s[], int N)
{
	int num[36];
	char suit[36];
	for(int i = 0; i < N; i++)
	{
		num[i] = n[i];
		suit[i] = s[i];
	}
	int min;
	for(int i = 0; i<N; i++)
	{
		min = i;
		for(int j = i; j < N; j++)
		{
			if(num[j]<num[min])
				min = j;
		}
		swap(num[i], num[min]);
		swap(suit[i], suit[min]);
	}
	showArray(num, suit, N);
}

void bubbleSort(int n[], char s[], int N)
{
	int num[36];
	char suit[36];
	for(int i = 0; i < N; i++)
	{
		num[i] = n[i];
		suit[i] = s[i];
	}
	for(int i = 0; i < N; i++)
		for(int j = N-1; j >= i; j--)
			if(num[j] < num[j-1])
			{
				swap(num[j], num[j-1]);
				swap(suit[j], suit[j-1]);
			}
	showArray(num, suit, N);
}

void swap(int& x, int& y)
{
	int temp = x;
	x = y;
	y = temp;
}

void swap(char& x, char& y)
{
	char temp = x;
	x = y;
	y = temp;
}

void showArray(int num[], char suit[], int N)
{
	cout<<suit[0] << num[0];
	for(int i = 1; i < N; i++)
		cout<<' '<< suit[i] << num[i];
	cout<<endl;
}

int decision(int n[], char s[], int N, Card c)
{
	for(int i = 0; i<N; i++)
		for(int j = i+1; j<N; j++)
			if(n[i]==n[j])
				for(int k = 0; k<N; k++)
					if(n[i]==c.getNum(k) && s[i]!=c.getSuit(k))
						return 0;
	return 1;
}

void showStable(int n[], char s[], int N, Card c)
{
	if(decision(n, s, N, c)==1)
		cout<<"Stable"<<endl;
	else
		cout<<"Not stable"<<endl;
}

