void SelectionSort(card *S, int N)
{
	int min;

	for (int i = 0; i <= N-1; i++) {
		min = i;

		for (int j = i; j <= N-1; j++) {
			if (S[min].num > S[j].num)
				min = j;
		}
		if (min != i)
			swap(S[min],S[i]);
	}
	return;
}

