#include <bits/stdc++.h>
using namespace std;

struct Card{ char Suit; int Value; };

void BubbleSort(struct Card A[], int N){

    Card bf;
    bool flag = true;

    while ( flag ){
        flag = false;
        for ( int i = N - 1; i >= 1; i-- ){
            if ( A[i].Value < A[i-1].Value ){
                bf     = A[i];
                A[i]   = A[i-1];
                A[i-1] = bf;
                flag = true;
            }
        }
    }
}

void SelectionSort(struct Card A[], int N){
    Card bf;
    int minj;

    for ( int i = 0; i < N; i++ ){
        minj = i;
        for ( int j = i; j < N; j++ ){
            if ( A[j].Value < A[minj].Value ) minj = j;
        }
        if ( minj != i ){
            bf = A[i];
            A[i] = A[minj];
            A[minj] = bf;
        }
    }
}

bool isStable( struct Card A[], struct Card B[], int N ){
    for ( int i = 0; i < N; i++ ){
        if ( A[i].Suit != B[i].Suit ) return false;
    }
    return true;
}

