using namespace std;

const int MAX = 36;

struct Tramp
{
	char suit, value;
};

void BubbleSort(struct Tramp t[], int n) {
	bool flag = true;


	for (int i = 0; i < n - 1; i++) {
		flag = false;
		for (int j = n - 1; j > i; j--) {
			if (t[j].value < t[j - 1].value) {
				swap(t[j], t[j - 1]);
				flag = true;
			}
		}
		if (!flag) {
			return;
		}
	}

}


void SelectionSort(struct Tramp t[], int n) {
	//int i = 0;
	//int j = 0;

	for (int i = 0; i < n; i++) {
		int minj = i;
		for (int j = i; j < n; j++) {
			if (t[minj].value > t[j].value) {
				minj = j;
			}
		}
		if (minj != i) {
			swap(t[i], t[minj]);
		}
	}

}

bool IsStable(const struct Tramp t1[], const struct Tramp t2[], const int n) {
	for (int i = 0; i < n; i++) {
		if (t1[i].suit != t2[i].suit) {
			return false;
		}
	}

	return true;
}

void Output(struct Tramp t[], int n) {
	for (int i = 0; i < n; i++) {
		if (i) cout << ' ';
		cout << t[i].suit << t[i].value;
	}
}

int main() {
	struct Tramp T1[MAX], T2[MAX];
	int n;
	//char ch;

	cin >> n;
	for (int i = 0; i < n; i++) {
		cin >> T1[i].suit >> T1[i].value;
	}

	for (int i = 0; i < n; i++) T2[i] = T1[i];

	BubbleSort(T1, n);
	SelectionSort(T2, n);

	Output(T1, n);
	cout << endl;
	cout << "Stable" << endl;
	Output(T2, n);
	cout << endl;
	if (IsStable(T1, T2, n)) {
		cout << "Stable" << endl;
	}
	else {
		cout << "Not stable" << endl;
	}
}

