void selectionsort(vector<pair<char,int>> &A){
    for(int i=0; i<A.size(); ++i){
        int minj = i;
        for(int j=i+1; j<A.size(); ++j){
            if( A[minj].second > A[j].second){
                minj = j;
            }
        }
        if( i!= minj){
            swap(A[i],A[minj]);
        }
    }
}

void bubblesort(vector<pair<char,int>> &A){
    bool flag = true;
    while(flag){
        flag = false;
        for(int j=A.size()-1; j>0; --j){
            if(A[j].second < A[j-1].second){
                swap(A[j], A[j-1]);
                flag =true;
            }
        }
    }
}

