void BubbleSort(vector<string> V, int N)
{
    for (int i = N - 1; i > 0; i--)
    {
        bool flag = true;
        for (int j = 0; j < i; j++)
        {
            flag = false;
            if (V[j][1] - '0' > V[j + 1][1] - '0')
            {
                swap(V[j], V[j + 1]);
                flag = true;
            }
        }
    }

    for (int i = 0; i < N; i++)
    {
        cout << V[i];
        if (i < N - 1)
        {
            cout << " ";
        }
    }
    cout << endl;
    cout << "Stable" << endl;
}

void SelectionSort(vector<string> V, int N)
{
    map<string, int> mp;
    for (int i = 0; i < N; i++)
    {
        mp[V[i]] = i;
    }

    for (int i = 0; i < N; i++)
    {
        int min_idx = i;
        for (int j = i + 1; j < N; j++)
        {
            if (V[min_idx][1] - '0' > V[j][1] - '0')
            {
                min_idx = j;
            }
        }
        swap(V[min_idx], V[i]);
    }

    for (int i = 0; i < N; i++)
    {
        cout << V[i];
        if (i < N - 1)
        {
            cout << " ";
        }
    }
    cout << endl;

    for (int i = 0; i < N; i++)
    {
        int x = V[i][1] - '0';
        for (int j = i + 1; j < N; j++)
        {
            int y = V[j][1] - '0';
            if (x == y && mp[V[i]] > mp[V[j]])
            {
                cout << "Not stable" << endl;
                return;
            }
        }
    }
    cout << "Stable" << endl;
}

