// Declaration of playing card structure
typedef struct{
    char mark;
    int number;
}CARD;

// Bubblesort
int Bubblesort(CARD* temp, int size){

    int swaps = 0;

    for(int i = 0; i < size; i++){
        for(int j = size-1; j > i; j--){
            if(temp[j].number < temp[j-1].number){
                swap(temp[j], temp[j-1]);
                swaps++;
            }
       }
    }
    return swaps;
}

// Selectionsort
int SelectionSort(CARD* temp, int size){

    int swaps = 0;

    for(int i = 0; i < size; i++){
            int mini = i;
        for(int j = i; j < size; j++){
            if(temp[j].number < temp[mini].number){
                mini = j;
            }
        }
        if(i != mini){
            swap(temp[i], temp[mini]);
            swaps++;
        }
    }
    return swaps;
}

