void bubbleSort(Card C[], int N) {
    int cnt = 0;
    for (int i = N - 1; i > 0; i--) {
        Card left = C[i-1];
        Card right = C[i];
        if (left.value > right.value) {
            C[i-1] = right;
            C[i] = left;
            cnt++;
        }
    }
    if (cnt > 0) {
        bubbleSort(C, N);
    }
}

void selectionSort(Card C[], int N, int step) {
    int min = -1;
    int minIdx = -1;
    for (int i = step; i < N; i++) {
        if (i == step) {
            min = C[i].value;
            minIdx = i;
            continue;
        }
        if (C[i].value < min) {
            min = C[i].value;
            minIdx = i;
        }
    }

    if (min == -1) {
        return;
    }

    if (minIdx != step) {
        Card v = C[step];
        C[step] = C[minIdx];
        C[minIdx] = v;
    }

    step++;
    selectionSort(C, N, step);
}

bool isStable(Card C[], int N, Card left, Card right) {
    Card P[N];
    int cnt = 0;
    for (int i = 0; i < N; i++) {
        if (C[i].value == left.value) {
            P[cnt] = C[i];
            cnt++;
        }
    }
    for (int i = 0; i < cnt; i++) {
        if (P[i].value == left.value && P[i].suit == left.suit) {
            return P[i+1].value == right.value && P[i+1].suit == right.suit;
        }
    }
    return false;
}

// 同じ数字を持つカードが複数ある場合、それらが入力に
