void checkStable(Card Original[], Card Sorted[], int N) {
    bool stable = true;
    for (int i = 1; i < N; i++) {
        Card left = Sorted[i-1];
        Card right = Sorted[i];
        if (left.value == right.value) {
            stable = isStable(Original, N, left, right) && stable;
        }
    }
    if (stable) {
        printf("%s", "Stable\n");
    } else {
        printf("%s", "Not stable\n");
    }
}

