            char t1=A[j][1],t2=A[j][0];
            A[j][1]=A[j-1][1]; A[j][0]=A[j-1][0];
            A[j-1][1]=t1; A[j-1][0]=t2;
        }
    }

  }


}

void SelectionSort(int N,char A[][2]){
  for(int i=0;i<N-1;i++){
    int minj=i;
    for(int j=i;j<N;j++){
        if(A[j][1]<A[minj][1])minj=j;

    }
    char t1=A[i][0],t2=A[i][1];
    A[i][0]=A[minj][0];A[i][1]=A[minj][1];
    A[minj][0]=t1;A[minj][1]=t2;

  }


}

