bool bubble_sort (vector<string> & a )
{
	vector<string> pre = a;
	int n = a.size();
	rep (i, n ){
		for (int j = n-1; j >= i + 1; j-- ){
			if ((int)(a[j][1] - '0' ) < (int)(a[j-1][1] - '0' ) ){
				swap (a[j], a[j-1] );
			} // end if
		} // end for
	} // end rep


	vector<string> p(10, "" );
	vector<string> q(10, "" );
	rep (i, n ){
		int num1 = (int)(pre[i][1] - '0' );
		p[num1] += pre[i][0];
		int num2 = (int)(a[i][1] - '0' );
		q[num2] += a[i][0];
	} // end rep

	rep (i, 10 )
		if (p[i] != q[i] ) return false;

	return true;
}

bool selection_sort (vector<string> & a )
{
	vector<string> pre = a;
	int n = a.size();

	rep (i, n ){
		int mini = i;
		for (int j = i; j < n; j++ ){
			if ((int)(a[j][1] - '0' ) < (int)(a[mini][1] - '0' ) ){
				mini = j;
			} // end if
		} // end for
		if (i != mini ){
			swap (a[i], a[mini] );
		} // end if
	} // end rep

	vector<string> p(10, "" );
	vector<string> q(10, "" );
	rep (i, n ){
		int num1 = (int)(pre[i][1] - '0' );
		p[num1] += pre[i][0];
		int num2 = (int)(a[i][1] - '0' );
		q[num2] += a[i][0];
	} // end rep

	rep (i, 10 )
		if (p[i] != q[i] ) return false;

	return true;
}
