void BubbleSort(char *a, int *c, int n){
  for(int i=0;i<n;i++){
    for(int j=n-1;j>i;j--){
      if(c[j] < c[j-1]){
	swap(a[j],a[j-1]);
	swap(c[j],c[j-1]);
      }
    }
  }
}

void SelectionSort(char *a, int *c, int n){
  for(int i=0;i<n;i++){
    int minj=i;
    for(int j=i;j<n;j++){
      if(c[minj] > c[j]){
	minj=j;
      }
    }
    if(minj!=i){
      swap(c[i],c[minj]);
      swap(a[i],a[minj]);
    }
  }
}

