	ss = new char[N];
	for (i=0; i<N; i++){
		std::cin >> suit >> value;
		bs[i] = suit; ss[i] = suit;
		bv[i] = value; sv[i] = value;
	}
	bubbleSort(bv, bs, N);
	trace(bv, bs, N);
	std::cout << "Stable" << std::endl;

	selectionSort(sv, ss, N);
	trace(sv, ss, N);
	if (std::strcmp(bs,ss)==0){
		std::cout << "Stable" << std::endl;
	}
	else{
		std::cout << "Not stable" << std::endl;
	}
	return 0;
}

