bool isStable(vector<Card>& in, vector<Card>& out, int n) {
    rep(i, n) {
        if (in[i].suit != out[i].suit) {
            return false;
        }
    }
    return true;
}

void bubble_sort(vector<Card>& A, int n) {
    bool flag = 1;
    for (int i = 0; flag; i++) {
        flag = 0;
        for (int j = n - 1; j >= i + 1; j--) {
            if (A[j].value < A[j - 1].value) {
                swap(A[j], A[j - 1]);
                flag = 1;
            }
        }
    }
    rep(i, n) {
        if (i) cout << " ";
        cout << A[i].suit << A[i].value;
    }
    cout << "\n";
    cout << "Stable\n";
}

void selection_sort(vector<Card>& A1, vector<Card>& A2, int n) {
    int minj;
    rep(i, n) {
        minj = i;
        for (int j = i; j < n; j++) {
            if (A2[j].value < A2[minj].value) {
                minj = j;
            }
        }
        if (minj != i) {
            swap(A2[i], A2[minj]);
        }
    }
    rep(i, n) {
        if (i) cout << " ";
        cout << A2[i].suit << A2[i].value;
    }
    cout << "\n";
    if (isStable(A1, A2, n)) {
        cout << "Stable\n";
    } else {
        cout << "Not stable\n";
    }
}

