template<class T> inline void sw(T& a, T& b) {
    T tmp = a;
    a = b;
    b = tmp;
}

template<class T> inline void bubble_sort(vector<T>& a) {
    ll n = a.size();
    rep(i, n-1) {
        rreps(j, i+1, n) {
            if (a[j] < a[j-1]) {
                sw<T>(a[j], a[j-1]);
            }
        }
    }
}
template<class T> inline bool selection_sort(vector<T>& a) {
    ll n = a.size();
    bool stable = true;

    rep(i, n-1) {
        ll argmin = i;
        T tmp = a[i];
        bool flag = false;

        reps(j, i+1, n) {
            if (a[j] == tmp) flag=true;
            if (a[j] < a[argmin]) {
                argmin = j;
                if (flag) stable = false;
            }
        }
        if (argmin != i) {
            sw<T>(a[i], a[argmin]);
        }
    }
    return stable;
}
template<class T> inline void output(vector<T>& a) {
    ll n = a.size();
    rep(i, n) {
        cout << a[i];
        if (i != n-1) cout << " ";
        else cout << "\n";
    }
}


