    }
    vector<Card> a2 = a;
    bubble_sort(a);
    output(a);
    cout << "Stable\n";

    bool stable = selection_sort(a2);
    output(a2);
    if (stable) cout << "Stable\n";
    else cout << "Not stable\n";
}

