#include <iostream>
#include <array>
#include <algorithm>
using namespace std;

static const int MAX_LEN = 36;

void output_array(array<string, MAX_LEN> arr, int arr_len)
{
  cout << arr.at(0);
  for (int i = 1; i < arr_len; ++i)
  {
    cout << ' ' << arr.at(i);
  }
  cout << endl;
}

bool card_greater(string card1, string card2)
{
  return ((int)(card1[1] - '0') < (int)(card2[1] - '0'));
}

void bubble_sort(array<string, MAX_LEN>& arr, int arr_len)
{
  bool rev_flag = true;

  for (int i = 0; i < arr_len; ++i)
  {
    rev_flag = false;

    for (int j = arr_len - 1; j > i; --j)
    {
      if (card_greater(arr.at(j), arr.at(j - 1)))
      {
        rev_flag = true;
        swap(arr.at(j - 1), arr.at(j));
      }
    }

    if (!rev_flag)
    {
      break;
    }
  }
}

void selection_sort(array<string, MAX_LEN>& arr, int arr_len)
{
  for (int i = 0; i < arr_len; ++i)
  {
    int min_index = i;

    for (int j = i; j < arr_len; ++j)
    {
      if (card_greater(arr.at(j), arr.at(min_index)))
      {
        min_index = j;
      }
    }

    if (i != min_index)
    {
      swap(arr.at(i), arr.at(min_index));
    }
  }
}

