	bool operator< (const card &rhs) const {
		return ((this->value) < (rhs.value));
	}
};

vector<card> bubble_sort (vector<card> c, size_t n) {
	for (size_t i = 0; i < n; i++) {
		for (size_t j = n; j --> i + 1;) {
			if (c[j] < c[j - 1]) swap(c[j], c[j - 1]);
		}
	}
	return c;
}

vector<card> selection_sort (vector<card> c, size_t n) {
	for (size_t i = 0; i < n; i++) {
		size_t min_j = i;
		for (size_t j = i; j < n; j++) {
			if (c[j] < c[min_j]) min_j = j;
		}
		swap(c[i], c[min_j]);
	}
	return c;
}

bool is_stable (const vector<card> &c) {
	bool flag = true;
	for (size_t i = 0; i + 1 < c.size(); i++) {
		if (c[i].value == c[i + 1].value) {
			flag &= (c[i].index < c[i + 1].index);
		}
	}
	return flag;
}

