void printStableSorted(Card a[], Card b[], int N){

    for(int i=1; i<=9; i++){

        //何個あるか
        int cnt = 0;
        for(int j=0; j<N; j++){
            if(a[j].value == i){
                cnt++;
            }
        }

        if(cnt==0) continue;

        //kindを順番にとうろく
        char akind[cnt];
        int ptr = 0;
        for(int j=0; j<N; j++){
            if(a[j].value == i){
                akind[ptr] = a[j].kind;
                ptr++;
            }
        }

        char bkind[cnt];
        ptr = 0;
        for(int j=0; j<N; j++){
            if(b[j].value == i){
                bkind[ptr] = b[j].kind;
                ptr++;
            }
        }

        //kindの順番が一致しているか
        for(int i=0; i<cnt; i++){
            if( akind[i] != bkind[i] ){
                cout << "Not stable" << endl;
                return;
            }
        }

    }

    cout << "Stable" << endl;

}

void flip(Card* a, Card* b){
    Card tmp = *a;
    *a = *b;
    *b = tmp;
}

void bubbleSort(Card C[], int N){

    for(int i=0; i<N; i++){
        for(int j=N-1; j>i; j--){
            if(C[j].value < C[j-1].value){
                flip(&C[j], &C[j-1]);
            }
        }
    }

}

void selectionSort(Card C[], int N){

    for(int i=0; i<N; i++){
        int minj = i;
        for(int j=i; j<N; j++){
            if( C[j].value < C[minj].value ){
                minj = j;
            }
        }
        flip(&C[i], &C[minj]);
    }

}

