    trump_t t0[36], t1[36];
    cin >> n;
    for(int i=0;i<n;i++){
        cin >> s;
        t0[i].suit = s[0];
        t0[i].num = s[1] - '0';
        t1[i] = t0[i];
    }
    bubbleSort(t0,n);
    pp_sorting(t0,n);
    cout << "Stable" << endl;
    selectionSort(t1,n);
