void bubbleSort(trump_t *t, int n){
    for(int i=0;i<n;i++){
        for(int j=0;j<n-1-i;j++){
            if((t+j)->num > (t+j+1)->num){
                trump_t temp = *(t+j);
                *(t+j) = *(t+j+1);
                *(t+j+1) = temp;
            }
        }
    }
}

void selectionSort(trump_t *t, int n){
    int ans = 1;
    for(int i=0;i<n;i++){
        int minj=i;
        for(int j=i;j<n;j++){
            if((t+j)->num < (t+minj)->num){
                minj = j;
            }
        }
        if(minj != i){
            trump_t temp = *(t+i);
            *(t+i) = *(t+minj);
            *(t+minj) = temp;
        }
    }
}

void pp_sorting(trump_t *t,int N){
    for(int i=0;i<N-1;i++){
        cout << (t+i)->suit << (t+i)->num << " ";
    }
    cout << (t+N-1)->suit << (t+N-1)->num << endl;
}

