#include<iostream>
using namespace std;

void BubbleSort(char *suit, int *value, int N){
    for(int i = 0; i < N; i++){
        for(int j = N-1; j > i; j--){
            if(value[j] < value[j-1]){
                int temp_int = value[j];
                value[j] = value[j-1];
                value[j-1] = temp_int;
                char temp_char = suit[j];
                suit[j] = suit[j-1];
                suit[j-1] = temp_char; 
            }
        }
    }
}

void SelectionSort(char *suit, int *value, int N){
    for(int i = 0; i < N; i++){
        int minj = i;
        for(int j = i; j < N; j++){
            if(value[j] < value[minj]){
                minj = j;
            }
        }
        int temp_int = value[i];
        value[i] = value[minj];
        value[minj] = temp_int;
        char temp_char = suit[i];
        suit[i] = suit[minj];
        suit[minj] = temp_char;
    }
}

bool isStable(char *suit1, char *suit2, int N){
    for(int i = 0; i < N; i++){
        if(suit1[i] != suit2[i]){
            return false;
        }
    }
    return true;
}

void PrintCard(char *suit, int *value, int N){
    for(int i = 0; i < N; i++){
        if(i > 0){
            cout << " ";
        }
        cout << suit[i] << value[i];
    }
    cout << endl;
}

