   for(int i = 0; i < N; i++){
       cin >> suit1[i] >> value1[i];
    }
    for(int i = 0; i < N; i++){
        suit2[i] = suit1[i];
        value2[i] = value1[i];
    }
    BubbleSort(suit1, value1, N);
    SelectionSort(suit2, value2, N);
    PrintCard(suit1, value1, N);
    cout << "Stable" << endl;
    PrintCard(suit2, value2, N);
    if(isStable(suit1, suit2, N)){
        cout << "Stable" << endl;
    }
    else{
        cout << "Not stable" << endl;
    }
    return 0;
}

