using namespace std;
void swap(int* x, int* y){
    *x += *y;
    *y = *x - *y;
    *x = *x - *y;
}
void swap2(char* x, char* y){
    *x += *y;
    *y = *x - *y;
    *x = *x - *y;
}

void trace(int A[], char B[], int n){
    cout << B[0] << A[0];
    for (int i = 1; i < n; i++)
    {
        cout << " " << B[i] <<A[i];
    }
    cout << endl;
}
void bubble_sort(int A[], char B[], int n){
    bool flag = true;
    while (flag)
    {
        flag = false;
        for (int i = n-1; i > 0; i--)
        {
            if (A[i] < A[i-1])
            {
                swap(&A[i], &A[i-1]);
                swap2(&B[i], &B[i-1]);
                flag = true;
            }   
        }   
    }
}
void insertion_sort(int A[], char B[], int n){
    int min_A;
    for (int i = 0; i < n-1; i++)
    {
        min_A = i;
        for (int j = i+1; j < n; j++)
        {
            min_A = ((A[min_A] <= A[j]) ? min_A : j);
        }
        if(min_A!=i){
        swap(&A[min_A], &A[i]);
        swap2(&B[min_A], &B[i]);
        }
    }
}

