#include <iostream>

using namespace std;

struct card {
    string lit;
    int value;

    bool operator>(const card &other) { return value > other.value; }

    bool operator<=(const card &other) { return !(*this > other); }

    bool operator!=(const card &other) { return lit != other.lit; }

    card() { ; }

    card(const string &s) {
        lit = s;
        value = s[1] - '0';
    }
};

card A[100], B[100];

void BubbleSort(card a[], int n) {
    for (int i = 0; i < n; ++i) {
        for (int j = n - 1; j > i; --j) {
            if (a[j - 1] <= a[j]) continue;
            swap(a[j - 1], a[j]);
        }
    }
}

void SelectionSort(card a[], int n) {
    for (int i = 0; i < n; ++i) {
        int selector = i;
        for (int j = i; j < n; ++j) {
            if (a[selector] > a[j])selector = j;
        }
        if (selector != i) {
            swap(a[i], a[selector]);
        }
    }
}

void outputArray(card a[], int n) {
    cout << a[0].lit;
    for (int i = 1; i < n; ++i) {
        cout << ' ' << a[i].lit;
    }
    cout << endl;
}

bool isEqual(card a[], card b[], int n) {
    for (int i = 0; i < n; ++i) if (a[i] != b[i]) return false;
    return true;
}

int main() {
    int n;
    string s;
    cin >> n;
    for (int i = 0; i < n; ++i) {
        cin >> s;
        A[i] = B[i] = card(s);
    }
    BubbleSort(A, n);
    SelectionSort(B, n);
    outputArray(A, n);
    cout << "Stable" << endl;
    outputArray(B, n);
    cout << (isEqual(A, B, n) ? "Stable" : "Not stable") << endl;
    return 0;
}

