		for(int j=n-1;j>=i;--j){
			if(a[j].value<a[j-1].value){
				swap(a[j],a[j-1]); 
			}
		}
	}
} 
void selectionsort(card a[],int n){
	int k;
	for(int i=0;i<n-1;++i){
		k=i;
		for(int j=i+1;j<n;++j){
			if(a[j].value<a[k].value){
				k=j;
			} 
		}
		if(k!=i){
			swap(a[k],a[i]);
		}
	}
}
