struct Card{
	char mark;
	int value;
};

void Swap(struct Card *x, struct Card *y){
	struct Card z = *x;
	*x = *y;
	*y = z;
}

void BubbleSort(struct Card *C, int n){
	for(int i=0;i<n;i++)
		for(int j=n-1;j>=i;j--)
			if(C[j].value < C[j-1].value)
				Swap(&C[j], &C[j-1]);
}

void SelectionSort(struct Card *C, int n){
	for(int i=0;i<n;i++){
		int minj = i;
		for(int j=i;j<n;j++)
			if(C[j].value < C[minj].value)
				minj = j;
		Swap(&C[minj], &C[i]);
	}
}

bool match(Card a, Card b){
	if((a.mark == b.mark) && (a.value == b.value))
		return true;
	else
		return false;
}

bool isStable(struct Card a[], struct Card b[], int n){
	for(int i=0;i<n;i++)
		if(!match(a[i], b[i]))
			return false;

	return true;
}

