    int flag = 1;
    int count = 0;
    int i = 0;
    while(flag){
        flag = 0;
        for(int j = N -1; j > i; j--){
            if(A[j].value < A[j-1].value){
                struct Card tmp = A[j];
                A[j] = A[j-1];
                A[j-1] = tmp;
                flag = 1;
                count++;
            }
        }
        i++;
    }
    return count;

}

int selectionSort(struct Card A[], int N){
    int count = 0;

    for(int i = 0; i < N; i++){
        int minj = i;
        for(int j = i; j < N; j++){
            if(A[j].value < A[minj].value){
                minj = j;
            }
        }
        if(i != minj){
            struct Card tmp = A[i];
            A[i]= A[minj];
            A[minj] = tmp;
            count++;
        }
    }
    return count;

}

