void Aoj_Learning()
{
	std::string sInput;
	int intInputNum = 0;
	std::istringstream ss;	// 汎用文字列ストリーム

	// 入力個数の取得
	std::cin >> sInput;
	ss = std::istringstream(sInput);
	ss >> intInputNum;
	if(intInputNum > 36 || 1 > intInputNum)
	{
		exit(0);
	}

	// 数列の取得
	std::string sInputNum[36];
	std::string sOutputBubble[36];
	std::string sOutputSelect[36];
	for(int i = 0; i < intInputNum; i++)
	{
		std::cin >> sInputNum[i];
		sOutputBubble[i] = sInputNum[i];
		sOutputSelect[i] = sInputNum[i];
	}

	// 数列を2種類のソートで整列する
	std::string sTemp;
	int temp1,temp2;

	// バブルソート
	for(int i = 0; i < intInputNum; i++)
	{
		for(int j = intInputNum-1; j > 0; j--)
		{
			sTemp = sOutputBubble[j].substr(1,1);
			ss = std::istringstream(sTemp);
			ss >> temp1;
			sTemp = sOutputBubble[j-1].substr(1,1);
			ss = std::istringstream(sTemp);
			ss >> temp2;

			if(temp1 < temp2)
			{
				sTemp = sOutputBubble[j];
				sOutputBubble[j] = sOutputBubble[j-1];
				sOutputBubble[j-1] = sTemp;
			}
		}
	}

	// バブルソートの出力
	for(int i = 0; i < intInputNum; i++)
	{
		std::cout << sOutputBubble[i];
		if(i == intInputNum-1)
		{
			std::cout << std::endl;
			// バブルソートは安定なソートとする
			std::cout << "Stable" << std::endl;
		}
		else
		{
			std::cout << " ";
		}
	}

	// 選択ソート
	int flag;
	int changeNum;
	for(int i = 0; i < intInputNum; i++)
	{
		//未整理領域から最小値を探す
		flag = 0;
		sTemp = sOutputSelect[i].substr(1,1);
		ss = std::istringstream(sTemp);
		ss >> temp1;
		for(int j = i; j < intInputNum; j++)
		{
			sTemp = sOutputSelect[j].substr(1,1);
			ss = std::istringstream(sTemp);
			ss >> temp2;
			if(temp1 > temp2)
			{
				temp1 = temp2;
				changeNum = j;
				flag = 1;	// 交換が発生する場合フラグを立てる
			}
		}

		// 最小値を未整理領域の先頭と交換
		if(flag == 1)
		{
			sTemp = sOutputSelect[i];
			sOutputSelect[i] = sOutputSelect[changeNum];
			sOutputSelect[changeNum] = sTemp;
		}
	}

	// 選択ソートの出力
	for(int i = 0; i < intInputNum; i++)
	{
		std::cout << sOutputSelect[i];
		if(i == intInputNum-1)
		{
			std::cout << std::endl;
		}
		else
		{
			std::cout << " ";
		}
	}
	// ソートの安定性チェック
	int iStableFlag = 0;
	// バブルソートの内容と比較するように変更
	for(int i = 0; i < intInputNum; i++)
	{
		if(0 != sOutputSelect[i].compare(sOutputBubble[i]))
		{
			iStableFlag = 1;
			break;
		}
	}

	if(iStableFlag == 1)
	{
		std::cout << "Not stable" << std::endl;
	}
	else
	{
		std::cout << "Stable" << std::endl;
	}
}

