template<typename T> void printVec(const vector<T>& v, char delim = ' ', ostream& os = cout) {
	os << v[0];
	for (int i = 1; i < v.size(); i++)
		os << delim << v[i];
	os << endl;
}


template<typename T> size_t insertionSort(vector<T>& A, int g = 1, bool verbose = false) {
	if (verbose)
		printVec(A);
	int N = (int)A.size();
	size_t cnt = 0;
	for (int i = g; i <= N - 1; i++) {
		T v = A[i];
		int j;
		for (j = i - g; j >= 0 && v < A[j]; j -= g) {
			A[j + g] = A[j];
			cnt++;
		}
		A[j + g] = v;
		if (verbose)
			printVec(A);
	}
	return cnt;
}

template<typename T> size_t shellSort(vector<T>& A, bool verbose = false) {
	int N = (int)A.size();
	size_t cnt = 0;

	vector<int> G;
	int g = 1;
	while (g < N) {
		G.push_back(g);
		g = 3 * g + 1;
	}
	reverse(G.begin(), G.end());

	int m = (int)G.size();
	for (int i = 0; i < m; i++)
		cnt += insertionSort(A, G[i], false);

	if (verbose) {
		cout << m << endl;
		printVec(G);
		cout << cnt << endl;
		printVec(A, '\n');
	}

	return cnt;
}

