        for (int j = N - 1; j > 0; j--) {
            // cout << v.at(j).substr(1) << endl;
            int a;
            int b;
            istringstream(v.at(j).substr(1)) >> a;
            istringstream(v.at(j - 1).substr(1)) >> b;
            if(a < b) {
                swap(v.at(j), v.at(j - 1));

                flag = 1;

                count ++;
            }
        }
    }

    for (int k = 0; k < N; k++) {
        if(k == N - 1) {
            cout << v.at(k);
        } else {
