vector<string> selectionSort(vector<string> v, int N) {
    int minj = 0;

    for (int i = 0; i < N; i++) {
        minj = i;

        for (int j = i; j < N; j++) {
            int a;
            int b;
            istringstream(v.at(j).substr(1)) >> a;
            istringstream(v.at(minj).substr(1)) >> b;
            if(a < b) {
                minj = j;
            }
        }

        if(i != minj) {
            swap(v.at(i), v.at(minj));
        }

    }

    for (int k = 0; k < N; k++) {
        if(k == N - 1) {
            cout << v.at(k);
        } else {
            cout << v.at(k) << " ";
        }
    }

    cout << endl;

    return v;
}

