void bubbleSort(Card *a, int n) {
	bool flag = true;
	while (flag) {
		flag = false;
		for (int j = n - 1; 0 < j; j--) {
			if (a[j].value < a[j - 1].value) {
				Card tmp = a[j];
				a[j] = a[j-1];
				a[j-1] = tmp;
				flag = true;
			}
		}
	}
	return;
}

void selectSort(Card *a, int n) {
	for (int i = 0; i < n; i++) {
		int min_idx = i;
		for (int j = i+1; j < n; j++) {
			if (a[j].value < a[min_idx].value) {
				min_idx = j;
			}
		}
		if (i != min_idx) {
			Card tmp = a[i];
			a[i] = a[min_idx];
			a[min_idx] = tmp;
		}
	}
	return;
}

