#include <bits/stdc++.h>
using namespace std;


int bubbleSort(string A[], int N){ // N個の要素を含む0-オリジンの配列
  int flag = 1;
  // int cnt = 0;
  while(flag) {
    flag = 0;
    for ( int j = N-1; j > 0; j--) {
      if ( A[j].at(1) < A[j-1].at(1) ) { // 交換処理があるなら、次も続けます。
        swap(A[j], A[j-1]);
        // cnt++; // counter は不要
        flag = 1;
      }
    }
  }
  return 0;
}


int selectionSort(string A[], int N) {
  int minj, flag = 1;
  for ( int i = 0; i < N - 1; i++ ) {
    minj = i;
    for ( int j = i; j < N; j++ ) { // j < Nをi < Nとすると、セグメンテーション違反となる
      if ( A[j].at(1) < A[minj].at(1) ) {
        minj = j;
      }
    }
    if ( i != minj ) {
      swap(A[i], A[minj]);
    }
  }
  return 0;
}


bool isStable(string in[], string out[], int N) {
  for ( int i = 0; i < N; i++ ) {
    for ( int j = i + 1; j < N - 1; j++ ) {
      for ( int a = 0; a < N; a++ ) {
        for ( int b = a + 1; b < N - 1; b++ ) {
          // i < j and a < b なので、1つでも入れ替わっていればfalseを返す
          if ( in[i].at(1) == in[j].at(1) && in[i] == out[b] && in[j] == out[a] ) {
            return false;
          }
        }
      }
    }
  }
  return true;
}

void out(string A[], int N, bool stability) {
  // int flag
  for (int i = 0; i < N; i++) {
    if(i) cout << " ";
    cout << A[i];
  }
  cout << endl;

  if (stability) {
    cout << "Stable" << endl;
  } else {
    cout << "Not stable" << endl;
  }
}

