	for(int i = 1;i <= 9;i++) {
		int ind[2] = {0,0};
		while(ind[0] != a.size() && ind[1] != b.size()) {
			while(a[ind[0]].value != i && ind[0] != a.size()-1) ind[0]++;
			while(b[ind[1]].value != i && ind[1] != b.size()-1) ind[1]++;
			if(a[ind[0]].suit != b[ind[1]].suit && a[ind[0]].value == i && a[ind[1]].value == i) return false;
