void printAry(Card src[], Card dst[], int N )
{ 
    if(src == NULL && dst == NULL ) {
        std::cout << "Stable" << std::endl;
        return;
    }
    if(src == NULL || dst == NULL ) {
        std::cout << "Not stable" << std::endl;
        return;
    }

    for( int i = 0; i < N; i++ ) {
        if( src[i].suit != dst[i].suit ) {
            std::cout << "Not stable" << std::endl;
            return;
        }
        if( src[i].value != dst[i].value ) {
            std::cout << "Not stable" << std::endl;
            return;
        }
    }

    std::cout << "Stable" << std::endl;
}

void printData(Card data[], int dataNum ) {
    for( int i = 0; i < dataNum; i++ ){
        if( i != 0 ) {
            std::cout << " ";
        }
        std::cout << data[i].suit << data[i].value;
    }
    std::cout << std::endl;
}

void bubbleSort(Card data[], int dataCnt ) {
    int swCnt = 0;
    for(int i = 0; i < dataCnt - 1; i++ ) {
        bool exchanged = false;
        for( int k = dataCnt - 1 - 1; k >= i; k-- ) {
            if( data[k+1].value < data[k].value ) {
                char suit = data[k+1].suit;
                int value = data[k+1].value;
                data[k+1].suit = data[k].suit;
                data[k+1].value = data[k].value;
                data[k].suit = suit;
                data[k].value = value;
                exchanged = true;
                swCnt++;
            }
        }
        if( !exchanged ) {
            break;
        }
    }
}

void selectionSort( Card data[], int dataCnt ) {
    for( int i = 0; i < dataCnt; i++) {
        int minValIndex = i;
        for( int k = i + 1; k < dataCnt; k++ ){
            if( data[minValIndex].value > data[k].value ) {
                minValIndex = k;
            }
        }
        if( i != minValIndex ) {
            Card minValCard = data[minValIndex];
            data[minValIndex] = data[i];
            data[i] = minValCard;
        }
    }
}

