template <class T>
vector<T> sosuu(T num) {
    vector<T> ans(0);
    vector<bool> p(num + 1, true);
    p[0] = false;
    p[1] = false;
    for (T i = 2; i < sqrt(num) + 1; i++) {
        if (p[i] == false) { continue; }
        T j = 2 * i;
        while (j < num + 1) {
            p[j] = false;
            j += i;
        }
    }
    for (int i = 2; i < num + 1; i++) {
        if (p[i]) { ans.push_back(i); }
    }
    return ans;
}

