    while (flag) {
        flag = false;
        for (int j = n - 1; j > 0; j--) {
            if (a[j][1] < a[j - 1][1]) {
                swap(a[j], a[j - 1]);
                flag = true;
                cnt++;
            }
        }
    }
    PRINT(a);
