void bubbleSort(struct Card A[], int N){
  for (int i=0; i<N-1; i++){
    for (int j=N-1; j>=i; j--){
      if (A[j].value < A[j-1].value) {
        // swap(A[j], A[j-1]);
        Card t = A[j]; A[j] = A[j-1]; A[j-1] = t;
      }

    }
  }
}

void selectionSort(struct Card A[], int N){
  int mini;
  for (int i=0; i<N-1; i++){
    mini = i;
    for (int j=i+1; j<N; j++){
      if (A[mini].value > A[j].value) mini = j;
    }
    Card t = A[mini]; A[mini] = A[i]; A[i] = t;
    // swap(A[mini], A[i]);
  }
}

