bool is_stable(const vector<A> &a,const vector<A> &b)
{
    vector<A> t=a;
    unsigned int i,j;
    for(i=0;i<b.size();i++)
    {
        for(j=0;j<t.size();j++)
        {
            if(t[j].num == b[i].num)
            {
                if(t[j].ch!=b[i].ch)
                {
                    return false;
                }
                t[j].num = 0;
                break;
            }
        }
    }
    return true;
}
