{
    unsigned int i,j;
    A t;
    bool flag = true;
    for(i=0;flag&&i<a.size();i++)
    {
        flag = false;
        for(j=a.size()-1;j>i;j--)
        {
            if(a[j].num<a[j-1].num)
            {
                t = a[j];
                a[j] = a[j-1];
                a[j-1] = t;
                flag = true;
            }
        }
    }
}
