using namespace std;

int main() {
	vector <int> orig;
	vector <char> origc;
	vector <int> list;
	vector <char> chars;
	int size = 5;
	int num = 0;
	char letter = ' ';

	scanf("%d%*c", &size);
	for (int i = 0; i < size; i++) {
		scanf("%c%d%*c", &letter, &num);
		orig.push_back(num);
		origc.push_back(letter);
	}
	list.assign(orig.begin(), orig.end());
	chars.assign(origc.begin(), origc.end());
	size = size-1;
	//bubble
	for (int i = 0; i <= size; i++) {
		for (int j = size; j > i; j--) {
			if (orig[j] < orig[j-1]) {
				num = orig[j];
				orig[j] = orig[j-1];
				orig[j-1] = num;

				letter = origc[j];
				origc[j] = origc[j-1];
				origc[j-1] = letter;
			}
		}
	}
	//selection
	for (int i = 0; i <= size; i++) {
		num = i;
		for (int j = i; j <= size; j++) {
			if (list[j] < list[num]) {
				num = j;
			}
		}
		if (i != num) {
			list[i] = list[i] + list[num];
			list[num] = list[i] - list[num];
			list[i] = list[i] - list[num];

			chars[i] = chars[i] + chars[num];
			chars[num] = chars[i] - chars[num];
			chars[i] = chars[i] - chars[num];
		}
	}
	for (int i = 0; i < size; i++) {
		printf("%c%d ", origc[i], orig[i]);
	}
	printf("%c%d\n", origc.back(), orig.back());
	printf("Stable\n");
	for (int i = 0; i < size; i++) {
		printf("%c%d ", chars[i], list[i]);
	}
	printf("%c%d\n", chars.back(), list.back());
	if (origc == chars) {
		printf("Stable\n");
	} else {
		printf("Not stable\n");
	}
}

