struct P{
    ll a;
    char c;

    bool operator < (const P &p){
        return a<p.a;
    }

    bool operator > (const P &p){
        return a>p.a;
    }
};

void select_sort(vector<P> &A){
    for(int i=0;i<A.size();i++){
        ll mi=i;
        for(int t=i;t<A.size();t++){
            if(A[t]<A[mi]){
                mi=t;
            }
        }
        swap(A[i],A[mi]);
    }
}


void merge_sort(vector<P> &A){
    bool j=true;
    while(j){
        j=false;
        for(int i=0;i+1<A.size();i++){
            if(A[i]>A[i+1]){swap(A[i],A[i+1]); j=true;}
        }
    }
}


