bool compare(Card C1[], Card C2[], int N) {
	bool isSame = true;
	for (int i = 0; i < N; i++) {
		if (C1[i].suit != C2[i].suit || C1[i].value != C2[i].value) {
			isSame = false;
			return isSame;
		}
	}
	return isSame;
}

int bubbleSort(Card C[], int N) {
    int sw = 0;
    bool flag = true;
    int i = 0;
    while (flag) {
        flag = false;
        for (int j = N - 1; j > i; j--) {
            if (C[j].value < C[j - 1].value) {
                flag = true;
                swap(C[j], C[j - 1]);
                sw++;
            }
        }
		i++;
    }

    return sw;
}

int selectionSort(Card C[], int N) {
    int sw = 0;
    int i = 0;
	for (int i = 0; i < N - 1; i++) {
		int minj = i;
		for (int j = i + 1; j < N; j++) {
			if (C[j].value < C[minj].value)
				minj = j;
		}
		if (minj != i) {
			swap(C[i], C[minj]);
			sw++;
		}
	}
    return sw;
}

