//Declaration
class Card{
public:
    Card( const std::string str );
    char GetSymbol();
    int GetNumber();
    std::string GetString();

private:
    std::string pair;
};

void MySwap( Card& a, Card& b );
void BubbleSort( std::vector<Card>& vec );
void SelectionSort( std::vector<Card>& vec );
std::unordered_map<char, int> CardSymbolOrder( std::vector<Card>& vec, int index );
std::string CheckStable( std::vector<Card>& vec, std::vector<Card>& input );

int main(){
