    for( ; i < n; ++i ){
        std::cin >> str;
        input.push_back( Card(str) );
        bubble.push_back( Card(str) );
        select.push_back( Card(str) );
    }

    //----Sort Section----
    BubbleSort(bubble);
    SelectionSort(select);

    //----Output Section----
    for( i = 0; i < n; ++i ){
        std::cout << bubble[i].GetString() << ( ( i != n-1 )? " " : "" );
    }
    std::cout << "\n" << CheckStable(bubble, input) << "\n";

    for( i = 0; i < n; ++i ){
