//Definition
Card::Card( const std::string str ){
    pair = str;
}

char Card::GetSymbol(){
    return pair[0];
}

int Card::GetNumber(){
    return static_cast<int>( pair[1] - '0' );
}

std::string Card::GetString(){
    return pair;
}

void MySwap( Card& a, Card& b ){
    Card tmp = std::move(a);
    a = std::move(b);
    b = std::move(tmp);
}

void BubbleSort( std::vector<Card>& vec ){
    int n = vec.size();
    for( int i = 0; i < n; ++i ){
        for( int j = n - 1; j > i; --j ){
            if( vec[j].GetNumber() < vec[j-1].GetNumber() ){
                MySwap( vec[j], vec[j-1] );
            }
        }
    }
}

void SelectionSort( std::vector<Card>& vec ){
    int n = vec.size();
    int minj;
    int j;
    for( int i = 0; i < n; ++i ){
        minj = i;
        for( j = i; j < n; ++j ){
            if( vec[j].GetNumber() < vec[minj].GetNumber() ){
                minj = j;
            }
        }
        if( i != minj ){
            MySwap( vec[i], vec[minj] );
        }
    }
}

std::unordered_map<char, int> CardSymbolOrder( std::vector<Card>& vec, int index ){
    std::unordered_map<char, int> csorder;
    int order = 0;
    for( int i = 0; i < vec.size(); ++i ){
        if( vec[i].GetNumber() == index ){
            csorder[vec[i].GetSymbol()] = order++;
        }
    }
    return csorder;
}

std::string CheckStable( std::vector<Card>& vec, std::vector<Card>& input ){
    int i = 0;
    int n = vec.size();
    std::unordered_map<char, int> csorder;
    for( i = 1; i < n; ++i ){
        if( vec[i-1].GetNumber() == vec[i].GetNumber() ){
            csorder = CardSymbolOrder( vec, vec[i].GetNumber() );
            if( csorder[vec[i-1].GetSymbol()] > csorder[vec[i].GetSymbol()] ){
                return "Not stable";
            }
        }
    }
    return "Stable";
}

#include <iostream>
#include <vector>
#define FOR(i,m,n) for(int i=(m);i<(n);++i)
#define REP(i,n) FOR(i,0,n)
using namespace std;
using ll = long long;

struct t{
  char mark;
  int num;
};

void Output(const vector<t> &a){
  REP(i,a.size()){
    cout << a[i].mark << a[i].num;
    if(i != a.size()-1) cout << " ";
  }
  cout << endl;
}

void isStable(vector<t> &card, const vector<vector<char>> &order){
  vector<vector<char>> buf(9, vector<char>());
  REP(i,card.size()) buf[card[i].num-1].push_back(card[i].mark);
  REP(i,9){
    if(buf[i] != order[i]){
      cout << "Not stable" << endl;
      return;
    }
  }
  cout << "Stable" << endl;
}

void BubbleSort(vector<t> a, int n, const vector<vector<char>> &order){
  bool flag = 1;
  while(flag){
    flag = 0;
    for(int i=n-1;i>=1;--i){
      if(a[i-1].num > a[i].num){
        swap(a[i-1], a[i]);
        flag = 1;
      }
    }
  }
  Output(a);
  isStable(a, order);
}

void SelectionSort(vector<t> a, int n, const vector<vector<char>> &order){
  REP(i,n){
    int minj = i;
    FOR(j,i,n){
      if(a[minj].num > a[j].num) minj = j;
    }
    if(i != minj){
      swap(a[i], a[minj]);
    }
  }
  Output(a);
  isStable(a, order);
}

