  vector<t> card(n);
  vector<vector<char>> order(9, vector<char>());
  REP(i,n){
    cin >> card[i].mark >> card[i].num;
    order[card[i].num-1].push_back(card[i].mark);
  }
  BubbleSort(card, n, order);
  SelectionSort(card, n, order);
  return 0;
}

