template<typename T>
void trace(T a[], int n) {
	for (int i = 0; i < n; i++) {
		if (i > 0) printf(" ");
		printf("%c%c", a[i].first, a[i].second);
	}
	printf("\n");
}
template<typename T> 
void MySwap(T &a, T &b) {
	T t = a;
	a = b;
	b = t;
}
template<typename T>
void bubbleSort(T a[], int n) {
	for (int i = n - 1; i > 0; i--) {
		int flag = 1; 
		for (int j = 0; j < i; j++) {
			if (a[j].second > a[j + 1].second) {
				MySwap(a[j], a[j + 1]);
				flag = 0; 
			}
		}
		if (flag) break; //当数组不存在顺序相反的相邻元素提前退出 
	}
	trace(a, n);
}
template<typename T>
void selectionSort(T a[], int n) {
	int minj;
	for (int i = 0; i < n; i++) {
		minj = i;
		for (int j = i; j < n; j++) {
			if (a[j].second < a[minj].second) minj = j;
		}
		if (i != minj) MySwap(a[i], a[minj]);
	}
 	trace(a, n);
} 

