#include<bits/stdc++.h>
using namespace std;

#define reps(i, a, b) for (int i = (a); i < (b); i++)
#define rreps(i, a, b) for (int i = (int) (a) - 1; i >= (b); i--)

vector<pair<int, char>> b(int N, const vector<pair<int, char>>& v) {
	auto res = v;
    reps(i, 0, N) {
        rreps(j, N, i+1) {
            if (res[j].first < res[j-1].first) {
                swap(res[j], res[j-1]);
            }
        }
    }
	return res;
}

vector<pair<int, char>> s(int N, const vector<pair<int, char>>& v) {
	auto res = v;
    reps(i, 0, N) {
        int mi = i;
        reps(j, i, N) {
            if (res[j].first < res[mi].first) {
                mi = j;
            }
        }
        if (i != mi) swap(res[i], res[mi]);
    }
	return res;
}

