    int N;
	cin >> N;
    vector<pair<int, char>> v;
    for (int i = 0; i < N; i++) {
        string s;
        cin >> s;
        v.emplace_back(s[1]-'0', s[0]);
    }
    auto a = b(N, v);
    auto w = s(N, v);
    for (int i = 0; i < N; i++) {
		if (i) cout << " ";
        cout << a[i].second << a[i].first;
