using namespace std; 

void bubblesort(int value[], char suit[], int n){
	for (int i=0; i<n; i++){
		for (int j=n-1; j>i; j--){
			if (value[j] < value[j-1]){
				int tmp_value = value[j];
				char tmp_suit = suit[j];
				value[j] = value[j-1];
				suit[j] = suit[j-1];
				value[j-1] = tmp_value;
				suit[j-1] = tmp_suit;
			}
		}
	}	
}

void selectionsort(int value[], char suit[], int n){
	for (int i=0; i<n; i++){
		int minj = i;
		for (int j=i; j<n; j++){
			if (value[j] < value[minj]){
				minj = j;
			}
		}
		if (minj != i){
			int tmp_value = value[i];
			char tmp_suit = suit[i];
			value[i] = value[minj];
			suit[i] = suit[minj];
			value[minj] = tmp_value;
			suit[minj] = tmp_suit;
		}
	}
}

void is_stable(int value[], char suit[], int v[], char s[], int n){
	char order[40];
	int ordercnt[10];
	char o[40];
	int ocnt[10];

	//initialize
	for (int i=0; i<10; i++){
		ordercnt[i] = 0;
		ocnt[i] = 0;
		for (int j=0; j<4; j++){
			//initialize
			order[j*10+i] = 'a';
			o[j*10+i] = 'a';
		}
	}

	for (int i=0; i<n; i++){
		order[ordercnt[value[i]]*10+value[i]] = suit[i];
		o[ocnt[v[i]]*10+v[i]] = s[i];
		ordercnt[value[i]] += 1;
		ocnt[v[i]] += 1;
	}

	bool stable = true;
	for (int i=0; i<40; i++){
		if (order[i] != o[i]){
			stable = false;
		}
	}

	if (stable){
		cout << "Stable" << endl;
	}
	else{
		cout << "Not stable" << endl;
	}
}

void copylist(int aint[], char achar[], int bint[], char bchar[], int n){
	for (int i=0; i<n; i++){
		bint[i] = aint[i];
		bchar[i] = achar[i];
	}
}

void printarray(int value[], char suit[], int n){
	for (int i=0; i<n; i++){
		if (i==n-1){
			cout << suit[i] << value[i] << endl;
		}
		else{
			cout << suit[i] << value[i] << " ";
		}
	}
}

int main(){
	int n;
	cin >> n;
	int value[n];
	char suit[n];
	for (int i=0; i<n; i++){
		int tmp_value;
		char tmp_suit;
		char tmp[2];
		cin >> tmp;
		value[i] = tmp[1]-'0';
		suit[i] = tmp[0];
	}
	int lb_value[n];
	char lb_suit[n];
	int ls_value[n];
	char ls_suit[n];
	copylist(value,suit,lb_value,lb_suit,n);
	copylist(value,suit,ls_value,ls_suit,n);

	bubblesort(lb_value, lb_suit, n);
	selectionsort(ls_value, ls_suit, n);

	printarray(lb_value, lb_suit, n);
	is_stable(value, suit, lb_value, lb_suit, n);
	printarray(ls_value, ls_suit, n);
	is_stable(value, suit, ls_value, ls_suit, n);

	return 0;
}

