void swap(card *a, int i, int j) {
	card tmp = a[i];
	a[i] = a[j];
	a[j] = tmp;
}

void printCard(card *a, int n) {
	cout << a[0].suit << a[0].value;
	for(int i=1; i<n; i++) {
		cout << " " << a[i].suit << a[i].value;
	}
	cout << endl;
}

