};


void BubbleSort(Trump trump[], int n){
	for (int i = 0; i < n ; i++){
		for (int j = n - 1; j >= i ; j--){
			if (trump[j].num < trump[j - 1].num){
				swap(trump[j], trump[j - 1]);
            }
        }
    }
}

void SelectionSort(Trump trump[], int n) {
    for (int i = 0; i < n; i++) {
        int minj;
        minj = i;
        for (int j = i; j < n  ; j++) {
            if (trump[j].num < trump[minj].num) {
                minj = j;
            }
        }
        swap(trump[i], trump[minj]);
    }
}


