#include<iostream>
#include<stdio.h>
#include<string>
#include <algorithm>
#include<cstring>
#include <math.h>
#include <iomanip>
using namespace std;

struct tr{
  char m;
  int value;
};

void BubbleSort(tr *C,int N)
{
  for(int i = 0;i<N;i++){
    for(int j = N-1; j>i;j--){
      if(C[j].value < C[j-1].value){
	tr a=C[j];
	C[j]=C[j-1];
	C[j-1]=a;
      }
    }
  }
}

void SelectionSort(tr *C,int N)
{
  for(int i = 0;i<N;i++){
    int minj = i;
    for(int j = i;j<N;j++){
      if (C[j].value < C[minj].value)
        minj = j;
    }
    tr a=C[i];
    C[i]=C[minj];
    C[minj]=a;
  }
}

bool isStable(tr *in,tr *out,int N){
  int i,j,a,b;
  for (i = 0;i<N;i++){
    for (j = i+1;j<N;j++){
      for (a = 0;a<N;a++){
	for (b = a+1;b<N;b++){
	  if(in[i].value==in[j].value){
	    if(in[i].m== out[b].m &&in[i].value== out[b].value){
	      if( in[j].m == out[a].m  && in[j].value == out[a].value)
		return false;
	    }
	  }
	}
      }
    }
  }
  return true;
}

