using namespace std;

void selection_sort(vector<int> &list, vector<int> &order) {
  for (int i = 0; i < list.size(); ++i) {
    int mini = i;
    for (int j = i + 1; j < list.size(); ++j) {
      if (list[j] < list[mini]) {
        mini = j;
      }
    }
    if (mini != i) {
      int tmp = list[mini];
      list[mini] = list[i];
      list[i] = tmp;
      int tmp_order = order[mini];
      order[mini] = order[i];
      order[i] = tmp_order;
    }
  }
}

void bubble_sort(vector<int> &list, vector<int> &order) {
  for (int i = 0; i < list.size(); ++i) {
    for (int j = list.size() - 1; j > i; --j) {
      if (list[j] < list[j-1]) {
        int tmp = list[j];
        list[j] = list[j-1];
        list[j-1] = tmp;
        int tmp_order = order[j];
        order[j] = order[j-1];
        order[j-1] = tmp_order;
      }
    }
  }
}

