    int minj = i;
    for(int j = i; j < N; j++){
      if(rt.at(j)[1] < rt.at(minj)[1]) minj = j;
    }
    if(i != minj) swap(rt.at(i), rt.at(minj));
  }
  if(rt == bs) return true;
  else return false;
}

