				for (int b = a + 1; b < N; ++b) {
					if ((In[i])[1] == (In[j])[1] && In[i] == Out[b] && In[j] == Out[a]) {
						return false;
					}
				}
			}
		}
	}
	return true;
}
void SelectionSort(vector<string> A, vector<string> inA, int N) { // N 個の要素を含む 0-オリジンの配列 A
	for (int i = 0; i < N-1;++i) {
		int minj = i;
		for (int j = i; j < N ;++j) {
			if ((A[j])[1]<(A[minj])[1]) {
				minj = j;
			}
		}
		if (i!=minj) {
