bool bubbleSort(char A[][2], long n) {
	bool stbl = true;
	bool flag = true;
	for (long m = n; flag && m > 0; m--) {
		flag = false;
		for (long i = 1; i < m; i++) {
			if (A[i - 1][1] > A[i][1]) {
				for (int j = 0; j < 2; j++) {
					char v = A[i][j];
					A[i][j] = A[i - 1][j];
					A[i - 1][j] = v;
					flag = true;
				}
			}
		}
	}
	return stbl;
}

bool selectionSort(char A[][2], long n) {
	char O[n][2];
	for (long i = 0; i < n; i++) {
		for (long j = 0; j < 2; j++) {
			O[i][j] = A[i][j];
		}
	}
	for (long i = 0; i < n; i++) {
		long mini = i;
		for (long j = i; j < n; j++) {
			if (A[j][1] < A[mini][1]) {
				mini = j;
			}
		}
		if (mini != i) {
			for (int k = 0; k < 2; k++) {
				char v = A[i][k];
				A[i][k] = A[mini][k];
				A[mini][k] = v;
			}
		}
	}

	bool stbl = true;
	for (long i = 0; i < n; i++) {
		long j;
		if (i == 0 || A[i][1] > A[i - 1][1]) {
			j = 0;
		}
		while (j < n && O[j][1] != A[i][1]) {
			j++;
		}
		if (j >= n) {
			stbl = false;
			break;
		}
		j++;
	}

	return stbl;
}

