		switch (i) {
			case 0: {
				stbl = bubbleSort(A, n);
				print(A, n);
				break;
			}
			case 1: {
				stbl = selectionSort(B, n);
				print(B, n);
				break;
			}
		}
		switch (stbl) {
			case true: {
