  int value;
};


void bubble_sort(Card cards[], const int n) {
  bool sorted;

  while(!sorted) {
    sorted = true;
    for (int i = n - 1; i > 0; i--) {
      if (cards[i].value < cards[i - 1].value) {
        Card tmp = cards[i];
        cards[i] = cards[i - 1];
        cards[i - 1] = tmp;
        sorted = false;
      }
    }
  }
}

void selection_sort(Card cards[], int n) {
  for (int i = 0; i < n; i++) {
    int min_index = i;
    for (int j = i + 1; j < n; j++) {
      if (cards[j].value < cards[min_index].value) {
        min_index = j;
      }
    }
    if (cards[min_index].value < cards[i].value) {
      Card tmp = cards[i];
      cards[i] = cards[min_index];
      cards[min_index] = tmp;
    }
  }
}


bool is_stable(Card input[], Card sorted[], int n) {
  for (int i = 0; i < n - 1; i++) {
    if (sorted[i].value == sorted[i+1].value) {
      for (int j = 0; j < n; j++) {
        if (input[j].value == sorted[i].value) {
          if (input[j].suit == sorted[i].suit) {
            break;
          } else if (input[j].suit == sorted[i+1].suit) {
            return false;
          }
        }
      }
    }
  }
  return true;
}


