typedef pair<char,int> Pair;

void BubbleSort(vector<Pair> &v){
  Pair tmp;
  for(int i=0;i<v.size();i++){
    for(int j=v.size()-1;j>i;j--){
      if(v.at(j).second < v.at(j-1).second){
        tmp=v.at(j);
        v.at(j)=v.at(j-1);
        v.at(j-1)=tmp;
      }
    }
  }
}

void SelectionSort(vector<Pair> &v){
  int minj;
  Pair tmp;
  for(int i=0;i<v.size();i++){
    minj=i;
    for(int j=i;j<v.size();j++){
      if(v.at(j).second < v.at(minj).second){
        minj=j;
      }
    }
    tmp=v.at(i);
    v.at(i)=v.at(minj);
    v.at(minj)=tmp;
  }
}

