template<class T>
void BubbleSort(std::vector<T> & A,int & swaptimes)
{
	for(int i=0;i<(int)A.size();i++){
		for(int j=(int)A.size()-1;j>i;--j){
			if (A[j].value < A[j-1].value) {
				T tmp = A[j];
				A[j] = A[j-1];
				A[j-1]=tmp;
				swaptimes++;
			}
		}
	}
}
template<class T>
void SelectionSort(std::vector<T> & A,int & swaptimes)
{
	for(int i=0;i<(int)A.size();++i){
		int mini=i;
		for(int j=i;j<(int)A.size();++j){
			if (A[j].value < A[mini].value) {
				mini = j;
			}
		}
		if (mini != i) {
			T tmp = A[mini];
			A[mini] = A[i];
			A[i]=tmp;
			swaptimes++;
		}
	}
}

