class CARD
{
public:
    CARD(){}
    CARD(CARD &card)
    : suit(card.suit), value(card.value) {}

    char suit;
    int  value;

    bool operator > (CARD target)
    {
        if (value > target.value) return true;
        else                      return false;
    }

    bool operator < (CARD target)
    {
        if (value < target.value) return true;
        else                      return false;
    }

    bool operator != (CARD target)
    {
        if (value != target.value) return true;
        else                       return false;
    }
};

int bubbleSort(CARD A[], int N)
{
    bool flag = true;
    while (flag)
    {
        flag = false;

        for (int j = N-1; j > 0; j--)
        {
            if (A[j] < A[j-1])
            {
                CARD temp = A[j];
                A[j]   = A[j-1];
                A[j-1] = temp;
                flag = true;
            }
        }
    }
}

void selectionSort(CARD A[], int N)
{
    for (int i = 0; i < N; i++)
    {
        int minj = i;

        for (int j = i; j < N; j++)
        {
            if (A[j] < A[minj])
            {
                minj = j;
            }
        }

        CARD temp = A[i];
        A[i] = A[minj];
        A[minj] = temp;
    }
}

