        if( k == n - 1) {
            cout << cards[k].suit << cards[k].value;
        } else {
            cout << cards[k].suit << cards[k].value << " ";
        }
    }
    cout << endl;
}

void bubble_sort(Card cards[], int n) {
    int flag = 1;
    for (int i = 0; flag; ++i) {
       flag = 0;
        for (int j = n - 1; j >= i + 1; --j) {
            if(cards[j].value < cards[j - 1].value) {
                Card temp = cards[j];
                cards[j] = cards[j - 1];
                cards[j - 1] = temp;
                flag = 1;
            }
        }
    }
    show(cards, n);
}

void select_sort(Card cards[], int n) {
    for (int i = 0; i < n; ++i) {
        int min = i;
        for (int j = i; j < n; ++j) {
            if(cards[j].value < cards[min].value) {
                min = j;
            }
        }
        if(i != min) {
            Card temp = cards[i];
            cards[i] = cards[min];
            cards[min] = temp;
        }
    }
    show(cards, n);
}

