void insertion_sort(long A[], int n, int g){
    for(int i = g; i <= n-1; ++i){
        int v = A[i];
        int j = i-g;
        while(j>=0&&A[j]>v){
            A[j+g] = A[j];
            j = j-g;
            cnt++;
        }
        A[j+g] = v;
    }
}

void shell_sort(long A[], int n, int m){
    for(int i = m-1; i >= 0; --i){
        insertion_sort(A, n, gap_list[i]);
    }
    return;
}

