  for(int i=0; i<N-1; ++i) {
    for(int j=N-1; j>i; --j) {
      if(C[j].number<C[j-1].number) {
        swap(C[j].number, C[j-1].number);
        swap(C[j].mark, C[j-1].mark);
      }
    }
  }
}

void selectionsort(struct Card C[], int N) {

  int minj;
  for(int i=0; i<N-1; ++i) {
    minj = i;
    for(int j = i; j<N; ++j) {
      if(C[j].number<C[minj].number)
        minj = j;
    }
    swap(C[i].number, C[minj].number);
    swap(C[i].mark, C[minj].mark);
  }
}

bool isStable(struct Card in[], struct Card out[], int N) {

  for(int i=0; i<N-1; ++i) {
    for(int j=i+1; j<N-1; ++j) {
      for(int a=0; a<N-1; ++a) {
        for(int b=a+1; b<N-1; ++b) {
          if(in[i].number==in[j].number&&in[i].number==out[b].number&&in[j].number==out[a].number) {
            return false;
          }
        }
      }
    }
  }

  return true;
}

