#include<stdio.h>
#include<string.h>

struct CARD {
	int num;
	char sym;
};

void PrintCARD(struct CARD a[], int N) {
	int i;
	for (i = 0; i < N; i++) {
		printf("%c%d", a[i].sym, a[i].num);
		if (!(i - N + 1)) break;
		printf(" ");
	}
	printf("\n");
}

void swap(struct CARD a[], int i, int j) {
	struct CARD buff = a[i];
	a[i] = a[j];
	a[j] = buff;
}

void BubbleSort(struct CARD a[], int N) {
	int i, j;
	for (i = 0; i < N; i++) {
		for (j = N - 1; j > i; j--) {
			if (a[j].num < a[j - 1].num) swap(a, j, j - 1);
		}
	}
}

void SelectionSort(struct CARD a[], int N) {
	int min;
	for (int i = 0; i < N; i++) {
		min = i;
		for (int j = i + 1; j < N; j++) {
			if (a[min].num > a[j].num) min = j;
		}
		if (min - i)
		{
			swap(a, i, min);
		}
	}
}


