void selectionSort(char A_symbol[], int A_num[],int N){
	int minj;//minjはA[i]?A[N-1]の最小値の添え字
	char tmpstr;
	int tmp;
	int cnt=0;//交換回数
	for(int i=0;i<N;i++){
		minj = i;
		for(int j=i;j<N;j++){
			if(A_num[j] < A_num[minj]){
				minj = j;
