int judge_stable(card c[],card sorted_c[], int N){
    int beforenum = 10;
    int samenum = 1;
    for(int i=0; i<N; i++){
        if(beforenum==sorted_c[i].value){
            samenum += 1;
        }else samenum = 1;

        int iter = samenum;
        for(int j=0; j<N; j++){
            if(c[j].value==sorted_c[i].value){
                iter -= 1;
                if((c[j].suit!=sorted_c[i].suit) && iter==0){
                    cout << "Not stable" << endl;
                    return 0;
                }else break;
            }
        }
        beforenum = sorted_c[i].value;
    }
    cout << "Stable" << endl;
    return 0;
}

