int bubbleSort(vector<string> &C, int N) {
  for (int i = 0; i < N; i++) {
    for (int j = N - 1; i < j; j--) {
      if (C.at(j).at(1) < C.at(j - 1).at(1)) {
        swap(C.at(j), C.at(j - 1));
      }
    }
  }
}

int selectionSort(vector<string> &C, int N) {
  int minj;

  for (int i = 0; i < N; i++) {
    minj = i;

    for (int j = i; j < N; j++) {
      if (C.at(j).at(1) < C.at(minj).at(1)) {
        minj = j;
      }
    }

    if (i != minj) {
      swap(C.at(i), C.at(minj));
    }
  }
}

