template<typename T>
vector<T> bubble_sort(vector<T> A)
{
  int n = A.size();
  for (int i = 0; i < n; ++i)
    for (int j = n-1; j > i; --j)
      if (A[j] < A[j-1])
        swap(A[j], A[j-1]);
  return A;
}

template<typename T>
vector<T> selection_sort(vector<T> A)
{
  int n = A.size();
  for (int i =0; i<n; ++i) {
    int minidx = i;
    for (int j = i; j < n; ++j) {
      if (A[j] < A[minidx])
        minidx = j;
    }
    swap(A[i], A[minidx]);
  }
  return A;
}

