	int num;
};

void BubbleSort(struct Card A[],int n){
	for(int i=0;i<n;i++){
		for(int j=n-1;j>i;j--){
			if(A[j].num<A[j-1].num) std::swap(A[j],A[j-1]);
		}
	}
	for(int i=0;i<n;i++)
		std::cout<<(i?" ":"")<<A[i].picture<<A[i].num;
	std::cout<<std::endl<<"Stable"<<std::endl;
}


void SelectionSort(struct Card A[],int n){
	for(int i=0;i<n;i++){
		int minj=i;
		for(int j=i+1;j<n;j++){
			if(A[j].num<A[minj].num) minj=j;
		}
		std::swap(A[minj],A[i]);
	}
	for(int i=0;i<n;i++)
		std::cout<<(i?" ":"")<<A[i].picture<<A[i].num;
	std::cout<<std::endl;
}


