#include<iostream>
using namespace std;

struct card{
    char suit;
    int value;
};

void bubbleSort(card a[],int n){
    int flag=1;
    for(int i=0;i<n-1;++i){
        if(!flag)break;
        flag=0;
        for(int j=n-1;j>i;j--){
            if(a[j]<a[j-1]){
                flag=1;
                card t=a[j];
                a[j]=a[j-1];
                a[j-1]=t;
            }
        }
    }
}

void selectionSort(card c[],int n){
   int min;
    for(int i=0;i<n-1;++i){
        min=i;
        for(int j=i+1;j<n;++j){
            if(c[j]<c[min])
                min=j;
        }
        if(min!=i){card t=c[i];c[i]=c[min];c[min]=t;}
    }
}

bool isStable(card c1[],card c2[];int n){
    for(int i=0;i<n;++i)
      if(c1[i]!=c2[i])return false;

    return true;
}
