int selectionSort(vector<pair<char, int> > &a, int n)
{
    int count = 0;

    rep(i, n)
    {
        int minj = i;
        for (int j = i; j < n; j++)
        {
            if (a.at(j).second < a.at(minj).second)
            {
                minj = j;
            }
        }

        swap(a.at(i), a.at(minj));
        count++;
    }
    return count;
}

