#include <bits/stdc++.h>
using namespace std;

struct Card { char suit, value; };

void bubble(Card A[], int N) {
    for (int i = 0; i < N; i++) {
        for (int j = N-1; j > i; j--) {
            if (A[j].value < A[j-1].value) {
                swap(A[j], A[j-1]);
            }
        }
    }
}

void selection(Card A[], int N) {
    for (int i = 0; i < N; i++) {
        int minj = i;
        for (int j = i; j < N; j++) {
            if (A[j].value < A[minj].value) minj = j;
        }
        swap(A[i], A[minj]);
    }
}

void printCard(Card A[], int N) {
    for (int i = 0; i < N; i++) {
        if (i == N-1) cout << A[i].suit << A[i].value << endl;
        else cout << A[i].suit << A[i].value << " ";
    }
}

// Stableなバブルソートを基準に選択ソートが安定かを判定
bool isStable(Card C1[], Card C2[], int N) {
    for (int i = 0; i < N; i++) {
        if (C1[i].suit != C2[i].suit) return false;
    }
    return true;
}

int main() {
    int N;
    Card C1[100], C2[100];
    char ch;

    cin >> N;
    for (int i = 0; i < N; i++) {
        cin >> C1[i].suit >> C1[i].value;
    }

    for (int i = 0; i < N; i++) C2[i] = C1[i]; // C1 を C2にコピー

    bubble(C1, N);
    selection(C2, N);

    printCard(C1, N);
    cout << "Stable" << endl;

    printCard(C2, N);
    if (isStable(C1, C2, N)) cout << "Stable" << endl;
