#include <iostream>
#include <string.h>

#define MAX 36

using namespace std;

void bubbleSort(string *a,int n){
    for(int i=0;i<n-1;i++){
        for(int j=n-1;i<j;j--){
            if(atoi(&a[j][1])<atoi(&a[j-1][1])){
                swap(a[j],a[j-1]);
            }
        }
    }
}

void selectionSort(string *a,int n){
    for(int i=0;i<n-1;i++){
        int minj=i;
        for(int j=i+1;j<n;j++){
            if(atoi(&a[j][1])<atoi(&a[minj][1])){
                minj=j;
            }
        }
        swap(a[i],a[minj]);
    }
}

void show(string *a,int n){
    for(int i=0;i<n;i++){
        cout<<a[i];
        if(i<n-1){
            cout<<" ";
        }else{
            cout<<endl;
        }
    }
}

void isStable(string *a, string *b, int n,bool mode){
    for(int i=0;mode==true && i<n;i++){
        if(a[i]!=b[i]){
            cout<<"Not stable"<<endl;
            return;
        }
    }
    cout<<"Stable"<<endl;
}

int main(){
    int n;
    string a[MAX], b[MAX],s[MAX];

    cin>>n;
    for(int i=0;i<n;i++){
        cin>>a[i];
    }
    memcpy(b,a, sizeof(a));
    bubbleSort(b,n);
    show(b,n);
    isStable(a,b,n, false);
    memcpy(s,a, sizeof(a));
    selectionSort(s,n);
    show(s,n);
    isStable(b, s, n, true);
    return 0;
}

