    rep(i, 0, n) {
        cout << a[i].suit << a[i].value;
        if (i != n - 1) { cout << " "; }
        else { cout << endl; }
    }
}

vector<Card> bubble_sort(const vector<Card>& a) {
    int n = a.size();

    vector<Card> b(n);
    rep(i, 0, n) { b[i] = a[i]; }

    rep(i, 0, n) {
        rrep(j, i + 1, n) {
            if (b[j - 1].value > b[j].value) { swap(b[j - 1], b[j]); }
        }
    }
    return b;
}

vector<Card> selection_sort(const vector<Card>& a) {
    int n = a.size();

    vector<Card> b(n);
    rep(i, 0, n) { b[i] = a[i]; }

    rep(i, 0, n) {
        int minj = i;
        rep(j, i + 1, n) {
            if (b[minj].value > b[j].value) { minj = j; }
        }
        swap(b[i], b[minj]);
    }
    return b;
}

