void  bubleSort(int N, vector<pair<char,int> > &A) {
	int flag = 1;
	while (flag) {
		flag = 0;
		for (int i = N - 1; i > 0; i--) {
			if (A[i].second < A[i - 1].second) {
				swap(A[i], A[i - 1]);
				flag = 1;
			}
		}
	}
}

void selectionSort(int N, vector<pair<char, int> >& A) {
	for (int i = 0; i < N; i++) {
		int minj = i;
		for (int j = i + 1; j < N; j++) {
			if (A[j].second < A[minj].second) minj = j;
		}
		if (i != minj) {
			swap(A[i], A[minj]);
		}
	}
}

