	for (int i = 0; i < N; i++) {
		for (int j = i+1; j < N; j++) {
			for (int a = 0; a < N; a++) {
				for (int b = a + 1; b < N; b++) {
					if (A[i].second == A[j].second && A[i] == B[b] && A[j] == B[a]) return "Not stable";
				}
			}
		}
	}
	return "Stable";
}

