class T{
  public:
    char kind; int value;
    T(){}
    T(char k, int v) { kind = k; value = v; }
    bool operator < (T &t) const { return value < t.value; }
    bool operator != (T &t) const { return !(value == t.value && kind == t.kind); }
};

void display(vector<T> &v){
  cout <<v[0].kind <<v[0].value;
  FOR(i, 1, v.size()) cout <<" " <<v[i].kind <<v[i].value;
  cout <<endl;
}

void bubbleSort(vector<T> &v){
  REP(i, v.size()) for(int j = (int)(v.size()) - 1; j >= i + 1; --j) if(v[j] < v[j - 1]) swap(v[j], v[j - 1]);
  display(v);
}

void selectionSort(vector<T> &v){
  REP(i, v.size()){
    int idx = i;
    FOR(j, i, v.size()) if(v[j] < v[idx]) idx = j;
    swap(v[i], v[idx]);
  }
  display(v);
}

bool isStable(vector<T> &v, vector<T> &origin){
  int num_cnt = 0;
  REP(i, v.size()){
    num_cnt = (i > 0 && v[i].value == v[i - 1].value ? num_cnt + 1 : 0);
    int cnt = 0;
    for(int j = 0; j < origin.size() && v[i] != origin[j]; ++j) if(v[i].value == origin[j].value) ++cnt;
    if(cnt > num_cnt) return false;
  }
  return true;
}

