  int N; cin >>N;
  vector<T> v(N);
  REP(i, N) cin >>v[i].kind >>v[i].value;
  vector<T> origin = v;
  bubbleSort(v);
  cout <<(isStable(v, origin) ? "Stable" : "Not stable") <<endl;
  v = origin;
  selectionSort(v);
  cout <<(isStable(v, origin) ? "Stable" : "Not stable") <<endl;
  return 0;
}

