template<typename U>
void sort_bubble(std::vector<U> &x) {
	// sort
	for (int i=0; i<x.size(); ++i) {
		for (int j=x.size()-1; j>i; --j) {
			if (x[j].value < x[j-1].value) {
				swap(x[j], x[j-1]);
			}
		}
	}
}

template<typename T>
void sort_selection(std::vector<T> &x){
	// sort
	for (int i=0; i<x.size(); ++i) {
		int min_index = i;
		for (int j=i+1; j<x.size(); ++j) {
			if (x[j].value < x[min_index].value) min_index = j; 
		}
		if (x[i].value == x[min_index].value) {
			continue;
		}
		swap(x[i], x[min_index]);
	}
}

