template<typename T>
bool check_stability(const std::vector<T> &x) {
	for (int i=1; i<x.size(); ++i) {
		if (x[i-1].value == x[i].value
		    &&  x[i-1].index > x[i].index) {
			return false;
		}
	}
	return true;
}

