void Bubble(int m[], char str[], int n)
{
	int flag = 1;
    while(flag)
    {
        flag = 0;
        for(int i = n-1; i > 0; i--)
        {
            if(m[i] < m[i-1])
            {
                int temp = m[i];
                m[i] = m[i-1];
                m[i-1] = temp;
                flag = 1;
                char temp1 = str[i];
                str[i] = str[i-1];
                str[i-1] = temp1;
            }
        }
    }
    cout << str[0] << m[0];
