        cout<<" "<<str[i]<<m[i];
    cout<<endl<<"Stable"<<endl;
}

void Selection(int m[], char str[], int n)
{
	for(int i = 0; i < n; i++)
	{
		int Min = INF, loc = i;
		for(int j = i; j < n; j++)
		{
			if(m[j]<Min)
			{
				Min = m[j];
				loc = j;
			}
		}
		int temp = m[i];
		m[i] = m[loc];
		m[loc] = temp;
        char temp1 = str[i];
        str[i] = str[loc];
        str[loc] = temp1;
	}

	cout << str[0] << m[0];
	for(int i = 1; i < n; i++)
		cout<< " " << str[i] << m[i];
	cout << endl;
}

