#include<iostream>
using namespace std;

typedef struct{
    int value;
    char suit;
}card;

void BubbleSort(card c[],int n){
    for(int i=0;i<n;i++){
        for(int j=n-1;j>i;j--){
            if(c[j-1].value>c[j].value){
                card v=c[j-1];
                c[j-1]=c[j];
                c[j]=v;
            }
        }
    }
}

void SelectionSort(card c[],int n){
    for(int i=0;i<n-1;i++){
        int minj=i;
        for(int j=i+1;j<n;j++)if(c[minj].value>c[j].value)minj=j;
        if(i!=minj){
            card v=c[i];
            c[i]=c[minj];
            c[minj]=v;
        }
    }
}

void printcard(card c[],int n){
    for(int i=0;i<n;i++){
        if(i)cout<<" ";
        cout<<c[i].suit<<c[i].value;
    }cout<<endl;
}

