void bubble(struct Card A[], int N){
  Card tmp;

  for( int i = 0; i < N-1; i++){
    for( int j = N-1; j >= i; j--) {
      if (A[j].value < A[j-1].value) {
        tmp = A[j-1]; A[j-1] = A[j]; A[j] = tmp;
      }
    }
  }
}

void selection(struct Card A[], int N) {
  int minj;
  Card tmp;

  for ( int i = 0; i < N-1; i++) {
    minj = i;
    for ( int j = i; j < N-1; j++) {
      if ( A[j].value < A[minj].value ) minj = j;
    }
    tmp = A[i]; A[i] = A[minj]; A[minj] = tmp;
  }
}

