	for(int i = 0; i < n; ++i) {
		for(int j = n - 1; j > i; --j) {
			if(number[j] < number[j - 1]) {
				copy_n = number[j];
				number[j] = number[j - 1];
				number[j - 1] = copy_n;
				copy_m = mark[j];
				mark[j] = mark[j - 1];
				mark[j - 1] = copy_m;
			}
		}
	}
	cout << mark[0] << number[0];
	for(int i = 1; i < n; ++i) {
		cout << ' ' << mark[i] << number[i];
	}
