const long long INF = numeric_limits<long long>::max();
typedef long long ll;

int trace(vector<pair<int, char>> a, int n)
{
    for(int i=0; i<n; i++){
        if(i == a.size()-1){
            cout << a[i].second << a[i].first << endl;;
        }
        else{
            cout << a[i].second << a[i].first << " ";
        }
    }
}

void BubbleSort(vector<pair<int, char>> &a, int n)
{
    bool flag = true;
    while(flag){
        flag = false;
        for(int i=n-1; i>0; i--){
            if(a[i].first < a[i-1].first){
                swap(a[i].first, a[i-1].first);
                swap(a[i].second, a[i-1].second);
                flag = true;
            }
        }
    }
}

void SelectionSort(vector<pair<int, char>> &a, int n)
{
    for(int i=0; i<n-1; i++){
        int minj = i;
        for (int j=minj; j<n; j++){
            if (a[minj].first > a[j].first) minj = j;
        }
        swap(a[i].first, a[minj].first);
        swap(a[i].second, a[minj].second);
    }
}

bool CheckStable(vector<pair<int, char>> a, vector<pair<int, char>> b, int n)
{
    for(int i=0; i<n; i++){
        if (a[i].second != b[i].second) return false;
    }
    return true;
}

