bool isStable(struct Card in[], struct Card out[], int n){
    for(int i = 0; i < n; i++)
        for(int j = i + 1; j < n; j++)
            for(int k = 0; k < n; k++)
                for(int h = k + 1; h < n; h++)
                    if(in[i].value == in[j].value && in[i].value == out[h].value && in[i].suit == out[h].suit && in[j].value == out[k].value && in[j].suit == out[k].suit)
                        return false;
    return true;
}

