struct data{
	char a;
	char b;
}; 

int BubbleSort(struct data *a,int n){
	int count=0;
	int flag=1;
	while(flag){
		flag=0;
		for(int i=n-1;i>0;i--){
			if(a[i].b<a[i-1].b){
				struct data temp=a[i];
				a[i]=a[i-1];
				a[i-1]=temp;
				flag=1;
				count++;
			}
		}
	}
}

int SelectionSort(struct data *a,int n){
	int count=0;
	for(int i=0;i<n-1;i++){
		int minj=i;
		for(int j=i+1;j<n;j++){
			if(a[minj].b>a[j].b){
				minj=j;
			}
		}
		if(minj!=i){
			struct data temp = a[minj];
			a[minj]=a[i];
			a[i]=temp;
			count++;
		}
	}
}


