void bubbleSort(int *C, char *S, int N) {
    for (int i=0; i<N; i++) {
        for (int j=N-1; j>i; j--) {
            if (C[j] < C[j-1]) { 
                int tn = C[j];
                C[j] = C[j-1];
                C[j-1] = tn;

                char ts = S[j];
                S[j] = S[j-1];
                S[j-1] = ts;
            }
        }
    }
}

void selectionSort(int *C, char *S, int N) { 
    for (int i=0; i<N; i++) {
        int minj = i;
        for (int j=i; j<N; j++) {
            if (C[j] < C[minj]) {
                minj = j;
            }
        }
        int tn = C[i];
        C[i] = C[minj];
        C[minj] = tn;

        char ts = S[i];
        S[i] = S[minj];
        S[minj] = ts;
    }
}

