void printArray( Card a[],int length)
{
	for (int i = 0; i < length - 1; ++i)
		cout << a[i].suit<<a[i].value << " ";
	cout << a[length-1].suit<<a[length - 1].value;                       //防止行元素后的空格多余导致PE
	cout << endl;                             //每一行结束输出要换行

}
void selectionSort(Card a[], int length)
{
	int count = 0;
	for (int i = 0; i < length; ++i)
	{
		int min = i;
		for (int j = i + 1; j < length; ++j)
			if (a[j].value < a[min].value)
				min = j;
		if (i != min)
		{
			++count;
			swap(a[i], a[min]);
		}
	}
}
void bubbleSort(Card b[], int length)
{
	bool flag = true;
	for (int i = 0; i < length&&flag; ++i)
	{
		flag = false;
		for (int j = 0; j < length - i - 1; ++j)
		{
			if (b[j].value > b[j + 1].value)
			{
				flag = true;
				swap(b[j], b[j + 1]);
			}
		}
	}
}
bool ifnStable(Card a[], Card b[],int n)         //判断选择排序是否稳定
{                                                //可以将选择排序的结果与冒泡排序的结果相比较，减少时间复杂度
	for (int i = 0; i < n; ++i)
	{
		if (a[i].suit != b[i].suit)
			return false;
	}
	return true;
}
