	Card* a = new Card[n];
	Card* b = new Card[n];
	for (int i = 0; i < n; ++i)
	{
		cin >> a[i].suit >> a[i].value;
		b[i] = a[i];
	}
	selectionSort(a, n);
	bubbleSort(b, n);
	printArray(b, n);
	cout << "Stable" << endl;
	printArray(a, n);
	cout << (ifnStable(a, b, n) ? ("Stable") :( "Not stable")) << endl;
	delete[]a;
	delete[]b;
	return 0;
}

