	rep(i, N){ cin >> A[i].suit >> A[i].value; }

	Card C1[MAX_N];
	Card C2[MAX_N];

	rep(i, N){ C1[i] = A[i]; C2[i] = A[i]; }

	bubbleSort(C1, N);
	selectionSort(C2, N);

	print(C1, N);
	cout << (isStable(A, C1, N) ? "Stable" : "Not stable") << endl;
	print(C2, N);
	cout << (isStable(A, C2, N) ? "Stable" : "Not stable") << endl;
}

#include <stdio.h>

void bubbleSort(int *C, char *S, int N) {
    for (int i=0; i<N; i++) {
        for (int j=N-1; j>i; j--) {
            if (C[j] < C[j-1]) { 
                int tn = C[j];
                C[j] = C[j-1];
                C[j-1] = tn;

                char ts = S[j];
                S[j] = S[j-1];
                S[j-1] = ts;
            }
        }
    }
}

void selectionSort(int *C, char *S, int N) { 
    for (int i=0; i<N; i++) {
        int minj = i;
        for (int j=i; j<N; j++) {
            if (C[j] < C[minj]) {
                minj = j;
            }
        }
        int tn = C[i];
        C[i] = C[minj];
        C[minj] = tn;

        char ts = S[i];
        S[i] = S[minj];
        S[minj] = ts;
    }
}

void outputArray(int *C, char *S, int N) {
    printf("%s%d",S[0], C[0]);
    for (int i=1; i<N; i++) printf(" %s%d", S[i], C[i]);
    printf("\n");
}

int checkCorrect(char *S1, char *S2, int N){
    int check = 1;
    for (int i=0; i<N; i++) {
        if (S1[i] != S2[i]) check=0;
    }
    return check;
}

int main() {
    int n;
    scanf("%d", &n);

    char s1[n], s2[n];
    int c1[n], c2[n];
    for (int i=0; i<n; i++) {
        scanf("%s", s1[i]);
        scanf("%d", c1[i]);
        c2[i] = c1[i];
        s2[i] = s1[i];
    }

    bubbleSort(c1, s1, n);
    outputArray(c1, s1, n);
    printf("Stable\n");

    selectionSort(c2, s2, n);
    outputArray(c2, s2, n);
    check=checkCorrect(s1, s2, n);
    if(check) printf("Stable");
    else printf("Not stable");

    return 0;
}

