    {
        int temp = i;
        //for(int j = i + 1;j < n;j++)
        for(int j = i;j < n;j++)
        {
            if(arr[temp].key > arr[j].key)
                temp = j;
        }
        swap(arr[i], arr[temp]);
    }
    for(int i = 0; i < n; i++)
    {
        if(i != n && arr[i].key == arr[i+1].key && arr[i].postition > arr[i+1].postition)
