struct Card {
  char type;
  int value;
  Card(char a, int b) : type(a), value(b) {}
  bool operator==(const Card& c) const {
    return c.type == type && c.value == value;
  }
};

ostream& operator<<(ostream& os, const Card& c) {
    os << c.type << c.value;
    return os;
}

vector<Card> bubbleSort(const vector<Card>& a, const int& n) {
  vector<Card> ret = a;
  bool flag = true;
  int count = 0;
  while (flag) {
    flag = false;
    for (int j = n-1; j > 0; j--) {
      if (ret[j].value < ret[j-1].value) {
        swap(ret[j], ret[j-1]);
        count++;
        flag = true;
      }
    }
  }
  return ret;
}

vector<Card> selectionSort(const vector<Card>& a, const int& n) {
  vector<Card> ret = a;
  int count = 0;
  int ms;
  for (int i = 0; i < n; i++) {
    ms = i;
    for (int j = i; j < n; j++) {
      if (ret[j].value < ret[ms].value) {
        ms = j;
      }
    }
    swap(ret[i], ret[ms]);
    if (ret[i].value != ret[ms].value) {
      count++;
    }
  }
  return ret;
}

