void BubbleSort(Card A[], int n) 
{
    int i = 0, j = 0;
    bool flag = true;
    while (flag) 
    {
        flag = false;
        for (j = n - 1; j > i; j--)
        {
            if (A[j].value < A[j - 1].value)
            {
                swap(A[j], A[j - 1]);
                flag = true;
            }
        }
        i++;
    }
}

void SectionSort(Card A[], int n) 
{
    int i, j, min;
    for (i = 0; i < n - 1; i++)
    {
        min = i;
        for (j = i + 1; j < n; j++)
        {
            if (A[j].value < A[min].value)
            {
                min = j;
            }
        }
        swap(A[i], A[min]);
    }
}

