using namespace  std;

void fnBubbleSort(vector<string> &a_rvsSortBbl)
{
  int ixSorting = 0;
  bool bSorting = true;

  while (bSorting)
  {
    bSorting = false;
    for (int j = a_rvsSortBbl.size() - 1; j > ixSorting; j--)
    {
      if (a_rvsSortBbl[j].at(1) < a_rvsSortBbl[j - 1].at(1))
      {
        swap(a_rvsSortBbl[j], a_rvsSortBbl[j - 1]);
        bSorting = true;
      }
    }
    ixSorting++;
  }
}

void fnOutputBbl(const vector<string> &a_cnrvsSortBbl)
{
  for (int i = 0; i < a_cnrvsSortBbl.size(); i++)
  {
    if (i) cout << " ";
    cout << a_cnrvsSortBbl[i];
  }
  cout << endl;
  cout << "Stable" << endl;
}

void fnSelectionSort(vector<string> &a_rvsSortSel)
{
  for (int ixSorting = 0; ixSorting < a_rvsSortSel.size() - 1; ixSorting++)
  {
    int ixMinimum = ixSorting;
    bool bSorting = false;
    for (int j = ixSorting + 1; j < a_rvsSortSel.size(); j++)
    {
      if (a_rvsSortSel[j].at(1) < a_rvsSortSel[ixMinimum].at(1))
      {
        ixMinimum = j;
        bSorting = true;
      }
    }
    if (bSorting == true)  swap(a_rvsSortSel[ixSorting], a_rvsSortSel[ixMinimum]);
  }
}

void fnOutputSel(const vector<string> &a_cnrvsSortSel, const vector<string> &a_cnrvsSortBbl)
{
  string sSortEnd = "Stable";

  for (int i = 0; i < a_cnrvsSortSel.size(); i++)
  {
    if (i) cout << " ";
    cout << a_cnrvsSortSel[i];

    if (a_cnrvsSortSel[i] != a_cnrvsSortBbl[i]) sSortEnd = "Not stable";
  }
  cout << endl;
  cout << sSortEnd << endl;
}

int main()
{
  vector<string> vsSortBbl, vsSortSel;
  int iMaxSize;

  cin >> iMaxSize;
  for (int i = 0; i < iMaxSize; i++)
  {
    string sCard;
    cin >> sCard;
    vsSortBbl.push_back(sCard);
    vsSortSel.push_back(sCard);
  }

  fnBubbleSort(vsSortBbl);
  fnOutputBbl(vsSortBbl); 

  fnSelectionSort(vsSortSel);
  fnOutputSel(vsSortSel, vsSortBbl);

  return 0;
}

