		LineB[i].Mark = Line[i].Mark;
		LineB[i].Number = Line[i].Number;

		LineS[i].Mark = Line[i].Mark;
		LineS[i].Number = Line[i].Number;
	}

	BubbleSort(LineB, N);
	Show(LineB, N);
