void bubble_sort (vector<string> &c, int n){
    for (int i = 0; i < n; i++){
        for (int j = n - 1; j > i; j--){
            if (c[j][1] < c[j-1][1]) {
                swap(c[j], c[j - 1]);
            }
        }
    }
}

void selection_sort (vector<string> &c, int n){
    for (int i = 0; i < n; i++){
        int minj = i;
        for (int j = i + 1; j < n; j++){
            if (c[j][1] < c[minj][1]){
                minj = j;
            }
        }
        swap(c[i], c[minj]);
    }
}

