        }
    }
}

void sort_selection(Card card[], int n){
    for(int i = 0; i < n; ++i){
        int mini = i;
        for(int j = i; j < n; j++){
            if(card[j]<card[mini]) mini = j;
        }
        swap(card[i], card[mini]);
    }
}

