void bubbleSort( vector<pair<string, int>>& A, int N ) {
	for( int i = 0; i < N; ++i ) {
		for( int j = N-1; j > i; --j ) {
			if( A.at( j ).first.at( 1 ) < A.at( j-1 ).first.at( 1 ) ) {
				swap( A.at( j ), A.at( j-1 ) );
			}
		}
	}
}

int selectionSort( vector<pair<string, int>>& A, int N ) {
	int count = 0;

	for( int i = 0; i < N; ++i ) {
		int minj = i;

		for( int j = i; j < N; ++j ) {
			if( A.at( j ).first.at( 1 ) < A.at( minj ).first.at( 1 ) ) {
				minj = j;
			}
		}

		if( i != minj ) {
			swap( A.at( i ), A.at( minj ) );
			count += 1;
		}
	}

	return count;
}

bool isStable( const vector<pair<string, int>>& A, int N ) {
	for( int i = 1; i < N; ++i ) {
		const auto& x = A.at( i );
		const auto& y = A.at( i-1 );

		if( x.first.at( 1 ) == y.first.at( 1 ) && x.second < y.second ) {
			return false;
		}
	}

	return true;
}

