#include <stdio.h>
#define rep(i, n) for(int i = 0; i < n; ++i)
#define repi(i, n, a) for(int i = a; i < n; ++i)

int main(void) {
  int n, i, j, st = 0;
  scanf("%d", &n);
  char a[n][5], b[n][5], s[n][5];
  rep(i, n) {
    scanf("%s", a[i]);
    rep(j, 5) b[i][j] = a[i][j], s[i][j] = a[i][j];
  }
  /*bubblesort*/
  int flag = 1;
  rep(i, n) {
    flag = 0;
    for(j = n - 1; j > i; --j) {
      if(b[j][1] < b[j - 1][1]) {
        char t;
        t = b[j][0], b[j][0] = b[j - 1][0], b[j - 1][0] = t;
        t = b[j][1], b[j][1] = b[j - 1][1], b[j - 1][1] = t;
       }
    }
  }
  /*selectionsort*/
  rep(i, n) {
    int minj = i;
    char t;
    repi(j, n, i) if(s[j][1] < s[minj][1]) minj = j;
    t = s[i][0], s[i][0] = s[minj][0], s[minj][0] = t;
    t = s[i][1], s[i][1] = s[minj][1], s[minj][1] = t;
  }
  rep(i, n) {
    if(i) printf(" %s", b[i]);
    else printf("%s", b[i]);
  }
  printf("\nStable\n");
  rep(i, n) {
    if(s[i][0] != b[i][0]) st = 1;
    if(i) printf(" %s", s[i]);
    else printf("%s", s[i]);
  }
  if(st) printf("\nNot stable\n");
  else printf("\nStable\n");
  return 0;
}

#include <iostream>
#include <stdio.h>
#include <algorithm>

struct Card {
    char suit;
    int value;
};

void trace(Card a[], int size) {
    for (int i = 0; i < size; ++i) {
        if (i > 0) {
            printf(" ");
        }
        printf("%c%d", a[i].suit, a[i].value);
    }
    printf("\n");
}

void BubbleSort(Card A[], int N) {
    int count  = 0;
    for (int i = 0; i < N; ++i) {
        for (int j = N - 1; j > i; --j) {
            if ( A[j].value < A[j-1].value ){
                std::swap(A[j], A[j-1]);
                ++count;
            }
        }
    }

    trace(A, N);
}

void SelectionSort(Card A[], int N) {
    int count  = 0;
    for (int i = 0; i < N; ++i) {
        int min = i;
        for (int j = i; j < N; ++j) {
            if (A[j].value < A[min].value) {
                min = j;
            }
        }
        if (i != min) {
            std::swap(A[i], A[min]);
            count++;
        }
    }

    trace(A, N);
}

bool IsStable (Card A[], Card B[], int N) {
    for (int i = 0; i < N; ++i) {
        if (A[i].suit != B[i].suit || A[i].value != B[i].value) {
            return false;
        }
    }
    return true;
}

int main() {
    int N;
    Card A[100], B[100];

    scanf("%d", &N);
    for (int i = 0; i < N; i++) {
        std::cin >> A[i].suit >> A[i].value;
        B[i] = A[i];
    }

    BubbleSort(A, N);
    printf("Stable\n");
    SelectionSort(B, N);
    IsStable(A, B, N) ? printf("Stable\n") : printf("Not stable\n");
    return 0;
}

