void bubbleSort(card a[], const int n) {
    int flag = 1;
    for (int i = 0; flag; ++i) {
        flag = 0;
        for (int j = n - 1; i < j; --j)
            if (a[j].value < a[j - 1].value) {
                swap(a[j], a[j - 1]);
                flag = 1;
            }
    }
}

void selectionSort(card a[], const int n) {
    for (int i = 0; i < n; ++i) {
        int min = i;
        // iより後でA[i]より最も小さい値の添字を求める
        for (int j = i; j < n; ++j)
            if (a[j].value < a[min].value) min = j;
        // iとminが異なれば交換
        if (i != min) swap(a[i], a[min]);
    }
}

