void BubbleSort(card* a, int n)
{
    int i;
    card z;
    bool inv = true;

    while(inv){
        inv = false;
        for(i = n - 1; i > 0; i--){
            if(a[i].value < a[i - 1].value){
                z = a[i];
                a[i] = a[i - 1];
                a[i - 1] = z;
                inv = true;
            }
        }
    };
    show(a, n);
    cout << "Stable" << endl;
}

