{
    int i, j, minj;
    card z;

    for(i = 0; i < n; i++){
        minj = i;
        for(j = i; j < n; j++){
            if(a[minj].value > a[j].value) minj = j;
        }
        if(i < minj){
            z = a[minj];
            a[minj] = a[i];
            a[i] = z;
        }
    }
    show(a, n);
}

