bool orstable(struct card *A, struct card *B, int N) {
	rep(i, N) {
		if (A[i].suit != B[i].suit)return false;
	}
	return true;
}

void bubblesort(struct card *A, int N) {
	int flag = 1;
	for (int i = 0; flag; i++) {
		flag = 0;
		for (int j = N - 2; j >= i; j--) {
			if (A[j].value > A[j + 1].value) {
				swap(A[j], A[j + 1]);
				flag = 1;
			}
		}
	}
}

void selectionsort(struct card *A, int N) {
	for (int i = 0; i < N - 1; i++) {
		int minj = i;
		for (int j = i + 1; j < N; j++) {
			if (A[minj].value > A[j].value)minj = j;
		}
		if (minj != i) {
			swap(A[minj], A[i]);
		}
	}
}

