	cout << ans1 << endl;
	cCards ccd2(C,N);
	ccd2.SelectionSort();
	cout << ccd2.getStr() << endl;
	string ans2 = (ccd1.getStr() == ccd2.getStr()) ? "Stable" : "Not stable";
	cout << ans2 << endl;

	return 0;
}

