template<typename U>
std::vector<int> sort_bubble(std::vector<U> &x) {
	std::vector<int> ix(x.size());
	// init
	for (int i=0; i<x.size(); ++i) ix[i] = i;
	// sort
	for (int i=0; i<x.size(); ++i) {
		for (int j=x.size()-1; j>i; --j) {
			if (x[j] < x[j-1]) {
				swap(x[j], x[j-1]);
				swap(ix[j], ix[j-1]);
			}
		}
	}
	return ix;
}
template<typename T>
std::vector<int> sort_selection(std::vector<T> &x){
	std::vector<int> ix(x.size());
	// init
	for (int i=0; i<x.size(); ++i) ix[i] = i;
	// sort
	for (int i=0; i<x.size(); ++i) {
		int min_index = i;
		for (int j=i+1; j<x.size(); ++j) {
			if (x[j] < x[min_index]) min_index = j; 
		}
		if (x[i] == x[min_index]) {
			continue;
		}
		swap(x[i], x[min_index]);
		swap(ix[i], ix[min_index]);
	}
	return ix;
}

template<typename T, typename U>
bool check_stability(
	const std::vector<T> &x  // x: original values
	,const std::vector<U> &ix // ix: sorted indices
	)	
{
	for (int i=1; i<ix.size(); ++i) {
		// if consecutive 2 values are the same, check the order of corresponding x 
		// x, not ix
		if ((x[ix[i-1]] == x[ix[i]]) && (ix[i-1] > ix[i])) {
			return false;
		}
	}
	return true;
}

