vector<string> BubbleSort(vector<string> data) {
    int size = data.size();
    rep(i, 0, size-1) for(int j=size-1; j>i; j--) {
        if (data[j][1] < data[j-1][1]) swap(data[j-1], data[j]);
    }
    return data;
}

vector<string> SelectionSort(vector<string> data) {
    int size = data.size();
    rep(i, 0, size) {
        int tmp = i;
        rep(j, i, size) {
            if (data[tmp][1] > data[j][1]) tmp = j;
        }
        if (tmp != i) {
            swap(data[i], data[tmp]);
        }
    }
    return data;
}

