    int minj = i;
    for (int j = i; j < n; j++) {
      if (cards[j].number < cards[minj].number) {
        minj = j;
      }
    }
    if (i != minj) {
      swap(cards[i], cards[minj]);
      switch_count++;
    }
  }
  return switch_count;
}

