  bool flag = true;
  int switch_count = 0;
  while(flag) {
    flag = false;
    for (int j = n - 1; j > 0; j--) {
      if (cards[j].number < cards[j - 1].number) {
        swap(cards[j], cards[j -1]);
        flag = true;
        switch_count++;
      }
    }
  }
  return switch_count;
}

