void bubble_sort(int n, Card A[]) {
  int flag = 1, sorted = 0;

  while (flag) {
    flag = 0;
    for (int i = n-1; i > sorted; i--) {
      if (A[i-1].num > A[i].num) {
        flag = 1;
        Card tmp = A[i];
        A[i] = A[i-1];
        A[i-1] = tmp;        
      }
    }
  }  
}

void selection_sort(int n, Card A[]) {
  for (int i = 0; i < n; i++) {
    int min_j = i;
    for (int j = i+1; j < n; j++) {
      if (A[j].num < A[min_j].num) min_j = j;
    }
    Card tmp = A[i];
    A[i] = A[min_j];
    A[min_j] = tmp;
  }    
}

