};

void bblsort( cards c[], int N )
{
	for( int i = 0; i < N; i++ ) {
		for( int j = N - 1; j > i; j-- ) {
			if( c[ j ].v < c[ j - 1 ].v ) {
				swap( c[ j ], c[ j - 1 ] );
			}
		}
	}
}

void selsort( cards c[], int N )
{
	for( int i = 0; i < N; i++ ) {
		int mini = i;
		for( int j = i; j < N; j++ ) {
			if( c[ j ].v < c[ mini ].v ) {
				mini = j;
			}
		}
		swap( c[ i ], c[ mini ] );
	}
}

void copy( cards c[], cards d[], int N )
{
	for( int i = 0; i < N; i++ ) {
		d[ i ] = c[ i ];
	}
}

void dump( cards c[], int N )
{
	for( int i = 0; i < N; i++ ) {
		cout << c[ i ].s << c[ i ].v;
		if( i != N -1 ) {
			cout << " ";
		}
		else {
			cout << endl;
		}
	}
}

void chkstable( cards s[], cards c[], int N )
{
	bool isstable = true;
	for( int i = 0; i < N; i++ ) {
		if( s[ i ].s != c[ i ].s and s[ i ].v == c[ i ].v ) {
			isstable = false;
		}
	}

	if( isstable == true ) {
		cout << "Stable" << endl;
	}
	else {
		cout << "Not stable" << endl;
	}
}

