		LineS[i].Mark = LineB[i].Mark;
		LineS[i].Number = LineB[i].Number;
	}

	BubbleSort(LineB, N);
	SelectionSort(LineS, N);

	Show(LineB, N);
	cout << "Stable" << endl;



	Show(LineS, N);
	if (Check(LineS, LineB, N)) {
		cout << "Stable" << endl;
	}
