int card2i(string c)
{
    if (c[1] >= '0' && c[1] <= '9')
    {
        return c[1] - '0';
    }
    return -1;
}

void bubbleSort(string A[], int N)
{
    bool flag = true;
    while (flag)
    {
        flag = false;
        for (int j = N - 1; j >= 1; j--)
        {
            if (card2i(A[j]) < card2i(A[j - 1]))
            {
                swap(A[j], A[j - 1]);
                flag = true;
            }
        }
    }
    for (int i = 0; i < N - 1; i++)
    {
        cout << A[i] << " ";
    }
    cout << A[N - 1] << endl;
}

void selectionSort(string A[], int N)
{
    for (int i = 0; i <= N - 1; i++)
    {
        int minj = i;
        for (int j = i; j < N; j++)
        {
            if (card2i(A[j]) < card2i(A[minj]))
            {
                minj = j;
            }
        }
        if (i != minj)
        {
            swap(A[i], A[minj]);
        }
    }

    for (int i = 0; i < N - 1; i++)
    {
        cout << A[i] << " ";
    }
    cout << A[N - 1] << endl;
}

void isStablePrint(string orig[], string sorted[], int N)
{
    char suitsOrg[36], suitsStd[36];
    for (int i = 1; i <= 9; i++)
    {
        int idxOrg = 0, idxStd = 0;
        bool isSame = true;
        for (int j = 0; j < N; j++)
        {
            if (card2i(orig[j]) == i)
            {
                suitsOrg[idxOrg++] = orig[j][0];
            }
            if (card2i(sorted[j]) == i)
            {
                suitsStd[idxStd++] = sorted[j][0];
            }
        }
        for (int j = 0; j < idxOrg; j++)
        {
            if (suitsOrg[j] != suitsStd[j])
            {
                isSame = false;
                break;
            }
        }
        if (!isSame)
        {
            cout << "Not stable" << endl;
            return;
        }
    }
    cout << "Stable" << endl;
    return;
}

