	for (i = 0; i < N; i++) {
		cin >> C1[i].moji >> C1[i].value;
	}

	for (i = 0; i < N; i++) C1[i] = C2[i];

	Bubble_Sort(C1, N);
	Selection_Sort(C2, N);

	print(C1, N);
	cout << "Stable" << endl;
	print(C2, N);

	if (Stable(C1, C2, N)) {
		cout << "Stable" << endl;
	}
	else {
		cout << "Not Stable" << endl;
	}


	return 0;

}

