void bubbleSort(Card c[],int n)
{
    int flag=1;
    Card t;
    while(flag)
    {
        flag=0;
        for(int i=0; i<n-1; i++)
        {
            if(c[i].value>c[i+1].value)
            {
                t=c[i];
                c[i]=c[i+1];
                c[i+1]=t;
                flag=1;
            }
        }
    }
}

void selectionSort(Card c[],int n)
{

    int minX;
    Card t;
    for(int i=0; i<n-1; i++)
    {
        minX=i;
        for(int j=i+1; j<n; j++)
        {
            if(c[j].value<c[minX].value)
                minX=j;
        }
        if(minX!=i)
        {
            t=c[i];
            c[i]=c[minX];
            c[minX]=t;
        }

    }
}

