bool check(card a[], card b[], int n){
  for(int i = 0; i < n; i++){
    if(a[i].c != b[i].c){
      return false;
    }
  }
  return true;
}

void bubblesort(card a[], int n){
  int i,j;
  for(i = 0; i < n; i++){
    for(j = n-1; j>= i+1; j--){
      if(a[j].v < a[j-1].v){
        card tmp = a[j];
        a[j] = a[j-1];
        a[j-1] = tmp;
      }
    }
  }
  for(i = 0; i < n; i++){
    if(i > 0){
      cout << " ";
    }
    cout << a[i].c << a[i].v;
  }
  cout << endl << "Stable" << endl;
}

void selectionsort(card a[], int n){
  int i,j,minj;
  for(i = 0; i < n; i++){
    minj = i;
    for(j = i; j < n; j++){
      if(a[j].v < a[minj].v){
        minj = j;
      }
    }
    card tmp = a[i];
    a[i] = a[minj];
    a[minj] = tmp;
  }
  for(i = 0; i < n; i++){
    if(i > 0){
      cout << " ";
    }
    cout << a[i].c << a[i].v;
  }
  cout << endl;
