int main() {
	int N; cin >> N;
	Card BubbleSorted[40], SelectionSorted[40];
	for (int i = 0; i < N; i++) {
		cin >> BubbleSorted[i].suit >> BubbleSorted[i].value;
		SelectionSorted[i] = BubbleSorted[i];
	}

	// Begin of BubbleSort
	for (int i = 0; i < N; i++) {
		for (int j = N-1; j > i; j--) {
			if (BubbleSorted[j].value < BubbleSorted[j-1].value) {
				Card temp = BubbleSorted[j];
				BubbleSorted[j] = BubbleSorted[j-1];
				BubbleSorted[j-1] = temp;
			}
		}
	}
	PrintCards(BubbleSorted, N);
	cout << "Stable" << endl;
	// End of BubbleSort

	// Begin of SelectionSort
	for (int i = 0; i < N; i++) {
		int minj = i;
		for (int j = i; j < N; j++) {
			if (SelectionSorted[j].value < SelectionSorted[minj].value) {
				minj = j;
			}
		}
		if (minj != i) {
			Card temp = SelectionSorted[i];
			SelectionSorted[i] = SelectionSorted[minj];
			SelectionSorted[minj] = temp;
		}
	}
	PrintCards(SelectionSorted, N);
