template<typename T> 
void buble_sort(int n, T ar[]){
    bool next = true;
    while (next) {
        next = false;
        for (int i = 0; i < n - 1; i++) {
            if(ar[i] > ar[i+1]){
                swap(ar[i], ar[i+1]);
                next = true;
            }
        }
    }
}

template<typename T>
void selection_sort(int n, T ar[]){
    for (int i = 0; i < n - 1; i++) {
        int minj = i;
        for (int j = i + 1; j < n ; j++) {
            if(ar[j] < ar[minj]){
                minj = j;
            }
        }
        if(minj != i){
            swap(ar[i], ar[minj]);
        }
    }
}

