void bubbleSort(struct CARD A[],int N)
{
	int flag=1;
	for (int i=0;flag;i++){
		flag=0;
		for (int j=N-1;j>=i+1;j--){
			if (A[j].num<A[j-1].num){
				struct CARD t=A[j];A[j]=A[j-1];A[j-1]=t;
				flag=1;
			}
		}
	}
}

void selectSort(struct CARD A[],int N)
{
	int minj,j;
	for (int i=0;i<N-1;i++){
		minj=i;
		for (j=i+1;j<N;j++){
			if (A[j].num<A[minj].num)minj=j;
		}
		struct CARD t=A[i];A[i]=A[minj];A[minj]=t;
	}
}

