auto bubble_sort(const vector<card> &a) {
	auto sorted = a;

	int n = sorted.size();
	for (int i = 0; i < n; ++i) {
		for (int j = n-1; j >= i+1; --j) {
			if (sorted[j].first < sorted[j-1].first) {
				swap(sorted[j], sorted[j-1]);
			}
		}
	}

	return sorted;
}

auto select_sort(const vector<card> &a) {
	auto sorted = a;

	int n = sorted.size();
	for (int i = 0; i < n; ++i) {
		int minj = i;
		for (int j = i; j < n; ++j) {
			if (sorted[j].first < sorted[minj].first) {
				minj = j;
			}
		}
		swap(sorted[i], sorted[minj]);
	}

	return sorted;
}

