vector<vector<char>> create_bucket(const vector<card> &a) {
	vector<vector<char>> bucket(9);
	for (auto e: a) {
		bucket[e.first-1].push_back(e.second);
	}
	return bucket;
}

void stability_check(const vector<card> &a, const vector<card> &b) {
	int n = a.size();
	cout << b[0];
	for (int i = 1; i < n; ++i) {
		cout << ' ' << b[i];
	}
	cout << '\n';

	auto c = create_bucket(a);
	auto d = create_bucket(b);
	if (c == d) {
		cout << "Stable";
	} else {
		cout << "Not stable";
	}
	cout << '\n';
}

