class Card{
    public:
    int value;
    string mark;
    Card(){}
    Card(string info){
        mark=info.substr(0,1);
        stringstream ss;
        ss<<info.substr(1);
        ss>>value;
    }
    string Output(){
        stringstream ss;
        ss<<value;
        return mark+ss.str();
    }
    bool isEqual(Card opponent){
        if(value == opponent.value && mark == opponent.mark)return true;
        else return false;
    }
};

vector<Card> bubblesort(vector<Card> A,int N){
    bool flag=1;
    while(flag){
        flag=0;
        for(int i=N-1;i>0;--i){
            if(A[i].value<A[i-1].value){
                Card buf=A[i];
                A[i]=A[i-1];
                A[i-1]=buf;
                flag=1;
            }
        }
    }
    return A;
}

vector<Card> selectionSort(vector<Card> A,int N){
    int counter=0;
    for(int i=0;i<N;++i){
        int minj=i;
        for(int j=i;j<N;++j){
            if(A[j].value<A[minj].value){
                minj=j;
            }
        }
        if(i!=minj){
            Card buf=A[i];
            A[i]=A[minj];
            A[minj]=buf;
            counter++;
        }
    }
    return A;
}

void CardsOutput(vector<Card> card){
    for(int i=0;i<card.size();++i){
        if(i!=0)cout<<" ";
        cout<<card[i].Output();
    }
    cout<<endl;
}

bool isStable(vector<Card> in,vector<Card> out){
    for(int i=0;i<in.size();++i){
        for(int j=i+1;j<in.size();++j){
            for(int a=0;a<out.size();++a){
                for(int b=a+1;b<out.size();++b){
                    if(in[i].value == in[j].value && in[i].isEqual(out[b]) && in[j].isEqual(out[a])){
                        return false;
                    }
                }   
            }   
        }   
    }
    return true;
}

