/* subroutines */

void bubble_sort(int n, Card as[]) {
  for (int i = 0; i < n; i++)
    for (int j = n - 1; j > i; j--)
      if (as[j] < as[j - 1])
	swap(as[j], as[j - 1]);
}

void selection_sort(int n, Card as[]) {
  for (int i = 0; i < n; i++) {
    int mini = i;
    for (int j = i; j < n; j++)
      if (as[j] < as[mini])
	mini = j;
    if (i != mini) swap(as[i], as[mini]);
  }
}

bool stable(int n, Card as[]) {
  for (int i = 0; i < n; i++) {
    Card &ai = as[i];
    for (int j = i + 1; j < n && ai.v == as[j].v; j++)
      if (ai.i > as[j].i) return false;
  }
  return true;
}

