#include<iostream>

using namespace std;

/*
 * 稳定排序定义：
 * 1. 待排序的记录序列中可能存在两个或两个以上关键字相等的记录。
 * 2. 排序前的序列中Ri领先于Rj（即i<j）.若在排序后的序列中Ri仍然领先于Rj，则称所用的方法是稳定的。
 * 常见的稳定排序：
 *  插入排序，基数排序，归并排序，冒泡排序，计数排序
 * 常见的不稳定排序：
 *  快速排序，希尔排序，简单选择排序，堆排序
 *
 *  本题思路：
 *  利用稳定的冒泡排序的输出结果与选择排序的输出结果进行比较
 *  若相同则是稳定输出，若不同则是不稳定输出
 */

typedef struct{
    char suit;
    char value;
}Cart;

void bubbleSort(Cart a[], int n){ // 冒泡排序
    for (int i = 0; i < n-1; i++){
        for (int j = 0; j < n-i-1; j++){
            if (a[j].value > a[j+1].value){
                swap(a[j], a[j+1]);
            }
        }
    }
}

void selectionSort(Cart a[], int n){ // 选择排序
    for (int i = 0; i < n-1; i++){
        int pos = i;
        for (int j = i; j < n; j++){
            if (a[pos].value > a[j].value){
                pos = j;
            }
        }
        swap(a[pos], a[i]);
    }
}

void print(Cart a[], int n){ // 输出函数
    for (int i = 0; i < n; i++){
        if (i != n-1){
            cout<<a[i].suit<<a[i].value<<" ";
        }else{
            cout<<a[i].suit<<a[i].value<<endl;
        }
    }
}

bool isStable(Cart a[], Cart b[], int n){ // 判断选择排序结果是否与冒泡排序结果一致
    for (int i = 0; i < n; i++){
        if (a[i].suit != b[i].suit){
            return false;
        }
    }
    return true;
}

int main(){
    Cart a[100], b[100];
    int n;
    cin>>n;
    for (int i = 0; i < n; i++){
        cin>>a[i].suit>>a[i].value;

    }
    for(int i = 0; i < n; i++){
        b[i] = a[i];
    }
    bubbleSort(a, n);
    selectionSort(b, n);
    print(a, n);
    cout<<"Stable"<<endl;
    print(b, n);
    if (isStable(a, b, n)){
        cout<<"Stable"<<endl;
    }else{
        cout<<"Not stable"<<endl;
    }
    return 0;
}

