void swap(int n,int m, char (*c)[3]){
	char val[3];

	strcopy(3,val,c[n]);
	strcopy(3,c[n],c[m]);
	strcopy(3,c[m],val);
}

int bubblesort(int n,char (*a)[3]){
	int i,j;
	for(i=0;i<n;i++){
		for(j=n-1;j>=i+1;j--){
			if(a[j-1][1]>a[j][1]){
				swap(j-1,j,a);
			}
		}
	}
	return 0;
}

int selectionsort(int n,char (*a)[3]){
	int i,j,mini;
	for(i=0;i<n;i++){
		mini=i;
		for(j=i+1;j<n;j++){
			if(a[mini][1]>a[j][1]){
				mini=j;
			}
		}
		swap(i,mini,a);
	}

	return 0;
}

