int comparecards(int n,int i,int k,char c,char (*org)[3],char (*sorted)[3]){
	int j,m=0,check;
	char cd[4],d[4];

	for(j=0;j<=k;j++){
		cd[j]=sorted[i+j][0];
	}

	for(j=0;j<n && m<=4;j++){
		if(org[j][1]==c){
			d[m]=org[j][0];
			m++;
		}
	}

	check=0;
	for(j=0;j<m && check==0;j++){
		if(cd[j] != d[j])
			check=-1;
	}

	return check;
}



int checkstable(int n,char (*org)[3],char (*sorted)[3]){
	int i,k,check=0;
	char c;
	for(i=0;i<n && check==0;i++){
		c=sorted[i][1];
		k=0;
		if(c==sorted[i+1][1]){
			k++;
			while(c==sorted[i+1+k][1] && i+1+k<n)
				k++;
			check = comparecards(n,i,k,c,org,sorted);

		}
		i+=k;
	}
	return check;
}

