using namespace std;

void calculate(stack<int> &st, char c) {
    int b = st.top();
    st.pop();
    int a = st.top();
    st.pop();
    switch (c) {
        case '+':
            st.push(a + b);
            break;
        case '-':
            st.push(a - b);
            break;
        case '*':
            st.push(a * b);
            break;
    }
};

int main() {
    stack<int> st;        
    char s[10];

    while(scanf("%s", s) != EOF) {
        if (s[0] == '+' || s[0] == '-' || s[0] == '*') {
            calculate(st, s[0]);
        } else {
            st.push(atoi(s));
        }
    }
    printf("%d\n", st.top());
}

