#include <stdio.h>
#include <vector>
#include <string>
#include <utility>
#include <algorithm>

void bubble_sort(const std::vector<std::string>& arr, std::vector<std::string>& sorting_arr)
{
  using std::swap;
  sorting_arr.resize(arr.size());
  std::copy(arr.begin(), arr.end(), sorting_arr.begin());
  for (int i = 0; i < sorting_arr.size(); i++) {
    for (int j = sorting_arr.size() - 1; j > i; j--) {
      if (sorting_arr[j][1] < sorting_arr[j - 1][1]) {
        swap(sorting_arr[j], sorting_arr[j - 1]);
      }
    }
  }
}

void selection_sort(const std::vector<std::string>& arr, std::vector<std::string>& sorting_arr)
{
  using std::swap;
  sorting_arr.resize(arr.size());
  std::copy(arr.begin(), arr.end(), sorting_arr.begin());
  for (int i = 0; i < sorting_arr.size() - 1; i++) {
    int minv = i;
    for (int j = i + 1; j < sorting_arr.size(); j++) {
      if (sorting_arr[minv][1] > sorting_arr[j][1]) {
        minv = j;
      }
    }
    if (i != minv) {
      swap(sorting_arr[i], sorting_arr[minv]);
    }
  }
}

bool is_stable(const std::vector<std::string>& arr, const std::vector<std::string>& stably_sorted_arr)
{
  return arr == stably_sorted_arr;
}

void output(const std::vector<std::string>& arr)
{
  for (int i = 0; i < arr.size(); i++) {
    if (i == arr.size() - 1) {
      printf("%s\n", arr[i].c_str());
    }
    else {
      printf("%s ", arr[i].c_str());
    }
  }
}

int main()
{
  int N;
  std::vector<std::string> arr;
  std::vector<std::string> bubble_sorted_arr;
  std::vector<std::string> selection_sorted_arr;

  scanf("%d", &N);
  for (int i = 0; i < N; i++) {
    char str[3];
    scanf("%s", str);
    arr.push_back(std::string(str));
  }

  bubble_sort(arr, bubble_sorted_arr);
  output(bubble_sorted_arr);
  puts("Stable");

  selection_sort(arr, selection_sorted_arr);
  output(selection_sorted_arr);
  if (is_stable(selection_sorted_arr, bubble_sorted_arr)) {
    puts("Stable");
  }
  else {
    puts("Not stable");
  }

  return 0;
}

