void bubbleSort(string* A, int n){
	bool flag = true;
	while(flag){
		flag = false;
		for(int j=n-1; j>0; j--)
			if(A[j-1][1] > A[j][1]){
				swap(A[j-1], A[j]);
				flag = true;
			}
	}
}
void selectionSort(string* A, int n){
	for(int i=0; i<n; i++){
		int minj = i;
		for(int j=i; j<n; j++)
			if(A[j][1] < A[minj][1]) minj = j;
		if(i != minj) swap( A[i], A[minj] );
	}
}
