bool operator==(const card a, const card b)
{
	if (a.c == b.c)
	{
		if (a.s == b.s)
		{
			return true;
		}
	}
	return false;
}

void swap(card& a, card& b)
{
	card v;
	v = a;
	a = b;
	b = v;
}

void print(card a[], int n)
{
