}

int check(card a[], card b[], int n)
{
	int i, j, k, l;
	for (i = 0; i < n - 1; i++)
	{
		for (j = i + 1; j < n; j++)
		{
			if (a[i].c == a[j].c)
			{
				for (k = 0; k < n - 1; k++)
				{
					for (l = k + 1; l < n; l++)
					{
						if (a[i] == b[l] && a[j] == b[k])
						{
							return 0;
						}
					}
				}
			}
		}
	}
	return 1;
}

