	else cout << "Not stable" << endl;
}

void bubble(card a[], int n)
{
	int i, j, flag = 0;
	for (i = 0; i < n; i++)
	{
		flag = 0;
		for (j = n - 1; j > i; j--)
		{
			if (a[j].c < a[j - 1].c)
			{
				swap(a[j], a[j - 1]);
				flag = 1;
			}
		}
		if (!flag)break;
	}
}

void select(card a[], int n)
{
	int i, j, min;
	for (i = 0; i < n; i++)
	{
		min = i;
		for (j = i + 1; j < n; j++)
		{
			if (a[j].c < a[min].c)
			{
				min = j;
			}
		}
		swap(a[i], a[min]);
	}
}

