struct Card{
	char suit;
	char value;
};

// バブルソート
// in/out 配列
// in 配列サイズ
void bubbleSort(Card* intArray, int arraySize){
	int flag = 1;
	Card tmp;
	for (int i=0; flag; ++i){
		flag = 0;
		for (int j=0; j<arraySize-i-1; ++j){
			if (intArray[j].value > intArray[j+1].value){ // > だと降順、< だと昇順
				tmp = intArray[j+1];
				intArray[j+1] = intArray[j];
				intArray[j] = tmp;
				flag = 1;
			}
		}
	}
}



// 選択ソート
// in/out 配列
// in 配列サイズ
int selectionSort(Card *a, int n){
	Card tmp;
	int minj;
	int count = 0;
	for(int i=0; i< n; ++i){
		minj = i;
		for(int j=i; j<n; ++j){
			if (a[j].value < a[minj].value){
				minj = j;
			}
		}
		if (i != minj){
			tmp = a[i];
			a[i] = a[minj];
			a[minj] = tmp;
			++count;
		}
	}
	return count;
}

