	for (int i = 0; i < N; ++i) {
		for (int j = i + 1; i < N; ++i) {
			for (int a = 0; a < N; ++a) {
				for (int b = a + 1;  b < N; ++b) {
					if (LineI[i].Number == LineI[j].Number&&LineI[i].Mark == Line[b].Mark&&LineI[j].Mark == Line[a].Mark) {
						return false;
					}
				}
			}
		}
	}
	return true;
}

