template<class T>
void swap(T* a, T* b)
{
    T temp = *a;
    *a = *b;
    *b = temp;
}

void bubble(struct Card A[], int N) //冒泡排序
{
    for(int i = 0; i < N; i++)
    {
        for(int j = N - 1; j > i; j--)
        {
            if(A[j].value < A[j - 1].value)
                swap(&A[j], &A[j - 1]);
        }
    }
}

void selection(struct Card A[], int N) // 选择排序
{
    for(int i = 0; i < N; i++)
    {
        int minj = i;
        for(int j = i; j < N; j++)
            if(A[j].value < A[minj].value)
                minj = j;
        swap(A[i], A[minj]);
    }
}

