            if (vector_array[j][1] < vector_array[j-1][1]){
                swap(vector_array[j],vector_array[j-1]);
                flag = true;
                counter ++ ;
            }
        }
    }
    return counter;
}

int selectionSort(vector<string>& vector_array,int n){
    int counter = 0;
