        for(int j = i;j < n;j++){
            if(vector_array[j][1] < vector_array[minj][1]) minj = j;
        }
        if(minj > i) {
            swap(vector_array[i],vector_array[minj]);
            counter++;
        }
    }
    return counter;
}

