  bool flag = true;
  for (int i = 0; flag; i++) {
    flag = false;
    for (int j = N-1; j >= i+1; j--) {
      if (A[j].value < A[j-1].value) {
        swap(A[j].value, A[j-1].value);
        swap(A[j].suit, A[j-1].suit);
        flag = true;
      }
    }
  }
}

void selectionSort(Card A[], int N) {
  for (int i = 0; i < N; i++) {
    int min_j = i;
    for (int j = i; j < N; j++) {
      if (A[j].value < A[min_j].value) {
        min_j = j;
      }
    }
    if (i != min_j) {
      swap(A[i].value, A[min_j].value);
      swap(A[i].suit, A[min_j].suit);
    }
  }
}

bool isStable(Card in[], Card out[], int N) {
  for (int i = 0; i < N; i++) {
    for (int j = i+1; j < N; j++) {
      for (int a = 0; a < N; a++) {
        for (int b = a+1; b < N; b++) {
          if (in[i].value == in[j].value &&
              out[a].value == out[b].value &&
              in[i].value == out[a].value &&
              in[i].suit == out[b].suit &&
              in[j].suit == out[a].suit) {
            return false;}
        }
      }
    }
  }
  return true;
}

