bool isStable(int N, Card *in, Card *out){
    for(int i=0; i<N; i++){
        for(int j=i+1; j<N; j++){
            for(int k=0; k<N; k++){
                for(int l=k+1; l<N; l++){
                    if(in[i].value==in[j].value
                        && in[i].mark==out[l].mark && in[i].value==out[l].value
                        && in[j].mark==out[k].mark && in[j].value==out[k].value
                    )
                        return false;

                }
            }
        }
    }
    return true;
}

