using namespace std;
static const int MAX = 100;

class Card
{
public:
    char Mark;
    int num;
};

void trace(Card *A, int N) {
    for ( int i = 0; i < N; ++i ) {
        if ( i > 0 ) {
            cout << ' ';
        }
        cout << A[i].Mark << A[i].num;
    }
    cout << endl;
}

void swap(Card *a, Card *b) {
    int temp_num;
    char temp_Mark;
    temp_num = (*a).num;
    temp_Mark = (*a).Mark;
    (*a).num = (*b).num;
    (*a).Mark = (*b).Mark;
    (*b).num = temp_num;
    (*b).Mark = temp_Mark;
}

int BubbleSort(Card *A, int N) {
    int flag = 0;
    int sw = 0;
    int cnt = 0;
    do {
        flag = 0;
        for (int i = N - 1; i > cnt; --i) {
            if (A[i].num < A[i - 1].num) {
                swap(&A[i], &A[i - 1]);
                sw++;
                flag = 1;
            }
        }
        cnt++;
    }while ( flag == 1 );
    return sw;
}

int SelectionSort(Card *A, int N) {
    int mini;
    int cnt = 0;
    for ( int i = 0; i < N; ++i ) {
        mini = i;
        for ( int j = i; j < N; ++j ) {
            if ( A[mini].num > A[j].num ) {
                mini = j;
            }
        }
        if ( A[mini].num < A[i].num) {
            swap(&A[mini], &A[i]);
            cnt++;
        }
    }
    return cnt;
}

