    for ( int i = 0; i < N; ++i ) {
        cin >> A[i].Mark >> A[i].num;
        B[i].Mark = A[i].Mark;
        B[i].num = A[i].num;
    }



    BubbleSort(A,N);
    trace(A,N);
    cout << "Stable" << endl;

    SelectionSort(B,N);
    trace(B,N);

    for ( int i = 0; i < N; ++i ) {
        if ( A[i].Mark != B[i].Mark ) {
            cout << "Not stable" << endl;
            return 0;
        }
    }
    cout << "Stable" << endl;


    return 0;
}

