class card{
public:
	char suit;
	int value;
};

void swapCard(card arr[], int i, int j){
	card temp;
	temp.value = arr[j].value;
	temp.suit = arr[j].suit;
	arr[j].value = arr[i].value;
	arr[j].suit = arr[i].suit;
	arr[i].value = temp.value;
	arr[i].suit = temp.suit;
}


void bubbleSort(card arr[], int n){
	card temp;
	for(int i = 0; i < n; i ++){
		for(int j = n - 1; j > i; j--){
			if(arr[j].value < arr[j - 1].value){
				swapCard(arr,j ,j-1);
			}
		}
	}
}

void selectionSort(card arr[], int n){
	card temp;
	int min_i;
	for(int i = 0; i < n; i++){
		min_i = i;
		for(int j = i; j < n; j++){
			if(arr[j].value < arr[min_i].value){
				min_i = j;
			}
		}
		if(min_i != i){
			swapCard(arr,i , min_i);
		}
	}
}

void printCardArr(card arr[], int n){
	for(int i = 0;i < n; i++){
		cout << arr[i].suit << arr[i].value;
