typedef vector <string> svector;

int bubblesort(svector &A){
    int n = A.size();
    for (int i=0; i<n; i++)
        for (int j=n-1; j>i; j--)
            if (A[j][1] < A[j-1][1]){
                swap(A[j], A[j-1]);
            }
    return 0;
}

int selectionsort(svector &A){
	int n = A.size(), mini;
	for (int i=0; i<n; i++){
		mini = i;
		for (int j=i; j<n; j++)
			if (A[j][1] < A[mini][1])
				mini = j;
		if (i!=mini){
			swap(A[i], A[mini]);
		}
	}
	return 0;
}


int nums_out(svector &A){
    int n=A.size();
    for (int i=0; i<n; i++){
        cout << A[i];
        if (i!= n-1) cout<<" ";
        else cout<<endl;
    }
    return 0;
}

