bool stable(vector<pic> in, vector<pic> out){
  size_t n = in.size();
  for (size_t i = 0; i < n; i++) {
    for (size_t j = i+1; j < n; j++) {
      if(in[i].first == in[j].first){
        size_t x = 0, y = 0;
        for(; x < n; x++){
          if(in[i] == out[x]) break;
        }
        for(; y < n; y++){
          if(in[j] == out[y]) break;
        }
        if((i<j) != (x<y)) return false;
      }
    }
  }
  return true;
}

void print2(vector<pic> in, vector<pic> v){
  if(stable(in, v)){
    cout << "Stable" <<endl;
  } else{
    cout << "Not stable" <<endl;
  }
}


