  vector<string> C(N);
  for (int i = 0; i < N; i++) {
    cin >> C.at(i);
  }

  vector<string> b_sorted = bubble_sort(C, N);
  print_vector(b_sorted, N);
  print_stable_condition(C, b_sorted, N);

  vector<string> s_sorted = selection_sort(C, N);
  print_vector(s_sorted, N);
  print_stable_condition(C, s_sorted, N);
  return 0;
}

