#include <iostream>
using namespace std;

long partition(pair<char, long> A[], long p, long r){
	long x = A[r].second;
	long i = p - 1;
	long j;
	for (j = p; j < r; j++){
		if (A[j].second <= x){
			i++;
			swap(A[i], A[j]);
		}
	}
	swap(A[i + 1], A[r]);
	return i + 1;
}

void quicksort(pair<char, long> A[], long p, long r){
	if (p < r){
		long q = partition(A, p, r);
		quicksort(A, p, q - 1);
		quicksort(A, q + 1, r);
	}
}

void BubbleSort(pair<char, long> A[], long n){
	for (long i = 0; i < n; i++){
		for (long j = n - 1; j >= i; j--){
			if (A[j].second < A[j - 1].second){
				swap(A[j], A[j - 1]);
			}
		}
	}
}

bool isStable(pair<char, long> A[], pair<char, long> B[], long n){
	for (long i = 0; i < n; i++){
		if (A[i].first != B[i].first && A[i].second == B[i].second){
			return 0;
		}
	}
	return 1;
}

