            {
                Min=j;
            }
        }
        swap(a[Min],a[i]);
    }
}

void bubble_sort(card a[],int n)
{
    bool flag=true;

    for(int i=0;i<n-1&&flag;i++)
    {
        flag=false;
        for(int j=0;j<n-1-i;j++)
        {
            if(a[j].value>a[j+1].value)
            {
                swap(a[j],a[j+1]);
                flag=true;
            }
        }
    }
}

