        {
            if(c.at(j).num < c.at(j - 1).num)
            {
                card t = c.at(j - 1);
                c.at(j - 1) = c.at(j);
                c.at(j) = t;
            }
        }
    }
}
void selectionSort(vector<card> &c,int n)
{
    for(int i = 0;i < n;i++)
    {
        int minj = i;
        for(int j = i;j < n;j++)
        {
            if(c.at(j).num < c.at(minj).num)
            {
                minj = j;
            }
        }
        card t = c.at(i);
        c.at(i) = c.at(minj);
        c.at(minj) = t;
    }
}
bool checkStable(vector<card> b,vector<card> a)
{
    string s;
    int n = 0;
    for(int i = 0;i < a.size();i++)
    {
        if(n == 0)
        {
            n = a.at(i).num;
            s = a.at(i).pic;
        }
        else if(n == a.at(i).num)
        {
            s += a.at(i).pic;
        }
        else
        {
            string t;
            for(int j = 0;j < b.size();j++)
            {
                if(b.at(j).num == a.at(i - 1).num)
                {
                    t += b.at(j).pic;
                }
            }
            if(s != t)
            {
                return false;
            }
            s.clear();
            n = 0;
        }
    }
    return true;
}
