class Card{
  public:
    char suit;
    int value;
};

typedef vector<Card> Cards;

void bubbleSort(const Cards in_cards, Cards &out_cards){
  int N = in_cards.size();
  assert(N==out_cards.size());
  out_cards = in_cards;

  for(int i=0; i<N; i++){
    for(int j=N-1; j>i; j--){
      if(out_cards[j].value < out_cards[j-1].value){
        swap(out_cards[j], out_cards[j-1]);
      }
    }
  }
}

void selectionSort(const Cards in_cards, Cards &out_cards){
  int N = in_cards.size();
  assert(N==out_cards.size());
  out_cards = in_cards;

  for(int i=0; i<N; i++){
    int min_j = i;
    for(int j=i; j<N; j++){
      if(out_cards[j].value < out_cards[min_j].value){
        min_j = j;
      }
    }
    swap(out_cards[i], out_cards[min_j]);
  }
}

void output_cards(const Cards cards){
  int N = cards.size();

  for(int i=0; i<N; i++){
    cout << cards[i].suit << cards[i].value;

    if(i != N-1){
      cout << " ";
    }
    else{
      cout << endl;
    }
