int Bsort(Card *arr,int n) {
	bool flag = true;
	int i = 0;
	int count = 0;
	while (flag) {
		flag = false;
		for (int j=n-1; j>i; j--) {
			if (arr[j].n < arr[j-1].n) {
				Card t = arr[j];
				arr[j] = arr[j-1];
				arr[j-1] = t;
				flag = true;
				count++;
			}
		}
		i++;
	}
	return count;
}
int Ssort(Card *arr,int n) {
	int count = 0;
	for (int i=0; i<n-1; i++) {
		int k = i;
		for (int j=i+1; j<n; j++) {
			if (arr[k].n > arr[j].n) {
				k = j;
			}
		}
		if (k != i) {
			Card t = arr[k];
			arr[k] = arr[i];
			arr[i] = t;
			count++;
		}
	}
	return count;
}

