    rep(i, N) {
        cin >> A[i].m >> A[i].n;
        B[i].m = C[i].m = A[i].m;
        B[i].n = C[i].n = A[i].n;
    }

    // bubble
    bool flag = 1;
    while(flag) {
        flag = 0;
        for(int j = N - 1; j > 0; j--) {
            if(B[j].n < B[j - 1].n) {
                swap(B[j], B[j - 1]);
                flag = 1;
