            cout << " ";
        cout << B[i].m << B[i].n;
    }
    cout << endl;
    cout << "Stable" << endl;

    // selection
    rep(i, N) {
        int min = i;
        rep(j, i, N) {
            if(C[j].n < C[min].n)
                min = j;
        }
        if(i != min) {
            swap(C[i], C[min]);
        }
    }
    rep(i, N) {
        if(i)
            cout << " ";
        cout << C[i].m << C[i].n;
    }
    cout << endl;
