int n;

bool compare(string c1, string c2){
    if(c1[1] < c2[1]) return true;
    else return false;
}

void swap(char *c1, char *c2){
    char *temp;
    temp = c1;
    c1 = c2;
    c2 = temp;
    return;
}

// sort "intput" by bubble sort
// then put the result into "output"
void bubble_sort(string *input, string *output)
{
    // copy input to output
    rep(i,n) output[i] = input[i];
    // execute bubble sort
    rep(i,n) for(int j = n-1; j > i; j--)
        if(compare(output[j], output[j-1]))
            swap(output[j], output[j-1]);
    return;
}

// sort "intput" by selection sort
// then put the result into "output"
void selection_sort(string *input, string *output)
{
    // copy input to output
    rep(i,n) output[i] = input[i];
    // execute selection sort
    rep(i,n){
        int min = i;
        for(int j = i; j < n; j++)
            if(compare(output[j],output[min])) 
                min = j;
        swap(output[i], output[min]);
    }
    return;
}

// print sorted cards dividing with space
void print_sorted(string p[])
{
    rep(i,n) cout << p[i] << ' ';
    cout << endl;
    return;
}

string str_cards(string str[], int x)
{
    string res;

    rep(i,n) if(str[i][1] == '0'+x) res += str[i] + ' ';

    return res;
}

// check stability
// stability: 
// cards with the same value appear in the output
// in the same order as they do in the input 
bool check_stability(string before[], string after[])
{
    for(int i = 1; i <= 9; i++){
        if(str_cards(before, i) != str_cards(after, i))
            return false;
    }

    return true;
}

int main(void)
{
    cin >> n;
    rep(i,n) cin >> s[i];

    // bubble sort
    bubble_sort(s, bs);
    print_sorted(bs);
    if(check_stability(s, bs)) cout << "Stable" << endl;
    else cout << "Not stable" << endl;

    // selection sort
    selection_sort(s, ss);
    print_sorted(ss);
    if(check_stability(s, ss)) cout << "Stable" << endl;
    else cout << "Not stable" << endl;

    return 0;
}

