    }
  	cout << Array[N-1] << endl;
  	cout << "Stable" << endl;
}

void SelectionSort(vector<string> Array, int N)
{
  	bool isStable=true;
  	for(int i = 0; i< N;i++)
    {
      int min_idx = i;
      bool isSame = false;
      int same_idx;
      for(int j=i+1;j<N;j++)
      {
        if(Array[j][1] - '0' == Array[min_idx][1] - '0') 
        {
          isSame=true;
          same_idx = j;
        }
        if(Array[j][1] - '0' < Array[min_idx][1] - '0')
        {
          min_idx = j;
        }
      }
      if(isSame && same_idx < min_idx) isStable = false;
      string tmp = Array[i];
      Array[i] = Array[min_idx];
      Array[min_idx] = tmp;
    }
	for(int i=0;i<N-1;i++)
    {
      cout << Array[i] << " ";
    }
  	cout << Array[N-1] << endl;
  	if(isStable) cout << "Stable" << endl;
  	else cout << "Not stable" << endl;
}

