void selectionSort(CARD* A, int N){
  int minj;

  for(int i = 0; i < N - 1; i++){
    minj = i;
    for(int j = i; j < N; j++){
      if(A[j].num < A[minj].num)
        minj = j;
    }

    if(minj != i){
      CARD tmp = A[i];
      A[i] = A[minj];
      A[minj] = tmp;
    }
  }

  return;
}

void bubbleSort(CARD* A, int N){

  bool flag = true;

  while(flag){
    flag = false;

    for(int i = N-1; i > 0; i--){
      if(A[i].num < A[i-1].num){
        CARD tmp = A[i];
        A[i] = A[i -1];
        A[i-1] = tmp;
        flag = true;
      }
    }
  }

  return;
}

