using namespace std;

struct Card
{
    string suit_value;
    char suit;
    int value;
    int original_position;

};

bool IsStable(Card cards[], int n) {
    bool is_stable = true;
    for (int i = 0; i < n - 1; i++) {

        for (int j = i + 1; j < n; j++) {
            if (cards[j].value != cards[i].value) break;
            if (cards[j].value == cards[i].value && cards[j].original_position < cards[i].original_position) is_stable = false;
            if (!is_stable) break;
        }
        if (!is_stable) break;
    }
    return is_stable;
}

bool BubbleSort(Card cards[], int n) {
    bool is_stable = true;
    for (int i = 0; i < n; i++) {
        for (int j = n - 1; j > i; j--) {
            if (cards[j].value < cards[j - 1].value) swap(cards[j], cards[j - 1]);
        }
    }
    is_stable = IsStable(cards, n);
    return is_stable;
}

bool SelectionSort(Card cards[], int n) {
    bool is_stable = true;
    for (int i = 0; i < n; i++) {
        int minj = i;
        for (int j = i + 1; j < n; j++) {
            if (cards[j].value < cards[minj].value) minj = j;
        }
        if (minj != i) swap(cards[i], cards[minj]);
    }
    is_stable = IsStable(cards, n);
    return is_stable;
}

