bool IsStable(const Card* const cards, const Card* const orig_cards, const int size){
    bool is_stable = true;
    for(int i=0; i<size; ++i){
        if(cards[i].pattern != orig_cards[i].pattern){
            is_stable = false;
        }
    }
    return is_stable;
}

void SelectionSort(Card* cards, const size_t size){
    for(int i=0; i<size; ++i){
        int min_j = i;
        for(int j=i; j<size; ++j){
            if(cards[j].num < cards[min_j].num) min_j = j;
        }
        std::swap(cards[i], cards[min_j]);
    }
}

void BubbleSort(Card* cards, const size_t size){
    bool swap_flag = true;
    for(int i=0; swap_flag; ++i){
        swap_flag = false;
        for(int j=size-1; j>=i+1; j--){
            if(cards[j].num < cards[j-1].num) {
                std::swap(cards[j], cards[j-1]);
                swap_flag = true;
            }
        }
    }
}

