  int count = 0;
  bool flag = 1;
  for (int i = 0; flag; i++) {
    flag = 0;
    for (int j = len - 1; j >= i + 1; j--) {
      if (A[j].value < A[j - 1].value) {
        swap(A[j], A[j - 1]);
        count++;
        flag = 1;
      }
    }
  }
  return count;
}

int selectionSort(struct Card A[], int len) {
  int count = 0;
  for (int i = 0; i < len; i++) {
    int mini = i;
    for (int j = i; j < len; j++) {
      if (A[j].value < A[mini].value) {
        mini = j;
      }
    }
    if (i != mini) {
      swap(A[i], A[mini]);
      count++;
    }
  }
  return count;
}

