void BubbleSort(Trump* C, const int N) {
	for(int i = 0; i < N; ++i){
		for(int j = N - 1; j > i; --j){
			if(C[j].value < C[j - 1].value){
				swap(C[j], C[j - 1]);
			}
		}
	}
}

void SelectionSort(Trump* C, const int N) {
	for(int i = 0; i < N; ++i) {
		int minj = i;
		for(int j = i; j < N; ++j) {
			if(C[j].value < C[minj].value) {
				minj = j;
			}
		}
		swap(C[i], C[minj]);
	}
}

bool isStable(const Trump* input, const Trump* output, const int* valList, const int N){
	int count;
	char suit[2][4];

	for(int i = 0; i < 9; ++i){
		if(2 <= valList[i]){
			memset(suit, 0, sizeof(suit));
			count = 0;
			for(int j = 0; j < N; ++j) {
				if(input[j].value == i + 1){
					suit[0][count++] = input[j].suit;
					if(valList[i] == count){
						break;
					}
				}
			}

			count = 0;
			for(int j = 0; j < N; ++j) {
				if(output[j].value == i + 1) {
					suit[1][count++] = output[j].suit;
					if(valList[i] == count) {
						break;
					}
				}
			}

			if(0 != strncmp(suit[0], suit[1], valList[i])) {
				return false;
			}
		}
	}
	return true;
}

void swap(Trump& x, Trump& y){
	Trump tmp = x;
	x.suit = y.suit;
	x.value = y.value;
	y.suit = tmp.suit;
	y.value = tmp.value;
}

