struct st{
	int val;
	char tag;
	st(int _val,char _tag):val(_val),tag(_tag){}
};

vector<st> bubblesort(vector<st> c){
	rep(i,c.size()){
		for(int j = c.size() - 1;j > i;j--){
			if(c[j].val < c[j-1].val)swap(c[j],c[j-1]);
		}
	}
	return c;
}

vector<st> selectionsort(vector<st> c){
	rep(i,c.size()){
		int minj = i;
		FOR(j, i+1 ,c.size()){
			if(c[minj].val > c[j].val)minj = j;
		}
		swap(c[i],c[minj]);
	}
	return c;
}



