//
//  安定なソート
//  バブルソートと選択ソート
//
#include <iostream>

class Trump {
private:
    char type;
    int  value;
public:
    Trump() { type = ' '; value = 0; }
    void setType(char c) { type = c; }
    void setValue(int i) { value = i; }
    char getType()  const { return type; }
    int  getValue() const { return value; }
};

void swap(Trump& a, Trump& b) {
    Trump tmp = a; a = b; b = tmp;
}
bool isStable(Trump* a, Trump* b, int n) {
    for (int i = 0; i < n; i++) {
        if (a[i].getType() != b[i].getType()) {
            return false;
        }
    }
    return true;
}

int bubbleSort(Trump* a, int n) {
    int count = 0;
    bool flag = true;
    while (flag) {
        flag = false;
        for (int j = n - 1; j > 0; j--) {
            // 配列の最後の要素から値をチェックする。
            // もし、配列の要素の値がソートできたら、flagはfalseのまま。
            if (a[j].getValue() < a[j - 1].getValue()) {
                // ひとつ前の要素の値のほうが大きいので、
                // 値を入れ替える。
                swap(a[j - 1], a[j]);
                flag = true;
                count++;
            }
        }
    }
    return (count);
}
int selectionSort(Trump* a, int n) {
    int count = 0;
    // 配列の中から最小値を探し、
    // 前から順に格納する。
    for (int i = 0; i < n; i++) {
        int min = i;
        for (int j = i; j < n; j++) {
            if (a[j].getValue() < a[min].getValue())
                min = j;
        }
        if (i < min) {
            swap(a[i], a[min]);
            count++;
        } // i == minであれば入れ替える必要がない
    }
    return (count);
}

int main() {
    int n;
    std::cin >> n;

    Trump* a = new Trump[n];
    Trump* b = new Trump[n];

    for (int i = 0; i < n; i++) {
        char type;
        int  value;
        std::cin >> type >> value;
        a[i].setType(type);
        a[i].setValue(value);
    }
    for (int i = 0; i < n; i++)
        b[i] = a[i];

    int cnt1 = bubbleSort(a, n);
    int cnt2 = selectionSort(b, n);

    // バブルソートの結果を出力
    for (int i = 0; i < n; i++) {
        std::cout << a[i].getType() << a[i].getValue();
        if (i == n - 1)
            std::cout << std::endl;
        else
            std::cout << ' ';
    }
    std::cout << "Stable\n";

    // 選択ソートの結果を出力
    for (int i = 0; i < n; i++) {
        std::cout << b[i].getType() << b[i].getValue();
        if (i == n - 1)
            std::cout << std::endl;
        else
            std::cout << ' ';
    }
    if (isStable(a, b, n)) {
        std::cout << "Stable\n";
    }
    else {
        std::cout << "Not stable\n";
    }

    return (0);
}

