	card t = c1[j - 1];
	c1[j - 1] = c1[j];
	c1[j] = t;
      }
    }
  }
}

void selection_sort(card c2[]){

  for( int i = 0 ; i < n ; i++ ){
    int mini = i;
    for( int j = i ; j < n ; j++ ){
      if( c2[j].num < c2[mini].num ) mini = j;
    }
    card t = c2[i];
    c2[i] = c2[mini];
    c2[mini] = t;
  }
}

void output(card a[]){

  for( int i = 0 ; i < n ; i++ ){
    if(i) cout << " ";
    cout << a[i].suit << a[i].num;
  }
  cout << endl;

}

bool isStable(card c1[], card c2[]){

  for( int i = 0 ; i < n ; i++ ){
    if( c1[i].suit != c2[i].suit ) return false;
  }
  return true;
}

