		flag = 0;
		for (int j = N - 1; j > i; j--) {
			if (A[j].value < A[j - 1].value) {
				swap(A[j], A[j - 1]);
				flag = 1;
			}
		}
	}
}

void Selectionsort(struct Card A[], int N) {
	for (int i = 0; i < N; i++) {
		int minj = i;
		for (int j = N - 1; j > i; j--) {
			if (A[minj].value > A[j].value) {
				swap(A[minj], A[j]);
			}
		}
	}
}

