static void bubbleSort(int *ID, int *A, int N){
	int temp;
	bool flag;
	do{
		flag = false;
		for (int j = N - 1; j >= 1; j--){
			if (A[ID[j]] < A[ID[j - 1]]){
				temp = ID[j];
				ID[j] = ID[j - 1];
				ID[j - 1] = temp;
				flag = true;
			}
		}
	} while (flag);
}

static void selectionSort(int *ID, int *A, int N){
	int minj, temp;
	for (int i = 0; i < N; i++){
		minj = i;
		for (int j = i + 1; j < N; j++){
			if (A[ID[j]] < A[ID[minj]]){
				minj = j;
			}
		}

		if (minj != i){
			temp = ID[i];
			ID[i] = ID[minj];
			ID[minj] = temp;
		}
	}
}

