int bubble_sort(card data[], int N) {
    int swap_count = 0;
    bool flag = true;
    while (flag) {
        flag = false;
        for (int i = N - 1; i > 0; i--) {
            if (data[i].value < data[i-1].value) {
                swap(data[i], data[i-1]);
                swap_count++;
                flag = true;
            }
        }
    }
    return swap_count;
}

int selection_sort(card data[], int N) {
    int swap_count = 0;

    for (int i = 0; i < N; i++) {
        int minj = i;
        for (int j = i; j < N; j++) {
            if (data[j].value < data[minj].value) {
                minj = j;
            }
        }
        if (i != minj) {
            swap(data[i], data[minj]);
            swap_count++;
        }
    }

    return swap_count;
}

bool is_stable(card data1[], card data2[], int N) {
    for (int i = 0; i < N; i++) {
        if (data1[i].type != data2[i].type) {
            return false;
        }
    }
    return true;
}

