  std::cin >> n;
  std::vector<std::string> c;
  for (int i = 0; i < n; ++i) {
    std::string str;
    std::cin >> str;
    c.push_back(str);
  }
  std::vector<std::string> bSorted = bubbleSort(c, n);
  for (int i = 0; i < n; ++i) {
    std::cout << bSorted[i];
    if (i == n - 1)
      std::cout << std::endl;
    else
      std::cout << " ";
  }
  std::cout << "Stable" << std::endl;

  std::vector<std::string> sSorted = selectionSort(c, n);
  bool stable = true;
  for (int i = 0; i < n; ++i) {
    std::cout << sSorted[i];
    if (i == n - 1)
      std::cout << std::endl;
    else
      std::cout << " ";
    if (sSorted[i] != bSorted[i])
      stable = false;
  }
