  for (int i=0; flag; i++) {
    flag = 0;
    for (int j=n-1; j>=i+1; j--) {
      if (A[j].value < A[j-1].value) {
        swap(A[j], A[j-1]);
        flag = 1;
      }
    }
  }
}

int selectionSort(struct card A[], int n) {
  int minj;
  for (int i=0; i<n-1; i++) {
    minj = i;
    for (int j=i+1; j<n; j++) {
      if (A[minj].value > A[j].value) {
        minj = j;
      }
    }
    if (i != minj) {
      swap(A[i], A[minj]);
    } 
  }
}

