void bsort(int *b,string *a,int n){
  bool j=true;
  while(j){
    j=false;
    for(int i=1;i<n;i++){
      if(*(b+i-1)>*(b+i)){j=true; swap(*(b+i-1),*(b+i)); swap(*(a+i-1),*(a+i));}
  }}
}


void ssort(int *b,string *a,int n){
  for(int i=0;i<n-1;i++){
    string mi=*(b+i);
    int k=i;
    for(int t=i+1;t<n;t++){
      if(mi>*(b+t)){mi=*(b+t); k=t;}
    }
    swap(*(b+i),*(b+k)); swap(*(a+i),*(a+k));
  }
}


