    int n;
    Card cards[40];
    std::string card;
    std::cin >> n;

    for(int i=0; i<n; ++i){
        std::cin >> card;
        cards[i].pattern = card[0];
        cards[i].num = static_cast<int>(card[1] - '0');
    }

    // copy
    Card orig_cards[40];
    for(int i=0; i<n; ++i){
        orig_cards[i] = cards[i];
    }

    // selection sort
    SelectionSort(cards, n);
    // Bubble Sort
    BubbleSort(orig_cards, n);

    Show(orig_cards, n);
    std::cout << "Stable" << std::endl;

    Show(cards, n);
    if(IsStable(cards, orig_cards, n)){
        std::cout << "Stable" << std::endl;
    }else{
        std::cout << "Not stable" << std::endl;
    }
}

