{
	for (int i = 0; i < n; i++)
	{
		for (int j = n - 1; j > i; j--)
		{
			if (A[j].value < A[j - 1].value)
				swap(A[j], A[j - 1]);
		}
	}
}

void Selectionsort(Card A[], int n)
{
	for (int i = 0; i < n; i++)
	{
		int mini = A[i].value;
		int mininum = i;
		for (int j = i + 1; j < n; j++)
		{
			if (A[j].value < mini)
			{
				mini = A[j].value;
				mininum = j;
			}
		}
		if (i != mininum)
		{
			swap(A[i], A[mininum]);
		}

	}
}

