  int i = 0;
  while (flag) {
    flag = 0;
    for (int j = N - 1; j >= i + 1; j--) {
      if (A[j].value < A[j - 1].value) {
        swap(A[j], A[j - 1]);
        flag = 1;
      }
    }
  }
}

void selection (struct Card A[], int N) {
  int i = 0;
  for (i = 0; i < N; i++) {
    int minj = i;
    for (int j = i; j < N; j++) {
      if (A[j].value < A[minj].value) {
        minj = j;
      }
    }
    if (i != minj) {
      swap(A[i], A[minj]); 
    }
  }
}

