	for (int i = 0; flag; i++) {
		flag =0;
		for (int j = N - 1; j > i; j--) {
			if (C[j].value < C[j-1].value) {
				swap(C[j], C[j-1]);
				flag = 1;
			}
		}
	}
}

void selectionSort(Card C[], int N) {
