    }
    cout << endl;
}

void selection(struct card A[],int N){
    for(int i=0; i < N-1; i++){
        int min = A[i].value;
        int index = i;
        for(int j = i+1; j < N; j++){
            if(A[j].value < min){
                min = A[j].value;
                index = j;
            }
        }
        if(i != index){
            swap(A[i],A[index]);
        }
    }
}

void bubble(struct card A[],int N){
    for(int i = 0; i < N-1; i++){
        int j = N-1;
        while(j > i){
            if(A[j-1].value > A[j].value){
                swap(A[j-1],A[j]);
            }
            j--;
        }
    }
}

bool judge(struct card A[],struct card B[], int N){
    for(int i = 0; i < N; i++){
        if(A[i].suit != B[i].suit){
            return false;
        }
    }
    return true;
}

