using namespace std;

class Card{
    public:
        Card(): suit(0), number(0){};
        ~Card(){};
        char suit;
        int number;
        friend ostream& operator<<(ostream& os, const Card& card){
            os << card.suit << card.number;
            return os;
        }
        bool operator!=(const Card& card){
            if(this->suit == card.suit){
                if(this->number == card.number){
                    return false;
                }
            }
            return true;
        }
};

int bubble_sort(Card A[], int N) {
    int count = 0;
	for (int i = 1; i < N; ++i) {
		bool flag = true;
		while (flag) {
            flag = false;
			for (int j = N - 1; j > 0; --j) {
				Card tmp = A[j - 1];
				if (A[j].number < tmp.number) {
					A[j - 1] = A[j];
					A[j] = tmp;
					flag = true;
                    ++count;
				}
			}
		}
	}
    return count;
}

int selection_sort(Card A[], int N) {
    int count = 0;
	for (int i = 0; i < N; ++i) {
		int minj = i;
        for(int j = i; j < N; ++j){
            if(A[j].number < A[minj].number){
                minj = j;
            }
        }
        if(i != minj){
            swap(A[i], A[minj]);
            ++count;
        }
	}
    return count;
}

// バブルソート(安定)の配列と比較して違いがあれば安定でない
bool is_stable(Card B[], Card S[], int N){
    for(int i = 0; i < N; ++i){
        if(B[i] != S[i]) return false;
    }
    return true;
}

