class Card{
    public:
    char name;
    int value;
};

void swap(Card *a, Card *b){
    Card tmp;
    tmp = *a;
    *a = *b;
    *b = tmp;
}

void BubbleSort(Card* C, int N){
    int i,j;
    for(i=0;i<N;i++){
        for(j=N-1;j>i;j--){
            if(C[j].value < C[j-1].value){
                swap(C[j],C[j-1]);
            }
        }
    }
}

void SelectionSort(Card* C, int N){
    int i,j,minj;
    for(i=0;i<N;i++){
        minj = i;
        for(j=i;j<N;j++){
            if(C[j].value < C[minj].value){
                minj = j;
            }
        }
        swap(C[i],C[minj]);
    }
}

