static const int N = 36;

void bubbleSort(char a[][3], int n) {
    int flag = 1;

    for (int i = 0; flag; i++) {
        flag = 0;
        for (int j = n - 1; j > i; j--) {
            if (a[j][1] < a[j-1][1]) {
                swap(a[j], a[j-1]);
                flag = 1;
            }
        }
    }
}

void selectionSort(char a[][3], int n) {
    for (int i = 0; i < n; i++) {
        int min = i;
        for (int j = i + 1; j < n; j++) {
            if (a[j][1] < a[min][1]) {
                min = j;
            }
        }
        if (min != i) {
            swap(a[min], a[i]);
        }
    }
}

void output(char a[][3], int n) {
    for (int i = 0; i < n; i++) {
        if (i > 0) {
            cout << ' ';
        }
        cout << a[i][0] << a[i][1];
    }
    cout << endl;
}

bool isStable(char a[][3], char b[][3], int n) {
    for (int i = 0; i < n; i++) {
        if (a[i][0] != b[i][0] || a[i][1] != b[i][1]) {
            return false;
        }
    }
    return true;
}

