    char a[N][3], b[N][3];
    int n;

    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        b[i][0] = a[i][0];
        b[i][1] = a[i][1];
    }

    bubbleSort(a, n);
    output(a, n);
    cout << "Stable" << endl;

    selectionSort(b, n);
    output(b, n);
    if (isStable(a, b, n)) {
        cout << "Stable" << endl;
    } else {
        cout << "Not stable" << endl;
    }

    return 0;
}

