};

bool IsSameCard(const Card &a, const Card &b);
bool IsSameValue(const Card &a, const Card &b);

struct CardGroup {
  int32_t count_;
  Card card_[kMaxArraySize];
};

class BubbleSort {
 public:
  BubbleSort() noexcept;
  ~BubbleSort() noexcept;
  void Sort() noexcept;
  void Print() noexcept;
  void Load(const CardGroup &card_group) noexcept;
  bool IsStable(const CardGroup &card_group);

 private:
  bool ShouldSwap(const int32_t index_target) noexcept;
  void SwapWithLeftNext(const int32_t index_target) noexcept;

 private:
  BubbleSort(const BubbleSort &obj) noexcept = delete;
  BubbleSort &operator=(const BubbleSort &obj) noexcept = delete;
  BubbleSort(BubbleSort &&obj) = delete;
  BubbleSort &operator=(BubbleSort &&obj) = delete;

 private:
  CardGroup card_group_;
};

class SelectionSort {
 public:
  SelectionSort() noexcept;
  ~SelectionSort() noexcept;
  void Sort() noexcept;
