 private:
  void Sort() noexcept;
  void Print() noexcept;
  void Load(std::istream &input_stream) noexcept;

 private:
  StableSort(const StableSort &obj) noexcept = delete;
  StableSort &operator=(const StableSort &obj) noexcept = delete;
  StableSort(StableSort &&obj) = delete;
  StableSort &operator=(StableSort &&obj) = delete;

 private:
  CardGroup card_group_;
  BubbleSort bubble_sort_;
  SelectionSort selection_sort_;
};


bool IsSameCard(const Card &a, const Card &b) {
  return (a.suit == b.suit) && (a.value == b.value);
}
bool IsSameValue(const Card &a, const Card &b) {
  return (a.value == b.value);
}

StableSort::StableSort() noexcept : bubble_sort_{}, selection_sort_{} {}

StableSort::~StableSort() noexcept {}

void StableSort::Main(std::istream &input_stream) noexcept {
  Load(input_stream);
  Sort();
  Print();
}

