#include <iostream>
using namespace std;

struct Data
{
    char s;
    int a;
};

void swap(Data *p,Data *q)
{
   Data temp;
   temp=*p;
   *p=*q;
   *q=temp;
}

void ButtleSort(int n,Data *p)
{
    for(int i=0;i<n-1;i++)
    {
        for(int j=n-1;j>i;j--)
        {
            if((p+j)->a<(p+j-1)->a)
            {
                swap((p+j),(p+j-1));
            }
        }
    }
}

void SelectSort(int n,Data *p)
{
    int mini,num=1;
    for(int i=0;i<n-1;i++)
    {
        mini=i;
        for(int j=i+1;j<n;j++)
        {
            if((p+j)->a<(p+mini)->a)
            {
               mini=j;
            }

        }
        if(mini!=i)
        {
            if((p+mini)->a==(p+i)->a)
            {
                num=0;
                swap((p+mini),p+i);
            }
            else
                swap((p+mini),p+i);
        }
    }
}


int main(int argc, char const *argv[])
{
    int n,num=1;  cin>>n;
    Data *p,*q;
    p=new Data[n];
    for(int i=0;i<n;i++)
    {
        cin>>(p+i)->s>>(p+i)->a;
    }
