    cout<<(q+n-1)->s<<(q+n-1)->a<<endl;
    for(int i=0;i<n;i++)
    {
        if((q+i)->s!=(p+i)->s)
            num=0;
    }
    if(num)
        cout<<"Stable"<<endl;
    else    
        cout<<"Not stable"<<endl;

    delete []p;
    delete []q;
    p=q=NULL;
