#include <stdio.h>
#include <math.h>

int makeelem(int suit, int number) { return suit * 256 + number; }
int getsuit(int elem) { return elem >> 8; }
int getvalue(int elem) { return elem & 255; }

int n;
int a[36];
int index[36];

void swap(int *a, int *b) {
	int tmp = *a;
	*a = *b;
	*b = tmp;
}

void bubblesort() {
	for (int i = 0; i < n; i ++) {
		for (int j = n - 1; j >= i + 1; j --) {
			if (a[j] < a[j-1]) {
				swap(&a[j], &a[j-1]);
			}
		}
	}
}

void selectionsort() {
	for (int i = 0; i < n; i ++) {
		int mini = i;
		for (int j = i; j < n; j ++) {
			if (getvalue(a[j]) < getvalue(a[mini])) {
				mini = j;
			}
		}
		swap(&a[i], &a[mini]);
		swap(&index[i], &index[mini]);
	}
}

int isstable() {
	int i = 0;
	while (i < n) {
		int val = getvalue(a[i]);
		int prev = index[i];
		i ++;
		while (i < n) {
			if (getvalue(a[i]) == val) { i ++; break; }
			if (prev > index[i]) return 0;
			i ++;
		}
	}
	return 1;
}

void print() {
	for (int i = 0; i < n; i ++) {
		if (i > 0) printf(" ");
		printf("%c%d", getsuit(a[i]), getvalue(a[i]));
	}
	printf("\n");
}

