		int value = line[3 * i + 1] - '0';
		a[i] = makeelem(suit, value);
	}
	for (int i = 0; i < n; i ++) {
		index[i] = i;
	}
	selectionsort();
	print();
	printf("Stable\n");
	print();
	if (isstable()) { printf("Stable\n"); } else { printf("Not stable\n"); }
	return 0;
}

#include <iostream>
#include <vector>

int bubbleSort(std::vector<std::string>& a, int n) {
    int x = 0;
    int flag = 1;
    int i = 0;
    while (flag) {
        flag = 0;
        for (int j = n - 1; j >= i + 1; j--) {
            if (a[j][1] < a[j - 1][1]) {
                std::iter_swap(a.begin() + j, a.begin() + j - 1);
                flag = 1;
                x++;
            }
        }
        i++;
    }
    return x;
}

int selectionSort(std::vector<std::string>& a, int n) {
    int x = 0;
    int minj = 0;
    for (int i = 0; i < n - 1; i++) {
        minj = i;
        for (int j = i + 1; j < n; j++) {
            if (a[j][1] < a[minj][1]) {
                minj = j;
            }
        }
        if (minj != i) {
            std::iter_swap(a.begin() + i, a.begin() + minj);
            x++;
        }
    }
    return x;
}

bool isStable(
    std::vector<std::string>& a,
    std::vector< std::vector<char> >& c)
{
    int i = 0;
    while (i < a.size()) {
        for (int j = 0; j < c[a[i][1] - '0' - 1].size(); j++) {
            if (a[i + j][0] != c[a[i][1] - '0' - 1][j]) {
                return false;
            }
        }
        i += c[a[i][1] - '0' - 1].size();
    }
    return true;
}

void output(
    std::vector<std::string>& a,
    std::vector< std::vector<char> >& c)
{
    std::cout << a[0];
    for (int i = 1; i < a.size(); i++) {
        std::cout << " " << a[i];
    }
    std::cout << std::endl;
    if (isStable(a, c)) {
        std::cout << "Stable" << std::endl;
    } else {
        std::cout << "Not stable" << std::endl;
    }
}

int main(int argc, const char *argv[]) {
    int n;
    std::cin >> n;
    std::vector<std::string> a(n);
    std::vector<std::string> b(n);
    std::vector< std::vector<char> > c(9);
    for (int i = 0; i < n; i++) {
        std::cin >> a[i];
        b[i] = a[i];
        c[a[i][1] - '0' - 1].push_back(a[i][0]);
    }

    bubbleSort(a, n);
    selectionSort(b, n);

    output(a, c);
    output(b, c);

    return 0;
}

