using namespace std;

struct P{
   char c;
   int n;
   P() {}
   P(char c, int n): c(c), n(n) {}

   bool operator < (const P& rhs) const {
      return( n < rhs.n );
   }

   bool operator > (const P& rhs) const {
      return( n > rhs.n );
   }

   bool operator == (const P &rhs) const {
      return( c == rhs.c && n == rhs.n);
   }
};

void bubble(P *a, int N){
   bool f = true;
   for(int i=0; f; ++i){
      f = false;
      for(int j = N-1; j > i; --j){
         if( a[j-1] > a[j] ){
            swap(a[j-1], a[j]);
            ++f;
         }
      }
   }
   return;
}

void selection(P *a, int N){
   rep(i, N){
      int minp = i;
      for(int j = i+1; j < N; ++j)
         if( a[j] < a[minp] )minp = j;
      if(i != minp)
         swap(a[i], a[minp]);
   }
   return;
}

