void swap(string *a,string *b)
{
	string c;

	c = *b;
	*b = *a;
	*a = c;
}

int selection_sort(int n,string *a)
{
	int min;
	int ans=0;
	for(int i=0;i<n;i++){
		min = i;
		for(int j = i;j<n;j++){
			if(a[j][1] < a[min][1]){
				min = j;
			}
		}
		if(i != min){
			swap(&a[i],&a[min]);
			ans++;
		}
	}

	return ans;
}

int bubble_sort(int n,string *a)
{
	int flag = 1;
	int ans=0;

	while(flag){
		flag = 0;
		for(int i=n-1;i>0;i--){
			if(a[i][1] < a[i-1][1]){
				swap(&a[i],&a[i-1]);
				ans++;
				flag = 1;
			}
		}
	}

	return ans;
}

