//
//  Stable sort
//
//
//  Description:
//
//      In the case when sorting cards by using
//      bubble sort and selection sort, bubble
//      sort can sort the cards correctly, but
//      selection sort sometimes fails to sort
//      them correctly.
//
//  Complexity of is Stable:
//
//  O(n)
//

#include<iostream>
using namespace std;

struct Card { char suit, value;};

void bubble(struct Card A[], int N) {
    for (int i = 0; i < N; i++) {
        for (int j = N - 1; j >= i; j--) {
            if (A[i].value < A[j - 1].value) {
                Card t = A[j]; A[j] = A[j - 1]; A[j - 1] = t;
            }
        }
    }
}

void selection(struct Card A[], int N) {
    for (int i = 0; i < N; i++) {
        int minj = i;
        for (int j = i; j < N; j++) {
            if (A[j].value < A[minj].value) minj = j;
        }
        Card t = A[i]; A[i] = A[minj]; A[minj] = t;
    }
}

