//Definition
Card::Card( const std::string str ){
    pair = str;
}

char Card::GetSymbol(){
    return pair[0];
}

int Card::GetNumber(){
    return static_cast<int>( pair[1] - '0' );
}

std::string Card::GetString(){
    return pair;
}

void MySwap( Card& a, Card& b ){
    Card tmp = std::move(a);
    a = std::move(b);
    b = std::move(tmp);
}

void BubbleSort( std::vector<Card>& vec ){
    int n = vec.size();
    for( int i = 0; i < n; ++i ){
        for( int j = n - 1; j > i; --j ){
            if( vec[j].GetNumber() < vec[j-1].GetNumber() ){
                MySwap( vec[j], vec[j-1] );
            }
        }
    }
}

void SelectionSort( std::vector<Card>& vec ){
    int n = vec.size();
    int minj;
    int j;
    for( int i = 0; i < n; ++i ){
        minj = i;
        for( j = i; j < n; ++j ){
            if( vec[j].GetNumber() < vec[minj].GetNumber() ){
                minj = j;
            }
        }
        if( i != minj ){
            MySwap( vec[i], vec[minj] );
        }
    }
}

std::string CheckStable( std::vector<Card>& vec ){
    int n = vec.size();
    int smaller;
    int bigger;
    for( int i = 1; i < n; ++i ){
        if( vec[i-1].GetNumber() == vec[i].GetNumber() ){
            smaller = int( vec[i-1].GetSymbol() );
            bigger = int( vec[i].GetSymbol() );
            if( smaller > bigger ){
                return "Not stable";
            }
        }
    }
    return "Stable";
}

