bool checkStable(card* in, card* out, int N){
    for(int i=0; i<N-1; i++){
        for(int j=i+1; j<N; j++){
            for(int k=0; k<N-1; k++){
                for(int l=k; l<N; l++){
                    if(in[i].number == in[j].number &&
                       in[i].number == out[l].number &&
                       in[i].suit == out[l].suit &&
                       in[j].number == out[k].number &&
                       in[j].suit == out[k].suit){
                           cout << "Not stable" << endl;
                           return false;
                       }
                }
            }
        }
    }
    cout << "Stable" << endl;
    return true;
}

