  while (flag) {
    flag = 0;
    int i = 0;
    for (int j = n - 1; j >= i + 1; j--) {
      if (c[j].second < c[j-1].second) {
        swap(c[j], c[j - 1]);
        flag = 1;
      }
    }
    i++;
  }
}

void selection_sort(vector<P>& c, int n) {
  for (int i = 0; i < n; i++) {
    int minj = i;
    for (int j = i; j < n; j++) {
      if (c[j].second < c[minj].second) {
        minj = j;
      }
    }
    swap(c[i], c[minj]);
  }
}

