void printList(Card num[], int n){
	for (int i = 0; i < n; i++){
		cout << num[i].suit;
		if (i != n-1) cout << ' ';
	}
	cout << endl;
}

void swap(int *x, int *y){
	int tmp;
	tmp = *x;
	*x = *y;
	*y = tmp;
}

void swapCard(Card *x, Card *y){
	Card tmp;
	tmp = *x;
	*x = *y;
	*y = tmp;
}

int bubbleSort(Card num[], int n){
	int count = 0;
	for (int i = 0; i < n; i++){
		for (int j = n-1; j > i; j--){
			if (num[j].num < num[j-1].num){
				swapCard(&num[j], &num[j-1]);
				count++;
			}
		}
	}
	return count;
}

int selectionSort(Card num[], int n){
	int min, j, count = 0;
	for (int i = 0; i < n; i++){
		min = i;
		for (j = i; j < n; j++){
			if (num[min].num > num[j].num)
				min = j;
		}
		if (min != i){
			swapCard (&num[min], &num[i]);
			count++;
		}
	}
	return count;
}

void copy(Card target[], Card source[], int n){
	for (int i = 0; i < n; i++)
		target[i] = source[i];
}

bool isStable(Card in[], Card out[], int n){
	for (int i = 0; i < n; i++){
		for (int j = i+1; j < n; j++){//前两层循环遍历所有两个数的情况
			for (int a = 0; a < n; a++){//i与j分别代表两个数
				for (int b = a+1; b < n; b++){//
					if (in[i].num == in[j].num && 
					strcmp(in[i].suit, out[b].suit) == 0 &&
					strcmp(in[j].suit, out[a].suit) == 0)
						return false;
				}
			}
		}
	}
	return true;
}

