    for(int j = N-1; j >= 1; j--){
      if(A[j].value < A[j-1].value){
        swap(A[j], A[j-1]);
        flag = 1;
      }
    }
  }
}

int SelectionSort(vector<card> &A, int N){
  for(int i = 0; i < N; i++){
    int minj = i;
    for(int j = i; j < N; j++){
      if(A[j].value < A[minj].value){
        minj = j;
      }
    }
    if(minj != i){
      swap(A[i], A[minj]);
    }
  }
}

