      return value == t.value && c == t.c;
    }
};

vector<T> BubbleSort(vector<T> C, int N){
  for(int i = 0; i < N; i++){
    for(int j = N-1; j >= i+1; j--){
      if(C[j].value < C[j-1].value)
        swap(C[j], C[j-1]);
    }
  }
  return C;
}

vector<T> SelectionSort(vector<T> C, int N){
  for(int i=0; i < N; i++){
    int minj = i;
    for(int j = i; j < N; j++){
      if(C[j].value < C[minj].value){
        minj = j;
      }
    }
    swap(C[i], C[minj]);
  }
  return C;
}

