/*
BubbleSort(C)
1 for i = 1 to length[C]
2     do for j = length[C] downto i+1
3         do if value[C[j]] < value[[C[j-1]]
4             then swap C[j] and C[j-1]

SelectionSort(C)
1 for i = 1 to length[C]
2     do mini = i
3     do for j = i to length[C]
4         do if value[C[j]] < value[C[mini]]
5             then mini = j
6        swap C[i] and C[mini]

*/

bool compare_less (string a, string b )
{
	if (a[1] != b[1] ) return a[1] < b[1];
}

vector<string> bubble_sort (vector<string> c )
{
	int n = c.size();
	rep (i, n ){
		for (int j = n-1; j >= i+1; j-- ){
			if (compare_less (c[j], c[j-1] ) ){
				swap (c[j], c[j-1] );
			} // end if
		} // end for
	} // end rep

	return c;
}

vector<string> selection_sort (vector<string> c )
{
	int n = c.size();
	rep (i, n ){
		int mini = i;
		for (int j = i; j < n; j++ ){
			if (compare_less (c[j], c[mini] ) ){
				mini = j;
			} // end if
		} // end for
		if (mini != i ){
			swap (c[i], c[mini] );
		} // end if
	} // end rep

	return c;
}

