int bubbleSort(vector<string> &v) {
  int tot = 0;
  for (int i = 0, n = v.size(); i < n; i++) {
    bool isSorted = true;
    for (int j = n - 1; j > i; j--) {
      if (cmp(v[j], v[j - 1]) < 0) {
        isSorted = false;
        swap(v[j], v[j - 1]);
        ++tot;
      }
    }
    if (isSorted) break;
  }
  return tot;
}
int selectionSort(vector<string> &v) {
  int tot = 0;
  for (int i = 0, n = v.size(); i < n; i++) {
    int k = i;
    for (int j = i; j < n; j++) {
      if (cmp(v[j], v[k]) < 0) {
        k = j;
      }
    }
    if (k != i) {
      ++tot;
      swap(v[k], v[i]);
    }
  }
  return tot;
}
