void BubbleSort(vector<Card> &c, int N){
    bool flag = true;
    while(flag){
        flag = false;
        repr(i, N - 2){
            if(c.at(i + 1).value < c.at(i).value){
                swap(c.at(i + 1), c.at(i));
                flag = true;
            }
        }
    }
}

void SelectionSort(vector<Card> &c, int N){
    int min;
    rep(i, N - 1){
        min = i;
        rep2(j, i, N){
            if(c.at(j).value < c.at(min).value){
                min = j;
            }
        }

        if(i != min){
            swap(c.at(i), c.at(min));
        }
    }
}

