bool isStable(const card in[], const card out[], int N){
    for(int i=0;i<N;++i)
        for(int j=i+1;j<N;++j)
            for(int a=0;a<N;++a)
                for(int b=a+1;b<N;++b)
                    if(in[i].num==in[j].num && in[i].type==out[b].type && in[j].type==out[a].type)
                        return false;
    return true;
}

