} card;

void print_cards(const int N, const card A[])
{
    for (int k=0; k < N-1; k++) cout << A[k].mark << A[k].value << " ";
    cout << A[N-1].mark << A[N-1].value << endl;
}

bool is_stable(const int N, const card A1[], const card A2[])
{
    for (int i=0; i < N; i++) {
        if (A1[i].mark != A2[i].mark) return false;
    }
    return true;
}

void bubbleSort(const int N, card A[])
{
    int flag = 1;

    while(flag) {
        flag = 0;
        for (int j=N-1; j > 0; j--) {
            if ( A[j].value < A[j-1].value ) {
                card tmp = A[j];
                A[j] = A[j-1];
                A[j-1] = tmp;
                flag = 1;
            }
        }
    }
}

void selectSort(const int N, card A[])
{
    for (int i=0; i < N-1; i++) {
        int minj = i;
        for (int j = i+1; j < N; j++) {
            if ( A[j].value < A[minj].value ) {
                minj = j;
            }
        }
        if (minj != i) {
            card tmp = A[minj];
            A[minj] = A[i];
            A[i] = tmp;
        }
    }
}

