std::string Print(int size, std::vector<Card> ls) {
	std::string sort = "";
	for (int i = 0; i < size; i++)
		i != size - 1 ? sort += ls[i].name + " " :
		sort +=  ls[i].name + "\n";
	return sort;
}

std::string BubbleSort(int size, std::vector<Card> ls) {
	int swap = 0;
	for (int i = 0; i < size; i++)
		for (int j = size - 1; j > 0; j--)
			if (ls[j].value < ls[j - 1].value) {
				Card _ = ls[j];
				ls[j] = ls[j - 1];
				ls[j - 1] = _;
				swap++;
			}
	return Print(size, ls);
}

std::string SelectionSort(int size, std::vector<Card> ls) {
	int swap = 0, mini;
	for (int i = 0; i < size; i++) {
		mini = i;
		for (int j = i; j < size; j++)
			if (ls[j].value < ls[mini].value) {
				mini = j;
			}
		if (i != mini) {
			Card _ = ls[i];
			ls[i] = ls[mini];
			ls[mini] = _;
			swap++;
		}
	}
	return Print(size, ls);
}

