void bubbleSort(Card c[], int N)
{
	for(int i = 0; i < N; i++)
		for(int j = N-1; j>=i; j--)
			if(c[j].num < c[j-1].num)
				swap(c[j], c[j-1]);
	showArray(c, N);
}

void selectionSort(Card c[], int N)
{
	int min;
	for(int i = 0; i<N; i++)
	{
		min = i;
		for(int j = i; j < N; j++)
			if(c[j].num<c[min].num)
				min = j;
		swap(c[i], c[min]);
	}
	showArray(c, N);
}

void swap(Card& x, Card& y)
{
	Card temp = x;
	x = y;
	y = temp;
}

