		for(int j = num - 1;j >= i+1; j--){
			if(c[j].value < c[j-1].value){
				std::swap(c[j],c[j-1]);		
				flag = true;
			}
		}
	}
}

void Selection_sort(struct Card c[],int num){
	for(int i=0;i<num;i++){
		int mini = i;
		for(int j = i;j < num;j++){
			if(c[j].value < c[mini].value){
				mini = j;
			}
		}
		std::swap(c[i],c[mini]);
	}
}

