void print_array(struct CARD a[],int n){
    for(int i=0;i<n;i++){
        if(i != 0) cout<<' ';
        cout<<a[i].symble<<a[i].value;
    }
    cout<<'\n';
}
void bubble_sort(struct CARD a[],int n){
    int start = 0;
    int flag = 1;
    while (flag){
        flag = 0;
        for (int j=n-1;j>start;j--){
            if (a[j].value<a[j-1].value){
                CARD t = a[j];
                a[j]=a[j-1];
                a[j-1]=t;
                flag = 1;
            }
        }
        start++;
    }
    print_array(a,n);
}
void selection_sort(struct CARD a[],int n){
    for(int i=0;i<n;i++){
        int min_key = i;
        for(int j=i;j<n;j++){
            if(a[j].value<a[min_key].value) {min_key = j;}
        }
        CARD t = a[i];
        a[i]=a[min_key];
        a[min_key]=t;
    }
    print_array(a,n);
}
bool compare_array(struct CARD a[],struct CARD b[],int n){
    for(int i=0;i<n;i++){
        if(a[i].symble != b[i].symble) {return false;}
    }
    return true;
}

