typedef long long ll;

typedef struct Node { ll num; char c; } node;

vector<node> bubble_sort(vector<node> s, ll n) {
    for(ll i = 0; i < n; i++) {
        for(ll j = n-1; j > i; j--) { 
            if( s.at(j).num < s.at(j-1).num) {
                swap(s.at(j-1), s.at(j));
            }
        }
    }
    return s;
}

vector<node> selection_sort(vector<node> s, ll n) {
    for(ll i = 0; i < n; i++) {
        ll min = i;
        for(ll j = i; j < n; j++) { 
            if( s.at(min).num > s.at(j).num) {
                min = j;
            }
        }
        if( s.at(min).num < s.at(i).num) {
            swap(s.at(min), s.at(i));
        }
    }
    return s;
}

