{

	int counter=0;

	for(int i=0; i<N-1; i++) {

		for(int j=0; j<N-i-1; j++) {
			if( arr[j].num > arr[j + 1].num )
				swap(arr[j], arr[j + 1]);
			counter++;
		}

//		show(arr, N);
	}
	return counter;
}

int SelectionSort(card* arr, int N){

	int mini,counter=0;
	for(int i=0; i<N-1; i++) {
		mini=i;

		for(int j=i+1; j<N; j++) {

			mini= (arr[mini].num > arr[j].num)? j : mini;

		}

		if(mini != i){
			swap( arr[mini], arr[i] );
			counter++;
		}
		//show(arr, N);
	}
	return counter;
}

