			if (d[i][1] < d[i-1][1]) {
				char x = d[i-1][1];
				char y = d[i-1][0];
				d[i-1][0] = d[i][0];
				d[i-1][1] = d[i][1];
				d[i][0] = y;
				d[i][1] = x;
				flag = true;
				++num;
			}
		}
	}

	return num;
}

