void selection_sort(struct Card A[], int n){
    int mini;
    for(int i=0;i<n;i++){
        mini = i;
        for(int j=i+1;j<n;j++){
            if(A[mini].value > A[j].value){
                mini = j;
            }
        }
        if(i != mini){
            swap(A[i], A[mini]);
        }
    }
}


