struct P {
	int id;
	char name;
};

P newP(int id, char name){
	P *v = new P;
	v->id = id; v->name = name;
	return *v;
}

void swap(P& a, P& b){
	P h = newP(a.id, a.name);
	a = b;
	b = h;
}

bool check(vector<P>& A, vector<P> a){
	int *ar1, *ar2;
	int n = A.size();
	ar1 = new int[n]; ar2 = new int[n];
	memset(ar1, 0, n*sizeof(int));
	memset(ar2, 0, n*sizeof(int));
	for(int i=0;i<n;i++){
		if(ar1[i] == 0){
			int rank = 1;
			ar1[i] = rank;
			for(int j=i+1;j<n;j++){
				if(A[i].id == A[j].id){
					rank++;
					ar1[j] = rank;
				}
			}
		}
		if(ar2[i] == 0){
			int rank = 1;
			ar2[i] = rank;
			for(int j=i+1;j<n;j++){
				if(a[i].id == a[j].id){
					rank++;
					ar2[j] = rank;
				}
			}
		}
	}
	bool ans = true;
	for(int i=0;i<n;i++){
		for(int j=0;j<n;j++){
			if(A[i].name == a[i].name && A[i].id == a[i].id){
				if(ar1[i] != ar2[i]) ans = false;
			}
		}
	}
	return ans;
}

