	for(int i = 0; i< A.size(); i++){
		int mini = i;
		for(int j = i; j < A.size(); j++){
			if(A[j].id < A[mini].id){
				mini = j;
			}
		}
		if(i != mini){
			swap(A[i], A[mini]);
		}
	}
}

