		for(int i = 0; i < N; ++i){
			int minj = i;
			for(int j = i; j < N; ++j){
				if(A[j].value < A[minj].value) minj = j;
			}
			Trump tmp = A[i];
			A[i] = A[minj];
			A[minj] = tmp;
		}
		for(int i = 0; i < N; ++i){
			if(i > 0) std::cout << " ";
			std::cout << A[i].c << A[i].value;
		}
		std::cout << std::endl;
	}

	void isStable(Trump *A_in, Trump *A_out, int N){
		for(int i = 0; i < N; ++i){
			for(int j = i; j < N; ++j){
				for(int a = 0; a < N; ++a){
					for(int b = a + 1; b < N; ++b){
						if((A_in[i].value == A_in[j].value) && (A_in[i].value == A_out[b].value) && (A_in[i].c == A_out[b].c) && (A_in[j].value == A_out[a].value) && (A_in[j].c == A_out[a].c)){
							std::cout << "Not stable" << std::endl;
							return;
						}
					}
				}
			}
		}
		std::cout << "Stable" << std::endl;
	}
};



