void selection_sort(char seq[100][2], int length) {
  char temp;
  int mini;
  for (int i = 0; i < length - 1; i ++) {
    mini = i;
    for (int j = i + 1; j < length; j ++) {
      if (seq[j][1] < seq[mini][1]) {
        mini = j;
      }
    }
    if (mini != i) {
      for (int j = 0; j < 2; j ++) {
        temp = seq[i][j];
        seq[i][j] = seq[mini][j];
        seq[mini][j] = temp;
      }
    }
  }
}


void buble_sort(char seq[100][2], int length) {
  char temp;
  for (int i = 0; i < length; i ++) {
    for (int j = length - 1; j > i; j --) {
      if (seq[j][1] < seq[j-1][1]) {
        for (int k = 0; k < 2; k ++) {
          temp = seq[j][k];
          seq[j][k] = seq[j-1][k];
          seq[j-1][k] = temp;
        }
      }
    }
  }
}


