// Cardのイコール演算子をオーバーライドする
struct Card {
  char suit;
  int value;

  bool operator==(const Card &other) {
    if ((suit == other.suit) && (value == other.value)) return true;
    else return false;
  }
  bool operator<(const Card &other) {
    if (value < other.value) return true;
    else return false;
  }
};

void bubbleSort(Card A[], int N) {
  int flag = 1;
  int counter = 0;
  int i = 0;
  while (flag) {
    flag = 0;
    for (int j=N-1; j>i; j--) {
      if (A[j] < A[j-1]) {
        swap(A[j], A[j-1]);
        flag = 1;
        counter += 1;
      }
    }
    i++;
  }
}

void selectionSort(Card A[], int N) {
  int counter = 0;
  for (int i=0; i<N; i++) {
    int minj = i;
    for (int j=i; j<N; j++) {
      if (A[j]<A[minj]) {
        minj = j;
      }
    }
    swap(A[i], A[minj]);
    if (i != minj) counter++;
  }
}

bool isStable(Card in[], Card out[], int N) {
  // in: sort前
  // out: sort後
  for (int i_in=0; i_in<N; i_in++) {
    // i_inに対応するi_outを探す
    int i_out;
    for (int j=0; j<N; j++) {
      if (in[i_in] == out[j]) {
        i_out = j;
        break;
      }
    }
    // i_outをもとに総当り, j_inはvalueがイコールじゃないとだめ
    for (int j_in=0; j_in<N; j_in++) {
      // j_inに対応するj_outを探す
      if ((i_in == j_in) || (in[i_in].value != in[j_in].value)) continue;
      else {
        int j_out;
        for (int j = 0; j < N; j++) {
          if (in[j_in] == out[j]) {
            j_out = j;
            break;
          }
        }
        if (!((i_in<j_in && i_out<j_out) || (i_in>j_in && i_out>j_out))) return false;
      }
    }
  }
  return true;
}

void print(Card in[], Card out[], int N) {
  for (int i=0; i<N; i++) {
    if (i > 0) cout << " ";
    cout << out[i].suit << out[i].value;
  }
  cout << endl;
  if (isStable(in, out, N)) cout << "Stable" << endl;
  else cout << "Not stable" << endl;
}

