static int N_MAX = 100;

class Pair {
public:
	int value;
	char kind;	

	bool operator==(Pair &a) {
		return (this->kind == a.kind && this->value == a.value);
	}

};

void p(Pair C[], int N) {
	for (int i = 0; i < N; ++i) {
		if (i > 0) cout << " ";
		cout << C[i].kind << C[i].value;
	}
	cout << endl;
}

void swap(Pair &a, Pair &b) {
	Pair c = a;
	a = b;
	b = c;
}


void BubbleSort(Pair C[], int N) {
	for (int i = 0; i < N; ++i)
		for (int j = N - 1; j >= i; --j)
			if (C[j].value < C[j - 1].value)
					swap(C[j], C[j-1]);
}

void SelectionSort(Pair C[], int N) {
	for (int i = 0; i < N; ++i) {
		int minj = i;
		for (int j = i; j < N; ++j)
			if (C[j].value < C[minj].value) minj = j;
		if (minj != i) {
			swap(C[i], C[minj]);
		}
	}
}

bool isStable(Pair C[], Pair D[], int N) {
	bool stable = true;
	for (int i = 0; i < N - 1; ++i) {
		int j = i + 1;
		if (C[i].value == C[j].value) {
			int k = 0, l = 0;
			for (; k < N; ++k)
				if (D[k] == C[i])
					break;
			for (; l < N; ++l)
				if (D[l] == C[j])
					break;
			if (k > l)
				return false;
		}
	}
	return true;
}

