		C[i].kind = c;
		C[i].value = d;
		D[i] = C[i];
		E[i] = C[i];
	}

	BubbleSort(D, N);
	p(D, N);
	cout << (isStable(D, C, N) ? "Stable" : "Not stable") << endl;

	SelectionSort(E, N);
