struct Card { char suit, value; };

void bubble(struct Card A[], int N) {
	bool flag = 1;
	for (int i = 0; flag; i++) {
		flag = 0;
		for (int j = N - 1; j > i; j--) {
			if (A[j - 1].value > A[j].value) {
				swap(A[j], A[j - 1]);
				flag = 1;
			}
		}
	}
}

void selection(struct Card A[], int N) {
	int minj;
	for (int i = 0; i < N - 1; i++) {
		minj = i;
		for (int j = i; j < N; j++) {
			if (A[j].value < A[minj].value) {
				minj = j;
			}
		}
		if (i != minj) {
			swap(A[i], A[minj]);
		}
	}
}

