{
	int flag=1;//存在顺序相反的相邻元素
	while(flag)
	{
		flag=0;
		for(int j=n-1;j>=1;j--)
		{
			if(num[j].key<num[j-1].key)//改为<=算法会失去稳定性 
			{

				struct node tt=num[j-1];
				num[j-1]=num[j];
				num[j]=tt;
				flag=1;
			}	
		}
	 } 
	 return 0;
}
