{
	for(int i=0;i<n;i++)
	{
		int minj=i;
		int j=i+1;
		for(;j<n;j++)
		{
			if(num[j].key<num[minj].key)
			{
				minj=j;
			}
		}
		struct node tt=num[minj];
		num[minj]=num[i];
		num[i]=tt;
	}	
	return 0;
} 
