using pic = pair<int,char> ;

vector<pic> bubble(vector<pic> a){
    bool flag = true ;
    while(flag){
        flag = false ;
        for(int i=a.size()-1;i>0;i--){
            if(a.at(i).first<a.at(i-1).first){
                flag = true ;
                int sub = a.at(i).first ;
                a.at(i).first = a.at(i-1).first ;
                a.at(i-1).first = sub ;
                char c = a.at(i).second ;
                a.at(i).second = a.at(i-1).second ;
                a.at(i-1).second = c ;
            }
        }
    }
    return a ;
}

vector<pic> select(vector<pic> a){
    for(int i=0;i<a.size()-1;i++){
        int mn = i ;
        for(int j=i+1;j<a.size();j++){
            if(a.at(mn).first>a.at(j).first) mn = j ;
        }
        int sub = a.at(i).first ;
        a.at(i).first = a.at(mn).first ;
        a.at(mn).first = sub ;
        char c = a.at(i).second ;
        a.at(i).second = a.at(mn).second ;
        a.at(mn).second = c ;
    }
    return a ;
}

