const int MAX = 36;

struct Card
{
	char suit;
	int num;
};

void swap(Card &c1, Card &c2)
{
	char suit_temp;
	int num_temp;

	suit_temp = c1.suit;
	num_temp = c1.num;

	c1.suit = c2.suit;
	c1.num = c2.num;
	c2.suit = suit_temp;
	c2.num = num_temp;

}

bool isEqual(Card c1[], Card c2[], int n)
{
	for(int i = 0; i < n; i++)
	{
		if((c1[i].suit != c2[i].suit) || (c1[i].num != c2[i].num))
			return false;
	}
	return true;
}

int main()
{
	int n, mini;

	cin >> n;

	Card c1[n], c2[n]; 
	for(int i = 0; i < n; i++)
	{
		cin >> c1[i].suit >> c1[i].num;
		c2[i].suit = c1[i].suit;
		c2[i].num = c1[i].num;
	}
	// BubbleSort
	for(int i = 0; i < n; i++)
	{
		for(int j = n-1; j >= i+1; j--)
		{
			if(c1[j-1].num > c1[j].num)
			{
				swap(c1[j-1], c1[j]);
			}
		}
	}
	// SelectionSort
	for(int i = 0; i < n; i++)
	{
		mini = i;
		for(int j = i; j < n; j++)
		{
			if(c2[mini].num > c2[j].num)
			{
				mini = j;
			}
		}
		if(mini != i)
		{
			swap(c2[mini], c2[i]);
		}
	}

	for(int i = 0; i < n-1; i++)
	{
		cout << c1[i].suit << c1[i].num << ' ';
	}
	cout << c1[n-1].suit << c1[n-1].num << endl;
	cout << "Stable\n";

	for(int i = 0; i < n-1; i++)
	{
		cout << c2[i].suit << c2[i].num << ' ';
	}
	cout << c2[n-1].suit << c2[n-1].num << endl;

	if(isEqual(c1, c2, n))
	{
		cout << "Stable\n";
	}
	else
	{
		cout << "Not stable\n";
	}

}

