using namespace std;

struct Card {
	char suit;
	int value;
  bool operator==(const Card& rhs) const {
    return this->suit == rhs.suit && this->value == rhs.value;
  }
};

static void printCard(Card cards[], int N) {
  for (int i = 0; i < N; i++) {
    cout << (i != 0 ? " " : "") << cards[i].suit << cards[i].value;
  }
  cout << endl; 
}

static void inputCard(Card cards[], int N) {
  for (int i = 0; i < N; i++) {
    cin >> cards[i].suit >> cards[i].value;
   }
}

static int bubbleSort(Card cards[], int N) {
  bool flag = true;
  int count = 0;
  for (int i =0; flag; i++) {
    flag = false;
    for (int j = N - 1; j > i; j--) {
      if (cards[j].value < cards[j - 1].value) {
        swap(cards[j], cards[j - 1]);
        flag = true;
        count++;
      }
    }
  }
  return count;
}

static int selectionSort(Card cards[], int N) {
  int minj, count = 0;
  for (int i = 0; i < N; i++) {
    minj = i;
    for (int j = i; j < N; j++) {
      if (cards[j].value < cards[minj].value) {
      	minj = j;
      }
    }
    if (cards[i].value != cards[minj].value) {
      swap(cards[i], cards[minj]);
      count++;
    }
  }
  return count;
}

static bool isStable(Card in[], Card out[], int N) {
  for (int i = 0; i < N; i++) {
    for (int j = i + 1; j < N; j++) {
      for (int a = 0; a < N; a++) {
        for (int b = a + 1; b < N; b++) {
          if (in[i].value == in[j].value && in[i] == out[b] && in[j] == out[a]) {
            return false;
          }
        }
      }
    }
  }
  return true;
}

static bool isSame(Card in[], Card out[], int N) {
  for (int i = 0; i < N; i++) {
    if (!(in[i] == out[i])) {
      return false;
    }
  }
  return true;
}

int main() {
  int N;
  cin >> N;

  array<Card, 36> A, B;
  inputCard(A.data(), N);

  B = A;
  bubbleSort(A.data(), N);
  selectionSort(B.data(), N);

  // バブルソートは常に stable.
  printCard(A.data(), N);
  cout << "Stable" << endl;

  // バブルソートと同じ結果か？
  printCard(B.data(), N);
  bool stable = isSame(A.data(), B.data(), N);
  cout << (stable ? "Stable" : "Not stable") << endl;

  return 0;
}

