void bubbleSort(Card C[], int N)
{
    for (int i = 0; i < N; i++)
    {
        for (int j = N-1; j > i; j--)
        {
            if (C[j].value < C[j-1].value)
                swap(C, j, j-1);
        }
    }
}

void selectionSort(Card *C, int N)
{
    for (int i = 0; i < N; i++)
    {
       int minj = i;
       for (int j = i; j < N; j++)
       {
            if (C[j].value < C[minj].value)
                minj = j;
       }
       swap(C, i, minj);
    }
}

