    bool operator==(const Card &card) const {
        return mrk==card.mrk&&num==card.num;
    }
};

ostream& operator <<(ostream &os, const Card &c){
    return os<<c.mrk<<c.num;
}

vector<Card> bubbleSort(vector<Card> a,ll n){
    rep(i,n){
        rfore(j,i+1,n-1){
            if(a[j].num<a[j-1].num)swap(a[j],a[j-1]);
        }
    }
    return a;
}

vector<Card> selectionSort(vector<Card> a,ll n){
    rep(i,n){
        ll minj=i;
        fore(j,i,n-1){
            if(a[j].num<a[minj].num)minj=j;
        }
        if(minj!=i)swap(a[minj],a[i]);
    }
    return a;
}

