	*x = *y;
	*y = tmp;
}

int bubbleSort(Card num[], int n){
	int count = 0;
	for (int i = 0; i < n; i++){
		for (int j = n-1; j > i; j--){
			if (num[j].num < num[j-1].num){
				swapCard(&num[j], &num[j-1]);
				count++;
			}
		}
	}
	return count;
}

int selectionSort(Card num[], int n){
	int min, j, count = 0;
	for (int i = 0; i < n; i++){
		min = i;
		for (j = i; j < n; j++){
			if (num[min].num > num[j].num)
				min = j;
		}
		if (min != i){
			swapCard (&num[min], &num[i]);
			count++;
		}
	}
	return count;
}

