using namespace std;

template<typename T>
void bubbleSort(vector<T>& ary, int& swapCount)
{
	swapCount = 0;
	bool existsInverseOrderElements = true;
	const int numberOfElements = ary.size();
	while (existsInverseOrderElements) {
		existsInverseOrderElements = false;
		for (int i = numberOfElements - 1; i != 0; --i) {
			T& front = ary.at(i - 1);
			T& back = ary.at(i);
			if (front > back) {
				swap(front, back);
				++swapCount;
				existsInverseOrderElements = true;
			}
		}
	}
}

template<typename T>
void selectionSort(vector<T>& ary, int& swapCount)
{
	swapCount = 0;
	const int numberOfElements = ary.size();
	for (int i = 0; i != numberOfElements - 1; ++i) {
		int minIndexJ = i;
		for (int j = i; j != numberOfElements; ++j) {
			if (ary.at(j) < ary.at(minIndexJ)) {
				minIndexJ = j;
			}
		}
		if (minIndexJ != i) {
			swap(ary.at(i), ary.at(minIndexJ));
			++swapCount;
		}
	}
}

struct Card
{
	//Card(const string& sign, const int number ):sign_(sign), number_(number){}
	bool operator<(const Card& rhs)const { return number_ < rhs.number_; }
	bool operator>(const Card& rhs)const { return number_ > rhs.number_; }
	bool operator==(const Card& rhs)const { return sign_ == rhs.sign_ && number_ == rhs.number_; }
	bool operator!=(const Card& rhs)const { return !(*this == rhs);}
	string getName()const { return sign_ + to_string(number_); }
	string sign_;
	int number_;
};

void outputCards(const vector<Card>& ary)
{
	const string values = accumulate(ary.begin() + 1, ary.end(), ary.front().getName()
		, [](const string& init, const Card& card) {return init + " " + card.getName(); });
	cout << values << endl;
}

auto& operator>>(istream& inputStream , Card& card)
{
	string input;
	inputStream >> input;
	card.sign_ = input.front();
	card.number_ = stoi(input.substr(1));
	return card;
}

int main()
{
	int n;
	cin >> n;
	vector<Card> aryBuble(n);

	for (auto& card : aryBuble) {
		cin >> card;
	}
	vector<Card> arySelection(aryBuble);

	int swapCount;
	bubbleSort(aryBuble, swapCount);
	selectionSort(arySelection, swapCount);

	const bool isSelectionStable = aryBuble == arySelection;//bubbleSortは安定なソートなので、これと比較してselectionSortが安定かどうか判断する

	outputCards(aryBuble);
	cout << "Stable" << endl;//bubbleSortは安定なソート
	outputCards(arySelection);
	cout << (isSelectionStable ? "Stable" : "Not stable") << endl;


	return 0;
}

