// 戻り値 : 転倒数
// stable
template<typename T> size_t bubbleSort(vector<T>& A) {
	int N = (int)A.size();
	size_t cnt = 0;
	for (int i = 0; i < N - 1; i++) {
		for (int j = N - 1; j > i; j--) {
			if (A[j] < A[j - 1]) {
				swap(A[j - 1], A[j]);
				cnt++;
			}
		}
	}
	return cnt;
}

template<typename T> size_t selectionSort(vector<T>& A) {
	int N = (int)A.size();
	size_t cnt = 0;
	for (int i = 0; i < N; i++) {
		int minj = i;
		for (int j = i; j < N; j++)
			if (A[j] < A[minj])
				minj = j;
		if (i != minj) {
			cnt++;
			swap(A[i], A[minj]);
		}
	}
	return cnt;
}

vector<string> getOrder(const vector<SCard>& cards) {
	vector<string> order(10);
	for (int i = 0; i < cards.size(); i++)
		order[cards[i].val].push_back(cards[i].suit);
	return order;
}

void solve(vector<SCard> cards, function<size_t(vector<SCard>&)> sortFunc) {
	auto order = getOrder(cards);
	sortFunc(cards);
	auto order_sorted = getOrder(cards);
	printVec(cards);
	cout << (order == order_sorted ? "Stable" : "Not stable") << endl;
}

