#define MAX_SIZE (40)

typedef struct
{
  int index;
  char suit;
  int num;
} Data;

void Reset(Data(*D)[MAX_SIZE], const char (*A)[3], int N)
{
  for (int i = 0; i < N; ++i)
  {
    ((*D)[i + 1]).index = i;
    ((*D)[i + 1]).suit = A[i][0];
    ((*D)[i + 1]).num = std::atoi(&A[i][1]);
  }
}

void BubbleSort(Data (*D)[MAX_SIZE], int N)
{
  for (int i = 1; i < N; ++i)
  {
    for (int j = N; j > i; --j)
    {
      if (((*D)[j - 1]).num > ((*D)[j]).num)
      {
        std::swap((*D)[j - 1], (*D)[j]);
      }
    }
  }
}

void SelectionSort(Data(*D)[MAX_SIZE], int N)
{
  for (int i = 1; i < N; ++i)
  {
    int minj = i;
    for (int j = i + 1; j <= N; ++j)
    {
      if (((*D)[j]).num < ((*D)[minj]).num)
      {
        minj = j;
      }
    }
    std::swap((*D)[i], (*D)[minj]);
  }
}

void Dump(const Data (&D)[MAX_SIZE], const char (*A)[3], int N)
{
  bool isStable = true;
  for (int i = 1; i <= N; ++i)
  {
    if (i > 1) std::cout << " ";
    std::cout << A[D[i].index];
    if (D[i - 1].num == D[i].num && D[i - 1].index > D[i].index)
    {
      isStable = false;
    }
  }
  std::cout << std::endl;

  if (isStable)
  {
    std::cout << "Stable";
  }
  else
  {
    std::cout << "Not stable";
  }
  std::cout << std::endl;
}

