  for (int i = 0; i < N; ++i)
  {
    std::cin >> A[i];
  }

  Reset(&D, A, N);
  BubbleSort(&D, N);
  Dump(D, A, N);

  Reset(&D, A, N);
  SelectionSort(&D, N);
  Dump(D, A, N);

  return 0;
}

