void dump(int N, valarray<int> vals, valarray<char> suits) {
  for (int i = 0; i < N; i++) {
    if (i > 0) {
      cout << " ";
    }
    cout << suits[i] << vals[i];
  }
  cout << endl;
}

void bubble(int N, valarray<int> vals, valarray<char> suits) {
  for (int i = 0; i < N; i++) {
    for (int j = N-1; j > i; j--) {
      if (vals[j] < vals[j-1]) {
        swap(vals[j], vals[j-1]);
        swap(suits[j], suits[j-1]);
      }
    }
  }
  dump(N, vals, suits);
  cout << "Stable" << endl;
}

void selection(int N, valarray<int> vals, valarray<char> suits) {
  bool stable = true;
  for (int i = 0; i < N; i++) {
    int mini = i;
    for (int j = i; j < N; j++) {
      if (vals[j] < vals[mini]) {
        mini = j;
      }
    }
    if (i != mini) {
      swap(vals[i], vals[mini]);
      if (suits[i] == suits[mini]) {
        stable = false;
      }
      swap(suits[i], suits[mini]);
    }
  }
  dump(N, vals, suits);
  if (stable) {
    cout << "Stable" << endl;
  } else {
    cout << "Not stable" << endl;
  }
}

