using namespace std;

int* BubbleSort(int num, int *val) {
  int *id;
  id = new int[num];

  for (int i = 0; i < num; i++) {
    id[i] = i;
  }

  for (int i = 0; i < num; i++) {
    for (int j = num - 1; j >= i + 1; j--) {
      if (val[id[j]] < val[id[j - 1]]) {
        int tmp;
        tmp = id[j];
        id[j] = id[j - 1];
        id[j - 1] = tmp;
      }
    }
  }

  return id;
}

int* SelectionSort(int num, int *val) {
  int *id;
  id = new int[num];

  for (int i = 0; i < num; i++) {
    id[i] = i;
  }

  for (int i = 0; i < num; i++) {
    int mini = i;
    for (int j = i; j < num; j++) {
      if (val[id[j]] < val[id[mini]]) {
        mini = j;
      }
    }
    if (mini != i) {
      int tmp;
      tmp = id[i];
      id[i] = id[mini];
      id[mini] = tmp;
    }
  }

  return id;
}

