  for (int i = 0; i < n; ++i) {
    for (int j = n - 1; i < j; --j) {
      if (c[j].value < c[j - 1].value) {
        tmp = c[j];
        c[j] = c[j - 1];
        c[j - 1] = tmp;
      }
    }
  }
}

void SelectionSort(Card c[], int n) {
  Card tmp;
  int j;
  for (int i = 1; i < n; ++i) {
    tmp = c[i];
    for (j = i - 1; 0 <= j; --j) {
      if (c[j].value < tmp.value) break;
      c[j + 1] = c[j];
    }
    c[j + 1] = tmp;
  }
}
