void swap(int &a, int &b){
	int temp;
	temp = a;
	a = b;
	b = temp;
}

void swap2(string& a, string& b)
{
	string temp;
	temp = a;
	a = b;
	b = temp;
}

void select_sort(int n, string*array, int*num){
	int min;
	for(int i=0;i<n;i++)
	{
		min = i;
		for(int j=i;j<n;j++)
		{
			if(num[j]<num[min])
			{
				min = j;
			}			
		}
		if(num[i] != num[min])
		{
			swap(num[i], num[min]);
			swap2(array[i], array[min]);
		}
	}	
}


