	for(int i = n-1; i>=0; i--)
	{
		for(int j = 0; j<=i-1; j++)
		{
			if(num1[j]>num1[j+1]) 
			{
				swap(num1[j], num1[j+1]);
				swap2(array1[j], array1[j+1]);
			}
		}
	}
}

void Ifstable(int n, string&pre, int*num, string*array)
{
	int flag = 0; 
	for(int i = 0; i<n; i++){
		for(int j = i+1; j<n; j++){
			if(num[i] == num[j]){
				pre.push_back(array[i][0]);
				pre.push_back(array[j][0]);
				flag = 1;
				break;
			}
		}
		if(flag == 1) break;
	}
	cout<<endl<<pre<<endl;
}

