void BubbleSort(int n, string *CB) {
    for (int i=0; i<n; i++) {
        for (int j = n-1; j >= i+1; j--) {
            if ( CB[j][1] < CB[j-1][1] ) {
                swap( CB[j], CB[j-1] );
            }
        }
    }
}

void SelectiveSort(int n, string *CS) {
    for (int i=0; i<n; i++) {
        int minj = i;
        for (int j=i; j <= n-1; j++) {
            if ( CS[j][1] < CS[minj][1] ) {
                minj = j;
            }
        }
        swap( CS[i], CS[minj] );
    }
}

bool isStable(string *In, string *Out, int n) {
    for (int i=0; i<n; i++) {
        for (int j = i+1; j<n; j++) {
            for (int a=0; a<n; a++) {
                for (int b = a+1; b < n-1; b++) {
                    if ( In[i][1] == In[j][1] && In[i] == Out[b] && In[j] == Out[a] ) {
                        return false;
                    }
                }
            }
        }
    }
    return true;
}

