      if (c.at(j).val < c.at(j-1).val)
        swap(c.at(j), c.at(j-1));
    }
  }
  return c;
}

V<Card> SelectionSort(V<Card> c) {
  REP(i, c.size()) {
    ll mini = i;
    rep(j, i, c.size()) {
      if (c.at(j).val < c.at(mini).val) mini = j;
    }
    swap(c.at(i), c.at(mini));
  }
  return c;
}

