#include <vector>
using namespace std;

void swap(int &a, int &b){
	int dum = a;
	a = b;
	b = dum;
	return;
}

void swap(char &a, char &b){
	char dum = a;
	a = b;
	b = dum;
	return;
}

int main(){
	int n, minj;
	cin >> n;
	vector<int> a(n), b(n);
	vector<char> s(n), t(n);
	for (int i = 0; i != n; i++){
		cin >> s[i] >> a[i];
		t[i] = s[i];
		b[i] = a[i];
	}

	int unsorted, flag, isstable;

	unsorted = 0;
	flag = 1;
	while (flag){
		flag = 0;
		for (int j = n - 1; j != unsorted; j--){
			if (a[j - 1] > a[j]){
				swap(a[j - 1], a[j]);
				swap(s[j - 1], s[j]);
				flag = 1;
			}
		}
		unsorted++;
	}

	for (int i = 0; i != n; i++) cout << (i == 0 ? "" : " ") << s[i] << a[i];

	cout << endl << "Stable" << endl;

	for (int i = 0; i != n; i++){
		minj = i;
		for (int j = i; j != n; j++){
			if (b[j] < b[minj]){
				minj = j;
			}
		}
		if (minj != i){
			swap(b[i], b[minj]);
			swap(t[i], t[minj]);
		}
	}

	for (int i = 0; i != n; i++) cout << (i == 0 ? "" : " ") << t[i] << b[i];

	isstable = 0;
	for (int i = 0; i != n; i++) if (s[i] != t[i]) isstable = 1;

	cout << endl << (isstable == 0 ? "Stable" : "Not Stable") << endl;

}

