        a[i]=s[i][1]-'0';
        if(s[i][0]=='H')
            c[i]=H;
        else if(s[i][0]=='S')
            c[i]=S;
        else if(s[i][0]=='C')
            c[i]=C;
        else
            c[i]=D;
        d[i]=c[i];
        b[i]=a[i];
    }
    for(int i=0;i<n;i++){
        int m=i;
        for(int j=i;j<n;j++){
            if(a[j]<a[m])
                m=j;
        }
        swap(a[i],a[m]);
        swap(c[i],c[m]);
        swap(s[i],s[m]);
    }
    for(int i=0;i<n;i++){
        for(int j=n-1;j>i;j--){
            if(b[j]<b[j-1]){
                swap(b[j],b[j-1]);
                swap(d[j],d[j-1]);
                swap(v[j],v[j-1]);
            }
        }
    }
    for(int i=0;i<n-1;i++)
        cout<<s[i]<<" ";
    cout<<s[n-1]<<endl<<"Stable"<<endl;
    bool ans=0;
    for(int i=0;i<n-1;i++){
        cout<<v[i]<<" ";
        if(c[i]!=d[i])
            ans=1;
    }
    cout<<v[n-1]<<endl;
    if(ans)
        cout<<"Not stable";
    else
        cout<<"Stable";
    return 0;
}

