        for(int j = i; j < n; j++){
            if(a[j].value < a[minj].value){
                minj = j;
            }
        }
        tmp = a[i];
        a[i] = a[minj];
        a[minj] = tmp;

    }
    return a;
}

std::vector<trump> bubbleSort(std::vector<trump> a, int n){
    bool flag = true;
    trump tmp;

    while(flag){
        flag = false;
        for(int j = n-1; j > 0; --j){
            if(a[j].value < a[j-1].value){
                tmp = a[j-1];
                a[j-1] = a[j];
                a[j] = tmp;
                flag = true;
            }
        }
    }
    return a;
}

