                    }
                    for(int l = k + 1; l < n; l++){
                       if(a[j].value == c[l].value){
                            if(a[j].mark == c[l].mark){
                                flag = true;
                            }else{
                                std::cout << "Not stable" << std::endl;
                                return -1;
                            }
                       }else if(l = n - 1){
