bool bubbleSort(char R[36][3], int N)
{
	bool isStable = true;

	for (int i = 0; i < (N - 1); i++)
	{
		for (int j = N - 1; j > i; j--)
		{
			if (R[j - 1][1] > R[j][1])
			{
				char temp[3];
				memcpy(temp, R[j], sizeof(temp));
				memcpy(R[j], R[j - 1], sizeof(R[0]));
				memcpy(R[j - 1], temp, sizeof(R[0]));
			}
		}
	}
	return isStable;
}

bool selectionSort(char R[36][3], int N)
{
	bool isStable = true;

	for (int i = 0; i < N - 1; i++)
	{
		int minPos = i;
		for (int j = i + 1; j < N; j++)
		{
			if (R[minPos][1] > R[j][1])
			{
				minPos = j;
			}
		}
		if (i != minPos) {
			swap(R[i], R[minPos]);
		}
	}
	return isStable;
}

void traceData(char R[36][3], int N, bool isStable)
{
	for (int i = 0; i < N - 1; i++)
	{
		cout << R[i] << " ";
	}
	cout << R[N - 1] << endl;
	if (isStable)
	{
		cout << "Stable" << endl;
	}
	else
	{
		cout << "Not stable" << endl;
	}
}

