using namespace std;

vector<string> bubblesort(vector<string> seq)
{
  for (int i = 1; i < seq.size(); ++i)
    for (int j = i; 0 < j; --j)
      if (seq[j][1] < seq[j-1][1])
        swap(seq[j-1], seq[j]);
  return seq;
}

vector<string> selectionsort(vector<string> seq)
{
  for (int i = 0; i < seq.size(); ++i)
  {
    int mini = i;
    for (int j = i; j < seq.size(); ++j) {
      if (seq[j][1] < seq[mini][1])
        mini = j;
    }
    swap(seq[mini], seq[i]);
  }
  return seq;
}


int main()
{
