void bubble_sort(Card cards[], const int n) {
  bool sorted;

  while(!sorted) {
    sorted = true;
    for (int i = n - 1; i > 0; i--) {
      if (cards[i].value < cards[i - 1].value) {
        Card tmp = cards[i];
        cards[i] = cards[i - 1];
        cards[i - 1] = tmp;
        sorted = false;
      }
    }
  }
}

