};
bool operator ==(Card c1, Card c2) {
	if ((c1.c == c2.c) && (c1.v = c2.v))
		return true;
	else
		return false;
}
bool operator !=(Card c1, Card c2) {
	if ((c1.c != c2.c) || (c1.v != c2.v))
		return true;
	else
		return false;
}
void Copy(Card c1[], Card c2[], int n) {
	for (int i = 0; i < n; i++) {
		c1[i].c= c2[i].c;
		c1[i].v = c2[i].v;
	}
}
void Bubble(Card c[], int n) {
	for (int i = 0; i < n; i++) {
		for (int j = n - 1; j > i; j--) {
			if (c[j].v < c[j - 1].v)
				swap(c[j], c[j - 1]);
		}
	}
}
void Selection(Card c[], int n) {
	for (int i = 0; i < n; i++) {
		int minv = i,flag=0;
		for (int j = i; j < n; j++) {
			if (c[minv].v > c[j].v) {
				minv = j;
				flag = 1;
			}
		}
		if (flag)
			swap(c[i], c[minv]);
	}
}
