	for (int i = 0; i < n; i++) {
		cout << c[i].c << c[i].v;
		if (i != n)
			cout << ' ';
	}
	cout << endl;
}
int ISstable(Card in[], Card out[],int n) {
	for (int i = 0; i < n; i++) {
		for (int j = i + 1; j < n; j++) {
			for (int a = 0; a < n; a++) {
				for (int b = a + 1; b < n; b++) {
					if ((in[i].v == in[j].v) && (in[i] == out[b]) && (in[j] == out[a])) {
						cout << "Not stable" << endl;
						return 0;
					}
				}
			}
		}
	}
	cout << "Stable" << endl;
	return 0;
}
int ISstable1(Card b[], Card s[], int n) {
	for (int i = 0; i < n; i++) {
		if (b[i] != s[i]) {
			cout << "Not stable" << endl;
			return 0;
		}
	}
	cout << "Stable" << endl;
	return 0;
}
