	for(int i = n-1; i>=0; i--)
	{
		for(int j = 0; j<=i-1; j++)
		{
			if(num1[j]>num1[j+1]) 
			{
				swap(num1[j], num1[j+1]);
				swap2(array1[j], array1[j+1]);
			}
		}
	}
}

