vs bubblesort(vs c, int n) {
    for (int i = 0; i < n; ++i) {
        for (int j = n-1; j >= i+1; --j) {
            if (c[j][1] - '0' < c[j-1][1] - '0') swap(c[j], c[j-1]);
        }
    }
    return c;
}

vs selectionsort(vs c, int n) {
    for (int i = 0; i < n; ++i) {
        int minj = i;
        for (int j = i; j < n; ++j) {
            if (c[j][1] - '0' < c[minj][1] - '0') {
                minj = j;
            }
        }
        if (minj != i) swap(c[minj], c[i]);
    }
    return c;
}

