	char Min;

	for(int i=0;i<N;i++){
		Min=A[i].val;
		for(int j=i;j<N;j++){
			if(Min>A[j].val)Min=A[j].val,cnt=j;
		}
		if(cnt)swap0(A[i],A[cnt]),cnt2++;
