void bubble(struct C A[],int N){
  for(int i=0;i<N;i++){
    for(int j=N-1;j>=i+1;j--){
      if(A[j].value < A[j-1].value){
	C t=A[j];
	A[j] = A[j-1];
	A[j-1] = t;
      }
    }
  }
}

void selection(struct C A[],int N){
  for(int i=0;i<N;i++){
    int minj = i;
    for(int j=i;j<N;j++){
      if(A[j].value < A[minj].value)minj = j;
    }
    C t = A[i];
    A[i] = A[minj];
    A[minj] = t;
  }
}

