void selectionSort(Card C[], int n){
    int minj;
    for(int i=0; i<n; i++){
        minj = i;
        for(int j=i; j<n; j++){
            if(C[j].value < C[minj].value){
                minj = j;
            }
        }
        if(i!=minj)
            swap(C[i],C[minj]);
    }
    for(int k=0; k<n; k++){
