	struct card C1[36],C2[36];
	cin >> n;
	// Input n cards
	for (int i = 0; i < n; i++) {
		cin >> C1[i].c >> C1[i].value;
		C2[i].c = C1[i].c;
		C2[i].value = C1[i].value;
	}

	// Do bubble sort
	bubbleSort(C1, n);

	// Print cards
	print(C1, n);
	// Print "Stable"
	cout << "Stable" << endl;

	// Do selection sort
	selectionSort(C2, n);
	//Print result
	print(C2, n);

	// Cheack if selection sort is stable
	if (isStable(C1, C2, n))
		cout << "Stable" << endl;
	else
		cout << "Not stable" << endl;
	return 0;
}

