{
  cout << join_vector(data) << endl;
}

int card_num(string a)
{
  return stoi(a.substr(1, a.size()));
}

vector<string> bubble_sort(vector<string> vec, int n)
{
  auto a = vector<string>(vec);
  for (auto i = n - 1; i >= 0; i--)
  {
    for (auto j = n - 1; j >= 0; j--)
    {
      if (j - 1 >= 0)
      {
        auto should_swap = card_num(a[j - 1]) > card_num(a[j]);
        if (should_swap)
          swap(a[j - 1], a[j]);
      }
    }
  }

  return a;
}

vector<string> selection_sort(vector<string> vec, int n)
{
  auto a = vector<string>(vec);
  for (auto i = 0; i < n; i++)
  {
    auto minj = i;
    for (auto j = i; j < n; j++)
    {
      if (card_num(a[minj]) > card_num(a[j]))
      {
        minj = j;
      }
    }

    swap(a[minj], a[i]);
  }

  return a;
}

