};

void bblsort( cards c[], int N )
{
	for( int i = 0; i < N; i++ ) {
		for( int j = N -1; j > i; j-- ) {
			if( c[ j ].val < c[ j - 1 ].val ) {
				swap( c[ j ], c[ j - 1 ] );
			}
		}
	}
	return;
}

void selsort( cards c[], int N )
{
	for( int i = 0; i < N; i++ ) {
		int minj = i;
		for( int j = i; j < N; j++ ) {
			if( c[ j ].val < c[ minj ].val ) {
				minj = j;
			}
		}
		swap( c[ i ], c[ minj ] );
	}
	return;
}

void dump( cards c[], int N )
{
	for( int i = 0; i < N; i++ ) {
		cout << c[ i ].suit << c[ i ].val;
		if( i == N - 1 ) {
			cout << endl;
		}
		else {
			cout << " ";
		}
	}
	return;
}

void copy( cards c[], cards d[], int N )
{
	for( int i = 0; i < N; i++ ) {
		d[ i ] = c[ i ];
	}
}

void mkstable( vector<cards> &v, cards c[], int N )
{
	for( int i = 1; i < 10; i++ ) {
		for( int j = 0; j < N; j++ ) {
			if( i == c[ j ].val ) {
				v.push_back( c[ j ] );
			}
		}
	}

	if( false ) {
		cout << "*";
		for( int i = 0; i < N; i++ ) {
			cout << v[ i ].suit << v[ i ].val << " ";
		}
		cout << endl;
		return;
	}
}

void chkstable( cards c[], cards d[], int N )
{
	vector<cards> sc;
	vector<cards> sd;

	mkstable( sc, c, N );
	mkstable( sd, d, N );

	bool isstable = true;
	for( int i = 0; i < N; i++ ) {
		if( sc[ i ].suit != sd[ i ].suit and sc[ i ].val == sd[ i ].val ) {
			isstable = false;
		}
	}

	if( isstable == true ) {
		cout << "Stable" << endl;
	}
	else {
		cout << "Not stable" << endl;
	}

	return;
}

