int main() {
  uint32_t N = 0;
  std::cin >> N;
  std::vector<std::string> B(N), S(N);
  for (auto &&elem : B) std::cin >> elem;
  std::copy(B.begin(), B.end(), S.begin());

  // Bubble Sort
  for (size_t i = 0; i < N - 1; i++) {
    bool flag = true;
    for (size_t j = 0; j < N - 1 - i; j++) {
      uint32_t v = B[N - 1 - j][1] - '0', w = B[N - 2 - j][1] - '0';
      if (v < w) {
        auto temp = B[N - 1 - j];
        B[N - 1 - j] = B[N - 2 - j];
        B[N - 2 - j] = temp;
        flag = false;
      }
    }
    if (flag) break;
  }

  // Selection Sort
  for (size_t i = 0; i < N - 1; i++) {
    uint32_t min_index = i;
    for (size_t j = i + 1; j < N; j++) {
      uint32_t v = S[min_index][1] - '0', w = S[j][1] - '0';
      if (v > w) min_index = j;
    }
    if (min_index != i) {
      auto temp = S[i];
      S[i] = S[min_index];
      S[min_index] = temp;
    }
  }

  for (uint32_t i = 0; i < N - 1; i++) std::cout << B[i] << " ";
  std::cout << B[N - 1] << std::endl;
  std::cout << "Stable" << std::endl;

  for (uint32_t i = 0; i < N - 1; i++) std::cout << S[i] << " ";
  std::cout << S[N - 1] << std::endl;
  std::cout << (B == S ? "Stable" : "Not stable") << std::endl;

  return 0;
}

