#define CARDSIZE 2

typedef struct {
    char suit;
    int num;
} card_t;

void SetCard(card_t *card, char data[]){
    card->suit = data[0];
    card->num = atoi(&data[1]);
    return;
}

void Swap(card_t *card1, card_t *card2){
    card_t tmp;
    tmp = *card1;
    *card1 = *card2;
    *card2 = tmp;
    return;
}

void PrintCards(card_t cards[], int length){
    int i;
    for(i = 0; i < length; i++){
        printf("%s", &cards[i].suit);
        printf("%d", cards[i].num);
        if(i == length - 1){
            printf("\n");
        } else {
            printf(" ");
        }
    }
    return;
}

card_t *BubbleSort(card_t *cards, int length){
    int i, j;
    for(i = 0; i < length; i++){
        for(j = length - 1; j > i; j--){
            if(cards[j].num < cards[j-1].num) Swap(&cards[j], &cards[j-1]);
        }
    }
    PrintCards(cards, length);
    return cards;
}

card_t *SelectionSort(card_t *cards, int length){
    int i, j, minj;
    for(i = 0; i < length; i++){
        minj = i;
        for(j = i; j < length; j++){
            if(cards[j].num < cards[minj].num) minj = j;
        }
        Swap(&cards[minj], &cards[i]);
    }
    PrintCards(cards, length);
    return cards;
}

