       swap = b[j];
       b[j] = b[j-1];
       b[j-1] = swap;
      }
    }
  }
}

void selection(struct Card s[], int n)
{
  int min, i, j;
  struct Card swap;

  for(i = 0; i < n; i++){
    min = i;
    for(j = i; j < n; j++){
      if(s[j].value < s[min].value)
        min = j;
    }
    if( i != min){
      swap = s[i];
      s[i] = s[min];
      s[min] = swap;
    }
  }
}

