      if(A[j].value < A[j-1].value){
	tmp=A[j];
	A[j]=A[j-1];
	A[j-1]=tmp;
      }
    }
  }
}

void Selection(struct Card A[], int num){
  int i,j,min;
  struct Card tmp;
  for(i=0;i<num;i++){
