                    {
                      for(f=j+1;f<n;f++)
                        {
                          if(A[i][1]==card[f][1])
                            {
                              if(A[i][0]==card[f][0])
                                {
                                  c=j+1;
                                  j=n;
                                  break;
                                }
                              else
                                {
                                  i=n;
                                  j=n;
                                  break;
                                }
                            }
