char chg(int type, char kind)
{
	if (type == 0) {
		switch(kind) {
		case 'S':
			return S_;
		case 'H':
			return H_;
		case 'C':
			return C_;
		default:
			return D_;
		}
	}
	else {
		switch(kind) {
		case S_:
			return 'S';
		case H_:
			return 'H';
		case C_:
			return 'C';
		default:
			return 'D';
		}
	}
}


