void bable_sort(CARD_T *cd_p,int n)
{
	int i;
	int j,flg;
	int wk;
	int wk_kind;


	for (flg=1,j=0 ; flg!=0 ; j++) {
		flg = 0;
		for(i=0 ; i<n-1 ; i++) {
			if (cd_p[i].data>cd_p[i+1].data) {
				flg++;
				wk = cd_p[i+1].data;
				wk_kind=cd_p[i+1].kind;
				cd_p[i+1].data = cd_p[i].data;
				cd_p[i+1].kind = cd_p[i].kind;
				cd_p[i].data   = wk;
				cd_p[i].kind   = wk_kind;
			}
		}
	}
}

void selec_sort(CARD_T *cd_p,int n)
{
	int minj;
	int chg_cnt;
	int i;
	int j;
	int wk;
	int wk_kind;
	int flg;

	for (chg_cnt=0,i=0 ; i<n ; i++) {
		minj=i;
		for (flg=0,j=i+1 ; j<n ; j++) {
			if (cd_p[j].data < cd_p[minj].data) {
				minj = j;
				flg++;
			}
		}
		if (flg != 0) {
			chg_cnt++;
			wk = cd_p[minj].data;
			wk_kind=cd_p[minj].kind;
			cd_p[minj].data = cd_p[i].data;
			cd_p[minj].kind = cd_p[i].kind;
			cd_p[i].data=wk;
			cd_p[i].kind=wk_kind;
		}
	}
}
