Card* bubbleSort(Card* c, int n){
	Card tmp;
	int last = n-1;
	for(int i = 0; i < n; i++){
		for(int j = last; j > 0; j--){
			if(c[j-1].value > c[j].value){
				tmp = c[j-1];
				c[j-1] = c[j];
				c[j] = tmp;
			}
		}
	}
	return c;
}
Card* selectionSort(Card* c, int n){
	Card tmp;
	int last = n-1, min_ind;
	for(int i = 0; i < last; i++){
		min_ind = i;
		for(int j = i+1; j < n; j++){
			if(c[min_ind].value > c[j].value){
				min_ind = j;
			}
		}
		if(min_ind != i){
			tmp = c[i];
			c[i] = c[min_ind];
			c[min_ind] = tmp;
		}
	}
	return c;
}

