void Babble_Sort(int n, Card *b_array){
        int i, j;
        Card buffer;

        for(j = 0 ; j < n ; j++){
                for(i = n - 1 ; i > j ; i--){
                        if(b_array[i].num < b_array[i - 1].num){
                                buffer = b_array[i];
                                b_array[i] = b_array[i - 1];
                                b_array[i - 1] = buffer;
                        }
                }
        }
}

void Selection_Sort(int n, Card *s_array){
        int i, j, minj; 
        Card buffer;

        for(i = 0 ; i < n ; i++){
                minj = i;
                for(j = i ; j < n ; j++){
                        if(s_array[j].num < s_array[minj].num){
                                minj = j;
                        }
                }
                if(minj != i){
                        buffer = s_array[minj];
                        s_array[minj] = s_array[i];
                        s_array[i] = buffer;
                }
        }
}

