                        if(c_array[i].num  == c_array[i + 2].num ){
                                if(c_array[i].num  == c_array[i + 3].num ){
                                        num_of_same = 4;
                                }else{
                                        num_of_same = 3;
                                }
                        }else{
                                num_of_same = 2;
                        }

                        for(j = 0 ; j < n ; j++){
                                if(array[j].num == c_array[i].num){
                                        mark_order[k] = array[j].mark;
                                        k++;
                                }
                        }

                        for(j = 0 ; j < num_of_same ; j++){
                                if(c_array[i + j].mark == mark_order[j])continue;
                                else return 1;
                        }

                        i += num_of_same - 1;
                }else{
                        continue;
                }

        }

        return 0;
}

