		mini=i;
		for(j=i+1;j<num;j++){
			if(A[j].key<A[mini].key){mini=j;}
			if(A[j].key==A[i].key&&count[A[j].key]!=-1){
				idx=A[j].key;
				if(count[idx]==0){seq[idx][0]=A[i].suits;count[idx]++;}
				seq[idx][count[idx]]=A[j].suits;count[idx]++;
			}
		}
