	for(i = 0; i < n; i++)
	{
		min = i;
		for(j = i; j < n; j++)
		{
			if(c[j].value < c[min].value)
			{
				min = j;
			}
		}
		temp = c[i];
		c[i] = c[min];
		c[min] = temp;
	}
}

