void swap(card *a, card *b)
{
    card temp = *a;
    *a = *b;
    *b = temp;
}

void bubble_sort(card a[], int length)
{
    //int swap_num = 0;
    for(int i=0; i<length; i++){
        //for(int j=0; j<length-i; j++){
        for(int j=length-1; j>=i+1; j--){
