                swap(&a[j],&a[j-1]);
                swap_num++;
            }
        }
    }
    //return swap_num;
}

void selection_sort(card a[], int length)
{
    //int swap_num = 0;
    for(int i=0; i<length; i++){
        int min_i = i;
        int swap_flag = 0;
        for(int j=i; j<length; j++){
            if(a[j].value < a[min_i].value){
                min_i = j;
                swap_flag = 1;
            }
        }
        swap(&a[i], &a[min_i]);
        if(swap_flag == 1) swap_num++;
    }
    //return swap_num;
}

