}

void swap(CARD *c, int x, int y)
{
  int inttmp;
  char chartmp;

  inttmp = c[x].value;
  c[x].value = c[y].value;
  c[y].value = inttmp;

  chartmp = c[x].suit;
  c[x].suit = c[y].suit;
  c[y].suit = chartmp;

  inttmp = c[x].order;
  c[x].order = c[y].order;
  c[y].order = inttmp;
}

