        if (i>0) {
            printf(" ");
        }
        printf("%c%c",Array2[i].design,Array2[i].value);
    }
    printf("\n");
    if (CompareData(Array1,Array2,index)) {
        printf("Stable\n");
    } else {
        printf("Not stable\n");
    }
}
