	int	i;
};
typedef struct card CARD;


int swap( CARD *c1, CARD *c2 ){

	CARD t;

	t.s = c1->s;
	t.v = c1->v;
	t.i = c1->i;

	c1->s = c2->s;
	c1->v = c2->v;
	c1->i = c2->i;

	c2->s = t.s;
	c2->v = t.v;
	c2->i = t.i;

	return 0;
}

