		flag=0;
		for(int i=n-1;i>0;i--){
			if(a[i]<a[i-1]){
				x=a[i];
				y=b[i];
				a[i]=a[i-1];
				b[i]=b[i-1];
				a[i-1]=x;
				b[i-1]=y;
				flag=1;
			}
		}
	}
	//出力
	for(int i=0;i<n;i++){
			printf("%c%d",b[i],a[i]);
			if(i!=n-1){
