}

void ssort(int* a,char* b,int n){

	int minj,x,flag=0;
	char y;

	for(int i=0;i<n;i++){
		minj=i;
		for(int j=i;j<n;j++){
			if(a[j]<a[minj]){
				minj=j;
				flag=1;
			}
		}
		x=a[i];
		y=b[i];
		a[i]=a[minj];
		b[i]=b[minj];
		a[minj]=x;
		b[minj]=y;
		flag=0;
	}
	for(int i=0;i<n;i++){
		printf("%c%d",b[i],a[i]);
		if(i!=n-1) printf(" ");
	}
	printf("\n");
}

