    for(i = 0; i < n; i++){
        scanf("%s", card);
        SetCard(&cards_bub[i], card);
    }
    memcpy(cards_sel, cards_bub, sizeof(card_t) * n);

    cards_bub = BubbleSort(cards_bub, n);
    printf("Stable\n");
    cards_sel = SelectionSort(cards_sel, n);
    if(memcmp(cards_bub, cards_sel, sizeof(card_t) * n) == 0){
        printf("Stable\n");
    } else {
        printf("Not stable\n");
    }

    free(cards_bub);
    free(cards_sel);
    return 0;
}

