    CS[i] = CB[i];
  }


  //Bubble
  for(i = 0; i < n; i++){
    for(j = n - 1; j > i; j--){//
      if(CB[j].a < CB[j - 1].a){
	TMP = CB[j];
	CB[j] = CB[j - 1];
	CB[j - 1] = TMP;
      }

    }

    }

  //Sellect
  for(i = 0; i < n; i++){
    minv = i;

    for(j = i; j < n; j++){
      if(CS[j].a < CS[minv].a){
	minv = j;
      }

    }

    TMP = CS[i];
    CS[i] = CS[minv];
    CS[minv] = TMP;
    }

  for(i = 0; i < n; i++){
    printf("%c%d", CB[i].c, CB[i].a);
    if(i < n - 1) printf(" ");
  }

  if(decision(n, &CB[0]) == 0) printf("\nStable\n");
