  for(i = 0; i < n; i++){
    printf("%c%d",CS[i].c, CS[i].a);
    if(i < n - 1) printf(" ");
  }

  if(decision(n, &CS[0]) == 0) printf("\nStable\n");
  else printf("\nNot Stable\n");

  return 0;
}

int decision(int n, Card *C){

  int i, j;
  Card TMP;

  for(i = 0; i < n - 1; i++){
    TMP = C[i];

    if(TMP.a == C[i + 1].a){
      if(TMP.c > C[i + 1].c) return 1;
    }

  }

  return 0;
}

