#include<stdio.h>
#define STABLE 1
#define NOT_STABLE 0
int BubbleSort( char Suit[], char Number[], int Order[], int n ){

  int i,j,k;
  char c;

  for ( i = 0 ; i < n ; i++ ){
    for ( j = n - 1 ; j > i ; j-- ){
      if ( Number[j] < Number[ j - 1 ] ) {
	c = Suit[j];
	Suit[j] = Suit[ j - 1 ];
	Suit[ j - 1 ] = c;
	c = Number[j];
	Number[j] = Number[ j - 1 ];
	Number[ j - 1 ] = c;
	k = Order[j];
	Order[j] = Order[ j - 1 ];
	Order[ j - 1 ] = k;
      }
    }
  }

  return 0;

}
int SelectionSort( char Suit[], char Number[], int Order[], int n ){

  int i,j,k,minj;
  char c;

  for ( i = 0 ; i < n ; i++ ){
    minj = i;
    for( j = i ; j < n ; j++ ){
      if ( Number[j] < Number[minj] ){
	minj = j;
      }
    }
    c = Suit[i];
    Suit[i] = Suit[minj];
    Suit[minj] = c;
    c = Number[i];
    Number[i] = Number[minj];
    Number[minj] = c;
    k = Order[i];
    Order[i] = Order[minj];
    Order[minj] = k;
  }

  return 0;

}
int is_stable( char Suit[], char Number[], int Order[], int n ){

  int i;

  for ( i = 0 ; i < n - 1 ; i++ ){
    if ( Number[i] == Number[ i + 1 ] && Order[i] > Order[ i + 1 ] ) {
      return NOT_STABLE;
    }
  }

  return STABLE;

}



