void  BubbleSort(int n, int a[][2]){
    int f = 1, i;

    while(f){
        f = 0;
        for(i = 0; n-1 > i; i++){
            if(a[i][0] > a[i+1][0]){
                int buf = a[i+1][0];
                a[i+1][0] = a[i][0];
                a[i][0] = buf;
                buf = a[i+1][1];
                a[i+1][1] = a[i][1];
                a[i][1] = buf;
                f = 1;
            }
        }
    }
}
