        for(j=0;j<N-i-1;j++){
           if(a[j]>a[j+1]){
               tmp=a[j];
               a[j]=a[j+1];
               a[j+1]=tmp;

               x=s[j];
               s[j]=s[j+1];
               s[j+1]=x;
           } 
        }
    }
}

void selection(int N,char s[],int a[]){
    int i,j,min,tmp;
    char x;

    for(i=0;i<N-1;i++){
        min=i;
        for(j=i;j<N;j++){
            if(a[j]<a[min]){
                min=j;
            }
        }
        tmp=a[i];
        a[i]=a[min];
        a[min]=tmp;

        x=s[i];
        s[i]=s[min];
        s[min]=x;
    }
}

