        mini=i;
        for (j=i;j<n;j++) {
            if (a[j]<a[mini]) {
                mini=j;
            }
        }
        tmp1=a[i];
        a[i]=a[mini];
        a[mini]=tmp1;
        tmp2=a_str[i];
        a_str[i]=a_str[mini];
        a_str[mini]=tmp2;
        // if (i!=mini) count++;
    }
    // return count;
}

void bubble_sort(int *a, int *a_str, int m) {
    int i, j, tmp1, tmp2;

    for (i=0;i<m;i++) {
        for (j=m-1; j>i; j--) {
            if (a[j]<a[j-1]) {
                tmp1=a[j];
                tmp2=a_str[j];
                a[j]=a[j-1];
                a_str[j]=a_str[j-1];
                a[j-1]=tmp1;
                a_str[j-1]=tmp2;
                // n++;
            }
        }
    }

    // return n;
}

