void bubble(Card *A,int n){
  int i,j;
  Card tmp;
  for(i=0;i<n;i++){
    for(j=n-1;j>i;j--){
      if(A[j].value < A[j-1].value){
	tmp = A[j];
	A[j] = A[j-1];
	A[j-1] = tmp;
      }
    }
  }
}

void selection(Card *A,int n){
  int i,j,minj;
  Card tmp;
  for(i=0;i<n;i++){
    minj = i;
    for(j=i;j<n;j++){
      if(A[j].value < A[minj].value) minj = j;
    }
    tmp = A[i];
    A[i] = A[minj];
    A[minj] = tmp;
  }
}

int isStable(Card *c1,Card *c2,int m){
  int i,j,a,b;
  for(i=0;i<m;i++){
    for(j=i+1;j<=m;j++){
      for(a=1;a<m;a++){
	for(b=a+1;b<=m;b++){
	  if(c1[i] == c2[j] && c1[i] == c2[b] && c1[j] == c2[a]) return FALSE;
	}
      }
    }
  }
  return TRUE;
}

