char **copyArray(char **A, int n){
  //Aをこぴーした配列の先頭アドレスを返す
  int i;
  char **res, *tmp;
  tmp = (char *)malloc(n*3*sizeof(char));
  res = (char **)malloc(n*sizeof(char *));
  for(i=0; i<n; i++){
    res[i] = tmp+3*i;
    strcpy(res[i],A[i]);
  }

  return res;
}

char *stableCheck(char** c, char** b, int n){
