    int i=0;
    int res=0;
    for (; i<n; i++) {
        if (!(a[i].suit==b[i].suit && a[i].num==b[i].num)) break;
    }
    if (i==n) res=1;
    return res;
}

void bubble_sort (struct card *a, int n) {
    for (int i=0; i<n; i++) {
        for (int j=n-1; j>i; j--) {
            if (a[j].num<a[j-1].num) {
                swap (a+j, a+j-1);
            }
        }
    }
}

void selection_sort (struct card *a, int n) {
    for (int i=0; i<n; i++) {
        int mini=i;
        for (int j=i; j<n; j++) {
            if (a[j].num<a[mini].num) mini=j;
        }
        if (i!=mini) {
            swap (a+i, a+mini);
        }
    }
}

