void BubbleSort(card *C,int n){
  int i,j;
  card tmp;
  for(i=0;i<n;i++){
    for(j = n-1;j>i;j--){
      if(C[j].value < C[j-1].value){
	tmp = C[j];
	C[j] = C[j-1];
	C[j-1] = tmp;
      }
    }
  }
}

void SelectionSort(card *C,int n){
  int i,j,minj;
  card tmp;
  for(i=0;i<n;i++){
    minj = i;
    for(j=i;j<n;j++){
      if(C[j].value < C[minj].value){
	minj = j;
      }
    }
    tmp = C[i];
    C[i] = C[minj];
    C[minj] = tmp;
  }
}

