        if (i > 0)
            printf(" ");
        printf("%c%d", A[i].suit, A[i].value);
    }
    printf("\n");
}

static void bubbleSort(struct Card A[], int N)
{
    for (int i = 0; i < N; i++) {
        for (int j = N - 1; j >= i + 1; j--) {
            if (A[j].value < A[j - 1].value) {
                struct Card tmp = A[j];
                A[j] = A[j - 1];
                A[j - 1] = tmp;
            }
        }
    }
}

static void selectionSort(struct Card A[], int N)
{
    for (int i = 0; i < N; i++) {
        int minj = i;
        for (int j = i + 1; j < N; j++) {
            if (A[j].value < A[minj].value) {
                minj = j;
            }
        }
        if (i != minj) {
            struct Card tmp = A[i];
            A[i] = A[minj];
            A[minj] = tmp;
        }
    }
}

