void swap(card *C1, card *C2) {
	card tmp = *C1;
	*C1 = *C2;
	*C2 = tmp;
}

void bubbleSort(card C[], int N) {
	int i, j;

	for (i = 0; i < N - 1; i++) {
		for (j = N - 1;j >= i + 1 ; j--) {
			if (C[j - 1].value > C[j].value) {
				swap(&C[j - 1], &C[j]);
			}
		}
	}
	output(C, N);

}

void selectionSort(card C[], int N) {
	int i, j, minj;

	for (i = 0; i < N - 1; i++) {
		minj = i;
		for (j = i; j < N; j++) {
			if (C[j].value < C[minj].value) {
				minj = j;
			}
		}
		swap(&C[i], &C[minj]);
	}
	output(C, N);
}


