int isStable(Card *in, Card *out, int n){
  int i, j, k, l;

  for (i=0; i<n; i++){
    for (j=i+1; j<n; j++){
      for (k=0; k<n; k++){
	for (l=k+1; l<n; l++){
	  if (in[i].value == in[j].value &&
	      in[i].value == out[l].value &&
	      in[j].value == out[k].value &&
	      in[i].mark == out[l].mark &&
	      in[j].mark == out[k].mark)
	    return 0;
	}
      }
    }
  }

  return 1;
}

