}trump;


int isStable(trump B[],trump C[], int m){
  int a,b,i,j;
  for(i = 0; i < m; i++){
    for(j = i+1; j < m; j++){
      for(a = 0; a < m; a++){
	for(b = a+1;b < m; b++){
	  if(B[i].num == B[j].num && B[i].mark == C[b].mark && B[i].mark == C[a].mark)
	    return 0;
	}
      }
    }
  }
  return 1;
}

