#include<stdio.h>

typedef struct card{
	char mark;
	int num;
}card;

void swap(card a[],int x,int y){
	card temp=a[x];
	a[x]=a[y];
	a[y]=temp;
	return;
}

void bubbleSort(card a[],int n){
	int i,j;

	for(i=n-1;i>=0;i--){
		for(j=0;j<i;j++){
			if(a[j].num > a[j+1].num){
				swap(a,j,j+1);
			}
		}
	}

	return;
}

void selectionSort(card a[],int n){
	int i,j;
	int min;
	int idx;

	for(i=0;i<n;i++){
		min=1000;
		for(j=i+1;j<n;j++){
			if(min > a[j].num){
				idx=j;
				min=a[j].num;
			}
		}
		if(a[i].num > min){
			swap(a,i,idx);
		}
	}

	return;
}

int is_stable(card a[],card b[],int n){
	for(int i=0;i<n;i++){
		if(a[i].mark!=b[i].mark)return 0;
	}
	return 1;
}

