void BubbleSort(char list[],int Num){
  if(Num<=4) return;
  int i,j;
  for(i=1;i<2*Num;i+=2){
    for(j=2*Num-1;j>i;j-=2){

      if(list[j]<list[j-2]){
        swap(&list[j],&list[j-2]);
        swap(&list[j-1],&list[j-3]);
      }

    }
  }
}

void SelectionSort(char *list,int Num){
  int i,j,key;
  for(i=0;i<2*Num;i+=2){
    key=i+1;
    for(j=2*Num-1;j>i;j-=2){
      if(list[j]<list[key])key=j;
    }
    swap(&list[key],&list[i+1]);
    swap(&list[key-1],&list[i]);
  }
}

