void BubSort(int *x, char **y, int n){

  int i,j;
  int tmpInt;
  char *tmpChar;

  for(i=0; i<n-1; i++){
    for(j=n-1; j>i; j--){
      if(x[j-1] > x[j]){
	tmpInt = x[j];
	x[j] = x[j-1];
	x[j-1] = tmpInt;

	tmpChar = y[j];
	y[j] = y[j-1];
	y[j-1] = tmpChar;
      }
    }
  }
}

void SelSort(int *x, char **y, int n) {

  int i,j;
  int min;
  int tmpInt;
  char *tmpChar;

  for(i=0; i<n-1; i++){
    min = i;           //小さい値の保持

    for(j=i+1; j<n; j++){
      if(x[j] < x[min]){ 
	min = j;     //小さい値の更新
      }
    }
    /*sort*/
    if(x[i] > x[min]){
      tmpInt = x[i];
      x[i] = x[min];
      x[min] = tmpInt;

      tmpChar = y[i];
      y[i] = y[min];
      y[min] = tmpChar;
    }
  }
}


