int decision(int n, Card *CC){

  int i, j;
  Card TMP;

  for(i = 0; i < n - 1; i++){
    TMP = CC[i];

    if(TMP.a == CC[i + 1].a){

      for(j = 0; j < n; j++){

	if(C[j].c == TMP.c && C[j].a == TMP.a) break;
	if(C[j].c == CC[i + 1].c && C[j].a == CC[i + 1].a) return 1;

      }

    }

  }

  return 0;
}

