        for (j=i;j<n;j++) {
            if (a[j]<a[mini]) {
                mini=j;
            }
        }
        tmp1=a[i];
        a[i]=a[mini];
        a[mini]=tmp1;
        tmp2=a_str[i];
        a_str[i]=a_str[mini];
        a_str[mini]=tmp2;
        // if (i!=mini) count++;
    }
    // return count;
}

