    int i, j, tmp1, tmp2;

    for (i=0;i<m;i++) {
        for (j=m-1; j>i; j--) {
            if (a[j]<a[j-1]) {
                tmp1=a[j];
                tmp2=a_str[j];
                a[j]=a[j-1];
                a_str[j]=a_str[j-1];
                a[j-1]=tmp1;
                a_str[j-1]=tmp2;
