void BubbleSort(char card[N][3], int n) {
	int i, j;
	char tmp[3];
	for (i = 0; i < n; i++) {
		for (j = n - 1; j >= i + 1; j--) {
			if (card[j][1] < card[j - 1][1]) {
				strcpy(tmp, card[j]);
				strcpy(card[j], card[j - 1]);
				strcpy(card[j - 1], tmp);
			}
		}
	}
}

void SelectionSort(char card[N][3], int n) {
	int i, j, minj;
	char tmp[3];
	for (i = 0; i < n; i++) {
		minj = i;
		for (j = i; j < n; j++) {
			if (card[j][1] < card[minj][1]) {
				minj = j;
			}
		}
		strcpy(tmp, card[i]);
		strcpy(card[i], card[minj]);
		strcpy(card[minj], tmp);
	}
}

