        minj = i;
        for(j=i;j<n;j++){
            if(res[j].value<res[minj].value) minj = j;
        }
        swap(&res[i], &res[minj]);
    }
    return res;
}

Card* bubblesort(int n, Card *r){
    int flag = 1;
    int i;
    Card *res;
    res = (Card *)malloc(N * sizeof(Card));
    for(i=0;i<n;i++) res[i] = r[i];

    while(flag){
        flag = 0;
        for(i=n-1;i>0;i--){
            if(res[i].value<res[i-1].value){
                swap(&res[i], &res[i-1]);
                flag = 1;
            }
        }
    }
    return res;
}

