#define swap(x, y) {char t = x[0]; x[0] = y[0]; y[0] = t; t = x[1]; x[1] = y[1]; y[1] = t;}

void
bubblesort(char c[MAX_N][2], int n)
{
	int i, j;

	bool b = true;
	for (i = 0; b; ++i)
	{
		b = false;
		for (j = n - 1; j >= i + 1; --j)
		{
			if (c[j - 1][1] > c[j][1])
			{
				swap(c[j - 1], c[j]);
				b = true;
			}
		}
	}
}

void
selectionsort(char c[MAX_N][2], int n)
{
	int i, j;

	for (i = 0; i < n; ++i)
	{
		int minj = i;
		for (j = i; j < n; ++j)
		{
			if (c[j][1] < c[minj][1])
				minj = j;
		}

		if (i != minj)
			swap(c[i], c[minj]);
	}
}

