void BubbleSort(struct Node *C, int n){
  int i, j;
  struct Node buf;

  for(i = 0; i < n; i++){
    for(j = n - 1; j > i; j--){
      if(C[j].value < C[j - 1].value){
	buf = C[j];
	C[j] = C[j - 1];
	C[j - 1] = buf;
      }
    }
  }
}

void SelectionSort(struct Node *C, int n){
  int i,j,minj;
  struct Node buf;

  for(i = 0; i < n; i++){
    minj = i;
    for(j = i; j < n; j++){
      if(C[j].value < C[minj].value){
	minj = j;
      }
    }
    buf = C[i];
    C[i] = C[minj];
    C[minj] = buf;
  }

}

