void Bubble(int N,card *C){

  int i;
  int j;
  int flag = 0;
  card temp;

  for(i = 0;i < N;i++){
    for(j = N-1;j > i;j--){
      if(C[j].value < C[j-1].value){
	if(C[j].value == C[j-1].value){
	  flag = 1;
	}
	temp = C[j];
	C[j] = C[j-1];
	C[j-1] = temp;
      }
    }
  }

  print_card(N,C);
  print_flag(flag);
}

void Selection(int N,card *C){

  int i;
  int j;
  int min;
  int flag = 0;
  card temp;

  for(i = 0;i < N;i++){
    min = i;
    for(j = i;j < N;j++){
      if(C[j].value < C[min].value){
	min = j;
      }
    }
    if(C[i].value == C[min].value){
      flag = 1;
    }
    temp = C[i];
    C[i] = C[min];
    C[min] = temp;
  }
  print_card(N,C);
  print_flag(flag);
}

