void bubble_sort(int C[], int value[], int length) {
  int i,j,tmp;
  for(i = 1; i <= length; ++i) {
    for(j = length; j >= i+1; --j) {
      if(value[C[j]] < value[C[j-1]]) {
        tmp = C[j];
        C[j] = C[j-1];
        C[j-1] = tmp;
      }
    }
  }
}

void select_sort(int C[], int value[], int length) {
  int i,j,mini,tmp;
  for(i = 1; i <= length; ++i) {
    mini = i;
    for(j = i; j <= length; ++j) {
      if(value[C[j]] < value[C[mini]] ){
        mini = j;
      }
    }
    tmp = C[i];
    C[i] = C[mini];
    C[mini] = tmp;
  }
}

void make_str(char str[], int C[], int value[], char mark[], int length) {
  int i,j,k;
  k = 0;
  for(i = 1; i <= 9; ++i) {
    for(j = 1; j <= length; ++j) {
      if(value[C[j]] == i) str[k++] = mark[C[j]];
    }
  }
  str[k] = '\0';
}

void show(int C[], int value[], char mark[], int length, int isStable) {
  int i;
  for(i = 1; i <= length; ++i) {
    if(i != 1) printf(" ");
    printf("%c%d", mark[C[i]], value[C[i]]);
  }
  printf("\n");
  printf("%s\n",isStable?"Stable":"Not stable");
}

