typedef struct{
  char suit;
  int num;
}Card;

void swap(Card *x, Card *y)
{
  Card tmp;
  tmp = *x;
  *x = *y;
  *y = tmp;
}

int bubbleSort(Card *A, int N) // N 個の要素を含む 0-オリジンの配列 A
{
  int count = 0;

  int flag = 1; // 逆の隣接要素が存在する
  while(flag){
    flag = 0;
    int j = N-1;
    while(j >= 1){
      if (A[j].num < A[j-1].num) {
        swap(&A[j], &A[j-1]);
        flag = 1;
        count++;
      }
      j--;
    }
  }
  return count;
}

int selectionSort(Card *A, int N) // N個の要素を含む0-オリジンの配列A
{
  int minj, tmp;
  int count = 0;

  for(int i=0; i<N; i++){
    minj = i;
    for(int j=i; j<N; j++){
      if (A[j].num < A[minj].num)
        minj = j;
    }
    if (i != minj) {
      swap(&A[i], &A[minj]);
      count++;
    }
  }

  return count;
}

