  Card tmp;
  tmp=*a;
  *a=*b;
  *b=tmp;
}
void BubbleSort(Card *s,int n){
  int j,i;
  for(i=0;i<n;i++){
    for(j=n-1;j>=i+1;j--){
      if(s[j].N<s[j-1].N) swap(&s[j],&s[j-1]);
    }
  }
}

void SelectionSort(Card *d,int n){
  int i,j,min;
  for(i=0;i<n;i++){
    min=i;
    for(j=i;j<n;j++){
      if(d[j].N<d[min].N) min=j;
    }
    swap(&d[i],&d[min]);
  }
}

int Stable(Card *s,Card *d,int n){
  int i;
  for(i=0;i<n;i++){
    if(s[i].M!=d[i].M) return 0;
  }
  return 1;
}



