  for (i=0; flag==1; i++) {
    flag = 0;
    for (j=N-1; j>=i+1; j--) {
      if (a[j-1].num > a[j].num) {
        temp       = a[j-1].num; 
        a[j-1].num = a[j].num;
        a[j].num   = temp;
        t             = a[j-1].design;
        a[j-1].design = a[j].design;
        a[j].design   = t;
        flag = 1;
      }
    }
  }
}
void selection(struct card a[], int N){
  int i, j, temp, minj;
  char t;
  for (i=0; i<N; i++) {
    minj = i;
    for (j=i; j<N; j++) {
      if (a[j].num < a[minj].num)
        minj = j;
    }
    temp       = a[j-1].num;
    a[j-1].num = a[j].num;
    a[j].num   = temp;
    t             = a[j-1].design;
    a[j-1].design = a[j].design;
    a[j].design   = t;
  }
}
