int dict[128][128];
int sort_bub[36][2];
int sort_sel[36][2];

void selection_sort(int arr[][2], int len)
{
	int tmp[2];
	for (int i = 0; i < len; i++)
	{
		int min = i;
		for (int j = i+1; j < len; j++)
		{
			if (arr[min][1] > arr[j][1])
			{
				min = j;
			}
		}
		if (i != min) {
			tmp[0] = arr[i][0];
			tmp[1] = arr[i][1];
			arr[i][0] = arr[min][0];
			arr[i][1] = arr[min][1];
			arr[min][0] = tmp[0];
			arr[min][1] = tmp[1];
		}
	}
}

void bubble_sort(int arr[][2], int len)
{
	int tmp[2];
	for (int i = 0; i < len; i++)
	{
		int max = len - i;
		for (int j = 1; j < max; j++)
		{
			if (arr[j - 1][1] > arr[j][1])
			{
				tmp[0] = arr[j-1][0];
				tmp[1] = arr[j-1][1];
				arr[j-1][0] = arr[j][0];
				arr[j-1][1] = arr[j][1];
				arr[j][0] = tmp[0];
				arr[j][1] = tmp[1];
			}
		}
	}
}

