    for(j=i+1;j<=num-1;j++){
      for(a=0;a<=num-1;a++){
        for(b=a+1;b<=num-1;b++){
          if(m[i] == m1[i] && in[i]==in[j] && in[i]==out[b] && in[j]==out[a]) return 1;
        }
      }
    }
  }
  return -1;
}

