#define FAILURE      (-1)
#define AOJ_TRUE     (1)
#define AOJ_FALSE    (0)

typedef struct card_info
{
    char value;
    char mark;
}CARD;

void selection_sort(CARD *p_card, int size);
void bubble_sort(CARD *p_card, int size);
