      if(B[i]<B[i-1]){
	n=B[i];
	B[i]=B[i-1];
	B[i-1]=n;
	keep[0]=A[i][0];
	A[i][0]=A[i-1][0];
	A[i-1][0]=keep[0];
	keep[1]=A[i][1];
	A[i][1]=A[i-1][1];
