    minj=i;
    for(j=i;j<N;j++){
      if(B[j]<B[minj]){
	minj=j;
      }
    }
    if(i!=minj){
      n=B[i];
      B[i]=B[minj];
      B[minj]=n;
      keep[0]=A[i][0];
      A[i][0]=A[minj][0];
      A[minj][0]=keep[0];
      keep[1]=A[i][1];
      A[i][1]=A[minj][1];
      A[minj][1]=keep[1];
    }
