void bubble(char cards[36][3], int n) {
	int i, j;
	char tmp[2];

	for (i = 0; i < n; i++) {
		for (j = n-1; j > i; j--) {
			if (cards[j][1] < cards[j-1][1]) {
				tmp[0] = cards[j][0];
				tmp[1] = cards[j][1];
				cards[j][0] = cards[j-1][0];
				cards[j][1] = cards[j-1][1];
				cards[j-1][0] = tmp[0];
				cards[j-1][1] = tmp[1];
			}
		}
	}
}


void selection(char cards[36][3], int n) {
	int i, j, mini;
	char tmp[2];

	for (i = 0; i < n; i++) {
		mini = i;
		for (j = i; j < n; j++) {
			if (cards[j][1] < cards[mini][1]) {
				mini = j;
			}
		}
		if (i != mini) {
			tmp[0] = cards[i][0];
			tmp[1] = cards[i][1];
			cards[i][0] = cards[mini][0];
			cards[i][1] = cards[mini][1];
			cards[mini][0] = tmp[0];
			cards[mini][1] = tmp[1];
		}
	}
}


int stable_test(char orders[9][4], char cards[36][3], int n) {
	int i, j, k, now, prev;

	for (i = 0; i < 9; i++) {
		if (!orders[i][0])
			continue;
		now = -1;
		for (j = 0; j < 4; j++) {
			prev = now;
			for (k = 0; k < n; k++) {
				if (cards[k][1]-'1' == i && cards[k][0] == orders[i][j]) {
					now = k;
					break;
				}
			}
			if (prev > now)
				return 0;
		}
	}
	return 1;
}


