int isStable(roll A, roll B) {
  int i, j, c, d;

  for(i=0; i<N-1; i++){
    for(j=i+1; j<N; j++){
      if(A.a[i][1] == A.a[j][1]){
	for(c=0; c<N; c++) if(A.a[i][0] == B.a[c][0] && A.a[i][1] == B.a[c][1]) break;
	for(d=0; d<N; d++) if(A.a[j][0] == B.a[d][0] && A.a[j][1] == B.a[d][1]) break;
	if(c<d) continue;
	else return 0;
      }
    }
  }
  return 1;
}

