#include <stdio.h>
#define N 36

void bubbleSort(int V[N],char S[N],int n){

	int temp;
	char ctemp;
	for(int i = 0; i < n-1; i++){
		for(int j = n-1; j > i; j--){
			if( V[j] < V[j-1]){
				temp = V[j]; ctemp = S[j];
				V[j] = V[j-1]; S[j] = S[j-1];
				V[j-1] = temp; S[j-1] = ctemp;
			}
		}
	}

}

void selectionSort(int V[N],char S[N],int n){

	int temp,min;
	char ctemp;
	for( int i = 0; i < n; i++){
		min = i;
		for( int j = i; j < n; j++){
			if( V[j] < V[min] ) min = j;
		}
		if( min != i ){
			temp = V[i]; ctemp = S[i];
			V[i] = V[min]; S[i] = S[min];
			V[min] = temp; S[min] = ctemp;
		}
	}

}

int check_stable(int v[N], char s[N], int v1[N], char s1[N], int n){

	char unsorted[4], sorted[4];

	for(int i = 1; i < 10; i++){
		int unsorted_c = 0, sorted_c = 0;
		for(int j = 0; j < n; j++){
			if( v[j] == i ){
				unsorted[unsorted_c] = s[j];
				unsorted_c++;
			} 
			if( v1[j] == i ){
				sorted[sorted_c] = s1[j];
				sorted_c++;
			} 
		}
		for(int j = 0; j < unsorted_c; j++){
			if( unsorted[j] != sorted[j] ) {
				return -1;
			}
		}
	}

	return 1;

}

