	  {
	    mini = j;
	  }
	}	
    swap=A[i][1];
	A[i][1] = A[mini][1];
	A[mini][1] = swap;
	swap=A[i][0];
	A[i][0] = A[mini][0];
	A[mini][0] = swap;

    }
}

int isStable(char in[][3], char out[][3])
{
	for(int i = 0; i<= N-1; i++)
	{
		for(int j = i+1; j<= N-1; j++)
		{
			for(int a = 0; a<=N-1; a++)
			{
				for(int b = a + 1; b<=N-1; b++)
				{
					if(in[i][1] == in[j][1])
					    if(in[i][1] == out[b][1] && in[i][0] == out[b][0])
					        if(in[j][1] == out[a][1] && in[j][0] == out[a][0])
					            return 0;
				}
			}
		}
	}
	return 1;
}

