void BubbleSort(Card a[],int n)
{
  int i,j;
  Card tmp;

  for(i=0; i<n; i++) 
    for(j=n-1; j>i; j--) 
      if(a[j].value < a[j-1].value){
	tmp = a[j];
	a[j] = a[j-1];
	a[j-1] = tmp;
      }
}

void SelectionSort(Card b[],int n)
{
  int i,j,minj;
  Card tmp;

  for(i=0; i<n-1; i++) {
    minj = i;
    for(j=i; j<n; j++) 
      if(b[j].value < b[minj].value) minj = j;
    tmp = b[i];
    b[i] = b[minj];
    b[minj] = tmp;
  }
}

int isStable(Card in[],Card out[],int n) 
{
  int i,j,a,b;
  for(i=0; i<n; i++) 
    for(j=i+1; j<n; j++)
      for(a=0; a<n; a++)
	for(b=a+1; b<n; b++)
	  if(in[i].value == in[j].value && in[i].sign == out[b].sign && in[j].sign == out[a].sign)
	    return 1;
  return 0;
}

