void swap(int *a, int *b)
{
    int tmp;
    tmp = *a;
    *a = *b;
    *b = tmp;
}

void bubbleSort_(int A[], int N)
{
    int flag;
    int j;

    flag = 1;
    while(flag) {
        flag = 0;
        for(j = N-1; j >= 1; j--) {
            //if(A[j]%4 < A[j-1]%4 && A[j]/4 < A[j-1]/4) {
            if(A[j]/4 < A[j-1]/4) {
                swap(&A[j], &A[j-1]);
                flag = 1;
            }
        }
    }
}

void bubbleSort(int A[], int N)
{
    int flag;
    int j;

    flag = 1;
    while(flag) {
        flag = 0;
        for(j = N-1; j >= 1; j--) {
            if((A[j]/4) < (A[j-1]/4)) {
                swap(&A[j], &A[j-1]);
                flag = 1;
            }
        }
    }
}

void selectionSort(int A[], int N)
{
    int i;
    int j;
    int minj;

    for(i = 0; i < N; i++) {
        minj = i;
        for(j = i; j < N; j++) {
            if((A[j]/4) < (A[minj]/4)) {
                minj = j;
            }
        }
        if(i != minj) {
            swap(&A[i], &A[minj]);
        }
    }
}

