void BubbleSort(To* A, int N){
  int flag=1,i,j;
  To tmp;
  while(flag==1){
    flag=0;
    for(j=N-1;j>=1;j--){
      if(A[j].num<A[j-1].num){
	tmp=A[j];
	A[j]=A[j-1];
	A[j-1]=tmp;
	flag=1;       
      }
    }
  } 
}
void SelectionSort(To* A, int N){
  int i,j,minj;
  To tmp;
  for(i=0;i<N;i++){
    minj=i;
    for(j=i;j<N;j++){
      if(A[j].num<A[minj].num)
	minj=j;
    }
    tmp=A[i];
    A[i]=A[minj];
    A[minj]=tmp; 
  }
}

