} Card ;


void swap_Card(Card *x, Card *y)
{
	Card temp = *x;
	*x = *y;
	*y = temp;
}


//バブルソート
void BubbleSort(Card A[], int N) {
	int i, j;
	Card temp;

	for (i = 0; i < N-1; i++) {
		for (j = N - 1; j > i ; j--) {
			if (A[j].value < A[j - 1].value) {
				temp = A[i];
				A[i] = A[minj];
				A[minj] = temp;
			}
		}
	}
}

//選択ソート
void SelectionSort(Card A[], int N) {
	int i, j;
	int minj;
	Card temp;

	for (i = 0; i < N-1; i++) {
		minj = i;
		for (j = i+1; j < N; j++) {
			if (A[j].value < A[minj].value) {
				minj = j;
			}
		}
		temp = A[i];
		A[i] = A[minj];
		A[minj] = temp;
	}
}

