int SelectionSort(int N, int row, int A[row][N]){
  int i, j;
  int tmp, min;
  int index;
  int count;
  char ch;
  for(i=0; i<(N-1); ++i){
	min=A[1][i];
	tmp=A[1][i];
	ch=A[0][i];
	for(j=(i+1); j<N; ++j){
	  if(min>A[1][j]){
		min=A[1][j];
		index=j;

	  }
	}
	if(tmp!=min){
	  A[1][i]=min;
	  A[1][index]=tmp;
	  A[0][i]=A[0][index];
	  A[0][index]=ch;
	  ++count;
	}
  }
  return 1;
}
int BubbleSort(int N, int r, int A[r][N]){
  int i, j;
  char tmp_ch;
  int tmp_int;
  for(i=0; i<(N-1); ++i){
	for(j=(N-1); j>i; --j){
	  if(A[1][j]<A[1][j-1]){
		tmp_ch=A[0][j];
		tmp_int=A[1][j];
		A[0][j]=A[0][j-1];
		A[1][j]=A[1][j-1];
		A[0][j-1]=tmp_ch;
		A[1][j-1]=tmp_int;
	  }

	}
  }
  return 1;
}
/* 安定<==>1  不安定<==>0 */
int CheckStable(int N, int row, int bbs[row][N], int sls[row][N]){
  int i;
  int flag=0;
  for(i=0; i<N; ++i){
	if((bbs[0][i]==sls[0][i])&&(bbs[1][i]==sls[1][i]));
	else
	  ++flag;

}
  return flag;
}

