int main(void)
{
    int n ,m;

    /*Nの入力*/
    do {
        scanf("%d" , &n);
    }while ( n < 1 || n > 36 );

    /*配列の生成*/
    char Char_A[n][3];

    for ( m = 0 ; m < n ; m++) {
            scanf("%s" ,Char_A[m]);
    }

/*-----------------------------------------------------------------------*/

    /*安定か判定するため、元のコピーを作成(Cではstrcpyを使う)*/
    char Copy_Char_C[n][3];

    for ( int x = 0 ; x < n ; x++) {
        strcpy(Copy_Char_C[x] ,Char_A[x]);
    }
    /*コピーの作成完了*/


/*-----------------------------------------------------------------------*/
/*-----------------------------------------------------------------------*/
/*-----------------------------------------------------------------------*/

    /*バブルソート*/
    Buble_Sort( n ,Char_A);

    /*バブルソート結果の表示*/
    for (int s = 0 ; s < n - 1 ; s++ )
        printf("%s " , Char_A[s]);
    /*最後の一つ*/
    printf("%s\n" , Char_A[n - 1]);

/*------------------------------------------------------*/

    /*安定の判定*/
    if ( Stable_Judge( n ,Copy_Char_C ,Char_A ) == 1 ) {
        /*安定判定の出力*/
        puts("Stable");
    }
    else if ( Stable_Judge( n ,Copy_Char_C ,Char_A ) == -1 ) {
        /*安定判定の出力*/
        puts("Not stable");
    }

/*-----------------------------------------------------------------------*/

    /*選択ソートのためにAたちを元に戻す*/
    for ( int y = 0 ; y < n ; y++) {
        strcpy(Char_A[y] ,Copy_Char_C[y]);
    }
    /*コピーの作成完了*/

/*-----------------------------------------------------------------------*/
/*-----------------------------------------------------------------------*/
/*-----------------------------------------------------------------------*/

    /*選択ソート*/
    Selection_Sort( n ,Char_A);

    /*選択ソート結果の表示*/
    for (int s = 0 ; s < n - 1 ; s++ )
        printf("%s " , Char_A[s]);
    /*最後の一つ*/
    printf("%s\n" , Char_A[n - 1]);

    /*------------------------------------------------------*/

    /*安定の判定*/
    if ( Stable_Judge( n ,Copy_Char_C ,Char_A ) == 1 ) {
        /*安定判定の出力*/
        puts("Stable");
    }
    else if ( Stable_Judge( n ,Copy_Char_C ,Char_A ) == -1 ) {
        /*安定判定の出力*/
        puts("Not stable");
    }

/*-----------------------------------------------------------------------*/

    return 0;
}

