void BubbleSort(AAA * C, int N){
  int i, j;
  AAA temp;
  for(i = 0; i < N - 1; i++){
    for(j = N - 1; j > i; j--){
      if(C[j - 1].value > C[j].value){
	temp = C[j];
	C[j] = C[j - 1];
	C[j - 1] = temp;
      }
    }
  }
}

void SelectionSort(AAA * C, int N){
  int i, j, minj, flag;
  AAA temp;

  for(i = 0; i < N - 1; i++){
    minj = i;
    for(j = i + 1; j < N; j++){
      if(C[minj].value > C[j].value){
	minj = j;
      }
    }
    temp = C[i];
    C[i] = C[minj];
    C[minj] = temp;
  }
}

