void bubbleSort(member *m,int n){
  int flag=1,i;
  while(flag){
    flag=0;
    for(i=n-1;i>0;i--){
      if(m[i].n < m[i-1].n){
        swap(&m[i],&m[i-1]);
        flag=1;
      }
    }
  }
}

void selectionSort(member *m,int n){
  int i,j,minj;
  for(i=0;i<n;i++){
    minj = i;
    for(j=i;j<n;j++){
      if(m[j].n < m[minj].n){
        minj = j;
      }
    }
    if(minj!=i){
      swap(&m[minj],&m[i]);
    }
  }
}

void swap(member *x,member *y){
  member r;
  r=*x;
  *x=*y;
  *y=r;
}

