//セレクションソート
void SelectionSort(card *A, int N) {
  int i,j,flag,minj;
  card x,B[36];
  for(i = 0; i < N; i++) {
    B[i].n = A[i].n;
    B[i].c = B[i].c;
  }


  for(i = 0; i < N; i++) {
    minj = i;
    flag = 0;
    for(j = i; j < N; j++) {
      if(A[j].n < A[minj].n) {
	minj = j; /*最小値があったらその位置を記憶するための動作*/
	flag = 1; /*for文で確かめるなかで、最小値が変わったらflagを1にする。*/

      }
    }
    if(flag == 1) {
      x.c = A[i].c;
      x.n = A[i].n;
      A[i].c = A[minj].c;
      A[i].n = A[minj].n; 
      A[minj].c = x.c;
      A[minj].n = x.n;
    }
  }
  for(i = 0; i < N; i++) {
    printf("%c%d",A[i].c,A[i].n);
    if(N-1 != i) printf(" ");
  }
  printf("\n");
  for(i = 0; i < N; i++) {
    if(B[i].c != A[i].c) flag = 1;
  }
  if(flag == 1) printf("Not stable\n");
  else printf("Stable\n");
  return;
}

