}

int selection_sort(CARD *A, int N)
{
	int i, j, minj;
	int cnt = 0;
	for (i = 0; i < N; i++) {
		minj = i;
		for (j = i; j < N; j++) {
			if (A[j].num < A[minj].num) {
				minj = j;
			}
		}
		if (i != minj) {
			swap(&A[i], &A[minj]);
			cnt++;
		}
	}
	return  cnt;
}

