void swap(Card *x, Card *y){
    Card temp;
    temp = *x;
    *x = *y;
    *y = temp;
}

void bubble(int n){

    int i, j;

    //sort
    for (i = 0; i < n-1; i++) {
        for (j = n-1; j > 0 ; j--) {
            if(C1[j].value < C1[j-1].value) swap(&C1[j], &C1[j-1]);
        }
    }

    // print
    for (i = 0; i < n-1; i++) {
        printf("%c%c ", C1[i].ch, C1[i].value);
    }
    printf("%c%c\n", C1[n].ch, C1[n].value);
    IsStable(C1, n);
}

void select(int n){

    int min, i, j;

    // sort
    for (i = 0; i < n-1; i++) {
        min = i;
        for (j = i; j < n; j++) {
            if(C2[j].value < C2[min].value) min = j;
        }
        swap(&C2[i], &C2[min]);
    }

    // print
    for (i = 0; i < n-1; i++) {
        printf("%c%c ", C2[i].ch, C2[i].value);
    }
    printf("%c%c\n", C1[n].ch, C1[n].value);
    IsStable(C2, n);
}

void IsStable(Card *c, int n){

    int cnt = 0, i;

    for (i = 0; i < n; i++) {
        if(c[i].value == C1[i].value && c[i].ch == C1[i].ch)
            cnt++;
    }
    if(n == cnt) printf("Stable\n");
    else printf("Not stable\n");

}

