    typedef struct { char suit, value;} Card;

void bubble(Card A[], int N){
    int i,j;
    Card t;
    for(i=0;i<N;i++){
        for(j=N-1;j>=i;j--){
            if(A[j].value < A[j-1].value){
                 t= A[j];
                 A[j] = A[j-1];
                 A[j-1] =t;
            }
        }
    }
}

void selection(Card A[], int N){
    int i,j,minj;
    Card t;
    for(i=0;i<N;i++){
        minj = i;
        for(j=i;j<N;j++){
            if(A[j].value < A[minj].value){
                minj = j;
            }
         }
         t= A[i];
         A[i] = A[minj];
         A[minj] =t;
    }
}

