        for (j = N -1; j > i; j--) {
            if (C[j].val < C[j - 1].val) {
                tmp = C[j];
                C[j] = C[j - 1];
                C[j - 1] = tmp;
            }
        }
    }
    return 0;
}

int
selection_sort(struct card *C, int N)
{
    int i, j, minj;
    struct card tmp;

    for (i = 0; i < N; i++) {
        minj = i;
        for (j = i; j < N; j++) {
            if (C[j].val < C[minj].val)
                minj = j;
        }
        if (C[i].val != C[minj].val) {
            tmp = C[i];
            C[i] = C[minj];
            C[minj] = tmp;
        }
    }
    return 0;
}

