print_card(struct card *c, int n)
{
    int i;

    for (i = 0; i < n; i++) {
        printf("%c%d", c[i].mark, c[i].val);
        if (i != (n - 1))
            printf(" ");
    }
    printf("\n");
}

int
chk_stable(struct card *c, int n) {
    int i;

    for (i = 0; i < n - 1; i++) {
        if (c[i].val == c[i + 1].val) {
            if (c[i].index > c[i + 1].index)
                return 1;
        }
    }
    return 0;
}

