void BubbleSort(int **A,int N){
	int tmp;
	for(int i=0;i<N-1;i++){
		for(int j=(N-1);j>i;j--){
			if(A[j][1]<A[j-1][1]){
				tmp=A[j][0];
				A[j][0]=A[j-1][0];
				A[j-1][0]=tmp;
				tmp=A[j][1];
				A[j][1]=A[j-1][1];
				A[j-1][1]=tmp;
			}
		}
	}
}

void SelectionSort(int **A,int N){
	int tmp;
	int min;
	for(int i=0;i<N-1;i++){
		min=i;
		for(int j=i+1;j<N;j++){
			if(A[j][1]<A[min][1]){
				min=j;
			}
		}
		tmp=A[i][0];
		A[i][0]=A[min][0];
		A[min][0]=tmp;
		tmp=A[i][1];
		A[i][1]=A[min][1];
		A[min][1]=tmp;
	}
}

