	for (i = 0; i < N; i++) {
		Card c;
		scanf("%s", &c.suit);
		scanf("%d ", &c.value);
		BC[i] = c;
		SC[i] = c;
	}

	SelectionSort(SC, N);
	BubbleSort(BC, N);

