    return 0;
}

int bubbleSort(CARD C[], int N)
{
    int i, j;
    CARD tmp;

    for (i = 0; i < N; i++)
    {
        for (j = N - 1; j > i; j--)
        {
            if(C[j].value < C[j - 1].value)
            {
                tmp = C[j];
                C[j] = C[j - 1];
                C[j - 1] = tmp;
            }
        }
    }

    return 0;
}

int selectionSort(CARD C[], int N)
{
    int i, j;
    int minj;
    CARD tmp;

    for (i = 0; i < N; i++)
    {
        minj = i;

        for (j = i; j < N; j++)
        {
            if(C[j].value < C[minj].value)
            {
                minj = j;
            }
        }

        tmp = C[i];
        C[i] = C[minj];
        C[minj] = tmp;
    }

    return 0;
}

int isStable(CARD C1[], CARD C2[], int N)
{
    int i;

    for (i = 0; i < N; i++)
    {
        if(C1[i].suit != C2[i].suit)
        {
            return 0;
        }
    }

    return 1;
}

int printArray(CARD C[], int N)
{
    int i;

    for (i = 0; i < N; i++)
    {
        printf("%c%d", C[i].suit, C[i].value);
        if (i < N - 1)
        {
            printf(" ");
        }
    }

    printf("\n");

    return 0;
}

