void BubbleSort(struct Card *c,int n){
  int i,j;

  for(i = 0;i < n ;i++){
    for(j = n - 1;j > i ; j--){
      if(c[j].value < c[j-1].value){
        struct Card C = c[j];
        c[j] = c[j-1];
        c[j-1] = C;
      }
    }
  }
}

void SerectionSort(struct Card *c,int n){
  int i,j,minj;

  for(i = 0;i < n;i++){
    minj = i;
    for(j = i;j < n;j++){
      if(c[j].value < c[minj].value)
        minj = j;
    }
    struct Card C = c[i];
    c[i] = c[minj];
    c[minj] = C;
  }
}

int hantei(struct Card *c1,struct Card *c2,int n){
  int i;

  for(i = 0;i < n;i++)
    if(c1[i].mark != c2[i].mark) return 0;

  return 1;
}

