  int i,flag=1;
  Roll tmp;

  while(flag){
    flag = 0;
    for(i = 0;i < n;i++){
      if(Sort[i].value < Sort[i-1].value){
	tmp = Sort[i];
	Sort[i]=Sort[i-1];
	Sort[i-1]=tmp;
	flag = 1;

      }
    }
  }
}

void SelectionSort(Roll *Sort,int n){

  int i,j,min;
  Roll tmp;

  for(i = 0;i < n;i++){
    min = i;
    for(j = i;j < n;j++){

      if(Sort[j].value < Sort[min].value){
    min = j;

      }
    }   
    if(Sort[i].value != Sort[min].value){ 
      tmp = Sort[i];
      Sort[i] = Sort[min];
      Sort[min] = tmp;

    }

  }
}
