void BubbleSort(struct Card C[], int N){
  int i, j;
  struct Card tmp;
  for( i = 0 ; i < N ; i++ ){
    for( j = N-1 ; j >= i+1 ; j-- ){
      if( C[j].value < C[j-1].value ){
        tmp = C[j];
        C[j] = C[j-1];
        C[j-1] = tmp;
      }
    }
  }
}

void SelectionSort(struct Card C[], int N){
  int i, j, minj;
  struct Card tmp;
  for( i = 0 ; i < N ; i++ ){
    minj = i;
    for( j = i ; j < N ; j++ ){
      if( C[j].value < C[minj].value ) minj = j;
    }
    tmp = C[i];
    C[i] = C[minj];
    C[minj] = tmp;
  }
}

void Stable(struct Card C[], int N){
  int i, flag=0;
  for( i = 0 ; i < N-1 ; i++ ){
    if( C[i].value == C[i+1].value ){
      if( C[i].i > C[i+1].i ){
        printf("Not stable\n");
        flag = 1;
        break;
      }
    }
  }
  if( flag == 0  )printf("Stable\n");
}

