int SelectionSort(struct card c[], int N) {
	int i, j, minj;
	int count = 0;
	for (i = 0; i < N - 1; i++) {
		minj = i;
		for (j = i; j < N; j++) {
			if (c[j].R < c[minj].R) {
				minj = j;
			}
		}
		Swap(&c[i].R, &c[minj].R, c[i].Rc, c[minj].Rc);
		if (i != minj) {
			count++;
		}
	}
	return count;
}
int  BubbleSort(struct card c[], int N) {
	int flag = 1;
	int count = 0;
	int j;
	while (flag != 0) {	//forにして、ソートを終える場所を少しづつ変えていけば完璧。（恐らくオーダーは変わらない。）
		flag = 0;
		for (j = N - 1; j >= 1; j--) {
			if (c[j].R < c[j-1].R) {
				Swap(&c[j].R, &c[j - 1].R, c[j].Rc, c[j - 1].Rc);
				flag = 1;
				count++;
			}
		}
	}
	return count;
}
void Swap(int *a, int *b,char aa[] ,char bb[]){
	int k,i;
	char t[2];

	k = *a;
	*a = *b;
	*b = k;

	for (i = 0; i < 2; i++) {
		t[i] = aa[i];
		aa[i] = bb[i];
		bb[i] = t[i];
	}
}
