	int i, j, a, b;
	for (i = 0; i < N; i++) {
		for (j = i + 1; j < N; j++) {
			for (a = 0; a < N; a++) {
				for (b = a + 1; b < N; b++) {
					if (c[j].Ri == c[i].Ri && strcmp(c[i].Rcc,c[b].Rc) == 0 && strcmp(c[j].Rcc,c[a].Rc) == 0){
						printf("\nNot Stable\n");
						return ;
					}
				}
			}
		}
	}
	printf("\nStable\n");
	return ;
}

