int decision(int n, Card *C){

  int i, j;
  Card TMP;

  for(i = 0; i < n; i++){
    TMP = C[i];

    if(TMP.a == C[i + 1].a){
      if(TMP.c > C[i + 1].c) return 1;
    }

  }

  return 0;
}

