void AtoI(char **a, int *in, int n){

  int i;

  for(i=0; i<n; i++){
    in[i] = atoi(&a[i][1]);
  }
}

void BubSort(int *x, char **y, int n){

  int i,j;
  int tmpInt;
  char *tmpChar;

  for(i=0; i<n-1; i++){
    for(j=n-1; j>i; j--){
      if(x[j-1] > x[j]){
	tmpInt = x[j];
	x[j] = x[j-1];
	x[j-1] = tmpInt;

	tmpChar = y[j];
	y[j] = y[j-1];
	y[j-1] = tmpChar;
      }
    }
  }
}

void SelSort(int *x, char **y, int n) {

  int i,j;
  int min;
  int tmpInt;
  char *tmpChar;

  for(i=0; i<n-1; i++){
    min = i;           //小さい値の保持

    for(j=i+1; j<n; j++){
      if(x[j] < x[min]){ 
	min = j;     //小さい値の更新
      }
    }
    /*sort*/
    if(x[i] > x[min]){
      tmpInt = x[i];
      x[i] = x[min];
      x[min] = tmpInt;

      tmpChar = y[i];
      y[i] = y[min];
      y[min] = tmpChar;
    }
  }
}


void ShowData(char **x, int n){

  int i;

  for(i=0; i<n; i++){
    if(i!=n-1) printf("%s ",x[i]);
    else printf("%s",x[i]);
  }

  printf("\n");
}

void Judge(char **x, char **y, int n){

  int i,j;
  char tmp;
  char tmpNum;
  int flag = 0;

  for(i=0; i<n-1; i++){
    if(y[i][1] == y[i+1][1]){ //同じ数字があるか判定
      tmpNum = y[i][1];            //ソート後の先に来た方を保持
      tmp = y[i][0];
      for(j=0; j<n-1; j++){
	if(x[j][1] == tmpNum){ //数字が同じだったら文字が一緒か判定
	  if(x[j][0] == tmp) printf("Stable\n");
	  else printf("Not stable\n");
	  break;
	}
      }
    }
  }
}

#include<stdio.h>

struct Card{
  char suit;
  char value;
};


void BubbleSort(struct Card *A, int length) {

  int i, j;
  char tmp;
  char tmp_1;

  for(i = 0; i < length; i++) {
    for(j = length-1; j > i; j--) {
      if(A[j].value < A[j-1].value) {

	tmp = A[j].value;
	tmp_1 = A[j].suit;

	A[j].value = A[j-1].value;
	A[j].suit = A[j-1].suit;

	A[j-1].value = tmp;
	A[j-1].suit = tmp_1;

      }
    }
  }
}

void SelectionSort(struct Card *A,int length) {

  int i, j, mini;
  char tmp;
  char tmp_1;

  for(i = 0; i < length; i++) {
    mini = i;
    for(j = i; j < length; j++) {
      if(A[j].value < A[mini].value) {
	mini = j;
      }
    }
    if(i != mini) {
    tmp = A[i].value;
    tmp_1 = A[i].suit;

    A[i].value = A[mini].value;
    A[i].suit = A[mini].suit;

    A[mini].value = tmp;
    A[mini].suit = tmp_1;

    }
  }
}



