typedef struct { char c; int a; int id; } DATA;

void bubble_sort(int n, DATA *a)
{
    int i, f;
    DATA x;

    do {
        f = 0;
        for (i = n-1; i > 0; i--) {
            if (a[i].a < a[i-1].a) {
                x = a[i], a[i] = a[i-1], a[i-1] = x;
                f = 1;
            }
        }
    } while (f);
}

void selection_sort(int n, DATA *a)
{
    int i, j, minj;
    DATA x;

    for (i = 0; i < n; i++) {
        minj = i;
        for (j = i; j < n; j++) {
            if (a[j].a < a[minj].a) minj = j;
        }
        if (i != minj) {
            x = a[i], a[i] = a[minj], a[minj] = x;
        }
    }
}


