int bubbleSort(card *a, int n) {
    int i, j, flag;
    j = 0; flag = 1;
    while (flag) {
        flag = 0;
        for (i = n - 1; i > j; i--) {
            if (a[i].value < a[i - 1].value) {
                swap(card, a[i], a[i - 1]);
                flag = 1;
            }
        }
        j++;
    }
    return 0;
}

int selectionSort(card *b, int n) {
    int i, j, mini;
    for (i = 0; i < n; i++) {
        mini = i;
        for (j = i; j < n; j++) {
            if (b[j].value < b[mini].value) mini = j;
        }
        if (i != mini) {
            swap(card, b[i], b[mini]);
        }
    }
    return 0;
}

