      if(b[j-1].value > b[j].value){
       swap = b[j-1];
       b[j-1] = b[j];
       b[j] = swap;
      }
    }
  }
}

void selection(struct Card s[], int n)
{
  int min, i, j;
  struct Card swap;

  for(i = 0; i < n; i++){
    min = i;
    for(j = i; j < n; j++){
      if(s[j].value < s[min].value)
        min = j;
    }
    if( i != min){
      swap = s[i];
      s[i] = s[min];
      s[min] = swap;
    }
  }
}

