  printf("Stable\n");
  /*bubble sort finish*/

  /*select sort start*/
  for(i = 0; i < length; i++)
    {
      min = i;
      for(j = i + 1; j < length; j++)
	{
	  if(C2[j].value < C2[min].value)
	    {
	      min = j;
	      flag = 1;
	    }
	}
      if(flag == 1)
	{
