	int order;
};

int check = 1;

int
card_key(void *arg)
{
	return ((struct card *)arg)->number;
}

void
print_card(struct card *a, int n)
{
	int i;

	for (i = 0; i < n; i++)
		printf("%s%c%d", i ? " " : "", a[i].suite, a[i].number);
	printf("\n");
}

int
bubble_sort(struct card *a, int n, int (*key)(void *))
{
	int i, flag = 1;
	struct card v;

	while (flag) {
		flag = 0;
		for (i = n - 1; i > 0;i--) {
			if (key(&a[i]) < key(&a[i - 1])) {
				v = a[i];
				a[i] = a[i - 1];
				a[i - 1] = v;
				flag = 1;
			}
		}
	}
}

void
selection_sort(struct card *a, int n, int (*key)(void *))
{
	int i, j, minj;
	struct card v;

	for (i = 0; i < n; i++) {
		if (i &&
		    (key(&a[i]) == key(&a[i - 1])) &&
		    (a[i].order < a[i-1].order))
			check = 0;
		minj = i;
		for (j = i + 1; j < n; j++)
			if (key(&a[j]) < key(&a[minj]))
				minj = j;
		if (i != minj) {
			v = a[i];
			a[i] = a[minj];
			a[minj] = v;
		}
	}
}

