void bubble(card C[],int n){
 for(int i=0;i<n-1;i++){
  for(int j=n-1;j>=i+1;j--){
   if(C[j].num<C[j-1].num){swap(C,j,j-1);}
  }
 }
}


void selesort(card C[],int n){
 for(int i=0;i<n-1;i++){int minid=i;
  for(int j=i;j<n;j++){
   if(C[j].num<C[minid].num){minid=j;}
  }
  swap(C,i,minid);
 }
return;
}




