    scanf("%c%d%c",&data[i].pattern,&data[i].value,&space);
    C1[i]=data[i];
    C2[i]=data[i];
  }

  BubbleSort(C1,n);
  PrintState(C1,n);
  printf("Stable\n");

  SelectionSort(C2,n);
  PrintState(C2,n);
  if(IsStable(C1, C2, n)) printf("Stable\n");
  else printf("Not stable\n");

  return 0;
}

