	for(i=0;i<N;i++){
		mini=i;
		for(j=i;j<N;j++){
			if(output2[j].num<output2[mini].num) mini=j;
		}
		temp=output2[i];
		output2[i]=output2[mini];
		output2[mini]=temp;
	}
	return ;
}

