struct card{
  char design;
  int num;
};

void bubble(struct card a[], int N){
  int i, j, temp;
  for (i=0; i<N; i++) {
    for (j=N-1; j>=i+1; j--) {
      if (a[j-1].num > a[j].num) {
        temp   = a[j-1];
        a[j-1] = a[j];
        a[j]   = temp;
      }
    }
  }
}
void selection(struct card a[], int N){
  int i, j, temp, minj;
  for (i=0; i<N; i++) {
    minj = i;
    for (j=i; j<N; j++) {
      if (a[j] < a[minj])
        minj = j;
    }
    temp    = a[i];
    a[i]    = a[minj];
    a[minj] = temp;
  }
}
void print(struct card a[], int N){
  int i;
  for (i=0; i<N; i++) {
    if (i>0) {
      putchar(' ');
      printf("%c%d", a[i].design, a[i].num);
    }
  }
  printf("\n");
}
int stable(struct card c1[], struct card c2[], int N){
  int i;
  for (i=0; i<N; i++) {
    if (c1[i].design != c2[i].design)
      return 0;
  }
  return 1;
}

