/*引数として与えられたCard型構造体 a,b を交換する関数*/
void swap(Card *a, Card *b)
{
  Card tmp;

  tmp = *a;
  *a  = *b;
  *b  = tmp;
}

/*ソートの出力が安定であるか調べる関数 
 戻り値： 安定 １  不安定 ０*/
int isStable(Card in[], Card out[], int n)
{
  int i,j, a, b;

  for( i = 0; i<n-1; i++ )
    {
      for( j = i+1; j<n; j++ )
	{
	  for( a = 0; a<n-1; a++ )
	    {
	      for( b = a+1; b<n; b++ )
		{
		  if( in[i].value == in[j].value &&  in[i].c == out[b].c && in[j].c == out[a].c && in[i].value == out[a].value && in[j].value == out[b].value )
		    return 0;
		}
	    }
	}
    }

  return 1;
}

