    {
        for (j=(len-1);j>i;j--)
        {
            if (array[j][0] < array[j-1][0])
                {
        tmp = array[j-1][0];
        array[j-1][0] = array[j][0];
        array[j][0] = tmp;
        int buf;
        buf = array[j-1][1];
        array[j-1][1] = array[j][1];
        array[j][1] = buf;

                    cnt += 1;
                }
