struct CARD{
   char mark;
   int  number;
};

int BubbleSort(struct CARD B[], int b){
   int flag;
   int i;
   int s = 0;
   struct CARD v;

   flag = 1;
   while (flag) {
      flag = 0;
      for (i = b - 1; i > 0; --i) {
         if (B[i].number < B[i - 1].number) {
            v = B[i];
			B[i] = B[i - 1];
			B[i - 1] = v;
			s = s + 1;
			flag = 1;
         }
      }
   }
   return s;
}

int SelectionSort(struct CARD C[], int c) {
   int i, j, minj;
   int s = 0;
   struct CARD v;


   for (i = 0; i < c - 1; ++i) {
      minj = i;
	  for (j = i; j < c; ++j) {
		 if (C[j].number < C[minj].number)
			minj = j;
	  }
	  if (i != minj) {
		 v = C[i];
		 C[i] = C[minj];
		 C[minj] = v;
		 s = s + 1;
	  }
   }
   return s;
}

