{
  deck_t *Deck;
  Deck = read_deck();
  deck_t *BubbledDeck;
  BubbledDeck = card_bubbleSort(Deck);
  deck_t *SelectedDeck;
  SelectedDeck = card_SelectionSort(Deck);
  print_deck(BubbledDeck);
  stability(BubbledDeck,Deck);
  print_deck(SelectedDeck);
  stability(SelectedDeck,Deck);
  return 0;
}

