#include <stdio.h>
#include <stdbool.h>

typedef struct Card{
    char c;
    int value;
}Card;

void bubbleSort(Card C[], int N)
{
    int i, j;
    Card tmp;
    for(i=0; i<N; i++){
        for(j = N-1; j>i; j--){
            if(C[j].value < C[j-1].value){
                tmp = C[j];
                C[j] = C[j-1];
                C[j-1] = tmp;
            }
        }
    }
}

void selectionSort(Card C[], int N)
{
    int i, j, minj;
    Card tmp;
    for(i=0; i<N; i++){
        minj = i;
        for(j=i; j<N; j++){
            if(C[j].value < C[minj].value){
                minj = j;
            }
        }
        tmp = C[i];
        C[i] = C[minj];
        C[minj] = tmp;
    }
}

bool isStable(Card in[], Card out[], int N)
{
    int i;
    for(i=0; i<N; i++){
        if(!(in[i].c == out[i].c && in[i].value == out[i].value)){
            return false;
        }
    }
    return true;
}

