        }
    }
    printf("Stable\n");

    // selection sortした構造体Cardの配列の表示と安定の判断を行う
    for(i=0; i<N; i++){
        if(i==N-1){
            printf("%c%d\n", c2[i].c, c2[i].value);
        }else{
            printf("%c%d ", c2[i].c, c2[i].value);
        }
    }
    if(isStable(c1, c2, N)){
