void BubbleSort(char c[], int num[], int n){
  int i, j, flag = 1, vi;
  char vc;

  for(i = 0; i <= n - 1; i++){
    for(j = n - 1; j >= i + 1; j--){
      if(num[j] < num[j - 1]){
        vc = c[j];
        vi = num[j];
        c[j] = c[j - 1];
        num[j] = num[j - 1];
        c[j - 1] = vc;
        num[j - 1] = vi;
      }
    }
  }

  for(i = 0; i < n; i++){
    printf("%c%d", c[i], num[i]);
    if(i != n - 1)
      printf(" ");
  }
  printf("\nStable\n");
}

