  for(i = 0; i <= n - 1; i++){
    minj = i;
    for(j = i; j <= n - 1; j++){
      if(num[j] < num[minj]){
        minj = j;
      }
    }
    vc = c[i];
    vi = num[i];
    c[i] = c[minj];
    num[i] =num[minj];
