void X (Point* A,int N){
  int j;
  Point p;
  int flag;
  flag=1;
  while (flag==1){
    flag=0;
    for (j=N-1;j>=1;j--){
      if (A[j].i<A[j-1].i){
	/*交換*/
	p=A[j];
	A[j]=A[j-1];
