    for (j=i;j<=N-1;j++){
      if (A[j].i<A[minj].i){
	minj=j;
      }
    }
    /*交換*/
    if(i!=minj){
      p=A[i];
      A[i]=A[minj];
      A[minj]=p; 
    }
  }

}

