	}

	printf("\n");

}

void bubbleSort(Card data[], int n){

	int i, j;
	Card temp;

	for(i=0; i<n; i++){

		for(j=n-1; j>i; j--){

			if(data[j-1].num > data[j].num){

				temp = data[j];
				data[j] = data[j-1];
				data[j-1] = temp;

			}

		}

	}


}



void selectionSort(Card data[], int n){

	int i, min;
	Card temp;

	for(i=0; i<n/2; i++){

		min = getMin(data, i , n);

		temp = data[min];
		data[min] = data[i];
		data[i] = temp;

	}

}



void judge(int b){

	if(b){

		printf("Stable\n");

	}
	else{

		printf("Not Stable\n");

	}

}



int isStable(Card data[], int n){

	int i;
	int ret = 1;

	for(i=0; i<n; i++){

		if(data[i].order >= 2){

			if(data[i-1].num != data[i].num){

				ret = 0;
				break;

			}
			else if(data[i-1].order != (data[i].order-1)){

				ret = 0;
				break;

			}

		}

	}

	return ret;

}



int getMin(Card data[], int from, int to){

	int i;
	int min = from;

	for(i=from+1; i<to; i++){

		if(data[i].num < data[min].num){

			min = i;

		}

	}

	return min;

}

