}

void getcarddata(int n)
{
	int i;
	for (i = 0; i < n; i++)
	{
		a[i].mark = getchar();
		a[i].num = getchar();
		a[i].id = i;
		getchar();
	}
	a[i].num = 0;
}

void swapcard(trumpcard *d, int i, int j)
{
	trumpcard tmp;
	tmp = d[i];
	d[i] = d[j];
	d[j] = tmp;
}

void bubble_sort(trumpcard *d, int n)
{
	int i, j;
	for (i = 0; i < n; i++)
		for (j = n-1; i<j; j--)
			if (d[j].num < d[j-1].num)
				swapcard(d, j, j-1);
}

void selection_sort(trumpcard *d, int n)
{
	int i,j, minj;
	for (i = 0; i <n; i++){
		minj = i;
		for (j = i; j < n; j++)
			if (d[j].num < d[minj].num)
				minj = j;
		swapcard(d, i, minj);
	}
}

int check_stable(trumpcard *d, int n)
{
	int flag = -1;
	for (int i =0; i < n-1; i++)
		if ((d[i].num == d[i+1].num && d[i].id > d[i+1].id))
			flag = 0;
	return flag;
}

