void swap(Card *a,Card *b){
  Card temp;
  temp = *a;
  *a = *b;
  *b = temp;
}

void bubbleSort(Card *c,int N){
  int i,j;
  for(i = 0 ; i < N ; i++){
    for(j = N-1 ; j > i ; j--){
      if(c[j].num < c[j-1].num){
        swap(&c[j],&c[j-1]);
      }
    }
  }
}

void selectionSort(Card *c,int N){
  int i,j,min;
  for(i = 0 ; i < N ; i++){
    min = i;
    for(j = i+1 ; j < N ; j++){
      if(c[j].num < c[min].num){
        min = j;
      }
    }
    swap(&c[i],&c[min]);
  }
}

