#include<stdio.h>
#include<stdlib.h>

struct Card {
  char suit;
  char value;
};

void bubble(struct Card *C, int n) {
  int i, j;
  char temp;

  for(i = 0; i < n; i++) {
    for(j = n-1; j > i; j--) {
      if(C[j-1].value > C[j].value) {
	temp = C[j].value;
	C[j].value = C[j-1].value;
	C[j-1].value = temp;
	temp = C[j].suit;
	C[j].suit = C[j-1].suit;
	C[j-1].suit = temp;
      }
    }
  }
}

void selection(struct Card *C, int n) {
  int i, j, min;
  char temp;

  for(i = 0; i < n; i++) {
    min = i;
    for(j = i; j < n; j++) {
      if(C[j].value < C[min].value) {
	min = j;
      }
    }
    if(min != i) {
	temp = C[i].value;
	C[i].value = C[min].value;
	C[min].value = temp;
	temp = C[i].suit;
	C[i].suit = C[min].suit;
	C[min].suit = temp;
    }
  }
}

