void a_swap(char C[][3], int i)
{
  char temp1;
  char temp2;

  temp1=C[i][0];
  C[i][0]=C[i-1][0];
  C[i-1][0]=temp1;

  temp2=C[i][1];
  C[i][1]=C[i-1][1];
  C[i-1][1]=temp2;
}

void b_swap(char C[][3], int j ,int minj)
{
  char temp1;
  char temp2;

  temp1=C[j][0];
  C[j][0]=C[minj][0];
  C[minj][0]=temp1;

  temp2=C[j][1];
  C[j][1]=C[minj][1];
  C[minj][1]=temp2;
}

void b_sort(char C[][3], int n)
{
  int i,j;

  for (i=0; i<n; i++) {
    for (j=n-1; j>i; j--) {
      if (C[j][1]<C[j-1][1]) {
        a_swap(C,j);
      }
    }
  }
}

void s_sort(char C[][3], int n)
{
  int i,j;
  int minj;

  for (i=0; i<n; i++) {
    minj=i;
    for (j=i; j<n; j++) {
      if (C[j][1]<C[minj][1]) {
        minj=j;
      }
    }
    b_swap(C,i,minj);
  }
}

