int isStable(Node *C, Node *C1, int n){

  int i;

  for(i=0; i<n; i++){
    if(C[i].value != C1[i].value) return 0;
  }

  return 1;

}

void BubbleSort(Node *C, int n){

  int i, j;
  Node tmp;

  for(i=0; i<n-1; i++){
    for(j=n-1; j>i; j--){
      if(C[j].num < C[j-1].num){
	tmp = C[j];
	C[j] = C[j-1];
	C[j-1] = tmp;
      }
    }
  }
}

void SelectionSort(Node *C1, int n){

  int i, j, minj;
  Node tmp;

   for(i=0; i<=n-1; i++){
     minj = i;
     for(j=i; j<=n-1; j++){
       if(C1[j].num < C1[minj].num){
	 minj = j;
       }
     }     
     tmp = C1[i];
     C1[i] = C1[minj];
     C1[minj] = tmp;
   }
}

