void BubbleSort(Card *c, int n){

  int i,j;
  Card tmp;

  for(i = 0 ; i <= n-1 ; i++){
    for(j = n-1 ; j > i ; j--){
      if(c[j].value < c[j-1].value){
    tmp = c[j];
    c[j] = c[j-1];
    c[j-1] = tmp;
      }
    }
  }

  return;

}


void SelectionSort(Card *c, int n){

  int i,minj,j;
  Card tmp;

  for(i = 0 ; i <= n-1 ; i++){
    minj = i;
    for(j = i ; j <= n-1 ; j++){
      if(c[j].value < c[minj].value){
    minj = j;
      }
    }
    tmp = c[i];
    c[i] = c[minj];
    c[minj] = tmp;

  }

  return;

}

