void Bubblesort(Card tramp[], int N){
	int i;
	Card tmp;
	int flag = 1;

	while (flag) {
		flag = 0;
		for (i = 1; i<N; i++) {
			if (tramp[i].num>tramp[i + 1].num) {
				tmp= tramp[i];
				tramp[i] = tramp[i + 1];
				tramp[i + 1] = tmp;

				flag = 1;
			}
		}
	}

}


