void bub_sort(Card c[],int n){
  int k,i,stable=0,j;
  Card a;
  for(i = 0; i < n-1; ++i){
    for(j=n-1;j>=1;j--){
      if(c[j].num<c[j-1].num){
	a=c[j];
	c[j]=c[j-1];
	c[j-1]=a;
      }
    }
  }
  stable = 1;
  for(i = 0; i < n; i++){
    if(i)printf(" ");
    printf("%c%d",c[i].suit,c[i].num);
    if(i > 0 && c[i].num == c[i-1].num && c[i].order < c[i-1].order) stable=0;
  }
  printf("\n");
  puts((stable ? "Stable" : "Not stable"));
}


void selec_sort(Card c[] ,int n){
  int i,j,minj,stable;
  Card a;
  for(i=0; i<n; i++){
    minj = i;
    for(j = i; j < n; j++){
      if(c[j].num < c[minj].num)
	minj = j;
    }
    a = c[i];
    c[i]=c[minj];
    c[minj]=a;
  }
  stable = 1;
  for(i=0; i < n; i++){
    if(i)printf(" ");
