  return 0;
}

#include<stdio.h>

#define M 36



typedef struct{
  char mark;
  int value;
} Data;

  Data A[M],B[M];



void Bubblesort(Data *C,int N){

  int i,j;
  Data k;

  for(i=0;i<N;i++){
    for(j=N-1;j>i;j--){
      if(C[j].value < C[j-1].value){
	k = C[j];
	C[j] = C[j-1];
	C[j-1] = k;
      }
    }
  }
}

void SelectionSort(Data *C, int N){

  int i,j,minj;
  Data k;

  for(i=0;i<N;i++){
    minj = i;
    for(j=i;j<N;j++){
      if(C[j].value < C[minj].value) minj = j;
    }

    k = C[i];
    C[i] = C[minj];
    C[minj] = k;
  }

}

int isStable(Data *A,Data *B,int n)
{
  int i;
  for(i=0;i<n;i++)
    {
      if(A[i].mark != B[i].mark)return 0;
    }
  return 1;
}


