	for (i = 1; i < n; i++)
	{
		j = i;
		while (j >= 1 && (p[j] < p[j - 1]))
		{
			swap(&p[j], &p[j - 1]);
			j--;
		}

		for (k = 0; k < n-1; k++)
			printf("%d ", p[k]);

		printf("%d\n",p[n-1]);
	}
}

int GCD(int x, int y)
{
	if (x < y)
		swap(&x, &y);

	if (y == 0)
		return x;

	return GCD(y, x % y);
}

int not_prime_count(int p[], int n)
{
	int count = 0;
	int i, j;
	int num;

	for (i = 0; i < n; i++)
	{
		for (j = 2; j < (int)(sqrt(p[i])+1); j++)
		{
			if (p[i] % j == 0)
			{
				count++;
				break;
			}
		}
	}
	return count;
}

