  Card temp;

  for(i = n; i > 0; i--){
    flag = 0;
    for(j = 1; j < i; j++){
      if(a[j-1].num > a[j].num){
	temp = a[j-1];
	a[j-1] = a[j];
	a[j] = temp;
	flag = 1;
      }
    }
    if(flag == 0)  break;
  }
}


void SelectionSort(Card *a, int n){
  int min, i, j;
  Card temp;

  for(i = 0; i < n-1; i++){
    min = i;
    for(j = i+1; j < n; j++){
      if(a[min].num > a[j].num){
	min = j;
      }
    }
    if(min != i){
      temp = a[i];
      a[i] = a[min];
      a[min] = temp;
    }
  }
}

