	};



void bubble(struct Card A[],int N) {
	int i, j;
	for (i = 0;i < N;i++) {
		for (j = N - 1;j >= i + 1;j--) {
			if (A[j].value < A[j - 1].value) {
				struct Card t = A[j];
				A[j] = A[j - 1];
				A[j - 1] = t;
			}
		}
	}
}

void selection(struct Card A[],int N) {
	int i, j;
	for (i = 0;i < N;i++) {
		int minj = i;
		for (j = i;j < N;j++) {
			if (A[j].value < A[minj].value)minj = j;
		}
		struct Card t=A[i];
		A[i] = A[minj];
		A[minj] = t;
	}
}

