	int i;
	for (i = 0;i < N;i++) {
		if (i >0)printf(" ");
		printf("%c%c",A[i].suit,A[i].value);
	}
	printf("\n");
}

bool isStable(struct Card C1[],struct Card C2[],int N) {
	int i;
	for (i = 0;i < N;i++) {
		if (C1[i].suit != C2[i].suit)return false;
	}
	return true;
}


