#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
  char suit;
  int value;
} Card;


void ChkIfStable(Card *c1, Card *c2, int n)
{
  int v, k;
  char a1[n];
  char a2[n];
  int len1, len2;
  len1 = len2 = 0;
  for (v=1; v<10; v++) {
    len1=0;
    for (k=0; k<n; k++) {
      if (c1[k].value == v) a1[len1++] = c1[k].suit;
    }
    a1[len1]=0;
    len2=0;
    for (k=0; k<n; k++) {
      if (c2[k].value == v) a2[len2++] = c2[k].suit;
    }
    a2[len2]=0;
    if (strcmp(a1,a2)) {
      fputs("Not stable\n", stdout);
      return;
    }
  }
  fputs("Stable\n", stdout);
}


void BubbleSort(Card *c, int n)
{
  int i, j;
  for (i=0; i<n; i++) {
    for (j=n-1; j>=i+1; j--) {
      if (c[j].value < c[j-1].value) {
	Card tmp = c[j];
	c[j] = c[j-1];
	c[j-1] = tmp;
      }
    }
  }
}


void  SelectionSort(Card *c, int n)
{
  int i, j, mini;
  for (i=0; i<n; i++) {
    mini = i;
    for (j=i; j<n; j++) {
      if (c[j].value < c[mini].value)	mini = j;
    }
    if (i!=mini) {
      Card tmp = c[i];
      c[i] = c[mini];
      c[mini] = tmp;
    }
  }
}

