	stbFlg = 0;
	break;
      }

      // add a checked number to array
      checkNum[k] = Ccopy[i].num;
      k++;

      // initializing mark array
      memset(markOri, 0, sizeof(markOri));
      memset(markSort, 0, sizeof(markSort));
    }
  }
  return stbFlg;
}

