     if (trump[j].num < trump[j-1].num) {
       box1  = trump[j-1].num;
       box2  = trump[j-1].mark[0];      
       trump[j-1].num     = trump[j].num;
       trump[j-1].mark[0] = trump[j].mark[0];
       trump[j].num     = box1;
       trump[j].mark[0] = box2;
     }
   }
 }

 for(i = 1;i < kosuu;i++){
   printf("%c%d ", trump[i].mark[0], trump[i].num);
 }
