 printf("Stable\n");
 return 0;
}

int select(int kosuu, card trump[])
{
 int i, j,  min, minnum, box1;
 char box2;

 for(i = 1;i <= kosuu;i++){
   min = trump[i].num;
   for(j = i + 1;j <= kosuu;j++){
     if(trump[j].num < min){
       min = trump[j].num;
       minnum = j;
     }
   }
   if(min < trump[i].num){
      box1  = trump[i].num;
      box2  = trump[i].mark[0];
      trump[i].num     = min;
      trump[i].mark[0] = trump[minnum].mark[0];
      trump[minnum].num     = box1;
      trump[minnum].mark[0] = box2;
   }
 }

 for(i = 1;i < kosuu;i++){
   printf("%c%d ", trump[i].mark[0], trump[i].num);
 }
 printf("%c%d\n", trump[i].mark[0], trump[i].num);
 printf("Stable\n");
 return 0;
}

