int judge(Data C[], Data D[], int N){
  int i;

  for(i = 0;i < N;i++){
    if(C[i].suit != D[i].suit || C[i].value != D[i].value){
      return 1;
    }
  }
  return 0;
}

void bubbleSort(Data C[], int N){
  int i,j;
  Data a;

  for(i = 0;i < N;i++){
    for(j = N-1;j >= i+1;j--){
      if(C[j].value < C[j-1].value){
	a = C[j];
	C[j] = C[j-1];
	C[j-1]  = a;
      }
    }
  }
