void bubbleSort(CARD *c,int N){
  int i,j;
  CARD temp;
  for(i=0;i<N;i++){
    for(j=N-1;j>=i+1;j--){
      if(c[j].num < c[j-1].num){
	temp = c[j];
	c[j] = c[j-1];
	c[j-1] = temp;
      }
    }
  }
}

void selectionSort(CARD *c,int N){
  int i,j,min;
  CARD temp;
  for(i = 0;i<N;i++){
    min = i;
    for (j = i;j<N;j++){
      if(c[j].num < c[min].num){
	min = j;
      }
    }
    temp = c[i];
    c[i] = c[min];
    c[min] = temp;
  }
}

