void BubbleSort(data *C, int N)
{
  int i, j;

  for(i=0; i<N-1; i++)
    {
      for(j=N-1; j>i; j--)
	{
	  if(C[j].val < C[j-1].val)
	    {
	      swap(&C[j], &C[j-1]);
	    }
	}
    }
}

void SelectionSort(data *C, int N)
{
  int i, j;
  int minj;

  for(i=0; i<N-1; i++)
    {
      minj = i;

      for(j=i+1; j<N; j++)
	{
	  if(C[j].val < C[minj].val)
	    {
	      minj = j;
	    }
	  if(minj != i)
	    {
	      swap(&C[i], &C[minj]);
	    }
	}
    }
}

void swap(data *a, data *b)
{
  data tmp;
  tmp = *a;
  *a = *b;
  *b = tmp;
}

