	int i, j;
	Card tmp;
	for (i = 0; i < N; ++i) {
		for (j = N - 1; j >= i +1 ; --j) {
			if (C[j].num < C[j-1].num) {
				tmp = C[j];
				C[j] = C[j-1];
				C[j - 1] = tmp;
			}
		}
	}
	return;
}

