void BubbleSort(CARD *B,int n){
  int i,j;
  CARD temp;

  for(i=0;i<n;i++){
    for(j=n-1;j>i;j--){
      if(B[j].value<B[j-1].value){
	temp=B[j];
	B[j]=B[j-1];
	B[j-1]=temp;
      }
    }
  }

  return;
}

void SelectionSort(CARD *S,int n){
  int i,j,min;
  CARD temp;

  for(i=0;i<n;i++){
    min=i;
    for(j=i;j<n;j++){
      if(S[j].value<S[min].value) min=j;
    }
    temp=S[i];
    S[i]=S[min];
    S[min]=temp;
  }

  return;
}

