void BubbleSort(trump *card,int N){
  int i,flag,swap;
  char temp[MAX];


  flag = 1;
  while(flag){
    flag = 0;
    for(i=N-1; i>=1; i--){
      if(card[i].num < card[i-1].num){
	*temp = card[i].mark;
	card[i].mark = card[i-1].mark;
	card[i-1].mark = *temp;
	swap = card[i].num;
	card[i].num = card[i-1].num;
	card[i-1].num = swap;
	flag = 1;
      }
    }
  }

  for(i=0; i<N; i++){
    printf("%c%d",card[i].mark,card[i].num);
    if(i==N-1) break;
    printf(" ");
  }
  printf("\n");

}

void SelectionSort(trump *card, int N){
  int i,j,minj,swap;
  char temp[MAX];

  for(i=0; i<N; i++){
    minj = i;
    for(j=i; j<N; j++){
      if(card[j].num < card[minj].num) minj = j;
    }
    if(i!=minj){
      *temp = card[i].mark;
      card[i].mark = card[minj].mark;
      card[minj].mark = *temp;
      swap = card[i].num;
      card[i].num = card[minj].num;
      card[minj].num = swap;
    }
  }
  for(i=0; i<N; i++){
    printf("%c%d",card[i].mark,card[i].num);
    if(i==N-1) break;
    printf(" ");
  }
  printf("\n");

}

