        p2[i] = p1[i];
    }
    bubbleSort(p1, n);
    selectionSort(p2, n);
    showArray(p1, n);
    printf("Stable\n");
    showArray(p2, n);
    if (isStable(p1, p2, n)) {
        printf("Stable\n");
    }
    else {
        printf("Not stable\n");
    }
    return 0;
}

