typedef struct{
  char suit;
  int value;
} Card;

void bubble(Card *A,int N){
  int i,j;
  Card temp;
  for(i=0 ; i<N ; i++){
    for(j=N-1 ; j>=i+1 ; j--){
      if(A[j].value < A[j-1].value){
        temp = A[j];
        A[j] = A[j-1];
        A[j-1] = temp;
      }
    }
  }
}

void selection(Card *A,int N){
  int i,j,minj;
  Card temp;
  for(i=0 ; i<N ; i++){
    minj = i;
    for(j=i ; j<N ; j++){
      if(A[j].value < A[minj].value) minj = j;
    }
    temp = A[i];
    A[i] = A[minj];
    A[minj] = temp;
  }
}

void print(Card *A,int N){
  int i;
  for(i=0 ; i<N ; i++){
    if(i == N-1) printf("%c%d\n",A[i].suit,A[i].value);
    else printf("%c%d ",A[i].suit,A[i].value);
  }
}

