void BubbleSort(Card C[],int N){
  int i,j,flag;

  flag = 1;

  while(flag){
    flag = 0;
    for(i=0;i < N;i++){
for(j=N-1;j >= i+1;j--){

        if( C[j].value < C[j-1].value ){
          swap(&C[j],&C[j-1]);

          flag = 1;

        }
      }
    }
  }
}

void SelectionSort(Card C[],int N){
  int i,j,minj;


  for(i=0;i<N-1;i++){
    minj=i;
    for(j=i;j < N;j++){
      if( C[j].value < C[minj].value){
        minj = j;
      }
    }
        swap(&C[i],&C[minj]);
    }
}



