		copy[i].mark=original[i].mark;
		copy[i].num=original[i].num;
	}
}

void card_change(card_t* a,card_t* b){
	char tmp_m;
	int tmp_n;

	tmp_m=a->mark;
	a->mark=b->mark;
	b->mark=tmp_m;

	tmp_n=a->num;
	a->num=b->num;
	b->num=tmp_n;
}

