  int n,i;

  scanf("%d",&n);
  for(i=0;i<n;i++){
    scanf(" %c%d",&ori[i].form,&ori[i].num);
    a[i]=b[i]=ori[i];
  }

  bubblesort(a,n);
  selectionsort(b,n);
  print(a,b,n);

  return 0;
}

