int BubbleSort(int A[],int N){
  int i,j,count=0,tmp;

  for(i = 0 ; i < N-1 ; i++){
    for(j = N-1 ; j >= 1 ; j--){
      if(A[j] < A[j - 1]){
	tmp = A[j];
	A[j] = A[j - 1];
	A[j - 1] = tmp;
	count++;
      }
    }
  }
  return count;
}


