int isStable(Card *IN, Card *OUT, int N) {
  int i, j, a, b;
  for ( i=0; i<N; i++ )
    for ( j=(i+1); j<N; j++ )
      for ( a=0; a<N; a++ )
	for ( b=(a+1); b<N; b++ )
	  if ( (IN[i].value == IN[j].value)
	       && (IN[i].mark == OUT[b].mark)
	       && (IN[i].value == OUT[b].value)
	       && (IN[j].mark == OUT[a].mark)
	       && (IN[j].value == OUT[a].value) ) return 0;
  return 1;
}

