			if(array[j][1] - '0' < array[min][1] - '0'){
				min = j;
			}
		}
		if(i != min){
			strcpy(tmp,array[i]);
			strcpy(array[i],array[min]);
			strcpy(array[min],tmp);
		}
	}
}

void bubbleSort(char array[ARRAY_SIZE][3],int n){

	char tmp[3];
	for(int i = n-1; i >0; i--){
		for(int j = 0; j < i; j++){
			if(array[j][1] - '0' > array[j+1][1] - '0'){
				strcpy(tmp,array[j+1]);
				strcpy(array[j+1],array[j]);
				strcpy(array[j],tmp);
			}
		}
	}
}

