void swap(int *p1, int *p2){
  int tmp;

  tmp = *p1;
  *p1 = *p2;
  *p2 = tmp;

}

void swap_char(char *p1, char *p2){
  char tmpc;

  tmpc = *p1;
  *p1 = *p2;
  *p2 = tmpc;

}

int isStable(Card *p1, Card *p2, int n){
