void bubble(card *p,int N){
	card key;
	int i,j;
	for(i=0;i<N;i++){
		for(j=N-1;j>i;j--){
			if(p[j].value<p[j-1].value){
				key=p[j];
				p[j]=p[j-1];
				p[j-1]=key;
			}
		}
	}
}

int selection(card *p,int N){
	card key;
	int i,j,min,f,l;
	for(i=0;i<N;i++){
		min=i;
		f=0;
		for(j=i+1;j<N;j++){
			if(p[j].value==p[min].value) f=1;
			if(p[j].value<p[min].value){
				min=j;
				if(f==1) l=1;
			}
		}
		if(min!=i){
			key=p[i];
			p[i]=p[min];
			p[min]=key;
		}
	}
	if(l==1) return 1;
	else return 0;
}

