int main(void)
{
    int card_num;
    CARD card[CARD_NUM_MAX];
    CARD cpy[CARD_NUM_MAX];

    if(get_int(&card_num, CARD_NUM_MIN, CARD_NUM_MAX) == -1)
    {
        return -1;
    }    

    get_card_info(&card[0], card_num);

    memcpy(&cpy[0], &card[0], sizeof(CARD) * card_num);

