    put_card_info(&cpy[0], card_num);

    if(memcmp(&cpy[0], &card[0], sizeof(CARD) * card_num) != 0)
    {
        printf("Not Stable\n");
    }
    else
    {
        printf("Stable\n");
    }

    return 0;
