void trace( char A[][3], int n )
{
	int i=0;
	while( i<n ) {
		printf( "%s", A[i++] );
		if( i != n ) { printf( " " ); }
	}
	printf( "\n" );

	return;
}

void BubbleSort( char A[][3], int n ) 
{
	int i,j;
	char tmp[3];

	for( i=0; i<n; i++ ) {
		for( j=n-1; i<j; j-- ) {
			if( A[j][1]-'0' < A[j-1][1]-'0' ) {
				strncpy( tmp, A[j-1], 3 );
				strncpy( A[j-1], A[j], 3 );
				strncpy( A[j], tmp, 3 );
			}
		}
	}

	trace( A, n );

	return;
}

void SelectionSort( char A[][3], int n ) 
{
	int i,j;
	char tmp[3];
	int mini;

	for( i=0; i<n; i++ ) {
		mini=i;
		for( j=i; j<n; j++ ) {
			if( A[j][1]-'0' < A[mini][1]-'0' ) {
				mini=j;
			}
		}
		if( mini != i ) {
			strncpy( tmp, A[i], 3 );
			strncpy( A[i], A[mini], 3 );
			strncpy( A[mini], tmp, 3 );
		}
	}

	trace( A, n );

	return;
}

