void bubble(Card array[],int n){
	int i,j;
	Card p;
	for(i = 0; i < n-1 ; i++){
    for(j = n-1; j > i ; j --){
      if(array[j-1].num > array[j].num){
        p = array[j];
        array[j] = array[j-1];
        array[j-1] = p;
       }
    }
  }
}
void sel(Card array[],int n){
	int lowkey,lowest,i,j;
	Card t;
	for(i=0;i<n;i++){
    lowkey = array[i].num;
    lowest = i;
    for(j=i+1;j<n;j++){
      if(lowkey > array[j].num){
        lowkey = array[j].num;
        lowest = j;
      }
    }
    t = array[i];
   	array[i] = array[lowest];
    array[lowest] = t;
  }
}
