    for(j=n-1;j>=i+1;j--){
      if(C[j].value<C[j-1].value ){
        cng=C[j];
        C[j]=C[j-1];
        C[j-1]=cng;
      }
    }
  }
}
void SelectionSort(Card C[], int n){
  int i,j,min;
  Card cng;

  for(i=0;i<=n-2;i++){
    min=i;
    for(j=i;j<=n-1;j++){
      if(C[j].value<C[min].value){
    min=j;
      }
    }
    cng=C[i];
    C[i]=C[min];
    C[min]=cng;
  }
}

