void bubbleSort(struct CARD A[],int N)
{
	struct CARD t;
	int flag=1,j;
	int i=0;
	for (i=0;flag;i++){
		flag=0;
		for (j=N-1;j>=i+1;j--){
			if (A[j].num<A[j-1].num){
				t=A[j];A[j]=A[j-1];A[j-1]=t;
				flag=1;
			}
		}
	}
}

void selectSort(struct CARD A[],int N)
{
	struct CARD t;
	int minj,j,i;
	for (i=0;i<N-1;i++){
		minj=i;
		for (j=i+1;j<N;j++){
			if (A[j].num<A[minj].num)minj=j;
		}
		t=A[i];A[i]=A[minj];A[minj]=t;
	}
}

