 } 

void isStable(struct CARD input[],struct CARD output[],int N)
 {
 	int i,j,k,m,ct;
 	for (i=0;i<N-1;i=i+m){
 		ct=1;
 		for (j=i+1;j<N;j++){
 			if (output[i].num==output[j].num)
 			ct++;
		 }
		 m=ct;
		 if (ct>1){
		 	for(k=0;ct>1;k++){
		 		if (output[i+m-ct].num==input[k].num){
		 			if (output[i+m-ct].color==input[k].color){
		 				ct--;
		 				continue;
					 }
					 else{
					 	printf("Not stable\n");
					 	return;
					 }
				 }
			 }
		 }
	 }
	 printf("Stable\n");
}

