int_swap(int *x, int *y) {
  int tmp;
  tmp = *x;
  *x  = *y;
  *y  = tmp;
}

void char_swap(char *x, char *y) {
  char tmp;
  tmp = *x;
  *x  = *y;
  *y  = tmp;
}

