void swap( card *a,   card *b)
{
  card t;
  t = *a;
  *a  = *b;
  *b =t;
}


 void BubbleSort(  card *C, int N)
 {
   int i,j;
   for(i=0;i < N-1;i++) {
     for(j =N-1;j>=i;j--) {
       if(C[j].value < C[j-1].value) swap(&C[j],&C[j-1]);
     }
   }
 }

void SelectionSort( card *C, int N)
 {
   int i,j,minj;
   for(i=0;i<N;i++) {
     minj = i;
     for(j=i;j<N;j++){
       if(C[j].value < C[minj].value)minj =j;
     }
       swap( &C[i] , &C[minj]);
   }
 }

