  for(i = 0; i < N; i++) {
    scanf("%s", c);    
    A[i] = mark2num(c[0]) * 9 + (c[1]-'0')-1;
  }
  BubbleSort(A, N);
  SelectionSort(A, N);
  return 0;
}

