void swap(Card *in,Card *out)
{
  Card temp;
  int i,j;
  temp.mark = out->mark;
  temp.value = out->value;
  temp.prev = out->prev;
  out->mark = in->mark;
  out->value = in->value;
  out->prev = in->prev;
  in->mark = temp.mark;
  in->value = temp.value;
  in->prev = temp.prev;
}

