  int i,j;
  struct cards tmp;
  for(i=0;i<n;i++){
    for(j=n-1;j>=i;j--){
      if(p[j].Value<p[j-1].Value){
        tmp=p[j];
        p[j]=p[j-1];
        p[j-1]=tmp;
      }
    }
  }
}

void selection(struct cards p[],int n){
  int i,j,minj;
  struct cards tmp;
  for(i=0;i<n;i++){
    minj=i;
    for(j=i;j<n;j++){
      if(p[j].Value<p[minj].Value) minj=j;
    }
    tmp=p[i];
    p[i]=p[minj];
    p[minj]=tmp;
  }
}

