void bubbleSort(Card *A, int n){
	int sw = 0, i, j;

	for(i = 0; i < n-1; i++){
		for(j = n-1; j > i; j--){
			if(A[j].value < A[j - 1].value) swap(A, j, j-1);
		}
	}
}


void selectionSort(Card *A, int n){
	int min_id, i, j, sw = 0;

	for(i = 0; i < n - 1; i++){
		min_id = i;
		for(j = i+1; j < n; j++){
			if(A[j].value < A[min_id].value){
				min_id = j;
			}
		}

		if(min_id != i) 	swap(A, i, min_id);
	}

}

void swap(Card *A, int x, int y){
	Card temp = A[x];
	A[x] =  A[y];
	A[y] = temp;
}

