  int i;

  for(i = 0; i < n - 1; i++) printf("%c%d " ,C[i].mark ,C[i].num);
  printf("%c%d\n" ,C[n - 1].mark ,C[n - 1].num);
  printf("Stable\n");
  printf("Not stable\n");

}

void judge(int n, Card *C, Card *F){

  Card check;
  int i, j;

  for(i = 0; i < n; i++){
    for(j = i + 1; j < n; j++){
      if(C[i].num == C[j].num){
	check[i].mark = C[i].mark;
	check[i].num = C[i].num;
      }
    }
  }

  for(i = 0; i < n; i++){
    for(j = i + 1; j < n; j++){
      if(F[i].num == check[j].num){
	if(F[i].mark == check[j].mark) printf("Stable\n");
	else printf("Not stable\n");
      }
    }
  }

}

