fun isStable(original: Array<String>, sorted: Array<String>): Boolean {
    val joinedOriginalByNumber = listOf(
        filterCards(original, 1),
        filterCards(original, 2),
        filterCards(original, 3),
        filterCards(original, 4),
        filterCards(original, 5),
        filterCards(original, 6),
        filterCards(original, 7),
        filterCards(original, 8),
        filterCards(original, 9)
    )
    val joinedSortedByNumber = listOf(
        filterCards(sorted, 1),
        filterCards(sorted, 2),
        filterCards(sorted, 3),
        filterCards(sorted, 4),
        filterCards(sorted, 5),
        filterCards(sorted, 6),
        filterCards(sorted, 7),
        filterCards(sorted, 8),
        filterCards(sorted, 9)
    )
    for (i in 1..9) {
        if (joinedOriginalByNumber[i-1] != joinedSortedByNumber[i-1]) {
            return false
        }
    }

    return true
}

