class CardComparator : Comparator<String> {

    override fun compare(o1: String?, o2: String?): Int {
        if (o1 == null && o2 == null) {
            throw IllegalArgumentException("o1 and o2 are null.")
        }
        if (o1 == null) {
            throw IllegalArgumentException("o1 is null.")
        }
        if (o2 == null) {
            throw IllegalArgumentException("o2 is null.")
        }
        if (o1.length != 2) {
            throw IllegalArgumentException("o1 [$o1] is an invalid format.")
        }
        if (o2.length != 2) {
            throw IllegalArgumentException("o2 [$o2] is an invalid format.")
        }

        val num1 = o1.substring(1, 2).toInt(10)
        val num2 = o2.substring(1, 2).toInt(10)

        return num1 - num2
    }

}

