  var c = cards.toMutableList()
  for (i in (0 until n)) {
    for (j in (n-1 downTo i+1)) {
      val x = Integer.valueOf(c[j][1].toString())
      val y = Integer.valueOf(c[j-1][1].toString())
      if (x < y) {
        val tmp = c[j]
        c[j] = c[j-1]
        c[j-1] = tmp
      }
    }
  }
  return c
}

fun selectionSort(cards: List<String>, n: Int) : List<String> {
  var c = cards.toMutableList()
  (0 until n).forEach { i ->
    var minX = i
    (i until n).forEach { j ->
      val a = Integer.valueOf(c[j][1].toString())
      val b = Integer.valueOf(c[minX][1].toString())
      if (a < b) {
        minX = j
      }
    }
