fun isStable(inArr: List<String>, outArr: List<String>, n: Int): Boolean {
  for (i in (0 until n)) {
    for (j in (i+1 until n)) {
      for (a in (0 until n)) {
        for (b in (a+1 until n)) {
          if (inArr[i][1] == inArr[j][1] && inArr[i] == outArr[b] && inArr[j] == outArr[a]) {
            return false
          }
        }
      }
    }
  }
  return true
}

