fun bubbleSort(array: Array<String>) {
    for (i in array.indices) {
        for (j in array.size - 2 downTo i) {
            if (compare(array[j], array[j+1])) {
                array.swap(j, j+1)
            }
        }
    }
}

fun selectionSort(array: Array<String>) {
    for (i in 0 until array.size - 1) {
        var min = i
        for (j in i + 1 until array.size) {
            if (compare(array[min], array[j])) {
                min = j
            }
        }
        if (min != i) {
            array.swap(i, min)
        }
    }
}

