	private static void selectionSort(String[] arrayString, int num) {

		for(int i=0;i<num;i++){
			int min=i;
			for(int j=i;j<num;j++){
				if(getNum(arrayString[j])<getNum(arrayString[min])){
					min=j;
				}
			}
			if(min!=i){
			String tmp=arrayString[i];
			arrayString[i]=arrayString[min];
			arrayString[min]=tmp;

			}
		}

		for(int i=0;i<arrayString.length;i++){
			System.out.printf("%s",arrayString[i]);
			if(i!=arrayString.length-1){
				System.out.printf(" ");
			}
		}
		System.out.println("");
	}

	private static void bubbleSort(String[] arrayString, int num) {
		boolean flag=true;


		while(flag){
			flag=false;
			for(int i=num-1;i>=1;i--){
				if(getNum(arrayString[i])<getNum(arrayString[i-1])){
					String tmp=arrayString[i];
					arrayString[i]=arrayString[i-1];
					arrayString[i-1]=tmp;
					flag=true;

				}
			}
		}
		for(int i=0;i<arrayString.length;i++){
			System.out.printf("%s",arrayString[i]);
			if(i!=arrayString.length-1){
				System.out.printf(" ");
			}
		}
		System.out.println("");
	}
	public static  int getNum(String card){
		return Integer.parseInt(card.substring(1,2));
	}

	public static boolean isStable(String[] arrayString1,String[] arrayString2 ,int num){
		for(int i=0;i<num;i++){
			if(!arrayString1[i].equals(arrayString2[i])){
				return false;
			}
		}
		return true;
	}
}

import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);

		int n = scan.nextInt();

		int[] num = new int[n];
		char[] mark = new char[n];

		for (int i = 0; i < n; i++) {
			String s = scan.next();
			mark[i] = s.charAt(0);
			num[i] = s.charAt(1) - '0';
		}

		int[] a = new int[num.length];
		char[] m = new char[num.length];
		for (int i = 0; i < num.length; i++) {
			a[i] = num[i];
			m[i] = mark[i];
		}
		runBub(m, a);

		int[] a1 = new int[num.length];
		char[] m1 = new char[num.length];
		for (int i = 0; i < num.length; i++) {
			a1[i] = num[i];
			m1[i] = mark[i];
		}

		runSel(m1, a1);
		int ic;
		for (ic = 0; ic < mark.length; ic++)
			if (m1[ic] != m[ic])
				break;
		if (ic < mark.length)
			System.out.println("Not stable");
		else
			System.out.println("Stable");

		scan.close();
		System.exit(0);
	}

	private static void runSel(char[] m, int[] a) {
		for (int i = 0; i < a.length; i++) {
			int min = i;
			for (int j = i; j < a.length; j++)
				if (a[j] < a[min])
					min = j;
			if (min != i) {
				int tmp = a[i];
				a[i] = a[min];
				a[min] = tmp;
				char tmpc = m[i];
				m[i] = m[min];
				m[min] = tmpc;
			}
		}

		outResult(m, a);
	}

	private static void runBub(char[] m, int[] a) {
		for (int i = 0; i < a.length; i++)
			for (int j = a.length - 1; j > i; j--)
				if (a[j] < a[j - 1]) {
					int tmp = a[j];
					a[j] = a[j - 1];
					a[j - 1] = tmp;
					char tmpc = m[j];
					m[j] = m[j - 1];
					m[j - 1] = tmpc;
				}

		outResult(m, a);
		System.out.println("Stable");
	}

	private static void outResult(char[] m, int[] a) {
		for (int i = 0; i < m.length; i++)
			if (i == 0)
				System.out.print("" + m[i] + a[i]);
			else
				System.out.print(" " + m[i] + a[i]);
		System.out.println();

	}

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {

	public static void printArray(String[] cardNumBubbleSort){
		for (int i = 0; i < cardNumBubbleSort.length; i++){
			System.out.print(cardNumBubbleSort[i]);

			if (i == cardNumBubbleSort.length - 1){
				break;
			}
			System.out.print(" ");
		}
		System.out.println();
	}

	public static void main(String[] args) throws NumberFormatException, IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		int progCardNumOfSheets = Integer.parseInt(br.readLine());

		String[] card = br.readLine().split(" ");

		String[] cardNumBubbleSort = new String[progCardNumOfSheets];
		String[] cardNumSelectionSort = new String[progCardNumOfSheets];


		for(int i = 0; i < progCardNumOfSheets; i++) {
			cardNumBubbleSort[i] = card[i];
			cardNumSelectionSort[i] = card[i];
		}

		int compareNumResult = 0;
		int compareStrResult = 0;
		String compareNum1 = "";
		String compareNum2 = "";
		String compareStr1 = "";
		String compareStr2 = "";
		int sortCount = 0;
		String compareJudge= "Stable";

		boolean isSortFlag = true;

		while(isSortFlag) {
			isSortFlag = false;

			for(int i = progCardNumOfSheets - 1; i > 0; i-- ) {
				compareNum1 = cardNumBubbleSort[i].substring(1);
				compareNum2 = cardNumBubbleSort[i - 1].substring(1);
				compareNumResult = compareNum1.compareTo(compareNum2);
				if(compareNumResult < 0) {
					String tmp = cardNumBubbleSort[i - 1];
					cardNumBubbleSort[i - 1] = cardNumBubbleSort[i];
					cardNumBubbleSort[i] = tmp;
					isSortFlag = true;
					sortCount++;
				}
			}
		}
		if(sortCount != 0) {
			for(int i = progCardNumOfSheets - 1; i > 0; i-- ) {
				compareNum1 = cardNumBubbleSort[i].substring(1);
				compareNum2 = cardNumBubbleSort[i - 1].substring(1);
				compareStr1 = cardNumBubbleSort[i].substring(0);
				compareStr2 = cardNumBubbleSort[i - 1].substring(0);

				if(compareNum1.equals(compareNum2)) {
					compareStrResult = compareStr1.compareTo(compareStr2);

					if(compareStrResult < 0) {
						compareJudge = "Not stable";
					}
				}
			}
		}
		printArray(cardNumBubbleSort);
		System.out.println(compareJudge);

		int minNum = 0;
		for(int i = 0; i < progCardNumOfSheets; i++) {
			minNum = i;

			for(int j = i; j < progCardNumOfSheets; j++) {
				compareNum1 = cardNumSelectionSort[j].substring(1);
				compareNum2 = cardNumSelectionSort[minNum].substring(1);
				compareNumResult = compareNum1.compareTo(compareNum2);
				if(compareNumResult < 0) {
					minNum = j;
				}
			}
			if(i != minNum) {
				String tmp = cardNumSelectionSort[i];
				cardNumSelectionSort[i] = cardNumSelectionSort[minNum];
				cardNumSelectionSort[minNum] = tmp;
				sortCount++;
			}
		}
		if(sortCount != 0) {
			for(int i = progCardNumOfSheets - 1; i > 0; i-- ) {
				compareNum1 = cardNumSelectionSort[i].substring(1);
				compareNum2 = cardNumSelectionSort[i - 1].substring(1);
				compareStr1 = cardNumSelectionSort[i].substring(0);
				compareStr2 = cardNumSelectionSort[i - 1].substring(0);

				if(compareNum1.equals(compareNum2)) {
					compareStrResult = compareStr1.compareTo(compareStr2);

					if(compareStrResult < 0) {
						compareJudge = "Not stable";
					}
				}
			}
		}
		printArray(cardNumSelectionSort);
		System.out.println(compareJudge);
	}
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int count = sc.nextInt();
        String[] a = new String[count];
        String[] b = new String[count];
        for (int i = 0; i < count; i++) {
            String tmp = sc.next();
            a[i] = tmp;
            b[i] = tmp;
        }
        a = bubbleSort(a);
        printArray(a);
        System.out.println("Stable");
        b = selectionSort(b);
        printArray(b);
        if (Arrays.equals(a, b)) {
            System.out.println("Stable");
        } else {
            System.out.println("Not stable");
        }
    }

    private static String[] bubbleSort(String[] a) {
        boolean flag = true;
        while (flag) {
            flag = false;
            for (int i = 1; i < a.length; i++) {
                if (a[i - 1].charAt(1) > a[i].charAt(1)) {
                    String tmp = a[i];
                    a[i] = a[i - 1];
                    a[i - 1] = tmp;
                    flag = true;
                }
            }
        }
        return a;
    }

    private static void printArray(String[] array) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < array.length; i++) {
            sb.append(array[i]);
            if (i != array.length - 1) {
                sb.append(" ");
            }
        }
        System.out.println(sb);
    }

    private static String[] selectionSort(String[] a) {
        for (int i = 0; i < a.length; i++) {
            int min = i;
            for (int j = i; j < a.length; j++) {
                if (a[j].charAt(1) < a[min].charAt(1)) {
                    min = j;
                }
            }
            if (i != min) {
                String tmp = a[i];
                a[i] = a[min];
                a[min] = tmp;
            }
        }
        return a;
    }
}

