    public static boolean isStable(int n, Card[] cards1, Card[] cards2) {
        for (int i = 0; i < n; i++) {
            if (!cards1[i].equals(cards2[i])) {
                return false;
            }
        }
        return true;
    }

    public static void bubbleSort(int n, Card[] cards) {
        boolean flag = true;
        while (flag) {
            flag = false;
            for (int i = n - 1; i >= 1; i--) {
                if (cards[i].number < cards[i - 1].number) {
                    // 要素の交換
                    Card tmp = cards[i];
                    cards[i] = cards[i - 1];
                    cards[i - 1] = tmp;
                    flag = true;
                }
            }
        }
    }

    public static void selectionSort(int n, Card[] cards) {
        int minj;
        int i, j;
        for (i = 0; i < n - 1; i++) {
            minj = i;
            for (j = i; j < n; j++) {
                if (cards[minj].number > cards[j].number) {
                    minj = j;
                }
            }
            if (i != minj) {
                Card tmp;
                tmp = cards[i];
                cards[i] = cards[minj];
                cards[minj] = tmp;
            }

        }
    }

