        for(int i=0; i<n-1; i++) {
            for(int j=n-1; j>i; j--) {
                if(c[j].charAt(1)<c[j-1].charAt(1)) {
                    String tmp = c[j];
                    c[j] = c[j-1];
                    c[j-1] = tmp;
                }   
            }
        }
    }

    void selectionSort(String[] c, int n) {
        for(int i=0; i<n; i++) {
            int minj = i;
            for(int j=i; j<n; j++) {
                if(c[j].charAt(1) < c[minj].charAt(1)) {
                    minj = j;
                }
            }
                String tmp = c[i];
                c[i] = c[minj];
