    public static void BubbleSort(String[] C, int N){
        for(int i = 0; i < N; i++){
            for(int j = N - 1; j > i; j--){
                int val1 = Character.getNumericValue(C[j].charAt(1));
                int val2 = Character.getNumericValue(C[j - 1].charAt(1));
                if(val1 < val2){
                    String temp = C[j];
                    C[j] = C[j - 1];
                    C[j - 1] = temp;
                }
            }
        }
    }

    public static void SelectionSort(String[] C, int N){
        for(int i = 0; i < N; i++){
            int minj = i;
