public class Main {
    static class Card {
        public String type;
        public int num;

        public Card(String cardString) {
            type = cardString.substring(0, 1);
            num = Integer.parseInt(cardString.substring(1, 2));
        }

        public String toString() {
            return type + num;
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader r = new BufferedReader(new InputStreamReader(System.in));
        int N = readInt(r);
        String[] numStrings = r.readLine().split(" ");
        Card[] A1 = new Card[N];
        Card[] A2 = new Card[N];
        for (int i = 0;i < N;i++) {
            A1[i] = new Card(numStrings[i]);
            A2[i] = new Card(numStrings[i]);
        }
        bubbleSort(A1, N);
        selectionSort(A2, N);
    }

    public static void bubbleSort(Card[] A, int N) {
        boolean stable = true;
        boolean flag = true;
        while (flag) {
            flag = false;
            for (int j = N - 1;j >= 1;j--) {
                if (A[j].num < A[j - 1].num) {
                    stable &= swapInt(A, j, j - 1);
                    flag = true;
                }
            }
        }
        System.out.println(dump(A, N));
        System.out.println(stable ? "Stable" : "Not stable");
    }

    public static void selectionSort(Card[] A, int N) {
        boolean stable = true;
        for (int i = 0;i < N;i++) {
            int minj = i;
            for (int j = i;j < N;j++) {
                if (A[j].num < A[minj].num) {
                    minj = j;
                }
            }
            //if (A[i].num != A[minj].num) {
                stable &= swapInt(A, i, minj);
            //}
        }
        System.out.println(dump(A, N));
        System.out.println(stable ? "Stable" : "Not stable");
    }

    // Stable: true
    // Unstable: false
    public static boolean swapInt(Card[] A, int j, int k) {
        Card v = A[j];
        A[j] = A[k];
        A[k] = v;

        int min = Math.min(j, k);
        int max = Math.max(j, k);
        for (int i = min + 1;i < max;i++) {
            if (A[j].num == A[i].num || A[k].num == A[i].num || A[j].num == A[k].num) {
                return false;
            }
        }
        return true;
    }

    public static String dump(Card[] A, int N) {
        StringBuilder builder = new StringBuilder();
        for (int i = 0;i < N;i++) {
            if (i != 0) {
                builder.append(" ");
            }
            builder.append(A[i]);
        }
        return builder.toString();
    }

    public static int readInt(BufferedReader r) throws Exception {
        return Integer.parseInt(r.readLine());
    }
}

import java.util.Scanner;

class Main {
  public static void main(String... args) {
    Scanner sc = new Scanner(System.in);
    int size = sc.nextInt();
    String[] array = new String[size];
    for (int i = 0; i < size; i++) {
      array[i] = sc.next();
    }

    checkStable(bubble(array), insert(array));
  }

  public static String[] bubble(String[] realArray) {
    String[] strArray = cpStrArray(realArray);
    int[] array = strToInt(strArray);
    int size = strArray.length;

    for (int i = 0; i < size; i++) {
      for (int j = size - 1; j > i; j--) {
        if (array[j] < array[j-1]) {
          swap(strArray, j - 1, j);
          swap(array, j - 1, j);
        }
      }
    }
    print(strArray);
    System.out.println("Stable");

    return strArray;
  }

  public static String[] insert(String[] realArray) {
    String[] strArray = cpStrArray(realArray);
    int[] array = strToInt(strArray);
    int size = strArray.length;

    for (int i = 0; i < size - 1; i++) {
      int min = i;
      for (int j = i + 1; j < size; j++) {
        if (array[j] < array[min]) {
          min = j;
        }
      }
      if (min != i) {
        swap(strArray, min, i);
        swap(array, min, i);
      }
    }
    print(strArray);

    return strArray;
  }

  public static String[] cpStrArray(String[] realArray) {
    String[] strArray = new String[realArray.length];
    for (int i = 0; i < realArray.length; i++) {
      strArray[i] = realArray[i];
    }

    return strArray;
  }

  public static int[] strToInt(String[] strArray) {
    int[] intArray = new int[strArray.length];
    for (int i = 0; i < strArray.length; i++) {
      intArray[i] = Integer.parseInt(strArray[i].replaceAll("[^0-9]", ""));
    }

    return intArray;
  }

  public static void swap(String[] array, int min, int i) {
    String tmp = array[i];
    array[i] = array[min];
    array[min] = tmp;
  }

  public static void swap(int[] array, int min, int i) {
    int tmp = array[i];
    array[i] = array[min];
    array[min] = tmp;
  }

  public static void print(String[] array) {
    int size = array.length;
    for (int i = 0; i < size - 1; i++) {
      System.out.print(array[i] + " ");
    }
    System.out.println(array[size - 1]);
  }

  public static boolean checkStable(String[] stableAns, String[] checkArr) {
    for (int i = 0; i < stableAns.length; i++) {
      if (!stableAns[i].equals(checkArr[i])) {
        System.out.println("Not stable");
        return false;
      }
    }
    System.out.println("Stable");
    return true;
  }
}

