    for(int i = 0; i < c.length; i++){
      for(int j = c.length - 1; j > i; j--){
        if(c[j].num < c[j-1].num){
          Card tmp = c[j];
          c[j] = c[j-1];
          c[j-1] = tmp;
        }
      }
    }
  }

  static void selectionSort(Card[] c){
    for(int i = 0; i < c.length; i++){
      int m = i;
      for(int j = i + 1; j < c.length; j++){
        if(c[m].num > c[j].num)
          m = j;
      }
      Card tmp = c[i];
      c[i] = c[m];
      c[m] = tmp;
    }
  }

