					minj = j;
				}
			}
			if (i != minj) {
				oki = A[minj];
				A[minj] = A[i];
				A[i] = oki;
			}
		}
	}

	public static void bubbleSort(String A[], int N) {
		String b;
		for (int i = 0; i < N - 1; i++) {
			for (int j = N - 1; j > i; j--) {
				if (A[j - 1].charAt(1) > A[j].charAt(1)) {
					b = A[j - 1];
					A[j - 1] = A[j];
					A[j] = b;
				}
			}
		}
	}

