    }
    public static void BubbleSort(Card[] C, int N){
        Card tmp;
        for (int i = 0; i < N; i++){
            for (int j = N - 1; j > i; j--){
                if (C[j].value < C[j-1].value){
                    tmp = C[j];
                    C[j] = C[j-1];
                    C[j-1] = tmp;
                }
            }
        }
    }
    public static void SelectionSort(Card[] C, int N){
        int minj;
        Card tmp;
        for (int i = 0; i < N; i++){
            minj = i;
            for (int j = i; j < N; j++){
                if (C[j].value < C[minj].value){
                    minj = j;
                }
            }
            tmp = C[i];
            C[i] = C[minj];
            C[minj] = tmp;
        }
    }
}

