			for (int i = n - 1; i > 0; i--) {

				int nowNumber = Integer.parseInt(targetArray[i].substring(1, 2));
				int leftNumber = Integer.parseInt(targetArray[i - 1].substring(1, 2));

				// 自分より小さい値が左側に居たら
				if (nowNumber < leftNumber) {
					// 2つの要素を入れ替える
					exchangeArrayValue(targetArray, i, i - 1);
