		ArrayList<String> list = new ArrayList<>();
		ArrayList<String> list2 = new ArrayList<>();
		for (int i=0; i<n; i++) {
			String s = next();
			list.add(s); list2.add(s);
		}

		//bubble sort
		for (int i=0; i<n; i++) {
			for (int j=0; j<n-i-1; j++) {
				if (list.get(j).charAt(1) > list.get(j+1).charAt(1)) {
					Collections.swap(list, j, j+1);
				}
			}
		}

		//selection sort
		for (int i=0; i<n; i++) {
			int min = i;
			for (int j=i; j<n; j++) {
				if (list2.get(j).charAt(1) < list2.get(min).charAt(1)) {
					min = j;
				}
			}
			Collections.swap(list2, i, min);
		}

		//bubble sort
		for (int i=0; i<n; i++) out.print((i==0?"":" ")+list.get(i));
		out.println(); out.println("Stable");

		//selections sort - stable or not stable
		for (int i=0; i<n; i++) out.print((i==0?"":" ")+list2.get(i));
		out.println();
		String ans = "Stable";
		for (int i=0; i<n; i++) {
			if (list.get(i).equals(list2.get(i)) == false) {
				ans = "Not stable"; break;
			}
		}
		out.println(ans);

	}


