	// <Fast Scanner> START -------------------------------------------------
	static InputStream in = System.in;
	static  byte[] buffer = new byte[1024];
	static int length = 0, p = 0;
	public static boolean hasNextByte () {
		if (p < length) return true;
		else {
			p = 0;
			try {length = in.read(buffer);}
			catch (Exception e) {e.printStackTrace();}
			if (length == 0) return false;
		}
		return true;
	}
	public static int readByte () {
		if (hasNextByte() == true) return buffer[p++];
		return -1;
	}
	public static boolean isPrintable (int n) {return 33<=n&&n<=126;}
	public static void skip () {
		while (hasNextByte() && !isPrintable(buffer[p])) p++;
	}
	public static boolean hasNext () {skip(); return hasNextByte();}
	public static String next () {
		if (!hasNext()) throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int temp = readByte();
		while (isPrintable(temp)) {
			sb.appendCodePoint(temp);
			temp = readByte();
		}
		return sb.toString();
	}
	public static String[] nextStrings (int n) {
		String[] ar = new String[n];
		for (int i=0; i<n; i++) ar[i] = next();
		return ar;
	}
	public static int nextInt () {return Math.toIntExact(nextLong());}
	public static int[] nextInts (int n) {
		int[] ar = new int[n];
		for (int i=0; i<n; i++) ar[i] = nextInt();
		return ar;
	}
	public static long nextLong () {
		if (!hasNext()) throw new NoSuchElementException();
		boolean minus = false;
		int temp = readByte();
		if (temp == '-') {
			minus = true;
			temp = readByte();
		}
		if (temp<'0' || '9'<temp) throw new NumberFormatException();
		long n = 0;
		while (isPrintable(temp)) {
			if ('0'<=temp && temp<='9') {
				n *= 10;
				n += temp - '0';
			}
			temp = readByte();
		}
		return minus? -n : n;
	}
	public static char[][] nextCharss (int h, int w, boolean b) {
		//b(番兵)がtrueなら配列を余計に確保する
		char[][] ar = new char[b?h+2:h][b?w+2:h];
		for (int i=b?1:0; i<(b?h+1:h); i++) {
			String temp = next();
			for (int j=0; j<w; j++) {
				ar[i][b?j+1:j] = temp.charAt(j);
			}
		}
		return ar;
	}
	// <Fast Scanner> END ----------------------------------------------------------
}

import java.util.*;

public class Main {
  public static void main(final String[] args) {
    @SuppressWarnings("resource")
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    Card[] arr = new Card[n];
    for (int i = 0; i < n; i++) {
      arr[i] = new Card();
      char[] c = sc.next().toCharArray();
      arr[i].suit = c[0];
      arr[i].value = c[1];
    }
    Card[] arr2 = Arrays.copyOf(arr, n);

    bubbleSort(arr);// always stable
    trace(arr);
    System.out.println("Stable");

    selectionSort(arr2);
    trace(arr2);
    System.out.println(isStable(arr, arr2) ? "Stable" : "Not stable");
  }

  static boolean isStable(Card[] arr, Card[] arr2) {
    for (int i = 0; i < arr.length; i++) {
      if (arr[i].suit != arr2[i].suit)
        return false;
    }
    return true;
  }

  static int selectionSort(Card[] arr) {
    int cnt = 0, minIdx;
    for (int i = 0; i < arr.length - 1; i++) {
      minIdx = i;
      // 未ソートの部分から最小の要素の位置を特定して
      for (int j = i; j < arr.length; j++) {
        if (arr[j].value < arr[minIdx].value)
          minIdx = j;
      }
      // 交換する
      if (i != minIdx) {
        Card tmp = arr[i];
        arr[i] = arr[minIdx];
        arr[minIdx] = tmp;
        cnt++;
      }
    }
    return cnt;
  }

  static int bubbleSort(Card[] arr) {
    int cnt = 0;
    for (int i = 0; i < arr.length - 1; i++) {
      for (int j = arr.length - 1; j >= i + 1; j--) {
        if (arr[j].value < arr[j - 1].value) {
          Card tmp = arr[j];
          arr[j] = arr[j - 1];
          arr[j - 1] = tmp;
          cnt++;
        }
      }
    }
    return cnt;
  }

  static void trace(Card[] arr) {
    StringBuilder sb = new StringBuilder();
    for (Card c : arr) {
      sb.append(c.toString()).append(' ');
    }
    System.out.println(sb.toString().trim());
  }
}

