import java.util.Scanner;

class Main {
  public static void main(String... args) {
    Scanner sc = new Scanner(System.in);
    int size = sc.nextInt();
    String[] array = new String[size];
    for (int i = 0; i < size; i++) {
      array[i] = sc.next();
    }

    stable(array);
    System.out.println("Stable");

    notStable(array);
    System.out.println("Not stable");
  }

  public static void stable(String[] realArray) {
    String[] strArray = cpStrArray(realArray);
    int[] array = strToInt(strArray);
    int size = strArray.length;

    for (int i = 0; i < size; i++) {
      for (int j = size - 1; j > i; j--) {
        if (array[j] < array[j-1]) {
          swap(strArray, j - 1, j);
          swap(array, j - 1, j);
        }
      }
    }
    print(strArray);
  }

  public static void notStable(String[] realArray) {
    String[] strArray = cpStrArray(realArray);
    int[] array = strToInt(strArray);
    int size = strArray.length;

    for (int i = 0; i < size - 1; i++) {
      int min = i;
      for (int j = i + 1; j < size; j++) {
        if (array[j] < array[min]) {
          min = j;
        }
      }
      if (min != i) {
        swap(strArray, min, i);
        swap(array, min, i);
      }
    }

    print(strArray);
  }

  public static String[] cpStrArray(String[] realArray) {
    String[] strArray = new String[realArray.length];
    for (int i = 0; i < realArray.length; i++) {
      strArray[i] = realArray[i];
    }

    return strArray;
  }

  public static int[] strToInt(String[] strArray) {
    int[] intArray = new int[strArray.length];
    for (int i = 0; i < strArray.length; i++) {
      intArray[i] = Integer.parseInt(strArray[i].replaceAll("[^0-9]", ""));
    }

    return intArray;
  }

  public static void swap(String[] array, int min, int i) {
    String tmp = array[i];
    array[i] = array[min];
    array[min] = tmp;
  }

  public static void swap(int[] array, int min, int i) {
    int tmp = array[i];
    array[i] = array[min];
    array[min] = tmp;
  }

  public static void print(String[] array) {
    int size = array.length;
    for (int i = 0; i < size - 1; i++) {
      System.out.print(array[i] + " ");
    }
    System.out.println(array[size - 1]);
  }
}

import java.util.Scanner;
import java.util.Arrays;

public class Main {
	public static boolean safetyJudge(String[] oldarray, String[] newarray) {
		for (int i = 1; i < newarray.length; i++) {
			if (newarray[i].charAt(1) != newarray[i-1].charAt(1)) continue;
			if (Arrays.asList(oldarray).indexOf(newarray[i]) < Arrays.asList(oldarray).indexOf(newarray[i-1]))
				return false;
		}
		return true;
	}

	public static String[] bubbleSort(String[] oldarray, int n) {
		String[] newarray = oldarray.clone();
		boolean flag = true;
		String tmp;
		while (flag) {
			flag = false;
			for (int j = n - 1; j > 0; j--) {
				if (newarray[j].charAt(1) - '0' < newarray[j-1].charAt(1) - '0') {
					tmp = newarray[j]; newarray[j] = newarray[j-1]; newarray[j-1] = tmp;
					flag = true;
				}
			}
		}
		return newarray;
	}

	public static String[] selectionSort(String[] oldarray, int n) {
		String[] newarray = oldarray.clone();
		int minj;
		String tmp;
		for (int i = 0; i < n; i++) {
			minj = i;
			for (int j = i; j < n; j++) {
				if (newarray[j].charAt(1) - '0'< newarray[minj].charAt(1) - '0') minj = j;
			}
			if (minj != i) {
				tmp = newarray[i]; newarray[i] = newarray[minj]; newarray[minj] = tmp;
			}
		}
		return newarray;
	}

	public static void print(String[] oldarray, String[] newarray) {
		for (int i = 0; i < newarray.length; i++) {
			System.out.print(newarray[i]);
			if (i < newarray.length - 1) System.out.print(" ");
		}
		System.out.println();
		if (safetyJudge(oldarray, newarray))
			System.out.println("Stable");
		else
			System.out.println("Not stable");
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = Integer.parseInt(sc.nextLine());
		String str = sc.nextLine();
		String[] array = new String[n];
		array = str.split(" ", 0);
		String[] bsortarray = bubbleSort(array, n);
		String[] ssortarray = selectionSort(array, n);
		print(array, bsortarray); print(array, ssortarray);
	}
}

