		String c;
		boolean flg;

		for (int i = 0; i < n - 1; i++) {
			for (int j = n - 1; j > i; j--) {
				min = Integer.parseInt(str[j].substring(1));
				a = Integer.parseInt(str[j - 1].substring(1));
				if (min < a) {
					c = str[j - 1];
					str[j - 1] = str[j];
					str[j] = c;
				}
			}

		}

		for (int i = 0; i < n; i++) {
