                if( A[j].value < A[ j-1 ].value ) {
                    tmp = A[ j-1 ];
                    A[ j-1 ] = A[ j ];
                    A[ j ] = tmp;
                }
            }
        }
        return;
    }    
    static void selectionSort( Card[] A ) 
    {
    	Card tmp;
    	int i, j, mini;
    	int n = A.length;

   		for( i=0; i<n; i++ ) {
   			mini = i;
   			for( j=i; j<n; j++ ) {
   				if( A[j].value < A[ mini ].value ) {
   					mini = j;
   				}
   			}
   			if( mini != i ) {
		   		tmp = A[ mini ];
				A[ mini ] = A[ i ];
				A[ i ] = tmp;
			}
   		}
   		return;
    }
}

