		boolean flag=true;
		int i=0;
		while(flag){
			flag=false;
			for(int j=n-1;j>i;j--){
				if(a[j].charAt(1)<a[j-1].charAt(1)){
					String temp=a[j];
					a[j]=a[j-1];
					a[j-1]=temp;
					flag=true;
				}
			}
			i++;
		}
		return a;
	}
	static String[] selectionSort(String[] a, int n){
		int minj;
		for(int i=0;i<n;i++){
			minj=i;
			for(int j=i;j<n;j++){
				if(a[j].charAt(1)<a[minj].charAt(1)){
					minj=j;
				}
			}
			String temp=a[i];
			a[i]=a[minj];
			a[minj]=temp;
		}
		return a;
	}

}

