			}

			//Bubble sort
			for(int i=0;i<N;i++){
				for(int j=N-1;j>i;j--){
					if(q[j].compareTo(q[j-1])<0){
						Card tmp=q[j];
						q[j]=q[j-1];
						q[j-1]=tmp;
					}
				}
			}

			//Colleciton sort
			for(int i=0;i<N;i++){
				int minj=i;
				for(int j=i;j<N;j++){
					if(r[j].compareTo(r[minj])<0){
						minj=j;
					}
				}
				Card tmp=r[i];
				r[i]=r[minj];
				r[minj]=tmp;
			}

			boolean BC=isStable(p,q);
			boolean SC=isStable(p,r);



			System.out.print(q[0]);
			for(int i=1;i<N;i++)System.out.print(" "+q[i]);
