//Stable Sort
public class Main {

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int num = scan.nextInt();

		// 準備
		Card[] card = new Card[num];
		for (int i = 0; i < num; i++) {
			card[i] = Card.newInstance(scan.next());
		}

		Card[] bubbleBefore = copyCard(card);
		Card[] selectBefore = copyCard(card);

		// バブルソート
		Card[] bubbleAfter = bubbleSort(bubbleBefore, num);
		// バブルソート出力
		System.out.print(bubbleAfter[0]);
		for (int i = 1; i < num; i++) {
			System.out.print(" " + bubbleAfter[i].toString());
		}
		System.out.println();
		System.out.println(stableCheck(bubbleAfter, card));

		// セレクションソート
		Card[] selectAfter = selectionSort(selectBefore, num);
		// セレクトソート出力
		System.out.print(selectAfter[0]);
		for (int i = 1; i < num; i++) {
			System.out.print(" " + selectAfter[i].toString());
		}
		System.out.println();
		System.out.println(stableCheck(selectAfter, card));
	}

	/**
	 * バブルソート
	 * 
	 * @param A
	 *            ソートする配列
	 * @param N
	 *            ソートする個数
	 * @return 昇順にソートされた配列
	 */
	public static Card[] bubbleSort(Card[] A, int N) {
		boolean flag = true;
		while (flag) {
			flag = false;
			for (int j = N - 1; j >= 1; j--) {
				if (A[j].getNumber() < A[j - 1].getNumber()) {
					Card tmp;
					tmp = A[j];
					A[j] = A[j - 1];
					A[j - 1] = tmp;
					flag = true;
				}
			}
		}
		return A;
	}

	/**
	 * セレクションソート。一番小さい値を選択して入れ替える。
	 * 
	 * @param A配列
	 * @param N配列の数
	 * @return入れ替え後の配列
	 */
	public static Card[] selectionSort(Card[] A, int N) {

		for (int i = 0; i < N; i++) {
			int mini = i;
			for (int j = i; j < N; j++) {
				if (A[j].getNumber() < A[mini].getNumber()) {
					mini = j;
				}
			}
			if (mini != i) {
				Card tmp;
				tmp = A[i];
				A[i] = A[mini];
				A[mini] = tmp;
			}

		}

		return A;
	}

	/**
	 * ソートが安定しているかを確認
	 * 
	 * @param Aftersort：ソート後のカード
	 * @param Input：ソート前の入力したカード
	 * @return：Stable/Not stableの出力
	 */
	public static String stableCheck(Card[] Aftersort, Card[] Input) {
		int i;
		int temae = -1;
		int ato = -1;
		for (i = 0; i < Input.length - 1; i++) {
			if ((Aftersort[i].getNumber()) == (Aftersort[i + 1].getNumber())) {
				for (int j = 0; j < Input.length; j++) {
					if (Aftersort[i].toString().equals(Input[j].toString())) {// H5
																				// =H5
						temae = j;// aftersorti = 0 // 2
					}
					if (Aftersort[i + 1].toString().equals(Input[j].toString())) {
						ato = j;// 1 sort4 //3
					}
				}
				if ((temae > ato)) {// 後のカードが手前のカードよりも前にくるのは安定していないので
					return "Not stable";
				}
			}
		}
		return "Stable";

	}

	/**
	 * カード（リスト）をコピーする
	 * 
	 * @param card:コピーするカード
	 * @returnコピーされたカード
	 */
	public static Card[] copyCard(Card[] card) {

		Card[] copycard = new Card[card.length];
		for (int i = 0; i < card.length; i++) {
			copycard[i] = Card.newInstance(card[i].toString());
		}
		return copycard;
	}

	private static class Card {
		private String mark;
		private int number;

		private Card(String str) {
			mark = str.substring(0, 1);
			number = Integer.valueOf(str.substring(1));
		}

		public static Card newInstance(String str) {
			return new Card(str);
		}

		public int getNumber() {
			return number;
		}

		public String getMark() {
			return mark;
		}

		@Override
		public String toString() {
			return mark + number;
		}
	}

}

import java.util.Scanner;

public class Main {

    public static void main(String args[]) {

        String[] inputs = input();
        String[] inputs = mockup();

        String[] inputs4S = inputs.clone();

        int swapCount = bubbleSort(inputs);
        output(inputs);
        System.out.println("stable");

        int swapCount4S = selectionSort(inputs4S);
        output(inputs4S);
        System.out.println("unstable");
    }

    /** bubble sort
     *
     * @param inputs
     * @return
     */
    private static int bubbleSort(String inputs[]) {
        int swapCount = 0;
        for (int i = 0; i < inputs.length; i++) {
            for (int j = inputs.length - 1; j > i; j--) {
                if (compare(inputs[j], inputs[j-1])) {
                    swap(inputs, j, j-1);
                    swapCount++;
                }
            }
        }
        return swapCount;
    }

    /**
     * selection sort
     * @param inputs
     * @return
     */
    private static int selectionSort(String[] inputs) {
        int swapCount = 0;
        int min = 0;

        for (int i = 0; i < inputs.length; i++) {
            min = i;
            for (int j = i; j < inputs.length; j++) {
                if (compare(inputs[j], inputs[min])) {
                    min = j;
                }
            }
            if (i != min) {
                swap(inputs, i, min);
                swapCount++;
            }
        }
        return swapCount;
    }

    private static String[] mockup() {
        String a[] = {"H4","C9","S4","D2","C3"};
        return a;
    }

    private static void swap(String[] inputs, int j, int i) {
        String a = inputs[j];
        String b = inputs[i];
        inputs[i] = a;
        inputs[j] = b;
    }
    private static boolean compare(String a, String b) {
        int iA = Integer.valueOf(a.substring(1));
        int iB = Integer.valueOf(b.substring(1));
        return iA < iB;
    }

    public static void output(String[] inputs) {
        // output
        StringBuilder output = new StringBuilder();
        for (String i : inputs) {
            output.append(i + " ");
        }
        String outputString = output.toString();
        System.out.println(outputString.substring(0,outputString.length() - 1));
    }

    public static String[] input() {
        Scanner in = new Scanner(System.in);
        int count = in.nextInt();
        String[] inputs = new String[count];
        for (int i = 0; i < count; i++) {
            inputs[i] = in.next();
        }
        in.close();
        return inputs;
    }

}

