            for(int j = i; j <= n - 1; j++){
                if(a[j].charAt(1) > a[minj].charAt(1)){
                    minj = j;
                }
            }
            if(a[i] != a[minj]) count++;
            String temp = a[i];
            a[i] = a[minj];
            a[minj] = temp;
        }
	}

}

