		for (int i = 0; i < cards.length; i++) {
			ret[i] = cards[i];
		}
		for (int i = 0; i < ret.length; i++) {
			for (int j = ret.length - 1; j >= i+1; j--) {
				if(ret[j].num < ret[j-1].num){
					Card temp = ret[j];
					ret[j] = ret[j-1];
					ret[j-1] = temp;
				}
			}
		}
		return ret;
	}

	static Card[] selectionSort(Card[] cards){
		Card[] ret = new Card[cards.length];
		for (int i = 0; i < cards.length; i++) {
			ret[i] = cards[i];
		}
		for (int i = 0; i < ret.length; i++) {
			int mini = i;
			for (int j = i; j < ret.length; j++) {
				if(ret[j].num < ret[mini].num)
					mini = j;
			}
			Card temp = ret[i];
			ret[i] = ret[mini];
			ret[mini] = temp;
		}
		return ret;
	}
}

