import java.util.ArrayList;
import java.util.Scanner;

public class Main {
	public static class Card implements Cloneable{
		public char suit;
		public char value;
		public Card() {}
		public Card(char suit, char value) {
			this.suit = suit; this.value = value;
		}
		public Card clone() {
			Card card = new Card();
			card.suit = this.suit; card.value = this.value;
			return card;
		}
	}
	public static void bubble(ArrayList<Card> A) {
		for(int i = 0; i < A.size(); i++) {
			for(int j = A.size() - 1; j >= 1; j--) {
				if(A.get(j).value < A.get(j-1).value) {
					Card t = A.get(j).clone(); A.set(j, A.get(j-1).clone()); A.set(j-1, t);
				}
			}
		}
	}
	public static void selection(ArrayList<Card> A) {
		for(int i = 0; i < A.size(); i++) {
			int minj = i;
			for(int j = i; j < A.size(); j++) {
				if(A.get(j).value < A.get(minj).value)minj =j;
			}
			Card t = A.get(i).clone(); A.set(i, A.get(minj).clone()); A.set(minj, t);
		}
	}
	public static void print(ArrayList<Card> A) {
		for(int i = 0; i < A.size(); i++) System.out.printf("%s%s%s",A.get(i).suit,A.get(i).value,i==A.size()-1?"\n":" ");
	}
	public static boolean isStable(ArrayList<Card> C1, ArrayList<Card> C2) {
		for(int i = 0; i < C1.size(); i++) {
			if(C1.get(i).suit != C2.get(i).suit) return false;
		}
		return true;
	}

	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);
		int N = (int)scanner.nextLine().charAt(0);
		ArrayList<Card> C1 = new ArrayList<>(),C2 = new ArrayList<>();
		String[] str = scanner.nextLine().split(" ");
		for(String s : str) {
			C1.add(new Card(s.charAt(0), s.charAt(1)));
			C2.add(new Card(s.charAt(0),s.charAt(1)));
		}
		bubble(C1);
		selection(C2);
		print(C1);
		System.out.println("Stable");
		print(C2);
		if(isStable(C1,C2)) System.out.println("Stable");
		else System.out.println("Not stable");

		scanner.close();
	}
}

import java.util.Scanner;
public class Main {
	static void output(int[][] card,int N){
		boolean judge=true;
		System.out.printf("%c%d",card[0][2],card[0][0]);
		for(int i=1;i<N;i++){
			System.out.printf(" %c%d",card[i][2],card[i][0]);
			if((card[i][0]==card[i-1][0])&&!(card[i-1][1]<card[i][1])){
				judge=false;
			}
		}
		System.out.println();
		if(judge) System.out.println("Stable");
		else System.out.println("Not stable");
	}
	static void BubbleSort(int[][] card,int N){
		int t;
		for(int i=0;i<N;i++){
			for(int j=N-1;i<j;j--){
				if(card[j][0]<card[j-1][0]){
					t=card[j][0];
					card[j][0]=card[j-1][0];
					card[j-1][0]=t;
					t=card[j][1];
					card[j][1]=card[j-1][1];
					card[j-1][1]=t;
					t=card[j][2];
					card[j][2]=card[j-1][2];
					card[j-1][2]=t;
				}
			}
		}
		output(card,N);
	}
	static void SelectionSort(int[][] card,int N){
		int min,t;
		for(int i=0;i<N;i++){
			min=i;
			for(int j=i;j<N;j++){
				if(card[j][0]<card[min][0]){
					min=j;
				}
			}
			t=card[i][0];
			card[i][0]=card[min][0];
			card[min][0]=t;
			t=card[i][1];
			card[i][1]=card[min][1];
			card[min][1]=t;
			t=card[i][2];
			card[i][2]=card[min][2];
			card[min][2]=t;
		}
		output(card,N);
	}
	static void cardcopy(int[][] card,int[][] copy,int N){
		for(int i=0;i<N;i++){
			copy[i][0]=card[i][0];
			copy[i][1]=card[i][1];
			copy[i][2]=card[i][2];
		}
	}
	public static void main(String[] args){
		Scanner scan=new Scanner(System.in);
		String s;
		int[] counter=new int[9];
		int N=scan.nextInt();
		int[][] card=new int[N][3];
		int[][] copy=new int[N][3];
		for(int i=0;i<N;i++){
			s=scan.next();
			card[i][0]=s.charAt(1)-'0';
			card[i][1]=counter[card[i][0]-1];
			card[i][2]=s.charAt(0);
			counter[card[i][0]-1]++;
		}
		cardcopy(card,copy,N);//一回目のコピーの作成
		BubbleSort(copy,N);
		cardcopy(card,copy,N);
		SelectionSort(copy,N);
		scan.close();
	}
}

