        for( i=0; i<n; i++ ) {
            for( j=n-1; i<j; j-- ) {
                if( A[j].value < A[ j-1 ].value ) {
                    tmp = A[ j-1 ];
                    A[ j-1 ] = A[ j ];
                    A[ j ] = tmp;
                }
            }
        }
        return;
    }    
