   				if( A[j].value < A[ mini ].value ) {
   					mini = j;
   				}
   			}
   			if( mini != i ) {
		   		tmp = A[ mini ];
				A[ mini ] = A[ i ];
				A[ i ] = tmp;
			}
   		}
   		return;
    }
