class BubbleSort {
    // -- field
    private Cards[] sort_array;
    // -- Constructor
    private BubbleSort() {}
    public BubbleSort(Cards[] sort_array) {
	this.sort_array = sort_array;
    }

    // -- Method
    public void display() {
	for (int i = 0; i < this.sort_array.length; i++) {
	    this.sort_array[i].print();
	    System.out.print(" ");
	    if(i == this.sort_array.length-1) {
		System.out.println();
		break;
	    }
	}
    }

    public void swap(int x, int y) {
	Cards temp = this.sort_array[x];
	this.sort_array[x] = this.sort_array[y];
	this.sort_array[y] = temp;
    }

    public void bubbleSort() {
	for (int i = this.sort_array.length - 1; i > 0; i--) {
	    for (int j = 0; j < i; j++) {
		if (this.sort_array[j].getValue() > this.sort_array[j + 1].getValue()) {
		    swap(j, j + 1);
		}
		// this.display(); // 動作チェック
	    }
	}
    }

    public boolean checkSort() {
	for (int i = 0; i < this.sort_array.length - 1; i++) {
	    if(this.sort_array[i].getValue() == this.sort_array[i + 1].getValue()) {
		if(this.sort_array[i].getId() > this.sort_array[i].getId()) {
		    return false;
		}
	    }
	}
	return true;
    }

}

class SelectionSort {
    // -- Field
    private Cards[] sort_array;
    // -- Constructor
    private SelectionSort() {}
    public SelectionSort(Cards[] sort_array) {
	this.sort_array = sort_array;
    }

    // -- Method
    public void display() {
	for (int i = 0; i < this.sort_array.length; i++) {
	    this.sort_array[i].print();
	    if(i == this.sort_array.length-1) {
		System.out.println();
		break;
	    }
	    System.out.print(" ");
	}
    }


    public void swap(int x, int y) {
	Cards temp = this.sort_array[x];
	this.sort_array[x] = this.sort_array[y];
	this.sort_array[y] = temp;
    }

    public void selectionSort() {
	int out, in, min;
	for (out = 0; out < this.sort_array.length - 1; out++) {
	    min = out;
	    for (in = out + 1; in < this.sort_array.length; in++) {
		if (this.sort_array[in].getValue() < this.sort_array[min].getValue()) {
		    min = in;
		}
	    }
	    // System.out.println("min = " + this.sort_array[min]); // 動作確認
	    this.swap(out, min);
	    // this.display(); // 動作確認
	}
    }

    public boolean checkSort() {
	for (int i = 0; i < this.sort_array.length - 1; i++) {
	    if(this.sort_array[i].getValue() == this.sort_array[i + 1].getValue()) {
		if(this.sort_array[i].getId() > this.sort_array[i + 1].getId()) {
		    return false;
		}
	    }
	}
	return true;
    }
}

import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in); 

		int n = sc.nextInt();
		Card[] src = new Card[n];
		Card[] cards = new Card[n];

    	for (int i = 0; i < n; i++) {
    		src[i] = new Card(sc.next());
    		cards[i] = src[i];
    	}

    	// Bubble Sort
    	for (int i = 0; i < n; i++) {
    		for (int j = n - 1; j > i; j--) {
    			if (cards[j].rank < cards[j - 1].rank) {
    				Card temp = cards[j];
    				cards[j] = cards[j - 1];
    				cards[j - 1] = temp;
    			}
    		}
    	}
//    	printData(src);
    	printData(cards);
    	if (checkStable(src, cards)) {
    		System.out.println("Stable");
    	} else {
    		System.out.println("Not stable");
    	}

    	for (int i = 0; i < n; i++) {
    		cards[i] = src[i];
    	}
//    	printData(src);
//    	printData(cards);

    	// SelectionSort
    	for (int i = 0; i < n; i++) {
    		int mini = i;
    		for (int j = i; j < n; j++) {
    			if (cards[j].rank < cards[mini].rank) {
    				mini = j;
    			}
    		}
    		if (mini != i) {
    			Card temp = cards[i];
    			cards[i] = cards[mini];
    			cards[mini] = temp;
    		}
    	}
//    	printData(src);
    	printData(cards);
    	if (checkStable(src, cards)) {
    		System.out.println("Stable");
    	} else {
    		System.out.println("Not stable");
    	}

    	sc.close();
	}

	private static boolean checkStable(Card[] src, Card[] result) {
		for (int i = 1; i < result.length; i++) {
			if (result[i - 1].rank == result[i].rank) {
				if (seekCard(src, result[i - 1].data) > seekCard(src, result[i].data)) {
					return false;
				}
			}
		}
		return true;
	}

	private static int seekCard(Card[] src, String key) {
		for (int i = 0; i < src.length; i++) {
			if (src[i].data.equals(key)) {
				return i;
			}
		}

		return -1;
	}

	private static void printData(Card[] data) {
		StringBuffer printData = new StringBuffer();
		for (int i = 0; i < data.length; i++) {
			printData.append(data[i].data);
			printData.append(" ");
		}
		printData.delete(printData.length() - 1, printData.length());
		System.out.println(printData);
	}
}

