import java.util.Arrays;
import java.util.Scanner; 

public class Main {

	public static void main(String arg[]){
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		String[]  a = new String[N];
		String[] resultArray;
		int minj = 0;
		int[][] A = new int[N][2];
		int[][] B = new int[N][2];
		int tmp = 0;
		int num = 0;

		for(int i=0; i<N; i++){
			a[i] = sc.next();
			resultArray = a[i].split("");
			num = Integer.parseInt(resultArray[1]);
			A[i][0] = i;
			A[i][1] = num;
			B[i][0] = A[i][0];
			B[i][1] = A[i][1];
		}

		/*Bubble*/
		for (int i=0; i<N; i++){
			for (int j=N-1; j>0; j--){
				if(B[j][1] < B[j-1][1]) {
					tmp = B[j][0];
					num = B[j][1];
					B[j][0] = B[j-1][0];
					B[j][1] = B[j-1][1];
					B[j-1][0] = tmp;
					B[j-1][1] = num;
				}
			}
		}
		for(int i=0; i<N; i++){
			if(i<N-1){
				System.out.print(a[B[i][0]] + " ");
			}else{
				System.out.println(a[B[i][0]]);
			}
		}
		System.out.println("Stable");

		/*Selection*/
		for(int i=0; i<N; i++){
			minj = i;
			for(int j=i; j<N; j++){
				if(A[j][1] < A[minj][1]){
					minj = j;
				}
			}
			if(A[i][1]!=A[minj][1]){
				tmp = A[i][0];
				num = A[i][1];
				A[i][0] = A[minj][0];
				A[i][1] = A[minj][1];
				A[minj][0] = tmp;
				A[minj][1] = num;
			}
		}
		for(int i=0; i<N; i++){
			if(i<N-1) {
				System.out.print(a[A[i][0]] + " ");
			}else{
				System.out.println(a[A[i][0]]);
			}
		}
		for(int i=0; i<N; i++){
			if(A[i][0]!=B[i][0]) {
				System.out.println("Not stable");
				break;
			}else if(A[i][0]==B[i][0] && i !=N-1){
				continue;
			}else{
				System.out.println("Stable");
			}
		}
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {

	public static void printArray(String[] cardSort) {
		for (int i = 0; i < cardSort.length; i++) {
			System.out.print(cardSort[i]);

			if (i == cardSort.length - 1) {
				break;
			}
			System.out.print(" ");
		}
		System.out.println();
	}

	public static boolean isStable(String in[], String out[], int N) {

		for(int i = 0; i < N; i++) {
			for(int j = i + 1; j < N; j++) {
				for(int a = 0; a < N; a++) {
					for(int b = a + 1; b < N; b++) {
						if(in[i].charAt(1) == in[j].charAt(1) && in[i].equals(out[b]) && in[j].equals(out[a])) {
							return false;
						}
					}
				}
			}
		}
		return true;
	}

	public static void main(String[] args) throws NumberFormatException, IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		int progCardNumOfSheets = Integer.parseInt(br.readLine());

		String[] card = br.readLine().split(" ");

		String[] cardNumBubbleSort = new String[progCardNumOfSheets];
		String[] cardNumSelectionSort = new String[progCardNumOfSheets];


		for(int i = 0; i < progCardNumOfSheets; i++) {
			cardNumBubbleSort[i] = card[i];
			cardNumSelectionSort[i] = card[i];
		}

		int compareNumResult = 0;
		String compareNum1 = "";
		String compareNum2 = "";

		boolean isSortFlag = true;

		while(isSortFlag) {
			isSortFlag = false;

			for(int i = progCardNumOfSheets - 1; i > 0; i-- ) {
				compareNum1 = cardNumBubbleSort[i].substring(1);
				compareNum2 = cardNumBubbleSort[i - 1].substring(1);
				compareNumResult = compareNum1.compareTo(compareNum2);
				if(compareNumResult < 0) {
					String tmp = cardNumBubbleSort[i - 1];
					cardNumBubbleSort[i - 1] = cardNumBubbleSort[i];
					cardNumBubbleSort[i] = tmp;
					isSortFlag = true;
				}
			}
		}

		printArray(cardNumBubbleSort);

		if(isStable(card, cardNumBubbleSort, progCardNumOfSheets)) {
			System.out.println("Stable");
		} else {
			System.out.println("Not stable");
		}

		int minNum = 0;
		for(int i = 0; i < progCardNumOfSheets; i++) {
			minNum = i;

			for(int j = i; j < progCardNumOfSheets; j++) {
				compareNum1 = cardNumSelectionSort[j].substring(1);
				compareNum2 = cardNumSelectionSort[minNum].substring(1);
				compareNumResult = compareNum1.compareTo(compareNum2);
				if(compareNumResult < 0) {
					minNum = j;
				}
			}
			if(i != minNum) {
				String tmp = cardNumSelectionSort[i];
				cardNumSelectionSort[i] = cardNumSelectionSort[minNum];
				cardNumSelectionSort[minNum] = tmp;
			}
		}

		printArray(cardNumSelectionSort);

		if(isStable(card, cardNumSelectionSort, progCardNumOfSheets)) {
			System.out.println("Stable");
		} else {
			System.out.println("Not stable");
		}
	}
}

import java.util.Scanner;

public class Main {

	public static String[] bubbleSort(String[] a, int num) {
		String[] b = new String[num];
		String temp;

		for(int i = 0; i < num; i++) {
			b[i] = a[i];
		}

		for(int i = 0; i < num - 1; i++) {
			for(int j = num - 1; j >= i + 1; j--) {
				if(b[j-1].charAt(1) > b[j].charAt(1)) {
					temp = b[j-1];
					b[j-1] = b[j];
					b[j] = temp;
				}
			}
		}

		return b;
	}

	public static String[] selectionSort(String[] a, int num) {
		String[]	c = new String[num];
		int minIndex = 0;
		String temp;

		for(int i = 0; i < num; i++) {
			c[i] = a[i];
		}

		for(int i = 0; i < num; i++) {
			minIndex = i;
			for(int j = i; j < num; j++){
				if(c[j].charAt(1) < c[minIndex].charAt(1)) {
					minIndex = j;
				}
			}
			temp = c[i];
			c[i] = c[minIndex];
			c[minIndex] = temp;
		}


		return c;
	}

	public static boolean isStable(String[] b, String[] c, int num) {

		for(int i = 0; i < num; i++) {
			if(!b[i].equals(c[i])){
				return false;
			}
		}

		return true;
	}

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		String[] a = new String[36];
		int num = scan.nextInt();
		for (int i = 0; i < num; i++) {
			a[i] = scan.next();
		}

		String[] b = bubbleSort(a, num);
		String[] c = selectionSort(a, num);

		for(int i = 0; i < num; i++) {
			if (i != 0) {
				System.out.print(" ");
			}
			System.out.print(b[i]);
		}
		System.out.println("");
		System.out.println("Stable");

		for(int i = 0; i < num; i++) {
			if (i != 0) {
				System.out.print(" ");
			}
			System.out.print(c[i]);
		}
		System.out.println("");
		if(isStable(b, c, num)) {
			System.out.println("Stable");
		} else {
			System.out.println("Not stable");
		}






	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.Arrays;

public class Main
{
	public static void main(String[] args)
	{
		try{
			StringBuilder sb = new StringBuilder();
			BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); 
			int n = Integer.parseInt(br.readLine());
			String[] str1 = br.readLine().split(" ");
			String[] str2 = Arrays.copyOf(str1,str1.length);
			bubbleSort(str1);
			selectionSort(str2);
			sb.append(appS(str1)).append("Stable\n")
			.append(appS(str2)).append(Arrays.equals(str1,str2) ? "Stable\n" : "Not Stable\n");
			System.out.print(sb.toString());


		}catch(IOException e){
			e.printStackTrace();
		}
	}
	public static void bubbleSort(String[] s)
	{
		boolean boo = true;
		for(int i = 0 ; boo ; i++)
		{
			boo = false;
			for(int j = s.length-1; j > i ; j--)
			{
				if(toInt(s[j]) < toInt(s[j-1]))
					swap(s,j,j-1);
					boo = true;
			}
		}

	}
	public static void selectionSort(String[] s)
	{
		int min;
		for(int i= 0 ; i< s.length-1; i++)
		{
			min = i;
			for(int j = i+1 ; j<s.length; j++)
			{
				if(toInt(s[j]) < toInt(s[min]))
				min = j;
			}
			if(min != i){
					swap(s,i,min);
			}
		}
	}
	public static int toInt(String s)
	{
		int ans;
		try{
			ans = (int)(s.charAt(1));
		}catch(NumberFormatException e){
			e.printStackTrace();
			//e.getMessage();
			return -1;
		}
		return ans;

	}
	public static void swap(String[] st,int z1,int z2)
	{
		String stemp = st[z2];
		st[z2] = st[z1];
		st[z1] = stemp;
	}
	public static String appS(String[] s)
	{
		StringBuilder sb = new StringBuilder();
		sb.append(s[0]);
		for(int i = 1 ; i < s.length ; i++)
		{
			sb.append(" ").append(s[i]);
		}
		sb.append("\n");
		return sb.toString();

	} 
}

