public class Main {

	public static <E> void print_array(E[] arr){
		int i=0;
		for(E element: arr){
			System.out.print(element);
			if(i != arr.length-1) System.out.print(" ");
			else System.out.print("\n");
			i++;
		}
	}

	public static void main(String[] args) throws IOException{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(br.readLine());
		String tmp_arr[] = new String[n];
		tmp_arr = br.readLine().split(" ");
		String tmp_arr1[] = new String[n];
		String base_arr[] = new String[n];

		// srcPos: beginning in tmp_arr, destPos: beginning in tmp_arr1
		System.arraycopy(tmp_arr, 0, base_arr, 0, n);		
		System.arraycopy(tmp_arr, 0, tmp_arr1, 0, n);

		String[] bubbled_arr = bubblesort(tmp_arr);
		print_array(bubbled_arr);
		if(check_stable(bubbled_arr, base_arr)) System.out.println("Stable");
		else System.out.println("Not stable");
		String[] selected_arr = selectionsort(tmp_arr1);
		print_array(selected_arr);
		if(check_stable(selected_arr, base_arr)) System.out.println("Stable"); 		
		else System.out.println("Not stable");

	}	

	public static String[] bubblesort(String[] arr){
		int n = arr.length;
		for(int i=0; i<n; i++){
			for(int j=1; j<n-i; j++){
				if(Character.getNumericValue(arr[j-1].charAt(1)) > Character.getNumericValue((arr[j].charAt(1)))){
					String tmp = arr[j-1];
					arr[j-1] = arr[j];
					arr[j] = tmp;
				}
			}
		}		
		return arr;
	}

	public static String[] selectionsort(String[] arr){
		for(int i=0; i<arr.length; i++){
			int min_ix = i;
			for(int j=i; j<arr.length; j++){
				if(Character.getNumericValue(arr[min_ix].charAt(1)) > Character.getNumericValue(arr[j].charAt(1))) min_ix = j;
			}
			if(min_ix != i){
				// swap
				String tmp = arr[min_ix];
				arr[min_ix] = arr[i];
				arr[i] = tmp;
			}
		}
		return arr;
	}
	public static boolean check_stable(String[] arr, String[] sorted_arr){
		int n = arr.length;
		for(int checknum=1; checknum<10; checknum++){
			String[] check_bff_1 = new String[n];
			String[] check_bff_2 = new String[n];

			int bff_ix_1 = 0;
			int bff_ix_2 = 0;

			for(int i=0; i<n; i++){
				if (Character.getNumericValue(sorted_arr[i].charAt(1)) == checknum){
					check_bff_1[bff_ix_1] = sorted_arr[i];
					bff_ix_1++;
				}
				if (Character.getNumericValue(arr[i].charAt(1)) == checknum){
					check_bff_2[bff_ix_2] = arr[i];
					bff_ix_2++;
				}
			}
			for(int j=0; j<n; j++){
				if(check_bff_1[j] == null && check_bff_2[j] == null) continue;
				if(check_bff_1[j] != check_bff_2[j]) return false;
			}
		}
		return true;
	}
}

import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int N = scan.nextInt();
		String[] C = new String[N];
		for(int i=0; i<N; i++) {
			C[i] = scan.next();
		}
		scan.close();
		String[] bubbleSortedC = C.clone();
		String[] SelectionSortedC = C.clone();

		BubbleSort(bubbleSortedC, N);
		SelectionSort(SelectionSortedC, N);

		trace(bubbleSortedC);
		System.out.println("Stable");	//バブルソートは安定
		trace(SelectionSortedC);

		for(int i=0; i<C.length; i++) {
			if(bubbleSortedC[i] == SelectionSortedC[i]) {
				continue;
			} else {
				//バブルソートと異なるので安定でない
				System.out.println("Not stable");
				return;
			}
		}
		System.out.println("Stable");	//バブルソートと一致したので安定

	}

	private static void SelectionSort(String[] C, int N) {
		for(int i=0; i<N; i++) {
			int minj = i;
			for(int j=i; j<N; j++) {

				if(Integer.parseInt(C[j].substring(1)) < Integer.parseInt(C[minj].substring(1))) {
					minj = j;
				}
			}
			String t = C[i];
			C[i] = C[minj];
			C[minj] = t;
		}
	}

	private static void BubbleSort(String[] C, int N) {
		for(int i=0; i<N; i++) {
			for(int j=N-1; j>i; j--) {
				if(Integer.parseInt(C[j].substring(1)) < Integer.parseInt(C[j-1].substring(1))) {
					String t = C[j];
					C[j] = C[j-1];
					C[j-1] = t;
				}

			}
		}
	}

	private static void trace(String[] C) {
		for(int i=0; i<C.length; i++) {
			if(i != 0) {
				System.out.print(" ");
			}
			System.out.print(C[i]);
		}
		System.out.println();
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;

//安定なソート
public class Main {

	public static void main(String[] args) {
		// 入力値の取得
		try (
				BufferedReader br = new BufferedReader(new InputStreamReader(System.in));) {

			int n = Integer.parseInt(br.readLine());
			String[] s = br.readLine().split("\\s");
			ArrayList<Card> bubList = new ArrayList<>(); // バブルソート用
			for (int i = 0; i < n; i++) {
				char suit = s[i].charAt(0);
				int num = Integer.parseInt(s[i].substring(1, 2));
				Card card = new Card(suit, num);
				bubList.add(card);
			}
			ArrayList<Card> selList = new ArrayList<>(bubList); // 選択ソート用（複製）
			// ソートの実行
			Main.bubbleSort(bubList);
			Main.selectionSort(selList);
			// 結果の表示
			Main.displayCard(bubList);
			System.out.println("Stable");
			Main.displayCard(selList);
			String ans = Main.isStable(bubList, selList) ? "Stable" : "Not stable";
			System.out.println(ans);

		} catch (IOException e) {
			e.printStackTrace();
		}

	}

	// バブルソート
	static int bubbleSort(ArrayList<Card> cl) {
		int cnt = 0;
		for (int i = 0; i < cl.size(); i++) {
			for (int j = cl.size() - 1; i + 1 <= j; j--) {
				// 1つ前のカードの数字の方が大きい場合
				if (cl.get(j).num < cl.get(j - 1).num) {
					cnt++;
					Card tmp = cl.get(j);
					cl.set(j, cl.get(j - 1));
					cl.set(j - 1, tmp);
				}
			}

		}
		return cnt;

	}

	// 選択ソート
	static int selectionSort(ArrayList<Card> cl) {
		int cnt = 0;
		for (int i = 0; i < cl.size(); i++) {
			int mini = i;
			for (int j = i + 1; j < cl.size(); j++) {
				if (cl.get(mini).num > cl.get(j).num) {
					mini = j;
				}
			}
			if (i != mini) {
				cnt++;
				Card tmp = cl.get(mini);
				cl.set(mini, cl.get(i));
				cl.set(i, tmp);
			}
		}

		return cnt;

	}

	// 配列の要素表示
	static void displayCard(ArrayList<Card> cl) {
		cl.get(0).showCard();
		for (int i = 1; i <= cl.size() - 1; i++) {
			System.out.print(" ");
			cl.get(i).showCard();
			if (i == cl.size() - 1) { // 最後の一回
				System.out.println();
			}
		}
	}

	// 安定性の愚直な判定
	static boolean isStable(ArrayList<Card> in, ArrayList<Card> out) {
		for (int i = 0; i < in.size(); i++) {
			for (int j = i; i < in.size(); j++) {
				for (int a = 0; a < in.size(); a++) {
					for (int b = a; b < in.size(); b++) {
						if (in.get(i).num == in.get(j).num
								&& in.get(i).num == out.get(b).num
								&& in.get(j).num == out.get(a).num) {
							return false;
						}
					}
				}
			}
		}

		return true;
	}

}

