	public void sort(){
		for(int i=0; i<this.length;i++){
			int minIndex=i;
			for(int j=i; j<this.length;j++){
				if(sortList.get(j).compValue()<sortList.get(minIndex).compValue())
					minIndex = j;
			}
			if(i!=minIndex)
				swap(i,minIndex);
		}
	}	
