				if (bCard[j].value  < bCard[j-1].value) {
					Card tmp = bCard[j];
					bCard[j] = bCard[j-1];
					bCard[j-1] = tmp;
				}
			}
		}

		for (int i = 0; i < n; i++) {
			System.out.print((i==0?"":" ") + bCard[i]);
		}
		System.out.println();
		System.out.println("Stable");
		// Selection sort
		Card[] sCard = Arrays.copyOf(card, card.length);
		for (int i = 0; i < n; i++) {
			int minj = i;
			for (int j = i; j < n; j++) {
				if (sCard[minj].value > sCard[j].value)
					minj = j;
			}
			if(minj == i)continue;
