	}

	public static int[] selectionSort( int[] Array, int num){
		int[] numArray = new int[num];
		int[] dig = new int[num];
		int[] out = new int[num];

		for(int i = 0; i < num; i ++)
		{
			dig[i] = Array[i] / 100;
			numArray[i] = Array[i] % 100;
		}

		//選択ソート
		for (int i = 0; i < num - 1; i++) {
			// 比較元の配列番号をセットする
			int comp = i;
			// 最小値の探索
			for (int j = i + 1; j < num; j++) {
				if (numArray[comp] > numArray[j]) {
					// 最少値設定
					comp = j;
				}
			}
			// 最小値が入れ替わっていなければ数値を入れ替えない
			if (i == comp) {
				continue;
			}
			//入れ替え処理
			int sub = numArray[i];
			numArray[i] = numArray[comp];
			numArray[comp] = sub;
			int work = dig[i];
			dig[i] = dig[comp];
			dig[comp] = work;
		}

		for(int i = 0; i < num; i ++)
		{
			out[i] = (dig[i] * 100)+  numArray[i];
		}

		//出力
		output(out, num);
		return out;
	}


