    Scanner s = new Scanner(System.in);
    int n = s.nextInt();
    String[] a = new String[n];
    for (int i = 0; i < n; i++)
      a[i] = s.next();
    s.close();
    String[] b = a.clone();

    String[] bubble_sorted = bubble_sort(a);
    String[] selection_sorted = selection_sort(b);
  }
