import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine());

        List<Card> original = Arrays.stream(scanner.nextLine().split(" "))
                .map(card -> new Card(card))
                .collect(Collectors.toList());

        List<Card> cards1 = original.stream().collect(Collectors.toList());
        List<Card> cards2 = original.stream().collect(Collectors.toList());

        Function<Integer, Integer> getSortNumber = a -> cards1.get(a).getNumber();
        bubbleSort(cards1, getSortNumber);
        System.out.println(cards1.stream().map(c -> c.toString()).collect(Collectors.joining(" ")));
        System.out.println("Stable");

        selectionSort(cards2, a -> cards2.get(a).getNumber());
        System.out.println(cards2.stream().map(c -> c.toString()).collect(Collectors.joining(" ")));

        if (IntStream.range(0, original.size())
                .anyMatch(index -> !(cards1.get(index).equals(cards2.get(index))))) {
            System.out.println("Not stable");
        } else {
            System.out.println("Stable");
        }
    }

    private static int bubbleSort(List a, Function<Integer, Integer> getSortNumber) {
        int swapCount = 0;
        int length = a.size();

        // N-1 + N-2 + ... + 1 = (N^2 - N)/2 回
        for (int i = 0; i < length; i++) {
            for (int j = length - 1; j > i; j--) {
                // 左隣の方が大きいならば、swapする
                if (getSortNumber.apply(j-1) > getSortNumber.apply(j)) {
                    Collections.swap(a, j, j-1);
                    swapCount++;
                }
            }
        }
        return swapCount;
    }

    private static int selectionSort(List a, Function<Integer, Integer> getSortNumber) {
        int length = a.size();
        int swapCount = 0;

        for (int i = 0; i < length; i++) {
            int minIndex = i;
            for (int j = i; j < length; j++) {
                if (getSortNumber.apply(j) < getSortNumber.apply(minIndex)) {
                    minIndex = j;
                }
            }

            if (getSortNumber.apply(i) > getSortNumber.apply(minIndex)) {
                Collections.swap(a, i, minIndex);
                swapCount++;
            }
        }
        return swapCount;
    }

    private static class Card {
        private char suit;
        private int number;

        public Card (String pair) {
            suit = pair.charAt(0);
            number = Integer.parseInt(pair.substring(1));
        }

        public int getSuit() {
            return suit;
        }

        public int getNumber() {
            return number;
        }

        @Override
        public String toString() {
            return String.valueOf(suit) + number;
        }

        @Override
        public boolean equals(Object card) {
            if (!(card instanceof Card)) super.equals(card);

            Card cardObj = (Card) card;
            return this.suit == cardObj.getSuit() && this.number == cardObj.getNumber();
        }
    }
}

import java.util.Scanner;

public class Main {

    public static void main(String args[]) {

        String[] inputs = input();
//        String[] inputs = mockup();

        String[] inputs4S = inputs.clone();

        int swapCount = bubbleSort(inputs);
        output(inputs);
        System.out.println("stable");

        int swapCount4S = selectionSort(inputs4S);
        output(inputs4S);
        System.out.println("Not stable");
    }

    /** bubble sort
     *
     * @param inputs
     * @return
     */
    private static int bubbleSort(String inputs[]) {
        int swapCount = 0;
        for (int i = 0; i < inputs.length; i++) {
            for (int j = inputs.length - 1; j > i; j--) {
                if (compare(inputs[j], inputs[j-1])) {
                    swap(inputs, j, j-1);
                    swapCount++;
                }
            }
        }
        return swapCount;
    }

    /**
     * selection sort
     * @param inputs
     * @return
     */
    private static int selectionSort(String[] inputs) {
        int swapCount = 0;
        int min = 0;

        for (int i = 0; i < inputs.length; i++) {
            min = i;
            for (int j = i; j < inputs.length; j++) {
                if (compare(inputs[j], inputs[min])) {
                    min = j;
                }
            }
            if (i != min) {
                swap(inputs, i, min);
                swapCount++;
            }
        }
        return swapCount;
    }

    private static String[] mockup() {
        String a[] = {"H4","C9","S4","D2","C3"};
        return a;
    }

    private static void swap(String[] inputs, int j, int i) {
        String a = inputs[j];
        String b = inputs[i];
        inputs[i] = a;
        inputs[j] = b;
    }
    private static boolean compare(String a, String b) {
        int iA = Integer.valueOf(a.substring(1));
        int iB = Integer.valueOf(b.substring(1));
        return iA < iB;
    }

    public static void output(String[] inputs) {
        // output
        StringBuilder output = new StringBuilder();
        for (String i : inputs) {
            output.append(i + " ");
        }
        String outputString = output.toString();
        System.out.println(outputString.substring(0,outputString.length() - 1));
    }

    public static String[] input() {
        Scanner in = new Scanner(System.in);
        int count = in.nextInt();
        String[] inputs = new String[count];
        for (int i = 0; i < count; i++) {
            inputs[i] = in.next();
        }
        in.close();
        return inputs;
    }

}

