		for(int i=0;i<in.length-1;i++){
			int mini=i;
			for(int j=i+1;j<in.length;j++){
				if(in[mini].charAt(1)>in[j].charAt(1)){
					mini=j;
				}
			}
			if(mini!=i){
			String tmp=in[i];
			in[i]=in[mini];
			in[mini]=tmp;}
		}}
