	public static void BubbleSort(String[] a, int n) {
		int flag = 1, i;
		String t;
		while (flag != 0) {
			flag = 0;
			for (i = n - 1; i > 0; i--) {
				if (a[i].charAt(1) < a[i-1].charAt(1)) {
					t = a[i];
					a[i] = a[i-1];
					a[i-1] = t;
					flag = 1;
				}
			}
		}
	}

	public static void SelectionSort(String[] a, int n) {
		int i, j, minat;
		String t;
		for (i = 0; i < n; i++) {
			minat = i;
			for (j = i + 1; j < n; j++)
				if (a[j].charAt(1) < a[minat].charAt(1))
					minat = j;
			if (i != minat) {
				t = a[i];
				a[i] = a[minat];
				a[minat] = t;
			}
		}
	}

	public static boolean isStable(String[] a, String[] b, int n) {
		for (int i = 0; i < n; i++)
			if (a[i].charAt(0) != b[i].charAt(0))
				return false;
		return true;
	}
}



