				if(C[j].getN() < C[j - 1].getN()) {
					Card v = C[j];
					C[j] = C[j - 1];
					C[j - 1] = v;
				}
			}
		}
	}
	static void selectionSort(Card[]C, int N) {
		for(int i = 0; i < N - 1; i++) {
			int min_j = i;
			for(int j = i; j < N; j++) {
				if(C[j].getN() < C[min_j].getN()) {
					min_j = j;
				}
			}
			Card v = C[i];
			C[i] = C[min_j];
			C[min_j] = v;
		}
	}
