namespace AOJ.ALDS
{
    public class StableSort
    {
        private struct Card
        {
            public string Suit { get; set; }
            public int Number { get; set; }
        }

        private static void BubbleSort(Card[] array, int N)
        {
            for (int i = 0; i < N; i++)
            {
                bool end = true;
                for (int j = N - 1; j > i; j--)
                {
                    if (array[j].Number < array[j - 1].Number)
                    {
                        var tmp = array[j];
                        array[j] = array[j - 1];
                        array[j - 1] = tmp;
                        end = false;
                    }
                }
                if (end) { break; }
            }
        }

        private static void SelectionSort(Card[] array, int N)
        {
            for (int i = 0; i < N; i++)
            {
                int min_j = i;
                for (int j = i; j < N; j++)
                {
                    if (array[j].Number < array[min_j].Number) { min_j = j; }
                }

                if (i != min_j)
                {
                    var tmp = array[i];
                    array[i] = array[min_j];
                    array[min_j] = tmp;
                }
            }
        }

        public static void Main()
        {
            int counter = int.Parse(Console.ReadLine());
            var input = Console.ReadLine().Trim().Split(' ');
            var bubble = new Card[counter];
            var select = new Card[counter];
            for (int i = 0; i < counter; i++)
            {
                bubble[i].Suit = input[i].Substring(0, 1);
                bubble[i].Number = int.Parse(input[i].Substring(1, 1));
                select[i] = bubble[i];
            }

            BubbleSort(bubble, counter);
            SelectionSort(select, counter);

            bool is_stable = true;
            for (int i = 0; i < counter; i++)
            {
                if (bubble[i].Suit != select[i].Suit || bubble[i].Number != select[i].Number)
                {
                    is_stable = false;
                    break;
                }
            }

            string out_bubble = "";
            foreach (var c in bubble) { out_bubble += c.Suit + c.Number + " "; }
            out_bubble = out_bubble.Trim();

            string out_sel = "";
            foreach (var c in select) { out_sel += c.Suit + c.Number + " "; }
            out_sel = out_sel.Trim();

            Console.WriteLine(out_bubble);
            Console.WriteLine("Stable");
            Console.WriteLine(out_sel);
            Console.WriteLine(is_stable ? "Stable" : "Not stable");
        }
    }
}

