  public static string check(String[] cmp, String[] arr, int max){
    List<string> t = new List<string>();
    int cur = int.Parse(arr[0].Substring(1,arr[0].Length-1));
    for(int i=0; i<max; i++){
      //Console.WriteLine("cur: {0}",cur);
      if(int.Parse(arr[i].Substring(1,arr[i].Length-1)) == cur){
        t.Add(arr[i]);
        continue;
      }
      else{
        int p = 0;
        for(int j=0; j<max; j++){
          if(cmp[j].Equals(t[p])){
            p++;
          }
          if(p == t.Count){
            break;
          }
        }
        if(p != t.Count){
          return "Not stable";
        }
        t.Clear();
        cur = int.Parse(arr[i].Substring(1,arr[i].Length-1));
        t.Add(arr[i]);
      }
    }
    if(t.Count != 0){
      int p = 0;
      for(int j=0; j<max; j++){
        if(cmp[j].Equals(t[p])){
          p++;
        }
        if(p == t.Count){
          break;
        }
      }
      if(p != t.Count){
        return "Not stable";
      }
    }
    return "Stable";
  }
  public static bool compare(String s1, String s2){
    String t1 = s1.Substring(1,s1.Length-1);
    String t2 = s2.Substring(1,s2.Length-1);
    return int.Parse(t1) < int.Parse(t2);
  }
  public static void BubbleSort(String[] s, int n){
    for(int i=0; i<n; i++){
      for(int j=n-1; j>i; j--){
        if(compare(s[j],s[j-1])){
          String t = s[j];
          s[j] = s[j-1];
          s[j-1] = t;
        }
      }
    }
  }
  public static void SelectionSort(String[] s, int n){
    int min;
    for(int i=0; i<n; i++){
      min = i;
      for(int j=i; j<n; j++){
        if(compare(s[j],s[min])){
          min = j;
        }
      }
      String t = s[min];
      s[min] = s[i];
      s[i] = t;
    }
  }
}

