    struct Card
    {
        int rank;
        string suit;
        public Card(String s)
        {
            suit = s[0].ToString();
            rank = int.Parse(s[1].ToString());
        }

        public static void BubbleSort(Card[] cards)
        {
            for (int i = 0; i < cards.Length; i++)
            {
                for (int j = cards.Length - 1; j > i; j--)
                {
                    if (cards[j].rank < cards[j - 1].rank)
                    {
                        var temp = cards[j];
                        cards[j] = cards[j - 1];
                        cards[j - 1] = temp;
                    }
                }
            }
        }

        public static bool SelectionSort(Card[] cards)
        {
            var stable1 = false;
            var stable2 = false;
            for (int i = 0; i < cards.Length; i++)
            {
                var minj = i;
                for (int j = i; j < cards.Length; j++)
                {
                    if (cards[j].rank == cards[minj].rank) stable1 = true ;
                        if (cards[j].rank < cards[minj].rank) minj = j;
                }
                if (minj != i)
                {
                    var temp = cards[i];
                    cards[i] = cards[minj];
                    cards[minj] = temp;
                    stable2 = true;
                }
            }
            return stable1&&stable2;
        }

        public override string ToString()
        {
            return suit + rank;
        }
    }
}

