    class Program
    {
        class Tramp
        {
            public char Mark { get; set; }
            public int Number { get; set; }
            public Tramp(char mark, int number)
            {
                Mark = mark;
                Number = number;
            }
            public Tramp(Tramp t) : this(t.Mark, t.Number)
            {

            }
            public void Swap(Tramp other)
            {
                var m = Mark;
                var n = Number;
                Mark = other.Mark;
                Number = other.Number;
                other.Mark = m;
                other.Number = n;
            }
            public override int GetHashCode()
            {
                return Number;
            }
            public override bool Equals(object obj)
            {
                if (obj == null)
                {
                    return false;
                }
                var t = obj as Tramp;
                if (t == null)
                {
                    return false;
                }
                return Number == t.Number;
            }
            public override string ToString()
            {
                return string.Format("{0}{1}", Mark, Number);
            }
        }

        static void Main(string[] args)
        {
            var N = GetNumber();
            var a = GetStrings(N).Select(xs => new Tramp(xs[0], int.Parse(xs.Substring(1)))).ToArray();
            var b = a.Select(x => new Tramp(x)).ToArray();
            var c = a.Select(x => new Tramp(x)).OrderBy(x => x.Number).ToArray();
            var outputC = string.Join(" ", c.Select(x => x.ToString()).ToArray());

            BubbleSort(a);
            var outputA = string.Join(" ", a.Select(x => x.ToString()).ToArray());
            System.Console.WriteLine(outputA);
            System.Console.WriteLine(outputA == outputC ? "Stable" : "Not stable");

            SelectionSort(b);
            var outputB = string.Join(" ", b.Select(x => x.ToString()).ToArray());
            System.Console.WriteLine(outputB);
            System.Console.WriteLine(outputB == outputC ? "Stable" : "Not stable");
        }

        //static StreamReader Console = new StreamReader("input.txt");

        static int BubbleSort(Tramp[] A)
        {
            var count = 0;
            for (int i = 0; i < A.Length - 1; i++)
            {
                for (int j = A.Length - 1; j >= i + 1; j--)
                {
                    if (A[j].Number < A[j - 1].Number)
                    {
                        count++;
                        A[j].Swap(A[j - 1]);
                    }
                }
            }
            return count;
        }

        static int SelectionSort(Tramp[] A)
        {
            var count = 0;
            for (var i = 0; i < A.Length; i++)
            {
                var mini = i;
                for (var j = i; j < A.Length; j++)
                {
                    if (A[j].Number < A[mini].Number)
                    {
                        mini = j;
                    }
                }

                if (i != mini)
                {
                    A[i].Swap(A[mini]);
                }
            }
            return count;
        }

