            {
                p1 = p2;
                for (int j = n - 1; j > p1; j--)
                    if (int.Parse(str[j - 1][1].ToString()) > int.Parse(str[j][1].ToString())) { string tmp = str[j]; str[j] = str[j - 1]; str[j - 1] = tmp; p2 = j; }
