		for (int j = i+1; j < IN.Length; j++)
		{
			for (int a = 0; a < IN.Length; a++)
			{
				for (int b = a+1; b < IN.Length; b++)
				{
					if(IN[i].ToCharArray()[1] == IN[j].ToCharArray()[1] 
						&& IN[i].ToCharArray()[0] == OUT[b].ToCharArray()[0]
						&& IN[j].ToCharArray()[0] == OUT[a].ToCharArray()[0])
						return false;
				}
			}
		}
	}
	return true;
}
