            A[i]=new Card(s[i][0], int.Parse(""+s[i][1]));
            B[i]=new Card(s[i][0], int.Parse(""+s[i][1]));
        }

        BubbleSort(A);
        for(var i=0; i<N; i++){
            Console.Write(""+A[i].suit+A[i].value);
