    private void Scan()
    {
        N = int.Parse(Console.ReadLine());
        A = Console.ReadLine().Split(' ');
    }

    private void Swap(ref string a, ref string b)
    {
        var t = a;
        a = b;
        b = t;
    }

    private void BubbleSort()
    {
        var C = A.ToArray();
        for (int i = 0; i < N; i++)
        {
            for (int j = N - 1; j > i; j--)
