        private static bool IsStable(IReadOnlyList<Card> input, IReadOnlyList<Card> sorted)
        {
            for (var i = 0; i < input.Count; i++)
            {
                for (var j = i + 1; j < input.Count; j++)
                {
                    for (var a = 0; a < input.Count; a++)
                    {
                        for (var b = a + 1; b < input.Count; b++)
                        {
                            if (input[i].Id == input[j].Id && input[i].Kind == sorted[b].Kind && input[j].Kind == sorted[a].Kind)
                                return false;
                        }
                    }
                }
            }
            return true;
        }

        private static void WritePartial(IEnumerable<Card> card)
        {
            WriteLine(card.Select(c => c.Kind).Aggregate((word, next) => $"{word} {next}"));
        }

