        {
            for (var i = 0; i < n; i++)
            {
                for (var j = n - 1; j > i; j--)
                {
                    if (cards[j].Id < cards[j - 1].Id)
                    {
                        // Swap
                        var tmp = cards[j];
                        cards[j] = cards[j - 1];
                        cards[j - 1] = tmp;
                    }
                }
            }
        }

        private static void SelectionSort(Card[] cards, int n)
        {

            for (var i = 0; i < n; i++)
            {
                var minj = i;
                for (var j = i; j < n; j++)
                {
                    // search minimum
                    if (cards[j].Id < cards[minj].Id) minj = j;
                }

                var tmp = cards[i];
                cards[i] = cards[minj];
                cards[minj] = tmp;
            }
        }        

    }

