	{
		for (int j = C.Length -1 ; i < j; j--)
		{
			if(int.Parse((C[j]).ToCharArray()[1].ToString()) < int.Parse((C[j-1]).ToCharArray()[1].ToString())){
				var tmp = C[j];
				C[j] = C[j-1];
				C[j-1] = tmp;
			}
		}
	}
	return C.ToList();
}

public static List<string> SelectionSort(string[] C)
{
	for (int i = 0; i < C.Length; i++)
	{
