		for (int j = i; j < C.Length; j++)
		{
			if(int.Parse(C[j].ToCharArray()[1].ToString()) < int.Parse(C[minj].ToCharArray()[1].ToString())){
				minj = j;
			}
		}
		var tmp = C[i];
