class StableSort {

    static void PrintArr(string[] C, int N) {
        for (int i = 0; i < N; i++) {
            Console.Write(C[i]);

            if (i != N-1)
                Console.Write(" ");
            else
                Console.Write("\n");
        }
    }

    static void BubbleSort(string[] C, int N) {

        for (int i = 0; i < N; i++) {
            for (int j = N-1; j > i; j--) {
                if (C[j][1] < C[j-1][1])
                    swap(C[j], C[j-1]);
            }
        }
        PrintArr(C, N);
        Console.WriteLine("Stable");
    }

    static void SelectionSort(string[] C, int N) {

        for (int i = 0; i < N; i++) {
            int minj = i;
            for (int j = i; j < N; j++){
                if (C[j][1] < C[minj][1])
                    minj = j;
            }
            swap(C[i], C[minj]);
        }
        PrintArr(C, N);
    }

