			}
		}
		var tmp = C[i];
		C[i] = C[minj];
		C[minj] = tmp;
	}

	return C.ToList();
}

public static bool IsStable(string[] IN, string[] OUT){
	for (int i = 0; i < IN.Length; i++)
	{
		if(!IN[i].Equals(OUT[i])) return false;
	}
	return true;
}
