            Output("Stable");

            var sS = selectionSort(CA, N);

            // Stable Check
            for(int i = 0; i < N; i++) {
                if(bS[i].suit != sS[i].suit) {
                    Output("Not stable");
                    return;
                }
            }
            Output("Stable");
		}

