        Card[] bubbleSort(Card[] A, int N) {
            //int swapCount = 0;
            var CA = A.Select(i => i.Clone())
					.ToArray();
            Card tmp;
            for(int i = 0; i < N -1; i++){
                for(int j = N - 1; j > i; j--){
                    if(CA[j-1].val <= CA[j].val) continue;
                    tmp = CA[j-1];
                    CA[j-1] = CA[j];
                    CA[j] = tmp;
                    //swapCount++;
                }
