namespace ALDS1_2_C {
    struct Card {
        public char suit;
        public int num;

        public Card(char suit,int num) {
            this.suit = suit;
            this.num = num;
        }

        public override string ToString() {
            return string.Format("{0}{1}", suit, num);
        }
    }

    class Program {
        static void Main(string[] args) {
            int n = int.Parse(Console.ReadLine());
            Card[] A = Console.ReadLine().Split(' ')
                .Select(c => new Card(c[0], int.Parse(c[1].ToString())))
                .ToArray();
            Card[] B = (Card[])A.Clone();
            Card[] stable = A.OrderBy(c => c.num).ToArray();

            // BubbleSort
            for (int i = 0; i < n; i++) {
                for (int j = n - 1; j > i; j--) {
                    if (A[j].num < A[j - 1].num) {
                        Card temp = A[j];
                        A[j] = A[j - 1];
                        A[j - 1] = temp;
                    }
                }
            }

            // SelectionSort
            for(int i = 0; i < n; i++) {
                int minj = i;
                for(int j = i; j < n; j++) {
                    if (B[j].num < B[minj].num)
                        minj = j;
                }

                if (minj != i) {
                    Card temp = B[i];
                    B[i] = B[minj];
                    B[minj] = temp;
                }
            }

            // result
            Print(A);
            Console.WriteLine(A.SequenceEqual(stable) ? "Stable" : "Not stable");
            Print(B);
            Console.WriteLine(B.SequenceEqual(stable) ? "Stable" : "Not stable");
