using System;

class Program
{
	static void Main(string[] args)
	{
		int n = int.Parse(Console.ReadLine());
		string[] input =new string[n];
		input = Console.ReadLine().Split(' ');

		BubbleSort(input);	
		SelectSort(input);
	}


	static void BubbleSort(string[] input)
	{
		string[] array = new string[input.Length];
		Array.Copy(input, array, input.Length);

		for (int i=0; i<array.Length; i++)
		{
			for (int j=0; j<array.Length-i-1; j++)
			{
				int a = int.Parse(array[j].Substring(1, 1));
				int b = int.Parse(array[j+1].Substring(1, 1));
				if (a > b)
				{
					Swap(ref array[j], ref array[j+1]);
				}
			}
		}

		Write(array, input);
	}

	static void SelectSort(string[] input)
	{
		string[] array = new string[input.Length];
		Array.Copy(input, array, input.Length);

		for (int i=0; i<array.Length; i++)
		{
			int min = i;
			for (int j=i+1; j<array.Length; j++)
			{
				int a = int.Parse(array[min].Substring(1, 1));
				int b = int.Parse(array[j].Substring(1, 1));
				if (a > b)
				{
					min = j;
				}
			}

			if (min != i)
			{
				Swap(ref array[i], ref array[min]);
			}
		}

		Write(array, input);
	}

	static void Swap(ref string a, ref string b)
	{
		string buf = a;
		a = b;
		b = buf;
	}

	static void Write(string[] array, string[] input)
	{
		bool is_stable = true;
		for (int i=0; i<array.Length; i++)
		{
			if(i > 0)
			{
				int a = int.Parse(array[i].Substring(1, 1));
				int b = int.Parse(array[i-1].Substring(1, 1));
				if(a == b)
				{
					for(int j=0; j<array.Length; j++)
					{
						if(array[i].Equals(input[j]))
						{
							is_stable = false;
							break;
						}
						else if(array[i-1].Equals(input[j]))
						{						
							break;
						}
					}
				}
			}
			Console.Write((i > 0 ? " " : "") + array[i]);
		}
		Console.WriteLine();
		Console.WriteLine(is_stable ? "Stable" : "Not stable");
	}
}

