            Console.WriteLine("Stable");

            Array.Copy(initCards, Cards, N);

            SelectionSort(Cards, N);
            Console.WriteLine(string.Join(" ", Cards));
            if (StableCheck(initCards, Cards))
                Console.WriteLine("Stable");
            else
                Console.WriteLine("Not stable");
        }

        public static void BubbleSort(string[] Cards, int N)
        {
            var temp = "";
            for (var i = 0; i < N; i++)
            {
                for (var j = N - 1; j > i; j--)
                {
                    if (Cards[j][1] < Cards[j - 1][1])
                    {
                        temp = Cards[j];
                        Cards[j] = Cards[j - 1];
                        Cards[j - 1] = temp;
                    }
                }
            }
        }

        public static void SelectionSort(string[] Cards, int N)
        {
            var minj = 0;
            var temp = "";
            for (var i = 0; i < N; i++)
            {
                minj = i;
                for (var j = i; j < N; j++)
                {
                    if (Cards[j][1] < Cards[minj][1])
                    {
                        minj = j;
                    }
                }
                temp = Cards[i];
                Cards[i] = Cards[minj];
                Cards[minj] = temp;
            }
        }

        public static bool StableCheck(string[] inCards, string[] outCards)
        {
            var N = inCards.Length;
            for(var i = 0; i < N; i++)
            {
                for(var j = i + 1; j < N; j++)
                {
                    for(var a = 0; a < N; a++)
                    {
                        for(var b = a + 1; b < N; b++)
                        {
                            if (inCards[i][1] == inCards[j][1] && inCards[i] == outCards[b] && inCards[j] == outCards[a])
                                return false;
                        }
                    }
                }
            }
            return true;
        }
