class Sorting
{
    public void BubbleSort(Card[] cards, int N) {
        Card temp = new Card();
        for (int i = 0; i < N; i++) {
            for(int j = N - 1; j > i; j--) {
                if (cards[j].numop < cards[j - 1].numop) {
                    temp = cards[j];
                    cards[j] = cards[j - 1];
                    cards[j - 1] = temp;
                }
            }
        }
        print(cards, N);
    }

    public void SelectionSort(Card[] cards, int N) {
        Card temp = new Card();
        for (int i = 0; i < N; i++) {
            int minj = i;
            for (int j = i; j < N; j++) {
                if (cards[j].numop < cards[minj].numop) {
                    minj = j;
                }
            }
            temp = cards[i];
            cards[i] = cards[minj];
            cards[minj] = temp;
        }
        print(cards, N);
    }

    public void print(Card[] cards, int n) {
        for(int i = 0; i < n; i++) {
            if (i > 0) {
                Console.Write(" ");
            }
            Console.Write("{0}{1}", cards[i].markop, cards[i].numop);
        }
        Console.WriteLine();
    }

