class Program
{    
    private struct Card
    {
        public string ch { set; get; }
        public int num { get; set; }
    }

    static void BubbleSort(Card[] data, int n)
    {
        bool flag = true;
        int k = 0;
        while (flag)
        {
            flag = false;
            for(int i = n - 1; i > k; i--)
            {
                if(data[i].num < data[i - 1].num)
                {
                    var temp = data[i];
                    data[i] = data[i - 1];
                    data[i - 1] = temp;
                    flag = true;
                }               
            }
            k++;
        }

    }

    static void SelectionSort(Card[] data, int n)
    {
        for(int i = 0; i < n - 1; i++)
        {
            int minj = i;
            for(int j = i; j < n; j++)
            {
                if(data[j].num < data[minj].num)
                {
                    minj = j;
                }
            }
            var temp = data[i];
            data[i] = data[minj];
            data[minj] = temp;
        }
    }

    static bool IsStable(Card[] select, Card[] bubule, int n)
    {
        for(int i = 0; i < n; i++)
        {
            if(select[i].ch != bubule[i].ch)
            {
                return false;
            }
        }
        return true;
    }


