                    if (int.Parse(str[j][1].ToString()) < int.Parse(str[mini][1].ToString())) mini = j;
                if (i != mini) { string tmp = str[i]; str[i] = str[mini]; str[mini] = tmp; }
            }
            Console.WriteLine(string.Join(" ", str));
        }

