        public void BubbleSort<T>(T[] A) where T : IComparable<T> {
            var N = A.Length;
            var flag = true;
            while (flag) {
                flag = false;
                for (int i = N - 2; i >= 0; i--) {
                    if (A[i].CompareTo( A[i + 1] ) > 0) {
                        A.Swap( i, i + 1 );
                        flag = true;
                    }
                }
            }
        }
        public void SelectionSort<T>(T[] A) where T : IComparable<T> {
            var N = A.Length;
            for (int i = 0; i < N; i++) {
                var mi = i;
                for (int j = i + 1; j < N; j++) {
                    if (A[j].CompareTo(A[mi])<0) {
                        mi = j;
                    }
                }
                if (i != mi) 
                    A.Swap( i, mi );
            }
        }   

        public bool isStable<T>(T[] src, T[] dst, int N) where T: IComparable<T> {
            int[] map = new int[N];
            for (int i = 0; i < N; i++) {
                map[i] = Array.IndexOf( dst, src[i] );
            }
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    if (src[i].CompareTo( src[j] ) == 0) {
                        if (i<j && map[i] > map[j]) return false;
                    }
                }
            }
            return true;
        }
    }

