        C[minj] = C[i];
        C[i] = temp;
      }

      if (StableCheck(C0, C) == true) Console.WriteLine("Stable");
      else Console.WriteLine("Not stable");
    }

    static bool StableCheck(string[] C0, string[] C)
    {
      foreach (var x in C)
      {
        Console.Write(x[0].ToString() + x[1].ToString() + " ");
      }
      Console.Write("\b\n");

      List<int> list = new List<int>();

      foreach (var x in C)
      {
        int count = 0;
        for (int i = 0; i < C.Length; i++)
        {
          if (C[i][1] == x[1]) count++;
        }
        if (count == 1)
        {
          count = 0;
          continue;
        }
        list.Add(x[1]);
      }

      foreach (var d in list)
      {
        List<char> s0 = new List<char>();
        List<char> s1 = new List<char>();

        for (int j = 0; j < C0.Length; j++)
        {
          if (C0[j][1] == d) s0.Add(C0[j][0]);
        }

        for (int j = 0; j < C.Length; j++)
        {
          if (C[j][1] == d) s1.Add(C[j][0]);
        }
        if (new String(s0.ToArray()) != new String(s1.ToArray())) return false;
      }
      return true;
    }
  }
