namespace Sorts
{
    class Program
    {
        public struct Card
        {
            public readonly char m;
            public readonly int n;
            public Card(char m, int n)
            {
                this.m = m;
                this.n = n;
            }
        }

        private static Card[] B_Sort(Card[] ca)
        {
            var c = new Card[ca.Length];
            Array.Copy(ca, 0, c, 0, c.Length);
            for (var i = 0; i < c.Length; i++)
                for (var j = c.Length - 1; j > i; j--)
                    if (c[j].n < c[j - 1].n)
                    {
                        var t = c[j];
                        c[j] = c[j - 1];
                        c[j - 1] = t;
                    }
            return c;
        }

        private static Card[] S_Sort(Card[] ca)
        {
            var c = new Card[ca.Length];
            Array.Copy(ca, 0, c, 0, c.Length);
            for (var i = 0; i < c.Length; i++)
            {
                var m = i;
                for (var j = i; j < c.Length; j++)
                {
                    if (c[m].n > c[j].n)
                        m = j;
                }
                var t = c[m];
                c[m] = c[i]; c[i] = t;
            }
            return c;
        }

        public static void Main()
        {
            Console.ReadLine();
            var i = Console.ReadLine().Split();
            var cards = new Card[i.Length];
            for(int j = 0; j < i.Length; j++)
            {
                var m = i[j][0];
                var n = int.Parse(i[j].Remove(0, 1));
                cards[j] = new Card(m, n);
            }
            var b_cards = string.Join(" ", Array.ConvertAll(B_Sort(cards), e => string.Format("{0}{1}", e.m, e.n)));
            var s_cards = string.Join(" ", Array.ConvertAll(S_Sort(cards), e => string.Format("{0}{1}", e.m, e.n)));
            Console.WriteLine("{0}", b_cards);
            Console.WriteLine("Stable");
            Console.WriteLine("{0}", s_cards);
            Console.WriteLine("{0}", b_cards == s_cards ? "Stable" : "Not stable");
        }
    }
}

