            T tmp = _arr[_i];
            _arr[_i] = _arr[_j];
            _arr[_j] = tmp;
        }

        static bool IsStableSort(string[] _orig, string[] _sorted)
        {
            for (int i = 1; i < _sorted.Length; i++)
            {
                if (GetNumber(_sorted[i - 1]) == GetNumber(_sorted[i]))
                {
                    if (Array.IndexOf(_orig, _sorted[i - 1]) > Array.IndexOf(_orig, _sorted[i]))
                    {
                        return false;
                    }
                }
            }
            return true;
        }

