using System;

class Stable_Sort {
	public static void Main() {

		string num = Console.ReadLine();
		int n = int.Parse(num);

		string[] arr = new string[n];

		string cards = Console.ReadLine();
		arr = cards.Split();
		string[] mem = arr;
		for(int j = 0; j < n; j++) {
			for(int i = n - 1; i > j; i--) {

				if((int)arr[i][1] < (int)arr[i - 1][1]) {
					Swap(ref arr[i], ref arr[i - 1]);
				}

			}
		}

		for(int i = 0; i < n; i++) {
			if(i != n - 1)
			Console.Write(arr[i] + " ");
			else
			Console.WriteLine(arr[i]);
		}
		Console.WriteLine("Stable");

		arr = mem;

		// -------------------------------

		int min;
		int minn = 0;
		for(int i = 0; i < n - 1; i++) {
			min = arr[i][1];
			for(int j = 1 + i; j < n; j++) {

				if((int)arr[j][1] < min) {
					min = (int)arr[j][1];
					minn = j;
				}
			}
			if((int)arr[i][1] != min) {
				Swap(ref arr[i], ref arr[minn]);
			}

		}

		for(int i = 0; i < n; i++) {
			if(i != n - 1)
			Console.Write(arr[i] + " ");
			else
			Console.WriteLine(arr[i]);
		}

		Console.WriteLine("Not stable");

	}

	static void Swap(ref string x, ref string y) {
		string comp = x;
		x = y;
		y = comp;
		return;
	}
}

