		for(int i = 0; i < n; i++) {
			mem[i] = arr[i];
		}

		for(int j = 0; j < n; j++) {
			for(int i = n - 1; i > j; i--) {

				if((int)arr[i][1] < (int)arr[i - 1][1]) {
					Swap(ref arr[i], ref arr[i - 1]);
				}

			}
		}

		for(int i = 0; i < n; i++) {
			if(i != n - 1)
			Console.Write(arr[i] + " ");
			else
			Console.WriteLine(arr[i]);
		}
		Console.WriteLine("Stable");

		// ------------------------------- Not stable
		int min;
		int minn = 0;
		for(int i = 0; i < n - 1; i++) {
			min = mem[i][1];
			for(int j = 1 + i; j < n; j++) {

				if((int)mem[j][1] < min) {
					min = (int)mem[j][1];
					minn = j;
				}
			}
			if((int)mem[i][1] != min) {
				Swap(ref mem[i], ref mem[minn]);
			}

