			Console.Write(mem[i] + " ");
			else
			Console.WriteLine(mem[i]);
		}

		Console.WriteLine("Not stable");

	}

	static void Swap(ref string x, ref string y) {
		string comp = x;
		x = y;
		y = comp;
		return;
	}
}

