class Program
{
    static void Main(string[] args)
    {
        int n = int.Parse(Console.ReadLine());

        string[] card = Console.ReadLine().Split(' ');

        BubbleSort(card);

        SelectSort(card);
    }

    static void BubbleSort(string[] card)
    {
        string[] a =  new string[card.Length];
        Array.Copy(card, a, card.Length);

        bool flag = true;
        while (flag)
        {
            flag = false;
            for (int i = a.Length-1; i > 0; i--)
            { 
                int n0 = int.Parse(a[i].Substring(1, 1));
                int n1 = int.Parse(a[i - 1].Substring(1, 1));
                if (n0 < n1)
                {
                    string buf = a[i - 1];
                    a[i - 1] = a[i];
                    a[i] = buf;
                    flag = true;
                }
            }
        }

        Output(card, a);
    }

    static void SelectSort(string[] card)
    {
        string[] a =  new string[card.Length];
        Array.Copy(card, a, card.Length);

        for (int i = 0; i < a.Length; i++)
        {
            int min = i;

            for (int j = i+1; j < a.Length; j++)
            {
                int n0 = int.Parse(a[j].Substring(1, 1));
                int n1 = int.Parse(a[min].Substring(1, 1));
                if (n0 < n1)
                {
                    min = j;
                }
            }

            if (i != min)
            { 
                string buf = a[i];
                a[i] = a[min];
                a[min] = buf;
            }
        }
        Output(card, a);
    }

    static void Output(string[] card, string[] a)
    {
        string output = "";
        bool stable = true;

        for (int i = 0; i < a.Length; i++)
        {
            output += a[i] + ((i == a.Length-1) ? "" : " ");

            if (i > 0)
            {
                int n = int.Parse(a[i].Substring(1, 1));
                int m = int.Parse(a[i-1].Substring(1, 1));

                if (stable && n == m)
                {
                    for (int j = 0; j < card.Length; j++)
                    {   
                        if (a[i] == card[j])
                        {
                            stable = false;
                            break;
                        }
                        else if (a[i - 1] == card[j])
                        {
                            break;
                        }
                    }
                }
            }
        }

        Console.WriteLine(output);
        Console.WriteLine(stable ? "Stable" : "Not stable");
    }
}

