        Card[] bubbleSort(Card[] A, int N) {
            //int swapCount = 0;
            var CA = A.Select(i => i.Clone())
					.ToArray();
            Card tmp;
            for(int i = 0; i < N -1; i++){
                for(int j = N - 1; j > i; j--){
                    if(CA[j-1].val <= CA[j].val) continue;
                    tmp = CA[j-1];
                    CA[j-1] = CA[j];
                    CA[j] = tmp;
                    //swapCount++;
                }
            }
            Output(CA.Select(i => i.ToString())
						.Aggregate((i, j) => i + " " + j));
            //Output(swapCount.ToString());
            return CA;
        }

        Card[] selectionSort(Card[] A, int N) {
            //int swapCount = 0;
            var CA = A.Select(i => i.Clone())
					.ToArray();
            int minIndex;
            Card tmp;
            for(int i = 0; i < N - 1; i++){
                minIndex = i;
                for(int j = i + 1; j < N; j++){
                    if(CA[j].val < CA[minIndex].val)
                        minIndex = j;
                }
                if(i == minIndex) continue;
                //swapCount++;
                tmp = CA[i];
                CA[i] = CA[minIndex];
                CA[minIndex] = tmp;
            }
            Output(CA.Select(i => i.ToString())
						.Aggregate((i, j) => i + " " + j));
            //Output(swapCount.ToString());
            return CA;
        }
	}
