            string bubbleSortResult = BubbleSort(strForBubbleSort, n);
            string selectionSortResult = SelectionSort(strForSelectionSort, n);

            Console.WriteLine(bubbleSortResult);
            Console.WriteLine("Stable");
            Console.WriteLine(selectionSortResult);
            if(bubbleSortResult == selectionSortResult)
            {
                Console.WriteLine("Stable\n");
            }
            else
            {
                Console.Write("Not stable\n");
            }
        }
        public static void swap<T>(ref T x ,ref T y)
        {
            T temp = x;
            x = y;
            y = temp;
        }
        public static string BubbleSort(string[] strArray,int n)
        {
            string result = string.Empty;

            for (int i = 0; i < n - 1; ++i)
            {
                for (int j = n - 1; j > i; --j)
                {
                    if (strArray[j][1] < strArray[j - 1][1])
                    {
                        swap(ref strArray[j], ref strArray[j - 1]);
                    }
                }
            }
            for (int i = 0; i < n; ++i)
            {
                result += strArray[i];
                if (i != n - 1)
                {
                    result += " ";
                }
            }

            return result;
        }

        public static string SelectionSort(string[] strArray, int n)
        {
            string result = string.Empty;

            for (int i = 0; i < n - 1; ++i)
            {
                int minj = i;
                for (int j = i + 1; j < n; ++j)
                {
                    if (strArray[j][1] < strArray[minj][1])
                    {
                        minj = j;

                    }

                }
                if (strArray[minj][1] < strArray[i][1])
                {
                    swap(ref strArray[i], ref strArray[minj]);
                }

            }
            for (int i = 0; i < n; ++i)
            {
                result += strArray[i];
                if (i != n - 1)
                {
                    result += " ";
                }
            }

            return result;
        }
    }
}

