		public static void bubbleSort(ref Card[] arr) {
			int numSwap = 0;
			bool isDone = false;
			while (!isDone) {
				isDone = true;
				for (int i = arr.Length - 1; i > 0; --i) {
					if (arr [i].number < arr [i - 1].number) {
						Card tmp = arr [i - 1];
						arr [i - 1] = arr [i];
						arr [i] = tmp;
						isDone = false;
						++numSwap;
					} else if (arr [i].number == arr [i - 1].number) {
						if (arr [i].ternAppear < arr [i - 1].ternAppear) {
							Card tmp = arr [i - 1];
							arr [i - 1] = arr [i];
							arr [i] = tmp;
							isDone = false;
							++numSwap;
						}
					}
				}
			}

			trace (ref arr);

		}

		public static void selectionSort(ref Card[] arr) {

			int numSwap = 0;
			for (int i = 0; i < arr.Length; ++i) {
				int minj = i;
				for (int j = i; j < arr.Length; ++j) {
					if (arr [j].number < arr [minj].number) {
						minj = j;
					} else if (arr [j].number == arr [minj].number &&
						arr[j].ternAppear > arr[minj].ternAppear) {
						minj = j;
					}
				}

				if (i != minj) {
					Card tmp = arr [i];
					arr [i] = arr [minj];
					arr [minj] = tmp;
					++numSwap;
				}
			}

			trace (ref arr);

		}

	}
