            string ans = "Stable";
            for(int i=0; i <= n - 1; i++)
            {
                if (num1[i].Suit != num2[i].Suit) stable = false;
            }
            if (!stable) ans = "Not stable";
            Console.WriteLine(ans);
        }
    }
