    static void BubbleSort(string[] C0, string[] C, int N)
    {
      for (int i = 0; i < N - 1; i++)
      {
        for (int j = N - 1; j >= i + 1; j--)
        {
          if ((int)C[j][1] < (int)C[j - 1][1])
          {
            string temp = C[j];
            C[j] = C[j - 1];
            C[j - 1] = temp;
          }
        }
      }
      if (StableCheck(C0, C) == true) Console.WriteLine("Stable");
      else Console.WriteLine("Not stable");
    }

    static void SelectionSort(string[] C0, string[] C, int N)
    {
      for (int i = 0; i < N - 1; i++)
      {
        int minj = i;
        for (int j = i; j <= N - 1; j++)
        {
          if (C[j][1] < C[minj][1]) minj = j;
        }
        string temp = C[minj];
        C[minj] = C[i];
        C[i] = temp;
      }

      if (StableCheck(C0, C) == true) Console.WriteLine("Stable");
      else Console.WriteLine("Not stable");
    }

