                    sortedCards[min] = sortedCards[i];
                    sortedCards[i] = tmp;
                }
            }

            return sortedCards;
        }

        static List<int> getCardValues(Card[] cards)
        {
            var values = new List<int>();
            foreach(var card in cards) {
                if (!values.Contains(card.Value))
                {
                    values.Add(card.Value);
                }
            }

            return values;
