            foreach (var key in originalSuitOrders.Keys)
            {
                for (var i = 0; i < originalSuitOrders[key].Count; i++)
                {
                    if (originalSuitOrders[key][i] != sortedSuitOrders[key][i])
                    {
                        return false;
                    }
                }
            }

