        {
            for (int j = 1; j < i; j++)
            {
                if (m[j - 1][1] > m[j][1])
                {
                    string buf = m[j];
                    m[j] = m[j - 1];
                    m[j - 1] = buf;
                }
            }
        }
        for (int i = 0; i < n; i++)
        {
            int min = i;
            for (int j = i; j < n; j++)
            {
                if (mcp[j][1] < mcp[min][1]) { min = j; }
            }
            if (i != min)
            {
                string buf = mcp[i];
                mcp[i] = mcp[min];
                mcp[min] = buf;
            }
        }
