        public static string[] BubbleSort(string[] A, int N)
        {
            var flag = true;
            var count = 0;
            while (flag)
            {
                flag = false;
                for (int j = N - 1; j >= 1; j--)
                {
                    if (A[j][1] < A[j - 1][1])
                    {
                        var c = A[j];
                        A[j] = A[j - 1];
                        A[j - 1] = c;
                        flag = true;
                        count++;
                    }
                }
            }
            return A;
        }

        public static string[] SelectionSort(string[] A, int N)
        {
            for (int i = 0; i <= N - 1; i++)
            {
                var minj = i;
                for (int j = i; j <= N - 1; j++)
                {
                    if (A[j][1] < A[minj][1])
                    {
                        minj = j;
                    }
                }
                if (A[i][1] != A[minj][1])
                {
                    var c = A[i];
                    A[i] = A[minj];
                    A[minj] = c;
                }
            }
            return A;
        }

        public static void Print(string[] A, int N)
        {
            var prt = "";
            for (int i = 0; i < N; i++)
            {
