namespace ALDS1_2_C
{
    public enum SortMethod
    {
        Bubble,
        Selection
    }
    public static class Algorithm
    {
        public static void Sort<T>(this T[] array, SortMethod method) where T : IComparable<T>
        {
            switch (method)
            {
                case SortMethod.Bubble: BubbleSort(array); break;
                case SortMethod.Selection: SelectionSort(array); break;
            }
        }

        private static void BubbleSort<T>(T[] array) where T : IComparable<T>
        {
            var n = array.Length;
            for (int i = 0; i < n; i++)
            {
                for (int j = n - 1; j > i; j--)
                {
                    if (array[j-1].CompareTo(array[j]) > 0)
                    {
                        var temp = array[j];
                        array[j] = array[j-1];
                        array[j-1] = temp;
                    }
                }
            }
        }
        private static void SelectionSort<T>(T[] array) where T : IComparable<T>
        {
            var n = array.Length;
            for (int i = 0; i < n - 1; i++)
            {
                int min = i;
                for (int j = i + 1; j < n; j++) if (array[min].CompareTo(array[j]) > 0) min = j;
                if (min != i)
                {
                    var temp = array[i];
                    array[i] = array[min];
                    array[min] = temp;
                }
            }
        }
    }

