    private static bool IsStable(Card[] raw, Card[] target) {
        for (int i = 0; i < raw.Length; i++) {
            for (int j = i + 1; j < raw.Length; j++) {
                for (int a = 0; a < target.Length; a++) {
                    for (int b = a + 1; b < target.Length; b++) {
                        if (raw[i].Value == raw[j].Value && raw[i].Raw == target[b].Raw && raw[j].Raw == target[a].Raw) {
                            return false;
                        }
                    }
                }
            }
        }
        return true;
    }

    private static Card[] SelectionSort(Card[] raw) {
        var cards = raw.DeepCopy();

        for (int i = 0; i < cards.Length; i++) {
            var minj = i;
            for (int j = i; j < cards.Length; j++) {
                if (cards[minj].Value > cards[j].Value) {
                    minj = j;
                }
            }

            if (minj != i) {
                cards.Swap(minj, i);
            }
        }

        return cards;
    }

    private static Card[] BubbleSort(Card[] raw) {
        var cards = raw.DeepCopy();

        for (int i = 0; i < cards.Length; i++) {
            for (int j = cards.Length - 1; j >= i + 1; j--) {
                if (cards[j].Value < cards[j - 1].Value) {
                    cards.Swap(j, j - 1);
                }
            }
        }

        return cards;
    }
}

