            {
                for (int j=n-1; j>i; j--)
                {
                    int a = int.Parse(str[j].Substring(1,1));
                    int b = int.Parse(str[j-1].Substring(1,1)); 
                    if (a < b)
                    {
                        string tmp = str[j];
                        str[j] = str[j-1];
                        str[j - 1] = tmp;
                    }
