                    Console.WriteLine();
                }
            }
        }

        static void SelectionSort(string[] str, int n)
        {
            for (int i=0; i<n; i++)
            {
                int minj = i;
                for (int j=i; j<n; j++)
                {
                    int c = int.Parse(str[j].Substring(1,1));
                    int d = int.Parse(str[minj].Substring(1,1));

                    if (c < d) minj = j;
                }
                string tmp = str[i];
                str[i] = str[minj];
                str[minj] = tmp;
            }

            for (int i=0; i<n; i++)
            {
