        for (int i = 0; i < N; i++) {
            for (int j = N-1; j > i; j--) {
                if (C[j][1] < C[j-1][1]) {
                    string tmp = C[j];
                    C[j] = C[j-1];
                    C[j-1] = tmp;
                }
            }
        }
        PrintArr(C, N);
        Console.WriteLine("Stable");
    }

    static void SelectionSort(string[] C, int N) {

        for (int i = 0; i < N; i++) {
            int minj = i;
            for (int j = i; j < N; j++){
                if (C[j][1] < C[minj][1])
                    minj = j;
            }
            string tmp = C[i];
            C[i] = C[minj];
            C[minj] = tmp;
        }
