using System;
using System.Linq;

namespace ALDS1_2_C {
    enum Suit {
        S = 'S',
        H = 'H',
        C = 'C',
        D = 'D',
    }

    class Card {
        public Suit suit{ get; private set; }
        public int val{ get; private set; }
        public Card(String str){
            var c = str.ToCharArray();
            suit = (Suit)c[0];
            val = int.Parse(c[1].ToString());
        }
        public override string ToString() {
            return this.suit.ToString() + this.val.ToString();
        }
        public Card Clone(){
            return (Card)MemberwiseClone();
        }
    }

	class Program {
		public Program() {}

		public static void Main() {
			new Program().Calc();
		}

		void Calc() {
			var N = int.Parse(Input);	// Number of elements
			var CA = Input				// CardArray : N elements
					.Split(' ')
					.Select(i => new Card(i))
					.ToArray();

			var bS = bubbleSort(CA, N);
            Output("Stable");

            var sS = selectionSort(CA, N);

            // Stable Check
            for(int i = 0; i < N; i++) {
                if(bS[i].suit != sS[i].suit) {
                    Output("Not stable");
                    return;
                }
            }
            Output("Stable");
		}

		String Input {
			get {
				return Console.ReadLine();
			}
		}

		void Output(String str) {
			Console.WriteLine(str);
		}

        Card[] bubbleSort(Card[] A, int N) {
            //int swapCount = 0;
            var CA = A.Select(i => i.Clone())
					.ToArray();
            Card tmp;
            for(int i = 0; i < N -1; i++){
                for(int j = N - 1; j > i; j--){
                    if(CA[j-1].val <= CA[j].val) continue;
