            {
                Console.WriteLine("Stable");
            }
            else
            {
                Console.WriteLine("Not stable");
            }
        }
        static int bubbleSort<T>(T[] array) where T: IComparable
        {
            int swapCnt = 0;
            for (var i = 0; i < array.Count(); i++)
            {
                for (var j = array.Count() - 1; j > i; j--)
                {
                    if (array[j - 1].CompareTo(array[j]) > 0)
                    {
                        var tmp = array[j - 1];
                        array[j - 1] = array[j];
                        array[j] = tmp;
                        swapCnt++;
                    }
                }
            }
            return swapCnt;
        }
        static int selectionSort<T>(T[] array) where T: IComparable
        {
            var swapCnt = 0;
            for (var i = 0; i < array.Length - 1; i++)
            {
                var min = array[i];
                var minIndex = i;
                for (var j = i + 1; j < array.Length; j++)
                {
                    if (array[j].CompareTo(min) < 0)
                    {
                        min = array[j];
                        minIndex = j;
                    }
                }
                if (min.CompareTo(array[i]) != 0)
                {
                    var tmp = array[i];
                    array[i] = array[minIndex];
                    array[minIndex] = tmp;
                    swapCnt++;
                }
            }
            return swapCnt;
        }
    }
