	public Card[] before_T = new Card[0];
	public Card[] after_T = new Card[0];

	public Card[] bubbleSortedArray = new Card[0];
	public Card[] selectionSortedArray = new Card[0];

	public StableSort(int n) {
		before_T = new Card[n];
		after_T = new Card[n];
		bubbleSortedArray = new Card[n];
		selectionSortedArray = new Card[n];
	}

	public void bubbleSort() {
		for (int i = 0; i < before_T.Length; i++) {
			for (int j = before_T.Length - 1; i < j; j--) {
				if (before_T [j].number < before_T [j - 1].number) {
					Card tmp = before_T [j];
					before_T [j] = before_T [j - 1];
					before_T [j - 1] = tmp;
				}
			}
		}
		// ???????????????????????????????????????
		before_T.CopyTo(bubbleSortedArray, 0);

		// before??¨after?????\????????????
		this.reset();
	}

	public void selectionSort() {
		for (int i = 0; i < before_T.Length; i++) {
			int minj = i;
			for (int j = i; j < before_T.Length; j++) {
				if (before_T [j].number < before_T [minj].number) {
					minj = j;
				}
			}
			Card tmp = before_T [i];
			before_T [i] = before_T [minj];
			before_T [minj] = tmp;
		}
		// ???????????????????????????????????????
		before_T.CopyTo(selectionSortedArray, 0);

		// before??¨after?????\????????????
		this.reset();
	}

	public void show() {
		for (int i = 0; i < after_T.Length; i++) {
			after_T [i].print ();			
		}
		Console.WriteLine ();
	}

	public void reset() {
		Card[] tmp = new Card[before_T.Length];
		before_T.CopyTo (tmp, 0);
		after_T.CopyTo (before_T, 0);
		tmp.CopyTo (after_T, 0);
	}


