		// ????????????????????????????????????????????????
		Console.WriteLine("Stable");

		// ?????????????????????????????????????????????
		stableSort.selectionSort();
		stableSort.show ();

		// ?????????????????????????????????????????????????????????(??????????????????????????£?????´??????????????????????????????)		
		for (int i = 0; i < N; i++) {
			// ????????????????????§??´????????????????????????????????¨????????????
