		private static string Judge_IsStable(Card[] cardArray)
		{
            foreach (var cardGroup in cardArray.GroupBy(card => card.Number).Where(g => g.Count() > 1))
            {
                int order_SameNumber = 1;
                foreach (var card in cardGroup)
                {
                    if (card.Order_SameNumber == order_SameNumber)
                    {
                        order_SameNumber++;
                        continue;
                    }
                    else
                    {
						return "Not stable";
                    }
                }
            }

			return "Stable";
		}

		private static Card[] BubbleSort(Card[] cardArray)
        {
			bool isSorted = true;
            while (isSorted)
            {
                isSorted = false;
                for (int i = cardArray.Length - 1; i > 0; i--)
                {
					if (cardArray[i - 1].Number > cardArray[i].Number)
                    {
						var temp = cardArray[i - 1];
						cardArray[i - 1] = cardArray[i];
						cardArray[i] = temp;

                        isSorted = true;
                    }
                }
            }

			return cardArray;
		}

		private static Card[] SelectionSort(Card[] cardArray)
        {
            for (int i = 0; i < cardArray.Length; i++)
            {
                int minIndex = i;
                for (int j = i; j < cardArray.Length; j++)
                {
                    if (cardArray[j].Number < cardArray[minIndex].Number)
                    {
                        minIndex = j;
                    }
                }

                if (minIndex != i)
                {
                    var temp = cardArray[i];
                    cardArray[i] = cardArray[minIndex];
                    cardArray[minIndex] = temp;
                }
            }

            return cardArray;
        }
    }
