function bubbleSort(A, N) {
  for (let i = 0; i < N - 1; ++i) {
    for (let j = N - 1; j >= i + 1; --j) {
      if (Number(A[j - 1][1]) > Number(A[j][1])) {
        const tmp = A[j];
        A[j] = A[j - 1];
        A[j - 1] = tmp;
      }
    }
  }
}

function selectionSort(A, N) {
  for (let i = 0; i < N - 1; ++i) {
    let minj = i;
    for (let j = i; j < N; ++j) {
      if (Number(A[j][1]) < Number(A[minj][1])) {
        minj = j;
      }
    }
    if (i !== minj) {
      const tmp = A[i];
      A[i] = A[minj];
      A[minj] = tmp;
    }
  }
}

