const largerThan = (a, b) => {
  let an = a.slice(1);
  let bn = b.slice(1);
  return an > bn;
};

const bubbleSort = (n, a) => {
  let isChanged = true;
  let index = 0;
  while (isChanged) {
    isChanged = false;
    for (let j = n - 1; j > index; j--) {
      if (largerThan(a[j - 1], a[j])) {
        let tmp = a[j - 1];
        a[j - 1] = a[j];
        a[j] = tmp;
        isChanged = true;
      }
    }
