function isStable(original, target) {
  for (var i = 0; i < original.length; i++) {
    var numOriginal = parseInt(original[i].slice(1, 2));
    for (var j = 0; j < target.length; j++) {
      var numTarget = parseInt(target[j].slice(1, 2));
      if (numOriginal === numTarget) {
        if (original[i].slice(0, 1) === target[j].slice(0, 1)) {
          target.splice(j, 1);
          break;
        } else {
          return 'Not stable';
        }
      }
    }
  }
  return 'Stable';
}

function BubbleSort(C, N) {
  var cnt = 0;
  while (cnt < N) {
    for(var i = N - 1; i > cnt; i--) {
      var num1 = parseInt(C[i-1].slice(1, 2));
      var num2 = parseInt(C[i].slice(1, 2));
      if (num1 > num2) {
        var tmp = C[i-1];
        C[i-1] = C[i];
        C[i] = tmp;
      }
    }
    cnt++;
  }
  return C;
}

function SelectionSort(C, N) {
  for (var i = 0; i < N - 1; i++) {
    var minj = parseInt(C[i].slice(1, 3));
    var minArrayNumber = i;
    for (var j = i + 1; j < N; j++) {
      var val = parseInt(C[j].slice(1, 3));
      if (minj > val) {
        minj = val;
        minArrayNumber = j;
      }
    }
    var tmp = C[i];
    C[i] = C[minArrayNumber];
    C[minArrayNumber] = tmp;
  }
  return C;
}

function bubble_sort(a, compare) {
    for (let i = 0; i < a.length; ++i) {
        for (let j = a.length - 1; j > i; --j) {
            if (compare(a[j - 1], a[j]) > 0) {
                [a[j - 1], a[j]] = [a[j], a[j - 1]];
            }
        }
    }
}

function selection_sort(a, compare) {
    for (let i = 0; i < a.length; ++i) {
        let min_j = i;
        for (let j = i + 1; j < a.length; ++j) {
            if (compare(a[j], a[min_j]) < 0) {
                min_j = j;
            }
        }
        [a[i], a[min_j]] = [a[min_j], a[i]];
    }
}

