  for (i = 0; i < N; i++) {
    var n = num(org, i);
    if (table[n] == null) table[n] = [];
    table[n].push(type(org, i));
  }

  for (var key in table) {
    var values = table[key];
    var count = 0;
    for (i = 0; i < N; i++) {
      if (num(a, i) == key) {
        if (values[count] == type(a, i)) {
          count++;
        } else {
          return false;
        }
      }
    }
  }
  return true;
}

