package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type trump struct {
	suit  string
	value int
}

func (t trump) String() string {
	return fmt.Sprintf("%s%d", t.suit, t.value)
}

func printTrumpArray(values []trump) {
	strValues := make([]string, len(values))
	for i, elm := range values {
		strValues[i] = fmt.Sprintf("%v", elm)
	}
	fmt.Printf("%v\n", strings.Join(strValues, " "))
}

func bubbleSort(tr []trump) int {
	flag := true
	count := 0
	for {
		if !flag {
			break
		}
		flag = false

		for j := len(tr) - 1; j >= 1; j-- {
			if tr[j].value < tr[j-1].value {
				tmp := tr[j]
				tr[j] = tr[j-1]
				tr[j-1] = tmp
				count++
				flag = true
			}
		}
	}
	return count
}

func selectionSort(tr []trump) int {
	count := 0
	for i := 0; i < len(tr); i++ {
		minj := i
		for j := i; j < len(tr); j++ {
			if tr[j].value < tr[minj].value {
				minj = j
			}
		}

		if i != minj {
			tmp := tr[i]
			tr[i] = tr[minj]
			tr[minj] = tmp
			count++
		}
	}
	return count
}

