type card struct {
	suite string
	num   int
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func ssort(a []card) (sw int) {
	n := len(a)
	for i := 0; i < n; i++ { // i-1番目までソート済みとする
		minv := a[i].num // i番目の値とそのインデックスを覚えておく
		mini := i
		for j := i + 1; j < n; j++ { // i+1番目以降で、minvより小さい値を探す
			if minv > a[j].num { // a[j]の方がminvより小さい
				minv = a[j].num // minv, miniを更新
				mini = j
			}
		}
		if i != mini {
			a[mini], a[i] = a[i], a[mini] // i番目の値とmini番目の値を交換する
			sw++
		}
	}
	return
}

func bsort(a []card) (sw int) {
	n := len(a)
	for i := 0; i < n; i++ {
		for j := n - 1; j >= i+1; j-- {
			if a[j].num < a[j-1].num {
				a[j], a[j-1] = a[j-1], a[j]
				sw++
			}
		}
	}
	return
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanLines)
	sc.Scan()
	n, _ := strconv.Atoi(sc.Text())
	sc.Scan()
	ss := strings.Split(sc.Text(), " ")
	cards := make([]card, n)
	for i := 0; i < len(ss); i++ {
		cards[i].suite = string(ss[i][0])
		cards[i].num = int(ss[i][1] - '0')
	}
	ccb := make([]card, n)
	copy(ccb, cards)
	bsort(ccb)
	showCards(ccb)
	fmt.Println("Stable")
	ccs := make([]card, n)
	copy(ccs, cards)
	ssort(ccs)
	showCards(ccs)
	for i := 0; i < n; i++ {
		if ccs[i].suite != ccb[i].suite {
			fmt.Println("Not stable")
			return
		}
	}
	fmt.Println("Stable")
}
func showCards(c []card) {
	for i := 0; i < len(c); i++ {
		if i > 0 {
			fmt.Print(" ")
		}
		fmt.Printf("%s%d", c[i].suite, c[i].num)
	}
	fmt.Println()
}

