func main() {
	var length int
	if n, err := fmt.Scanf("%d", &length); n != 1 || err != nil {
		log.Fatalln(n, err)
	}

	array := make([]string, length)
	for i := 0; i < length; i++ {
		if n, err := fmt.Scanf("%s", &array[i]); n != 1 || err != nil {
			log.Fatalln(n, err)
		}
	}

	array2 := make([]string, length)
	copy(array2, array)

	bubbleSort(array, length)
	selectionSort(array2, length)

	printArray(array, length)
	fmt.Println("Stable")

	printArray(array2, length)
	if reflect.DeepEqual(array, array2) {
		fmt.Println("Stable")
	} else {
		fmt.Println("Not stable")
	}
}

func bubbleSort(array []string, length int) {
	for i := 0; i < length-1; i++ {
		for j := length - 1; j > i; j-- {
			num1, _ := strconv.Atoi(array[j][1:])
			num2, _ := strconv.Atoi(array[j-1][1:])
			if num1 < num2 {
				array[j], array[j-1] = array[j-1], array[j]
			}
		}
	}
}

func selectionSort(array []string, length int) {
	for i := 0; i < length-1; i++ {
		min := i
		for j := i + 1; j < length; j++ {
			num1, _ := strconv.Atoi(array[min][1:])
			num2, _ := strconv.Atoi(array[j][1:])
			if num1 > num2 {
				min = j
			}
		}
		if min != i {
			array[min], array[i] = array[i], array[min]
		}
	}
}

func printArray(array []string, length int) {
	fmt.Print(array[0])
	for i := 1; i < length; i++ {
		fmt.Printf(" %s", array[i])
	}
	fmt.Print("\n")
}

