	ba := make([]string, N)
	copy(ba, A)

	f := true
	for f {
		f = false
		for i := N - 1; i > 0; i-- {
			j := i - 1
			ai := parseNum(ba[i])
			aj := parseNum(ba[j])
			if ai < aj {
				ba[i], ba[j] = ba[j], ba[i]
				f = true
			}
		}
	}
	return ba
}

func selectionSort(A []string, N int) []string {
	sa := make([]string, N)
	copy(sa, A)

	for i := 0; i < N-1; i++ {
		min := i
		for j := i + 1; j < N; j++ {
			ai := parseNum(sa[j])
			aj := parseNum(sa[min])
			if ai < aj {
				min = j
			}
		}
		if min != i {
			sa[i], sa[min] = sa[min], sa[i]
		}
	}
	return sa
}

