func bubbleSort(n int64, sa []int64, ss []string) ([]int64, []string) {
	a := make([]int64, cap(sa))
	copy(a, sa)

	s := make([]string, cap(ss))
	copy(s, ss)

	isIncomp := true

	for isIncomp {
		isIncomp = false
		for j := n - 1; j >= 1; j-- {
			if a[j] < a[j-1] {
				t := a[j-1]
				a[j-1] = a[j]
				a[j] = t

				ts := s[j-1]
				s[j-1] = s[j]
				s[j] = ts

				isIncomp = true
			}
		}
	}
	return a, s
}

func selectionSort(n int64, sa []int64, ss []string) ([]int64, []string) {
	a := make([]int64, cap(sa))
	copy(a, sa)

	s := make([]string, cap(ss))
	copy(s, ss)

	for i := int64(0); i <= n-1; i++ {
		minJ := i
		for j := int64(i); j <= n-1; j++ {
			if a[j] < a[minJ] {
				minJ = j
			}
		}
		t := a[minJ]
		a[minJ] = a[i]
		a[i] = t

		ts := s[minJ]
		s[minJ] = s[i]
		s[i] = ts
	}
	return a, s
}

