	sorted := 0
	for sorted < len(a)-1 {
		for cur := len(a) - 1; cur > sorted; cur-- {
			if a[cur-1].value > a[cur].value {
				// 左隣の方が大きいので入れ替える.
				v := a[cur]
				a[cur] = a[cur-1]
				a[cur-1] = v
			}
		}
		sorted++
	}
