func selectionSort(a cards) {
	for sorted := 0; sorted < len(a)-1; sorted++ {
		// ソートしていない部分から最小値を探す
		i := sorted + 1
		mini := i
		for ; i < len(a); i++ {
			if a[i].value < a[mini].value {
				mini = i
			}
		}
		// 入れ替える
		if a[mini].value < a[sorted].value {
			v := a[sorted]
			a[sorted] = a[mini]
			a[mini] = v
		}
	}
