func BubbleSort(a []Card) ([]Card, int) {
	var count int
	flag := true
	for flag {
		flag = false
		for i := len(a) - 1; i > 0; i-- {
			if a[i].value < a[i-1].value {
				a[i], a[i-1] = a[i-1], a[i]
				flag = true
				count++
			}
		}
	}
	return a, count
}

func SelectionSort(a []Card) ([]Card, int) {
	var minj, count int
	n := len(a)
	for i := 0; i < n; i++ {
		minj = i
		for j := i; j < n; j++ {
			if a[j].value < a[minj].value {
				minj = j
			}
		}
		if a[i].value > a[minj].value {
			count++
			a[i], a[minj] = a[minj], a[i]
		}
	}
	return a, count
}

