func IsStable(a []Card, sorted []Card) bool {
	for i := 1; i < len(sorted); i++ {
		prev := sorted[i-1]
		curr := sorted[i]
		if prev.value == curr.value && prev.suit != curr.suit {
			prevFound := len(a)
			for j, v := range a {
				if v == prev {
					prevFound = j
				}
				if v == curr && prevFound > j {
					return false
				}
			}
		}
	}
	return true
}

