type Card struct {
	sign  string
	value int
}

func stringify(C []Card) string {
	r := make([]string, len(C))
	for i, v := range C {
		r[i] = v.sign
	}
	return strings.Join(r, " ")
}

func bubbleSort(C []Card, N int) ([]Card, int) {
	count := 0
	flag := 1

	for flag == 1 {
		flag = 0
		for j := N - 1; j > 0; j-- {
			if C[j].value < C[j-1].value {
				tmp := C[j]
				C[j] = C[j-1]
				C[j-1] = tmp
				flag = 1
				count++
			}
		}
	}
	return C, count
}

func selectionSort(C []Card, N int) ([]Card, int) {

	count := 0
	for i := 0; i < N; i++ {
		minj := i
		for j := i; j < N; j++ {
			if C[j].value < C[minj].value {
				minj = j
			}
		}

		// changed value i
		if i != minj {
			count++
		}

		tmp := C[i]
		C[i] = C[minj]
		C[minj] = tmp
	}

	return C, count
}

func signed_order(C []Card) map[int][]string {

	m := make(map[int][]string, 0)

	prev := C[0]
	for i := 1; i < len(C); i++ {
		if prev.value == C[i].value {
			if len(m[C[i].value]) == 0 {
				m[C[i].value] = append(m[C[i].value], prev.sign)
			}
			m[C[i].value] = append(m[C[i].value], C[i].sign)
		}
		prev = C[i]
	}
	return m
}

func same_value(C []Card) map[int][]string {
	m := map[int][]string{}

	for _, v := range C {
		m[v.value] = append(m[v.value], v.sign)
	}
	return m
}

