		minj := i
		for j := i; j < n; j++ {
			if arr[j][1] < arr[minj][1] {
				minj = j
			}
		}
		temp := arr[i]
		arr[i] = arr[minj]
		arr[minj] = temp
	}
	return arr
}

func insertionSort(arrOrig []string) []string {
	n := len(arrOrig)

	arr := make([]string, n)
	copy(arr, arrOrig)

	for i := 1; i < n; i++ {
		v := arr[i]
		j := i - 1
		for j >= 0 && arr[j][1] > v[1] {
			arr[j+1] = arr[j]
			j--
		}
		arr[j+1] = v
	}
	return arr
}

