func main() {
	sc.Split(bufio.ScanWords)
	var n int = nextInt()
	var A []Card

	for i := 0; i < n; i++ {
		A = append(A, nextCard())
	}

	bubble_A := make([]Card, n)

	copy(bubble_A, A)

	var flag = true
	for flag {
		flag = false
		for i := n - 1; i >= 1; i-- {

			if bubble_A[i].number < bubble_A[i-1].number {
				bubble_A[i], bubble_A[i-1] = bubble_A[i-1], bubble_A[i]
				flag = true
			}
