func bubble(arr []Card, N int) []Card {
	changeNum := 0

	// n
	for n := 0; n < N; {

		last := N - 1
		first := n

		// 最終ラインまで
		for ; first != last; {

			last_m := arr[last]
			last_n := arr[last-1]

			// 比較する
			if last_n.toInt() > last_m.toInt() {
				changeNum ++
				temp := arr[last]
				arr[last] = arr[last-1]
				arr[last-1] = temp
				//fmt.Println(reduce(arr), "交換")
			}

			// 最後から減らしていく。
			last -= 1
		}
		//fmt.Println(reduce(arr))
		n++
	}
	fmt.Println(reduce(arr))
	return arr
}

func selection(arr []Card, N int) []Card {
	changeNum := 0
	// n
	for n := 0; n < N-1; {

		//fmt.Println(arr[n], "ターゲット", n)
		//fmt.Println(arr)
		//fmt.Println(range_f, "####", range_l)

		range_f := n
		range_l := N - 1

		min_k := range_f

		// 最終ラインまで
		for ; range_f != range_l+1; {

			// 最小値を更新する
			if arr[min_k].toInt() > arr[range_f].toInt() {
				min_k = range_f
			}
			range_f++
		}

		// 最小値とターゲットを交換
		if min_k != n {
			//fmt.Println(arr[n], " ==> ", arr[min_k])

			changeNum++

			temp := arr[n]
			arr[n] = arr[min_k]
			arr[min_k] = temp
		}
		//fmt.Println(arr)
		n++
	}

	fmt.Println(reduce(arr))

	return arr
}

