	checkedCardLabels := make([]string, 0)

	for _, card := range formattedCardArray {
		for _, otherCard := range cardArray {

			// 順序が一緒だったらok
			if otherCard.label == card.label {
				checkedCardLabels = append(checkedCardLabels, card.label)
				break
			}

			if otherCard.toInt() == card.toInt() && !arrayContains(checkedCardLabels, otherCard.label) {
				return false
			}
		}
	}
	return true
}

