	g rune // group (S, H, C, D)
}

func bubblesort(a []node) int {
	done := true
	n := len(a)
	c := 0
	for done {
		done = false
		for j := n - 1; j >= 1; j-- {
			if a[j].v < a[j-1].v {
				a[j-1], a[j] = a[j], a[j-1]
				c++
				done = true
			}
		}
	}
	return c
}

func selectsort(a []node) int {
	n := len(a)
	c := 0
	for i := range a {
		minj := i
		for j := i; j < n; j++ {
			if a[j].v < a[minj].v {
				minj = j
			}
		}
		a[i], a[minj] = a[minj], a[i]
		if minj != i {
			c++
		}
	}
	return c
}

func printSlice(a []node) {
