func BubbleSort(in []string) []string {
	var _in []string = make([]string, len(in))
	copy(_in, in)
	for i := 0; i < len(_in); i++ {
		for j := len(_in) -1 ; j > i; j-- {
			if _in[j][1] < _in[j-1][1] {
				swap(&_in[j], &_in[j-1])
			}
		}
	}
	return _in
}

func SelectionSort(in []string) []string {
	var _in []string = make([]string, len(in))
	copy(_in, in)
	for i := 0; i < len(_in); i++ {
		min := i
		for j := i + 1; j < len(_in); j++ {
			if _in[j][1] < _in[min][1] {
				min = j
			}
		}
		if min != i {
			swap(&_in[min], &_in[i])
		}
	}
	return _in
}

func IsStable(tested []string, stable []string) bool {
	for index, value := range stable {
		if tested[index] != value {
			return false
		}
	}
	return true
}

func swap(a *string, b *string) {
	temp := *b
	*b = *a
	*a = temp
}

func trace(in []string)  {
	for index, value := range in {
		if index == 0 {
			fmt.Print(value)
		} else {
			fmt.Print(" ", value)
		}
	}
	fmt.Println()
}

