package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

var cards map[string]int

func print(A []string) {
	fmt.Println(strings.Join(A, " "))
}

func parseNum(c string) int {
	if n, ok := cards[c]; ok {
		return n
	}

	ar := strings.Split(c, "")
	n, err := strconv.Atoi(ar[1])
	if err != nil {
		panic(err)
	}
	cards[c] = n
	return n
}

func bubbleSort(A []string, N int) []string {
	ba := make([]string, N)
	copy(ba, A)

	f := true
	for f {
		f = false
		for i := N - 1; i > 0; i-- {
			j := i - 1
			ai := parseNum(ba[i])
			aj := parseNum(ba[j])
			if ai < aj {
				ba[i], ba[j] = ba[j], ba[i]
				f = true
			}
		}
	}
	return ba
}

func selectionSort(A []string, N int) []string {
	sa := make([]string, N)
	copy(sa, A)

	for i := 0; i < N-1; i++ {
		min := i
		for j := i + 1; j < N; j++ {
			ai := parseNum(sa[j])
			aj := parseNum(sa[min])
			if ai < aj {
				min = j
			}
		}
		if min != i {
			sa[i], sa[min] = sa[min], sa[i]
		}
	}
	return sa
}

func main() {
	var sc = bufio.NewScanner(os.Stdin)

	sc.Scan()
	N, e := strconv.Atoi(sc.Text())
	if e != nil {
		panic(e)
	}

	sc.Scan()
	A := strings.Split(sc.Text(), " ")

	ba := bubbleSort(A, N)
	print(ba)
	fmt.Println("Stable")

	isStable := true
	sa := selectionSort(A, N)
	print(sa)
	for i, c := range ba {
		if sa[i] != c {
			isStable = false
			break
		}
	}
	if isStable {
		fmt.Println("Stable")
	} else {
		fmt.Println("Not stable")
	}
}

