type Card struct {
	suit  string
	value int
}

func (c Card) inspect() string {
	return c.suit + strconv.Itoa(c.value)
}

func trace(arr []Card) {
	for i, card := range arr {
		if i == len(arr)-1 {
			fmt.Printf("%s\n", card.inspect())
		} else {
			fmt.Printf("%s ", card.inspect())
		}
	}
}

func isEqual(a, b []Card) bool {
	for i, e := range a {
		if e.inspect() != b[i].inspect() {
			return false
		}
	}
	return true
}

func bubbleSort(arr []Card, len int) []Card {
	change := true
	for i := 0; change; i++ {
		change = false
		for j := len - 1; j > i; j-- {
			if arr[j].value < arr[j-1].value {
				arr[j], arr[j-1] = arr[j-1], arr[j]
				change = true
			}
		}
	}
	trace(arr)
	return arr
}

func selectionSort(arr []Card, len int) []Card {
	for i := 0; i < len; i++ {
		minIndex := i
		for j := i + 1; j < len; j++ {
			if arr[j].value < arr[minIndex].value {
				minIndex = j
			}
		}
		arr[i], arr[minIndex] = arr[minIndex], arr[i]
	}
	trace(arr)
	return arr
}

