	var n int
	fmt.Scan(&n)
	cards := make([]Card, n)
	var tmp string
	for i := 0; i < n; i++ {
		fmt.Scan(&tmp)
		suit := string(tmp[0])
		value, _ := strconv.Atoi(string(tmp[1]))
		cards[i] = Card{suit, value}
	}
	bubble := make([]Card, n)
	copy(bubble, cards)
	bubble = bubbleSort(bubble, n)
	fmt.Println("Stable")

	selection := make([]Card, n)
	copy(selection, cards)
	selection = selectionSort(selection, n)
	if isEqual(bubble, selection) {
		fmt.Println("Stable")
	} else {
		fmt.Println("Not stable")
	}
}

