def bubble_sort(a_list):
    n = len(a_list)
    for i in range(0, n):
        for j in reversed(range(i + 1, n)):
            if a_list[j - 1][1] > a_list[j][1]:
                a_list[j - 1], a_list[j] = a_list[j], a_list[j - 1]
    return a_list


def selection_sort(a_list):
    n = len(a_list)
    for i in range(0, n):
        mini = i
        for j in range(i, n):
            if a_list[j][1] < a_list[mini][1]:
                mini = j
        if i != mini:
            a_list[i], a_list[mini] = a_list[mini], a_list[i]
    return a_list


