    for i in range(n):
        for j in range(n - 1, i, -1):
            if cards[j - 1].value > cards[j].value:
                cards[j - 1], cards[j] = cards[j], cards[j - 1]


def selection_sort(cards):
    n = len(cards)
    for i in range(n):
        minj = min(range(i, n), key=lambda j: cards[j].value)
        if i != minj:
            cards[i], cards[minj] = cards[minj], cards[i]


