import copy

class StableSort():
    def __init__(self):
        self.N = n
        self.C = copy.copy(c) #こうしないと書き換わってしまう


    def BS(self):
        A = [self.C[i][1] for i in range(self.N)] #数値
        if self.N == 1:
            C = " ".join(self.C)
            return C
        else:
            for i in range(self.N): #比較は常にリストの一番後ろからはじまる
                for j in range(self.N - i - 1):
                    if A[self.N - j - 1] < A[self.N - j - 2]: #常に安定である 
                        A[self.N - j - 1], A[self.N - j - 2] = A[self.N - j - 2], A[self.N - j - 1] 
                        self.C[self.N - j - 1], self.C[self.N - j - 2] = self.C[self.N - j - 2], self.C[self.N - j - 1] 

            C = " ".join(self.C)
            return C


    def SS(self):
        A = [self.C[i][1] for i in range(self.N)] #数値
        if self.N == 1:
            print(self.C[0] + "\n" + "stable")
        else:
            for i in range(self.N - 1):
                A_r = A[i:] #確定してないAの右側の領域
                mini = min(A_r)
                #AとA_rのインデックスは違うので，抜いた左側の分の+iの補正が必要
                mini_index = i + A_r.index(mini) 
                if A[i] > mini:
                    A[i], A[mini_index] = A[mini_index], A[i] 
                    self.C[i], self.C[mini_index] = self.C[mini_index], self.C[i] 

            C = " ".join(self.C) 
            return C

