def bubbleSort(x):
    A = x[:]
    flag_stable = True

    for i in range(1, len(A)):
        for j in range(1, len(A) - i + 1):
            if  A[j - 1][1] > A[j][1]:
                A[j], A[j - 1] = A[j - 1], A[j]

                if not flag_stable:
                    continue

                if A[j - 1][1:] == A[j][1:]:
                    flag_stable = False

    return A, flag_stable

def selectionSort(x):
    A = x[:]
    flag_stable = True

    for i in range(len(A)):
        minj = i

        for j in range(i + 1, len(A)):

            if A[j][1] < A[minj][1]:
                minj = j

        if minj != i:
            A[i], A[minj] = A[minj], A[i]

            if not flag_stable:
                continue

            for k in range(i, minj):
                if A[k][1] == A[minj][1]:
                    flag_stable = False

    return A, flag_stable




