    return c

def insertion_sort(cs, f):
    c = cs[:]
    for i in range(1, len(c)):
        w = c[i]
        j = i - 1
        while j >= 0 and f(c[j]) > f(w):
            c[j + 1] = c[j]
            j -= 1
        c[j + 1] = w
    return c

