fn solve(input: &str) -> String {
    let mut iterator = input.split_whitespace();

    let n: usize = iterator.next().unwrap().parse().unwrap();
    let mut cards1: Vec<Card> = Vec::with_capacity(n);
    let mut cards2: Vec<Card> = Vec::with_capacity(n);
    for _i in 0..n {
        let input = iterator.next().unwrap().to_string();
        cards1.push(Card::new(&input));
        cards2.push(Card::new(&input));
    }

    let mut result = String::new();

    // Bubble Sort
    for i in 0..n {
        for j in ((i + 1)..n).rev() {
            if cards1[j].number < cards1[j - 1].number {
                cards1.swap(j, j - 1);
            }
        }
    }
    result += &cards1.iter().map(|it| it.to_string()).collect::<Vec<String>>().join(" ");
    result += "\nStable\n"; // always stable

    // Selection Sort
    for i in 0..n {
        let mut minj = i;
        for j in i..n {
            if cards2[j].number < cards2[minj].number {
                minj = j;
            }
        }
        cards2.swap(i, minj);
    }
    result += &cards2.iter().map(|it| it.to_string()).collect::<Vec<String>>().join(" ");
    result += if is_stable(&cards1, &cards2) { "\nStable" } else { "\nNot stable" };

    return result.trim().to_string();
}

fn is_stable(cards1: &Vec<Card>, cards2: &Vec<Card>) -> bool {
    for i in 0..cards1.len() {
        let c1 = &cards1[i];
        let c2 = &cards2[i];
        if c1.suit != c2.suit || c1.number != c2.number {
            return false;
        }
    }
    true
}

