fn bubble_sort(c: &mut Vec<Card>) {
    let n = c.len();
    for i in 0..n {
        for j0 in i..n-1 {
           let j = n + i - 1 - j0;
           if c[j].num < c[j-1].num {
               c.swap(j, j-1);
           }
        }
    }
}

fn selection_sort(c: &mut Vec<Card>) {
    let n = c.len();
    for i in 0..n {
        let mut min_i = i;
        for j in i..n {
           if c[j].num < c[min_i].num {
               min_i = j;
           }
        }
        c.swap(i, min_i);
    }
}

fn check_stable(c0: &Vec<Card>, c: &Vec<Card>) -> bool {
    let mut left = -1;
    let mut right = -1;
    for i in 1..c.len() {
        if c[i].num != c[i-1].num {
            left = -1;
            continue;
        }
        for j in 0..c0.len() {
            if c0[j].num == c[i].num && c0[j].suit == c[i].suit {
                right = j as i32;
                if left >= 0 {
                    break;
                }
            }
            if c0[j].num == c[i-1].num && c0[j].suit == c[i-1].suit {
                left = j as i32;
                if right >= 0 {
                    break;
                }
            }
        }
        if left > right {
            return false;
        }
        left = right;
        right = -1;
    }
    true
}

