// "S1", "H2"などを数字の部分のみを比較して結果を返す関数。
// mx, nyに対して、x < yを返す
// なお、x,yは1..9であるとする。
fn cmp(s1: &str, s2: &str) -> bool {
    let d1: i32 = s1.chars().nth(1).unwrap().to_digit(10).unwrap() as i32;
    let d2: i32 = s2.chars().nth(1).unwrap().to_digit(10).unwrap() as i32;
    d1 < d2
}


