fn BubbleSort(A:&mut Vec<Vec<char>>,N:usize){
    let mut flag = true;
    while flag{
        flag = false;
        for j in 1..N{
            let j = N-j;
            if A[j][1] < A[j-1][1]{
                let tmp = A[j].clone();
                A[j] = A[j-1].clone();
                A[j-1] = tmp;
                flag = true;
            }
        }
    }
}

fn SelectionSort(A:&mut Vec<Vec<char>>,N:usize){
    for i in 0..N{
        let mut minj = i;
        for j in i..N{
            if A[j][1] < A[minj][1]{
                minj = j;
            }
        }
        if i != minj {
            let tmp = A[i].clone();
            A[i] = A[minj].clone();
            A[minj] = tmp;
        }
    }
}

