fn bubble_sort(
    a: &mut Vec<Card>,
    n: usize,
) {
    for i in 0..n {
        let mut j = n - 1;
        while j >= i + 1 {
            if a[j].value < a[j - 1].value {
                let t = a[j];
                a[j] = a[j - 1];
                a[j - 1] = t;
            }
            j -= 1;
        }
    }
}

fn selection_sort(
    a: &mut Vec<Card>,
    n: usize
) {
    for i in 0..n {
        let mut minj = i;
        let mut j = i;
        while j < n {
            if a[j].value < a[minj].value {
                minj = j;
            }
            j += 1;
        }
        let t = a[i];
        a[i] = a[minj];
        a[minj] = t;
    }
}

