/// 入力と出力から安定なソートか調べる
pub fn is_stable(input: &[String], out: &[String]) -> bool {
    let len = input.len();
    for i in 0..len {
        for j in i+1..len {
            // 同じ値が存在するか確認
            if get_num(input[i].as_str()) == get_num(input[j].as_str()) {
                for a in 0..len {
                    for b in a+1..len {
                        // 出力においてもi番目があと(b)、手前にj番目(a)が来ていたらFlase
                        if input[i] == out[b] && input[j] == out[a] {
                            return false;
                        }
                    }
                }
            }
        }
    }
    true
}


/// バブルソート
/// 何回更新したかを返す
/// https://onlinejudge.u-aizu.ac.jp/courses/lesson/1/ALDS1/2/ALDS1_2_A
pub fn bubble_sort(x: &mut [String]) {
    let mut flag = true;
    while flag {
        flag = false;
        for j in 1..x.len() {
            if get_num(x[j].as_str()) < get_num(x[j - 1].as_str()) {
                x.swap(j, j - 1);
                flag = true;
            }
        }
    }
}

/// 選択ソート
/// 左から順に最小の値を検索しては入れていく
/// https://onlinejudge.u-aizu.ac.jp/courses/lesson/1/ALDS1/2/ALDS1_2_B
pub fn selection_sort(x: &mut [String]) {
    for i in 0..x.len() {
        let mut minj = i;
        for j in i+1..x.len() {
            if get_num(x[j].as_str()) < get_num(x[minj].as_str()) {
                minj = j;
            }
        }
        x.swap(i, minj);
    }
}

