fn bubble_sort(c: &mut Vec<(char, u8, usize)>) {
    let n = c.len();
    for i in 0..n {
        for j in (i+1..n).rev() {
            if c[j].1 < c[j-1].1 {
                c.swap(j, j-1);
            }
        }
    }
}

fn selection_sort(c: &mut Vec<(char, u8, usize)>) {
    let n = c.len();
    for i in 0..n {
        let mut minj = i;
        for j in i..n {
            if c[j].1 < c[minj].1 {
                minj = j;
            }
        }
        c.swap(i, minj);
    }
}

fn is_stable(c: &Vec<(char, u8, usize)>) -> bool {
    let n = c.len();
    for i in 0..n {
        for j in i+1..n {
            if c[i].1 == c[j].1 && c[i].2 > c[j].2 {
                return false;
            }
        }
    }
    true
}

