use std::io::Read;
struct Scanner<R> {
    reader: R,
}

impl<R: Read> Scanner<R> {
    fn new(reader: R) -> Scanner<R> {
        Scanner { reader }
    }

    fn next<T>(&mut self) -> T
    where
        T: std::str::FromStr,
    {
        self.reader
            .by_ref()
            .bytes()
            .map(|r: Result<u8, std::io::Error>| -> char { r.unwrap() as char })
            .skip_while(|c: &char| -> bool { c.is_whitespace() })
            .take_while(|c: &char| -> bool { !c.is_whitespace() })
            .collect::<String>()
            .parse::<T>()
            .ok()
            .unwrap()
    }
}

