fn bubble(v: &mut Vec<Card>) {
    for i in 0..v.len() {
        for j in (i + 1..v.len()).rev() {
            if v[j].number < v[j - 1].number {
                v.swap(j, j - 1);
            }
        }
    }
}

fn selection(v: &mut Vec<Card>) {
    for i in 0..v.len() {
        let mut min_idx = i;
        for j in i..v.len() {
            if v[j].number < v[min_idx].number {
                min_idx = j;
            }
        }
        v.swap(i, min_idx);
    }
}

fn is_stable(v1: &Vec<Card>, v2: &Vec<Card>) -> bool {
    v1.iter().zip(v2.iter()).all(|(c1,c2): (&Card, &Card)| -> bool { c1 == c2})
}

