fn bubble_sort(mut v: Vec<Vec<char>>) -> (Vec<Vec<char>>, u32) {
    let mut tmp;
    let mut t:u32 = 0;

    for i in 0..v.len()-1 {
        for j in (i+1..v.len()).rev() {
            if eval_val(&v[j]) < eval_val(&v[j-1]) {
                tmp = v[j].clone();
                v[j] = v[j-1].clone();
                v[j-1] = tmp;
                t += 1;
            }
        }
    }
    (v, t)
}

fn selection_sort(mut v: Vec<Vec<char>>) -> (Vec<Vec<char>>, u32) {
    let mut tmp;
    let mut t:u32 = 0;

    for i in 0..v.len()-1 {
        let mut mini = i;
        for j in i..v.len() {
            if eval_val(&v[j]) < eval_val(&v[mini]) {
                mini = j
            }
        }
        if i != mini {
            tmp = v[mini].clone();
            v[mini] = v[i].clone();
            v[i] = tmp;
            t += 1;
        }
    }
    (v, t)
}

fn eval_val(card: &Vec<char>) -> u32 {
    card[1] as u32 - 48
}

