fn format_output(xs: &Vec<String>) -> String {
    xs.join(" ")
}

fn get_number(card: &str) -> u32 {
    card.chars().nth(1).unwrap().to_digit(10).unwrap()
}

fn bubble_sort(n: usize, xs: &Vec<String>) -> String {
    let mut copied_xs = xs.clone();

    for i in 0..n {
        for j in ((i + 1)..n).rev() {
            if get_number(&copied_xs[j]) < get_number(&copied_xs[j - 1]) {
                let tmp = copied_xs[j].clone();
                copied_xs[j] = copied_xs[j - 1].clone();
                copied_xs[j - 1] = tmp;
            }
        }
    }

    format_output(&copied_xs)
}

fn selection_sort(n: usize, xs: &Vec<String>) -> String {
    let mut copied_xs = xs.clone();

    for i in 0..n {
        let mut minj = i;

        for j in i..n {
            if get_number(&copied_xs[j]) < get_number(&copied_xs[minj]) {
                minj = j;
            };
        };

        let tmp = copied_xs[i].clone();
        copied_xs[i] = copied_xs[minj].clone();
        copied_xs[minj] = tmp;
    }
    format_output(&copied_xs)
}

fn main() {
    let n: usize = read();
    let xs: Vec<String> = read_vec();

    let ans_bubble = bubble_sort(n, &xs);
    let ans_select = selection_sort(n, &xs);

    println!("{}", ans_bubble);
    println!("Stable");
    println!("{}", ans_select);
    println!("{}", if ans_bubble == ans_select { "Stable" } else { "Not stable" });
}
